logger = logging.getLogger(__name__)


CURRICULUM_SCHEMA = 'curriculum'
TRAINING_MODULE_CATALOGUE_COLUMN = 'module_catalogue_id'
CANONICAL_MODULE_ID_PATTERN = re.compile(r'^MOD-[A-Z0-9][A-Z0-9_-]*$', re.I)
STAFF_PROFILE_EMAIL_PATTERN = re.compile(r'^[^\s@]+@[^\s@]+\.[^\s@]+$')
STAFF_PROFILE_PHONE_PATTERN = re.compile(r'^[+()\d\s.\-]{7,20}$')
CURRICULUM_CACHE_TTL_SECONDS = 1800
# Programme payloads that carry learner figures: learner counts on the
# programme, its cohorts and groups (``Learner.learners``), and learner KSB
# progress (``learner_progress_ksbs``). No curriculum epoch covers those
# tables -- they are written by learner, hours and progress code, management
# commands and imports outside any curriculum request -- so this TTL is their
# only freshness bound. Under the global epoch any curriculum save anywhere
# happened to refresh them; a programme-scoped key no longer is, so without
# this they could be 30 minutes old. Same order as the 30s learner roster.
# The modules section carries no learner data and keeps the full TTL.
CURRICULUM_LEARNER_DATA_TTL_SECONDS = 60
# The raw table reads behind every payload are visibility-independent: whether a
# row is operational or archived is decided in Python, in
# _build_curriculum_payload_from_rows(). Caching the rows lets one set of Neon
# round trips serve both visibilities, which a Curriculum page needs on every
# load -- it asks for `?visibility=all` and the default in the same burst, and
# each used to pay for its own full read.
#
# The TTL is deliberately short. The win is entirely within one page load, so a
# minute covers it, while keeping the window in which a write from another
# worker could be missed far below the payload TTL. A write in this process
# clears the rows with everything else; a write in another one bumps the shared
# epoch, which invalidates them here too whenever Redis is configured.
CURRICULUM_ROWS_CACHE_TTL_SECONDS = 60
_CURRICULUM_CACHE = {}
_CURRICULUM_CACHE_LOCK = threading.Lock()
# One lock per payload key, so concurrent misses on the same key rebuild once
# instead of each running the factory. See curriculum_build_lock().
_CURRICULUM_BUILD_LOCKS = {}
# L1 generation: prevents an in-flight factory in this process from publishing
# stale rows. The Django-cache generation below provides the cross-worker layer.
_CURRICULUM_CACHE_EPOCH = 0
_CURRICULUM_SHARED_EPOCH_KEY = 'curriculum:cache-epoch'
# The cross-worker generation counter, kept in the one store every worker really
# shares: the database.
#
# It used to live in Django's cache alone. With a Redis CACHE_URL that is shared
# and correct; without one Django falls back to LocMemCache, which is per
# process -- and production runs nine services of two workers, so a write bumped
# the epoch in exactly one of eighteen caches. The other seventeen kept serving
# their pre-write payload for the whole 1800s TTL, which is a cohort, group,
# module or authored week that saves successfully and then does not appear:
# reload and you are talking to a different worker that never heard about it.
# Reads still answer from the process-local cache; this is only what tells a
# worker that its copy is out of date.
CURRICULUM_EPOCH_TABLE = 'cache_epoch'
# How long a worker may go on trusting the epoch it last read. It bounds both
# the staleness a write in another worker can cause and the cost of asking: one
# single-row read per worker per window, against the ~13s rebuild it protects.
SHARED_EPOCH_POLL_SECONDS = 3.0
_SHARED_EPOCH_STATE = {'value': None, 'checked_at': 0.0}
_SHARED_EPOCH_LOCK = threading.Lock()
_SHARED_EPOCH_REFRESH_LOCK = threading.Lock()
_CURRICULUM_EPOCH_TABLE_READY = False
# Per-thread: a write in this request has invalidated, and one shared bump is
# owed once the request is through. Deduped because invalidate_curriculum_cache()
# is called from inside write helpers, sometimes once per written row -- a tree
# save would otherwise spend thousands of UPDATEs on one counter.
_CURRICULUM_EPOCH_BUMP = threading.local()
_TABLE_COLUMNS_CACHE = {}
_TABLE_EXISTS_CACHE = {}
_AUTHORING_TABLES_READY = False
_FREE_PROGRAMME_TABLES_READY = False
_PROGRAMME_CONFIG_DEDUP_READY = False
_KSB_PROFILE_PROGRAMME_ID_READY = False
_TRAINING_PLAN_CANONICAL_READY = False
_LIVE_SESSIONS_TABLE_READY = False
_LIVE_SESSION_TRACKING_TABLES_READY = False
SUPPORTED_KSB_SOURCE_TYPES = {'standard', 'framework'}
LIVE_SESSIONS_TABLE = 'live_sessions'
LIVE_SESSION_OCCURRENCES_TABLE = 'live_session_occurrences'
LIVE_SESSION_ATTENDANCE_TABLE = 'live_session_attendance'
LIVE_SESSION_ARTIFACTS_TABLE = 'live_session_artifacts'
LIVE_SESSION_RECORDING_EVENTS_TABLE = 'live_session_recording_events'
LIVE_SESSION_JOIN_LAUNCHES_TABLE = 'live_session_join_launches'
SOFT_DELETE_COLUMNS = {'deleted_at', 'deleted_by', 'deleted_via_parent'}
SUPPORTED_KSB_WEIGHT_CLASSES = {'hard', 'soft', 'possible'}


def invalidate_curriculum_cache():
    global _CURRICULUM_CACHE_EPOCH
    with _CURRICULUM_CACHE_LOCK:
        # Programme-scoped entries stay: their generation is checked on every
        # read, and the bump this write owes retires exactly the ones it touched.
        for key in [key for key, entry in _CURRICULUM_CACHE.items() if not entry.get('scoped')]:
            _CURRICULUM_CACHE.pop(key, None)
        # Bumping the epoch discards results from any factory that is mid-flight
        # right now. Without it, a build that started before this write completes
        # afterwards and repopulates the cache with pre-write rows, which would
        # then serve stale authoring data for the rest of the TTL.
        _CURRICULUM_CACHE_EPOCH += 1
    # Generation-based invalidation: every worker keys its cache entries on the
    # counter, so moving it retires all of them at once without needing a
    # backend-specific delete-pattern API. Old generations expire naturally
    # after the normal TTL.
    bump_shared_curriculum_epoch()
    # One outbox pair per write request, recorded while the caller's database
    # transaction is still active. A tree save can invalidate once per row, so
    # the request-scoped marker prevents that from becoming thousands of
    # duplicate outbox inserts; the worker still coalesces concurrent requests.
    if not getattr(_CURRICULUM_EPOCH_BUMP, 'read_model_queued', False):
        try:
            from .read_model import enqueue_all_curriculum_home_refreshes
            enqueue_all_curriculum_home_refreshes(reason='curriculum-change')
        except Exception:
            logger.warning('Unable to enqueue Curriculum Home refresh.', exc_info=True)
        if getattr(_CURRICULUM_EPOCH_BUMP, 'scoped', False):
            _CURRICULUM_EPOCH_BUMP.read_model_queued = True
    # Only the negative answers are dropped. Whether a table exists changes on
    # DDL, never on a curriculum write, and the ensure_* helpers only ever add
    # tables -- so a cached True is still true, while a cached False may have
    # been provisioned since and has to be asked again. Clearing the lot cost
    # ~8 information_schema round trips on the rebuild straight after every
    # write (~1-2s against a remote database) to re-learn a schema that had not
    # moved. Tests that roll the schema away call reset_schema_ready_flags(),
    # which still clears this outright.
    for key in [key for key, exists in _TABLE_EXISTS_CACHE.items() if not exists]:
        _TABLE_EXISTS_CACHE.pop(key, None)
    # Rebuild what was just dropped, off the request path. Scheduling rather
    # than building keeps this call as cheap as it was -- it is made from inside
    # write handlers, sometimes once per written row -- and the delay in the
    # warm loop collapses a burst of these into one rebuild.
    #
    # on_commit, because several handlers invalidate from inside their atomic
    # block: a warm that started before the commit would read the pre-write
    # rows and cache them for the full TTL, with no later invalidation to
    # correct it. Outside an atomic block this runs straight away, and a
    # rollback correctly warms nothing.
    try:
        transaction.on_commit(schedule_curriculum_warm)
    except Exception:
        logger.warning('Unable to schedule curriculum cache warm.', exc_info=True)


# ---------------------------------------------------------------------------
# Curriculum write tracking
#
# Two layers, both correlated by the request_id that
# config.observability.RequestObservabilityMiddleware puts on every request, so
# one request's whole story can be pulled out of the stream with a single grep.
#
#   INFO  - decision events. What a handler *chose* to do and why: created a new
#           row, matched an existing one, skipped an archived namesake, revived a
#           tombstone, refused. Low volume (a handful per request) and always on,
#           because these are the events whose absence made the "recreate an
#           archived group" bug invisible: the API answered 200 and nothing,
#           anywhere, recorded that the write had landed on an archived row.
#
#   DEBUG - storage events. One line per write call reaching a curriculum table,
#           with the table, the key and the row count. Complete by construction
#           (every write funnels through the helpers below) but far too chatty
#           for normal running: a tree save writes thousands of rows. Turn it on
#           per-process with CURRICULUM_WRITE_TRACE=true, or globally with
#           LOG_LEVEL=DEBUG.
#
# Ids, tables, counts and branch names only. Never names of groups, cohorts or
# staff -- config.observability.SAFE_LOG_FIELDS drops anything not on its
# allowlist in production, and the allowlist is deliberately id-only so that
# turning the trace on cannot start spilling people's names into the logs.
# ---------------------------------------------------------------------------

write_logger = logging.getLogger('curriculum_api.writes')

CURRICULUM_WRITE_TRACE = os.environ.get('CURRICULUM_WRITE_TRACE', 'false').lower() == 'true'


def _write_log_fields(fields):
    """Keep only the allowlisted, non-empty fields, stringified for the log."""
    allowed = (
        'entity_type', 'entity_id', 'parent_id', 'action',
        'outcome', 'table', 'row_count', 'matched_id', 'reason',
    )
    return {
        key: (value if isinstance(value, int) else clean_str(value))
        for key, value in fields.items()
        if key in allowed and value not in (None, '')
    }


def log_curriculum_decision(action, **fields):
    """Record what a curriculum write handler decided, and on which row.

    ``action`` is a dotted event name (``group.create``, ``cohort.archive``).
    ``outcome`` is the branch taken, and is the field worth alerting on: an
    ``outcome`` that is not what the caller expected is the whole point of this
    log existing.
    """
    safe = _write_log_fields({'action': action, **fields})
    summary = ' '.join(f'{key}={value}' for key, value in sorted(safe.items()) if key != 'action')
    write_logger.info('%s %s', action, summary, extra={'event': f'curriculum.{action}', **safe})


def log_curriculum_storage(action, table, *, rows=None, **fields):
    """Record one write reaching a curriculum table. DEBUG; see the note above.

    ``rows`` may be the returned row list or an int; anything else is ignored
    rather than guessed at, because this must never be the reason a write fails.
    """
    if not (CURRICULUM_WRITE_TRACE or write_logger.isEnabledFor(logging.DEBUG)):
        return
    try:
        if isinstance(rows, int):
            row_count = rows
        elif rows is None:
            row_count = None
        else:
            row_count = len(rows)
        safe = _write_log_fields({'action': action, 'table': table, 'row_count': row_count, **fields})
        summary = ' '.join(f'{key}={value}' for key, value in sorted(safe.items()) if key != 'action')
        write_logger.debug('storage.%s %s', action, summary, extra={'event': f'curriculum.storage.{action}', **safe})
    except Exception:
        # A trace that can break a write is worse than no trace.
        logger.debug('Curriculum write trace failed.', exc_info=True)


# Whole-table reads memoised for the duration of one payload build. build_programmes()
# calls programme_component_ksb_mapping_count() and programme_learner_ksb_progress()
# once per programme, and each of those re-reads authoring modules, programmes,
# cohorts, groups and ksb_profiles in full. On a remote database that turned a
# ~30-row payload into ~300 round trips (35s per build). The scope is opened only
# around read-only payload assembly and torn down on exit, so a write path never
# reads back rows it just wrote from a stale memo.
_CURRICULUM_READ_SCOPE = threading.local()


@contextlib.contextmanager
def curriculum_read_scope(targeted_child_reads=False):
    """Deduplicate repeated whole-table curriculum reads inside one build.

    Reentrant: a nested ``with`` reuses the outermost scope, which owns the
    lifetime, so a payload build called from inside another one still sees a
    single set of reads.

    ``targeted_child_reads`` is for a build that answers about one scope rather
    than looping over every programme. It keeps weeks/components/mappings on the
    ``module_catalogue_id in (...)`` query instead of the shared full read that
    only pays off across many programmes — see authoring_child_rows_for_modules.
    Dedup of the parent tables (modules, programmes, cohorts, groups) is
    unaffected, and both read paths are memoised, so nothing is read twice
    either way. Set on the outermost scope; a nested one inherits it.
    """
    if getattr(_CURRICULUM_READ_SCOPE, 'memo', None) is not None:
        yield
        return
    _CURRICULUM_READ_SCOPE.memo = {}
    _CURRICULUM_READ_SCOPE.targeted_child_reads = bool(targeted_child_reads)
    try:
        yield
    finally:
        _CURRICULUM_READ_SCOPE.memo = None
        _CURRICULUM_READ_SCOPE.targeted_child_reads = False


def _scope_memo_key(value):
    """Hashable stand-in for a call argument (query params arrive as lists)."""
    if isinstance(value, (list, tuple)):
        return tuple(_scope_memo_key(item) for item in value)
    if isinstance(value, (set, frozenset)):
        return frozenset(_scope_memo_key(item) for item in value)
    if isinstance(value, dict):
        return tuple(sorted((key, _scope_memo_key(item)) for key, item in value.items()))
    return value


def scoped_curriculum_read(fn):
    """Memoise a read-only helper for the current curriculum_read_scope().

    Outside a scope the call passes straight through, so nothing changes for
    write paths or for callers that have not opted in. An argument that cannot
    be reduced to a hashable key also passes straight through rather than
    failing the request.

    Arguments are bound to the signature before keying, so a caller that spells
    out a default (``ensure_tables=True``) shares the memo with one that leaves
    it off. Without that, two reads of curriculum.modules that differ only in
    how they were written cost two round trips.
    """
    signature = inspect.signature(fn)

    def memo_key(*args, **kwargs):
        bound = signature.bind(*args, **kwargs)
        bound.apply_defaults()
        key = (
            fn.__qualname__,
            _scope_memo_key(tuple(bound.arguments.items())),
        )
        hash(key)
        return key

    @functools.wraps(fn)
    def wrapped(*args, **kwargs):
        memo = getattr(_CURRICULUM_READ_SCOPE, 'memo', None)
        if memo is None:
            return fn(*args, **kwargs)
        try:
            key = memo_key(*args, **kwargs)
        except (TypeError, ValueError):
            return fn(*args, **kwargs)
        if key not in memo:
            memo[key] = fn(*args, **kwargs)
        return memo[key]
    # The key a call would be memoised under, for prefetch_authoring_reads().
    wrapped.memo_key = memo_key
    return wrapped


def ensure_curriculum_epoch_table():
    """Provision the one-row counter table, once per process.

    Created here rather than in a migration for the same reason the other
    ``ensure_*`` helpers do it: this app owns externally managed tables in the
    ``curriculum`` schema and provisions them on first use. Returns False when
    the table cannot be reached at all, which is the signal to fall back to the
    process-local counter rather than fail a read.
    """
    from config.management_safety import reconciliation_command
    if reconciliation_command():
        return False
    global _CURRICULUM_EPOCH_TABLE_READY
    if _CURRICULUM_EPOCH_TABLE_READY:
        return True
    try:
        # Under a savepoint: this runs on a read path that a write request may
        # already have inside an atomic block, and in PostgreSQL a failed
        # statement poisons the whole transaction unless it can be rolled back
        # to one. The same guard is on every other statement below.
        with transaction.atomic(), connection.cursor() as cursor:
            if connection.vendor == 'postgresql':
                cursor.execute('create schema if not exists %s' % quote_ident(CURRICULUM_SCHEMA))
            cursor.execute(
                'create table if not exists %s ('
                ' id integer primary key,'
                ' epoch bigint not null default 0'
                ')' % table_name(CURRICULUM_EPOCH_TABLE)
            )
            cursor.execute(
                'insert into %s (id, epoch) values (1, 0) on conflict (id) do nothing'
                % table_name(CURRICULUM_EPOCH_TABLE)
            )
    except Exception:
        logger.warning('Unable to provision the shared curriculum epoch table.', exc_info=True)
        return False
    _CURRICULUM_EPOCH_TABLE_READY = True
    return True


def local_shared_curriculum_epoch():
    """The pre-database behaviour: the counter in Django's own cache.

    Correct when a Redis ``CACHE_URL`` is configured and harmless when it is
    not, so it stays as the fallback for a database that cannot answer.
    """
    try:
        cache.add(_CURRICULUM_SHARED_EPOCH_KEY, 0, timeout=None)
        return int(cache.get(_CURRICULUM_SHARED_EPOCH_KEY) or 0)
    except Exception:
        # A cache backend must never turn a cacheable read into an outage.
        logger.warning('Unable to read shared curriculum cache epoch.', exc_info=True)
        return 0


def remember_shared_curriculum_epoch(value):
    with _SHARED_EPOCH_LOCK:
        _SHARED_EPOCH_STATE['value'] = int(value)
        _SHARED_EPOCH_STATE['checked_at'] = time.monotonic()


def note_read_shared_curriculum_epoch(value):
    """A reading of the epoch row taken by another query (cache_scope's poll).

    Taken as this worker's poll when it is not older than what is held. The
    scope poll reads the epoch in the same statement, so this spares the
    separate read -- and keeps the two polls from disagreeing: a scope
    generation newer than the global one let a build pair post-write scope
    keys with rows the rows cache still held from before the write.
    """
    with _SHARED_EPOCH_LOCK:
        current = _SHARED_EPOCH_STATE['value']
        if current is None or int(value) >= current:
            _SHARED_EPOCH_STATE['value'] = int(value)
            _SHARED_EPOCH_STATE['checked_at'] = time.monotonic()


def refresh_curriculum_generations():
    """Make this worker's next generation lookup read the database.

    For a read straight after this client's own save, which may have been
    taken by another worker less than a poll interval ago. Costs the one
    epoch read; cached entries of the current generation still serve.
    """
    with _SHARED_EPOCH_LOCK:
        _SHARED_EPOCH_STATE['checked_at'] = 0.0
    from .cache_scope import forget_epochs
    forget_epochs()


def read_shared_curriculum_epoch_row():
    rows = fetch_all(
        'select %s from %s where %s = 1'
        % (quote_ident('epoch'), table_name(CURRICULUM_EPOCH_TABLE), quote_ident('id'))
    )
    return int((rows[0] if rows else {}).get('epoch') or 0)


def shared_curriculum_epoch():
    """The generation every worker's cache entries are keyed on.

    Read from the database at most once per ``SHARED_EPOCH_POLL_SECONDS``; in
    between, this process answers from what it last saw. A bump made *here*
    writes straight through to that memory, so the change-log middleware still
    sees the epoch move across its own request.
    """
    from config.management_safety import reconciliation_command
    if reconciliation_command():
        return 0
    now = time.monotonic()
    with _SHARED_EPOCH_LOCK:
        value = _SHARED_EPOCH_STATE['value']
        checked_at = _SHARED_EPOCH_STATE['checked_at']
    if value is not None and now - checked_at < SHARED_EPOCH_POLL_SECONDS:
        return value
    # Concurrent page requests share one refresh. The short state lock stays
    # free while SQL runs, so writes can still publish their new generation.
    with _SHARED_EPOCH_REFRESH_LOCK:
        with _SHARED_EPOCH_LOCK:
            value = _SHARED_EPOCH_STATE['value']
            checked_at = _SHARED_EPOCH_STATE['checked_at']
        if value is not None and time.monotonic() - checked_at < SHARED_EPOCH_POLL_SECONDS:
            return value
        if not ensure_curriculum_epoch_table():
            return local_shared_curriculum_epoch()
        try:
            # A standalone SELECT needs no BEGIN/COMMIT round trips. Inside a
            # caller's transaction retain the savepoint: a failed SELECT must
            # not poison that caller's transaction.
            needs_savepoint = connection.in_atomic_block or not connection.get_autocommit()
            guard = transaction.atomic() if needs_savepoint else contextlib.nullcontext()
            with guard:
                epoch = read_shared_curriculum_epoch_row()
        except Exception:
            logger.warning('Unable to read the shared curriculum epoch.', exc_info=True)
            with _SHARED_EPOCH_LOCK:
                latest = _SHARED_EPOCH_STATE['value']
            return latest if latest is not None else local_shared_curriculum_epoch()
        with _SHARED_EPOCH_LOCK:
            # A local write may have published a newer epoch during the read.
            if _SHARED_EPOCH_STATE['checked_at'] != checked_at:
                return _SHARED_EPOCH_STATE['value']
            _SHARED_EPOCH_STATE['value'] = epoch
            _SHARED_EPOCH_STATE['checked_at'] = time.monotonic()
        return epoch


def write_shared_curriculum_epoch_bump(scopes=None):
    """Move the counter by one and record where it landed.

    ``scopes`` is the set of programmes the write was attributed to. Without
    one the unscoped counter moves, which retires every programme's payloads
    exactly as the global epoch always has.
    """
    from .cache_scope import bump_scopes, remember_scope_epochs
    if not ensure_curriculum_epoch_table():
        # No database counter, so nothing retires this process's scoped
        # entries either; drop them here, as before scoping.
        drop_scoped_curriculum_entries()
        try:
            cache.add(_CURRICULUM_SHARED_EPOCH_KEY, 0, timeout=None)
            cache.incr(_CURRICULUM_SHARED_EPOCH_KEY)
        except Exception:
            logger.warning('Unable to invalidate shared curriculum cache.', exc_info=True)
        return
    scope_rows = None
    try:
        with transaction.atomic():
            if connection.vendor == 'postgresql':
                rows = fetch_all(
                    'update %s set %s = %s + 1 where %s = 1 returning %s'
                    % (
                        table_name(CURRICULUM_EPOCH_TABLE),
                        quote_ident('epoch'),
                        quote_ident('epoch'),
                        quote_ident('id'),
                        quote_ident('epoch'),
                    )
                )
                epoch = int((rows[0] if rows else {}).get('epoch') or 0)
                # Same transaction as the global bump, so a reader's snapshot
                # sees both moves or neither. See cache_scope for why.
                scope_rows = bump_scopes(scopes)
            else:
                with connection.cursor() as cursor:
                    cursor.execute(
                        'update %s set %s = %s + 1 where %s = 1'
                        % (
                            table_name(CURRICULUM_EPOCH_TABLE),
                            quote_ident('epoch'),
                            quote_ident('epoch'),
                            quote_ident('id'),
                        )
                    )
                epoch = read_shared_curriculum_epoch_row()
    except Exception:
        # Nothing committed: no worker will be told about this write. Other
        # workers serve their copies until the TTL, as they always have when
        # this counter could not move; this one, at least, must not keep
        # serving the programme pages it just changed.
        logger.error(
            'Unable to bump the shared curriculum epoch; other workers keep '
            'their cached curriculum payloads until they expire.',
            exc_info=True,
        )
        drop_scoped_curriculum_entries()
        return
    remember_shared_curriculum_epoch(epoch)
    if connection.vendor == 'postgresql':
        remember_scope_epochs(scope_rows, epoch)


def drop_scoped_curriculum_entries():
    """Forget this process's programme-scoped payloads and in-flight builds.

    invalidate_curriculum_cache() keeps scoped entries because the database
    bump is what retires them. When that bump cannot be made, this restores
    the pre-scoping behaviour for the writing worker: everything it cached is
    dropped, and a build already running cannot publish (the local epoch moves).
    """
    global _CURRICULUM_CACHE_EPOCH
    from .cache_scope import forget_epochs
    with _CURRICULUM_CACHE_LOCK:
        for key in [key for key, entry in _CURRICULUM_CACHE.items() if entry.get('scoped')]:
            _CURRICULUM_CACHE.pop(key, None)
        _CURRICULUM_CACHE_EPOCH += 1
    forget_epochs()


def bump_shared_curriculum_epoch():
    """Retire every worker's cached payload, once per request that writes.

    Inside a request the bump is owed rather than made: the change-log
    middleware flushes it after the view, so one save costs one UPDATE however
    many rows it wrote, and the new generation becomes visible to other workers
    only once the data it describes has committed. Outside a request (a
    management command, the warm loop) there is nobody to flush it, so it is
    made straight away.
    """
    if getattr(_CURRICULUM_EPOCH_BUMP, 'scoped', False):
        _CURRICULUM_EPOCH_BUMP.pending = True
        return
    write_shared_curriculum_epoch_bump()


def begin_curriculum_write_scope():
    _CURRICULUM_EPOCH_BUMP.scoped = True
    _CURRICULUM_EPOCH_BUMP.pending = False
    _CURRICULUM_EPOCH_BUMP.read_model_queued = False
    from .module_live import begin_request
    begin_request()


def end_curriculum_write_scope(scopes=None):
    """Make the request's one bump, if anything in it invalidated."""
    pending = getattr(_CURRICULUM_EPOCH_BUMP, 'pending', False)
    _CURRICULUM_EPOCH_BUMP.scoped = False
    _CURRICULUM_EPOCH_BUMP.pending = False
    _CURRICULUM_EPOCH_BUMP.read_model_queued = False
    try:
        if pending:
            write_shared_curriculum_epoch_bump(scopes)
    finally:
        # The per-module counters the Module Builder watches. Moved after the
        # global bump and in their own statement, so a reader that sees a
        # module counter move also finds the data it describes committed.
        from .module_live import end_request
        end_request()


def curriculum_write_pending():
    """Whether this request has invalidated and still owes its bump."""
    return bool(getattr(_CURRICULUM_EPOCH_BUMP, 'pending', False))


def programme_cache_generation(programme_id):
    from .cache_scope import programme_generation
    return programme_generation(programme_id)


CURRICULUM_CHANGE_LOG_KEY = 'curriculum:changes'
# Enough to cover the epochs a polling client can fall behind by between two
# reads. A save is a handful of bumps and a client asks every 25 seconds, so 50
# spans a burst of writing comfortably; past that the client is told nothing
# useful and falls back to dropping everything, which is where it started.
CURRICULUM_CHANGE_LOG_SIZE = 50


def record_curriculum_change(path, low, high):
    """Note that the epochs in ``(low, high]`` were moved by a write to ``path``.

    The counter on its own says only that something changed, which leaves every
    open tab in the estate to throw away its whole cache and read the ~13s
    overview back. This log is what turns that into "re-read the programmes".

    Deliberately best-effort. The read-modify-write below is not atomic, so two
    workers finishing at once can lose an entry -- and that is safe, because a
    client only trusts the log when it covers every epoch it missed and drops
    back to the blunt refresh when it does not. A lost entry costs one wasted
    reload; a lost entry mistaken for "nothing relevant changed" would cost a
    stale screen, which is why coverage is checked rather than assumed.
    """
    if high <= low:
        return
    try:
        entries = list(cache.get(CURRICULUM_CHANGE_LOG_KEY) or [])
        entries.append({'path': path, 'lo': int(low), 'hi': int(high)})
        cache.set(
            CURRICULUM_CHANGE_LOG_KEY,
            entries[-CURRICULUM_CHANGE_LOG_SIZE:],
            timeout=None,
        )
    except Exception:
        logger.warning('Unable to record curriculum change for %s.', path, exc_info=True)


def recent_curriculum_changes():
    try:
        return list(cache.get(CURRICULUM_CHANGE_LOG_KEY) or [])
    except Exception:
        logger.warning('Unable to read the curriculum change log.', exc_info=True)
        return []


def shared_curriculum_cache_key(key, epoch):
    digest = hashlib.sha256(str(key).encode()).hexdigest()
    return f'curriculum:v{epoch}:{digest}'


def curriculum_build_lock(key):
    """The lock that serialises rebuilds of one cache key.

    Kept in its own map rather than reusing ``_CURRICULUM_CACHE_LOCK`` so a build
    holds only its own key: reads of other keys, and cache hits on this one, stay
    lock-free. The map is bounded by the number of payload keys (visibility x
    compact), so nothing is ever evicted from it.
    """
    with _CURRICULUM_CACHE_LOCK:
        lock = _CURRICULUM_BUILD_LOCKS.get(key)
        if lock is None:
            lock = threading.Lock()
            _CURRICULUM_BUILD_LOCKS[key] = lock
        return lock


def cached_curriculum_value(key, factory, force=False, ttl=None, shared=True, scope=None, fingerprint=None):
    """The cached payload for ``key``, rebuilding it when it is not there.

    ``force`` skips both cache layers and rebuilds from the database, then stores
    the result the same way a normal miss does. It is for a caller that has just
    written and is asking for the state it wrote: the invalidation on the write
    path only reaches the process that handled it, and the shared epoch it bumps
    lives in Django's cache -- which is per-process LocMemCache unless a Redis
    ``CACHE_URL`` is configured. Under more than one worker that left every other
    worker serving its own pre-write payload for the rest of the TTL, which is a
    new group or programme that does not appear until the page is reloaded enough
    times to land on the worker that took the write.

    ``shared=False`` keeps a value in this process only, for one that is large
    and cheap to reassemble but expensive to fetch -- the raw curriculum rows.
    Round-tripping those through Redis costs more in pickling than the read it
    saves, and every worker warms its own copy in a second anyway. The shared
    epoch is still honoured, so a write elsewhere still invalidates it.

    ``scope`` is a programme id for a payload about that programme alone. Its
    generation is then the programme's own counter plus the unscoped one (see
    cache_scope), so a save to another programme leaves it cached. Without the
    scope table, or for an identifier that is not exactly a programme id, the
    global epoch applies as before.

    ``fingerprint`` is for a payload whose short ``ttl`` stands in for data no
    epoch covers (learner counts, say). It is a callable returning a value that
    changes whenever that data does; it is called in the caller's read scope
    just before the factory, so the stored entry is exactly the data its
    fingerprint describes. An entry past its ``ttl`` whose generation still
    matches is then checked rather than rebuilt: the fingerprint is taken again
    and, if equal, the entry is served for another ``ttl``. A rebuild costs the
    whole payload; the check costs only what the fingerprint reads. Entries
    taken from the shared cache carry no fingerprint and expire as before.
    """
    ttl = CURRICULUM_CACHE_TTL_SECONDS if ttl is None else ttl
    # When this call began. A force caller may take a value whose build started
    # later than this: every read that build made came after anything the
    # caller had committed before asking (see the build-lock re-check below).
    requested_at = time.monotonic()
    # Not for a caller that has written in this request: its writes may still
    # be uncommitted, invisible to a build on another thread.
    shares_forced_builds = (
        not getattr(_CURRICULUM_EPOCH_BUMP, 'pending', False)
        and not connection.in_atomic_block
    )
    scoped = scope is not None and programme_cache_generation(scope) is not None
    if scoped and getattr(_CURRICULUM_EPOCH_BUMP, 'pending', False):
        # This request has written and its bump is still owed: read its own
        # writes rather than a scoped entry that bump has yet to retire.
        force = True

    def generation():
        if scoped:
            value = programme_cache_generation(scope)
            if value is not None:
                return value
        return shared_curriculum_epoch()

    now = datetime.now().timestamp()
    shared_epoch = generation()
    with _CURRICULUM_CACHE_LOCK:
        entry = _CURRICULUM_CACHE.get(key)
        if not force and entry and entry['expires_at'] > now and entry.get('shared_epoch') == shared_epoch:
            return entry['value']
    if (
        not force and fingerprint is not None and entry
        and entry.get('shared_epoch') == shared_epoch and 'fingerprint' in entry
    ):
        # Past its ttl but of the current generation: ask whether the data the
        # ttl stands in for has moved before paying for a rebuild.
        current = fingerprint()
        if current == entry['fingerprint']:
            with _CURRICULUM_CACHE_LOCK:
                if _CURRICULUM_CACHE.get(key) is entry:
                    entry['expires_at'] = datetime.now().timestamp() + ttl
            return entry['value']

    shared_key = shared_curriculum_cache_key(key, shared_epoch)
    try:
        shared_value = None if (force or not shared) else cache.get(shared_key)
    except Exception:
        logger.warning('Unable to read shared curriculum payload cache.', exc_info=True)
        shared_value = None
    if shared_value is not None:
        with _CURRICULUM_CACHE_LOCK:
            _CURRICULUM_CACHE[key] = {
                'expires_at': now + ttl,
                'shared_epoch': shared_epoch,
                'value': shared_value,
                'scoped': scoped,
            }
        return shared_value

    # One build per key at a time. Several endpoints read the same payload —
    # programmes/ and ksb-sets/ both key overview:<visibility>:compact — and a page
    # that mounts them together used to hit a cold cache in parallel, so each
    # request ran the whole multi-table rebuild while the others waited on the same
    # Neon connections. The lock is per key, not the cache lock, so a build still
    # never blocks a cached read or a different key.
    with curriculum_build_lock(key):
        now = datetime.now().timestamp()
        shared_epoch = generation()
        # Whoever held this lock has just published its result, so the requests
        # queued behind it cost a cache read rather than another rebuild. A force
        # caller has written and is asking for its own state back, so it skips the
        # re-check: the value waiting here may predate that write.
        with _CURRICULUM_CACHE_LOCK:
            entry = _CURRICULUM_CACHE.get(key)
            if entry and entry['expires_at'] > now and entry.get('shared_epoch') == shared_epoch and (
                not force
                # Several forced reads queued on one key -- a save's reload
                # and a Refresh, two tabs -- take the first build that began
                # after they asked instead of each paying for its own.
                or (shares_forced_builds and entry.get('build_started', float('-inf')) >= requested_at)
            ):
                return entry['value']

        # The lock above covers this process only. When the shared cache is
        # really shared (Redis), another worker may already be running this
        # exact build; wait for its result rather than run a second copy
        # against the database. See shared_build for every way this falls back
        # to building here. A force caller has just written and wants its own
        # state back, so it never waits on a build that may predate the write.
        shared_key = shared_curriculum_cache_key(key, shared_epoch)
        build_token = None
        if shared and not force:
            for _attempt in range(2):
                acquired, build_token = shared_build.try_acquire(cache, shared_key)
                if acquired:
                    break
                waited, holder_gone = shared_build.wait_for_value(cache, shared_key)
                if waited is not None:
                    with _CURRICULUM_CACHE_LOCK:
                        _CURRICULUM_CACHE[key] = {
                            'expires_at': datetime.now().timestamp() + ttl,
                            'shared_epoch': shared_epoch,
                            'value': waited,
                            'scoped': scoped,
                        }
                    return waited
                if not holder_gone:
                    # Waited the full window: build here, without the lock.
                    break

        try:
            with _CURRICULUM_CACHE_LOCK:
                epoch = _CURRICULUM_CACHE_EPOCH
            build_started = time.monotonic()

            # Taken before the factory and in the same read scope, so the
            # factory's own reads of that data are the ones fingerprinted.
            built_fingerprint = fingerprint() if fingerprint is not None else None
            # An exception propagates without storing anything, so failures are never
            # cached.
            value = factory()

            # Network I/O must not hold the global cache lock: a slow epoch
            # read or shared-cache write would stall hits for unrelated keys.
            current_shared_epoch = generation()
            with _CURRICULUM_CACHE_LOCK:
                # Only publish if no write invalidated the cache while we were building.
                publish = epoch == _CURRICULUM_CACHE_EPOCH and shared_epoch == current_shared_epoch
                if publish:
                    _CURRICULUM_CACHE[key] = {
                        'expires_at': datetime.now().timestamp() + ttl,
                        'shared_epoch': shared_epoch,
                        'value': value,
                        'scoped': scoped,
                        'build_started': build_started,
                        **({'fingerprint': built_fingerprint} if fingerprint is not None else {}),
                    }
            if publish and shared:
                # This key includes the generation: a concurrent invalidation
                # retires it even if this network write finishes afterwards.
                try:
                    cache.set(shared_key, value, timeout=ttl)
                except Exception:
                    logger.warning('Unable to populate shared curriculum payload cache.', exc_info=True)
        finally:
            # After publishing, so a waiter that sees the lock gone finds the
            # value already there.
            shared_build.release(cache, shared_key, build_token)
    return value


def request_bypasses_curriculum_cache(request):
    cache_control = clean_str(request.headers.get('Cache-Control')).lower()
    pragma = clean_str(request.headers.get('Pragma')).lower()
    return (
        'no-cache' in cache_control
        or 'no-store' in cache_control
        or 'no-cache' in pragma
        or truthy(request.GET.get('skipCache'))
        or clean_str(request.GET.get('_ts'))
    )


# ---------------------------------------------------------------------------
# Cache warming
#
# Every payload above used to be built on the request path: the first person to
# open Curriculum Studio after a restart or a save paid the whole multi-table
# rebuild, holding the per-key build lock while the rest of the page queued
# behind it. A page load asks for these keys at two visibilities, so that cost
# was paid several times over in one load.
#
# Warming moves it off the request path. A background thread builds the same
# keys the same way, so a request only ever reads. It is best-effort by
# construction: a failed warm logs and leaves the cache empty, and the request
# path rebuilds exactly as it does today.
# ---------------------------------------------------------------------------

CURRICULUM_WARM_ENABLED = os.environ.get('CURRICULUM_WARM', 'true').lower() not in {'false', '0', 'no'}
# The delay coalesces a burst. A tree save calls invalidate_curriculum_cache()
# once per written entity, and warming after each one would rebuild dozens of
# times over a payload that is still moving. Waiting also keeps the warm behind
# the commit of the write that triggered it -- and if it does land early, the
# epoch check in cached_curriculum_value() discards the result rather than
# publishing pre-write rows.
CURRICULUM_WARM_DELAY_SECONDS = float(os.environ.get('CURRICULUM_WARM_DELAY', '2'))
_CURRICULUM_WARM_LOCK = threading.Lock()
_CURRICULUM_WARM_RUNNING = False
_CURRICULUM_WARM_REQUESTED = False


def warm_curriculum_caches():
    """Build the payload keys a Curriculum page load reads, for both visibilities.

    Deliberately the compact keys only. They are what the page actually asks for
    -- overview, modules, programmes -- and they share one rows read, so warming
    both visibilities costs a single trip to the database.

    The whole warm runs inside one read scope. On the request path each build
    opens its own, which is right there -- a request must not read back rows
    memoised before someone else's write. Here there is no such caller: this is
    one batch, assembling one consistent snapshot, and the two visibilities plus
    the enrichments otherwise re-read the same authoring tables several times
    over. curriculum.components alone is ~18k rows on a remote database and
    dominates the build, so reading it once is most of what warming saves.
    """
    from config.management_safety import reconciliation_command
    if reconciliation_command():
        return
    with curriculum_read_scope():
        for visibility in ('operational', 'all'):
            payload = cached_curriculum_value(
                f'overview:{visibility}:compact',
                lambda visibility=visibility: build_curriculum_payload(visibility, compact=True),
            )
            enriched_modules = cached_curriculum_value(
                f'modules:{visibility}:enriched',
                lambda visibility=visibility: enrich_modules_with_authoring(
                    payload['modules'], include_programme_deleted=visibility == 'all',
                ),
            )
            cached_curriculum_value(
                f'programmes:{visibility}:with-module-counts',
                lambda visibility=visibility: enrich_programmes_with_module_counts(
                    payload['programmes'], enriched_modules,
                    modules_enriched=True, include_archived=visibility == 'all',
                ),
            )


def _curriculum_warm_loop():
    from config.management_safety import reconciliation_command
    if reconciliation_command():
        return
    global _CURRICULUM_WARM_RUNNING, _CURRICULUM_WARM_REQUESTED
    try:
        while True:
            time.sleep(CURRICULUM_WARM_DELAY_SECONDS)
            with _CURRICULUM_WARM_LOCK:
                _CURRICULUM_WARM_REQUESTED = False
            started = datetime.now().timestamp()
            try:
                warm_curriculum_caches()
                logger.info(
                    'Curriculum cache warm finished in %.1fs.',
                    datetime.now().timestamp() - started,
                )
            except Exception:
                # A warm that fails must never take the process with it; the
                # request path still rebuilds on demand.
                logger.warning('Curriculum cache warm failed.', exc_info=True)
            try:
                # Apart from the warm above: that one is a single untargeted
                # read scope, and a programme build needs its own targeted one.
                warm_programme_detail_sections()
            except Exception:
                logger.warning('Programme section warm failed.', exc_info=True)
            finally:
                # This thread opened its own connection. Neon counts it, and a
                # warm runs rarely enough that holding one between runs is pure
                # cost.
                connections.close_all()
            with _CURRICULUM_WARM_LOCK:
                if not _CURRICULUM_WARM_REQUESTED:
                    _CURRICULUM_WARM_RUNNING = False
                    return
    except BaseException:
        with _CURRICULUM_WARM_LOCK:
            _CURRICULUM_WARM_RUNNING = False
        raise


def schedule_curriculum_warm():
    """Ask for a warm, coalescing with one already pending.

    Returns whether a warm is now scheduled, so callers and tests can tell the
    disabled case from the queued one.
    """
    from config.management_safety import reconciliation_command
    if reconciliation_command() or not CURRICULUM_WARM_ENABLED:
        return False
    global _CURRICULUM_WARM_RUNNING, _CURRICULUM_WARM_REQUESTED
    with _CURRICULUM_WARM_LOCK:
        _CURRICULUM_WARM_REQUESTED = True
        if _CURRICULUM_WARM_RUNNING:
            # The running loop re-reads the flag after it publishes and goes
            # round again, so a write during a warm is never lost.
            return True
        _CURRICULUM_WARM_RUNNING = True
    try:
        threading.Thread(
            target=_curriculum_warm_loop,
            name='curriculum-cache-warm',
            daemon=True,
        ).start()
    except Exception:
        with _CURRICULUM_WARM_LOCK:
            _CURRICULUM_WARM_RUNNING = False
        logger.warning('Unable to start curriculum cache warm thread.', exc_info=True)
        return False
    return True


def reference_json_response(request, payload):
    """JSON response with a validating ETag, for reference data only.

    Suitable for endpoints whose body depends on nothing but the reference tables:
    no per-user, per-role or per-programme variation. The ETag is derived from the
    serialised body, so it changes exactly when the content does — there is no TTL
    to tune and no way to serve content that is newer than its validator.

    ``Cache-Control: private, no-cache`` makes the browser revalidate every time
    and keeps the payload out of shared caches; a match then costs a 304 with no
    body instead of the full response. Deliberately not ``public``: these endpoints
    sit behind authentication, so a shared cache must not retain them.
    """
    body = json.dumps(payload, cls=DjangoJSONEncoder)
    etag = f'"{hashlib.sha256(body.encode()).hexdigest()[:32]}"'
    if_none_match = clean_str(request.headers.get('If-None-Match'))
    if if_none_match and etag in [value.strip() for value in if_none_match.split(',')]:
        response = HttpResponseNotModified()
    else:
        response = HttpResponse(body, content_type='application/json')
    response['ETag'] = etag
    response['Cache-Control'] = 'private, no-cache'
    return response


def rows_as_dicts(cursor):
    columns = [col[0] for col in cursor.description]
    return [dict(zip(columns, row)) for row in cursor.fetchall()]


def fetch_all(query, params=None):
    with connection.cursor() as cursor:
        cursor.execute(query, params or [])
        return rows_as_dicts(cursor)


def execute_returning(query, params=None):
    return fetch_all(query, params)


def quote_ident(value):
    return '"' + str(value).replace('"', '""') + '"'


def table_name(table):
    # PostgreSQL uses the dedicated ``curriculum`` schema; sqlite (tests) keeps
    # the tables in the default schema, so drop the schema qualifier there to
    # stay consistent with authoring_table_name().
    if connection.vendor != 'postgresql':
        return quote_ident(table)
    return f'{quote_ident(CURRICULUM_SCHEMA)}.{quote_ident(table)}'


def column_names(table):
    cache_key = f'{CURRICULUM_SCHEMA}.{table}'
    if cache_key in _TABLE_COLUMNS_CACHE:
        return _TABLE_COLUMNS_CACHE[cache_key]

    if connection.vendor == 'postgresql':
        rows = fetch_all(
            '''
            select column_name
            from information_schema.columns
            where table_schema = %s and table_name = %s
            ''',
            [CURRICULUM_SCHEMA, table],
        )
        names = {row['column_name'] for row in rows}
    else:
        with connection.cursor() as cursor:
            cursor.execute(f'pragma table_info({quote_ident(table)})')
            names = {row[1] for row in cursor.fetchall()}
    _TABLE_COLUMNS_CACHE[cache_key] = names
    return names


def has_column(table, column):
    return column in column_names(table)


def table_exists(table):
    # Cached because this runs on hot read paths and the schema does not change
    # under us; invalidate_curriculum_cache() clears it, as does a process restart.
    # A failed probe is deliberately not cached, so a transient error does not
    # pin a table to "missing" for the life of the process.
    cache_key = f'{CURRICULUM_SCHEMA}.{table}'
    if cache_key in _TABLE_EXISTS_CACHE:
        return _TABLE_EXISTS_CACHE[cache_key]
    try:
        # schema_gate owns the probe, so the gate and these read paths share one
        # answer instead of each asking information_schema the same question.
        # The first call there lists the schema once; after it, a table that
        # exists is answered without touching the database at all.
        exists = schema_gate.table_exists(table)
        _TABLE_EXISTS_CACHE[cache_key] = exists
        return exists
    except (Exception, AssertionError):
        logger.debug('Could not check whether table %s exists.', table, exc_info=True)
        return False


def ensure_columns(table, specs):
    missing = {column: definition for column, definition in specs.items() if not has_column(table, column)}
    if not missing:
        return
    with connection.cursor() as cursor:
        for column, definition in missing.items():
            if connection.vendor == 'postgresql':
                add_column = f'add column if not exists {quote_ident(column)} {definition}'
            else:
                # SQLite supports ADD COLUMN but not ADD COLUMN IF NOT EXISTS.
                # ``missing`` was already calculated through PRAGMA table_info.
                add_column = f'add column {quote_ident(column)} {definition}'
            cursor.execute(
                f'alter table {table_name(table)} {add_column}'
            )
    _TABLE_COLUMNS_CACHE.pop(table, None)
    _TABLE_COLUMNS_CACHE.pop(f'{CURRICULUM_SCHEMA}.{table}', None)


def ensure_ksb_profile_programme_id_column():
    global _KSB_PROFILE_PROGRAMME_ID_READY
    _KSB_PROFILE_PROGRAMME_ID_READY = True


def ensure_ksb_profile_identity_columns():
    ensure_ksb_profile_programme_id_column()
    try:
        ensure_columns('ksb_profiles', {
            'ksb_profile_id': 'varchar(128)',
            'programme_ids': 'jsonb',
            # A reusable profile can carry its own KSB definitions while still
            # inheriting funding, duration and compliance metadata from the
            # Skills England standard it was derived from.
            'standard_source_id': 'varchar(128)',
        })
        if connection.vendor == 'postgresql':
            with connection.cursor() as cursor:
                cursor.execute(f'''
                    create unique index if not exists curriculum_ksb_profiles_profile_id_idx
                    on {table_name("ksb_profiles")} ({quote_ident("ksb_profile_id")})
                    where {quote_ident("ksb_profile_id")} is not null and {quote_ident("ksb_profile_id")} <> ''
                ''')
    except Exception as exc:
        logger.warning('Could not ensure KSB profile identity column: %s', exc)


def is_canonical_module_catalogue_id(value):
    return bool(CANONICAL_MODULE_ID_PATTERN.match(clean_str(value)))


def training_row_column_module_catalogue_id(row):
    return clean_str((row or {}).get(TRAINING_MODULE_CATALOGUE_COLUMN))


def training_row_legacy_module_catalogue_id(row):
    meta = (row or {}).get('_meta') or extract_notes_meta((row or {}).get('notes'))
    return clean_str(meta.get(TRAINING_MODULE_CATALOGUE_COLUMN))


def training_row_invalid_explicit_module_catalogue_id(row):
    value = training_row_column_module_catalogue_id(row)
    return value if value and not is_canonical_module_catalogue_id(value) else ''


def training_row_stale_legacy_module_catalogue_id(row):
    column_value = training_row_column_module_catalogue_id(row)
    if column_value:
        return ''
    value = training_row_legacy_module_catalogue_id(row)
    return value if value and not is_canonical_module_catalogue_id(value) else ''


def training_row_module_catalogue_id(row):
    column_value = training_row_column_module_catalogue_id(row)
    if column_value:
        return column_value if is_canonical_module_catalogue_id(column_value) else ''
    legacy_value = training_row_legacy_module_catalogue_id(row)
    return legacy_value if is_canonical_module_catalogue_id(legacy_value) else ''


