def ensure_program_config_archive_columns():
    # standard/owner/created_by/is_active/structure_type were dropped from
    # curriculum.programmes. They are deliberately absent here: re-adding them
    # would resurrect the columns empty on the next process start.
    # is_archived is now the sole archive signal.
    #
    # Schema is migration-owned in production, so the ALTER TABLE path and the
    # is_archived NULL->false backfill that used to follow it are confined to
    # test/local provisioning. The backfill matched 0 production rows when it
    # was removed (verified 2026-08-16); read paths already coalesce a NULL
    # is_archived to false.
    if not schema_gate.runtime_bootstrap_allowed():
        return
    try:
        ensure_columns('programmes', {
            'level': 'varchar(64)',
            'color': 'varchar(32)',
            'description': 'text',
            'is_archived': 'boolean',
            'status': 'varchar(32)',
            'ksb_profile_source_id': 'varchar(128)',
            'required_otjh': 'numeric(8, 2)',
            'display_order': 'integer',
        })
    except Exception as exc:
        logger.warning('Could not inspect programme config archive columns: %s', exc)
        return
    if has_column('programmes', 'is_archived'):
        try:
            update_rows('programmes', 'is_archived is null', [], {'is_archived': False})
        except Exception:
            pass
    if has_column('programmes', 'status'):
        try:
            update_rows('programmes', "coalesce(btrim(status), '') = ''", [], {'status': 'active'})
        except Exception:
            pass


def filtered_payload(table, payload, allow_null_columns=None):
    allow_null_columns = set(allow_null_columns or [])
    columns = column_names(table)
    return {
        key: value
        for key, value in payload.items()
        if key in columns and (value is not None or key in allow_null_columns)
    }


def json_body(request):
    try:
        return json.loads(request.body.decode('utf-8') or '{}')
    except (TypeError, ValueError, UnicodeDecodeError):
        return None


COMPONENT_UPLOAD_ROOT = 'curriculum_component_uploads'
COMPONENT_UPLOAD_MAX_BYTES = 300 * 1024 * 1024
COMPONENT_UPLOAD_EXTENSIONS = {
    'podcast': {'.mp3', '.m4a', '.mp4', '.wav', '.aac', '.ogg', '.oga', '.webm'},
    'powerpoint': {'.ppt', '.pptx', '.pps', '.ppsx', '.pdf'},
    'reading': {'.txt', '.doc', '.docx', '.pdf', '.rtf', '.odt'},
    # Topic instructions can contain written briefs, documents and videos.
    'assignment': {'.txt', '.doc', '.docx', '.pdf', '.rtf', '.odt', '.ppt', '.pptx', '.mp4', '.webm', '.mov', '.m4v'},
}


# The AI Material book a module carries. It is one file per module, uploaded
# from the builder, and it is a *book*: the formats a reader can actually open.
# EPUB is included because it is how most books arrive, even though the browser
# cannot render it inline -- the dialog offers a download for those and an
# in-page viewer only for what the uploads route can already display.
AI_MATERIAL_UPLOAD_EXTENSIONS = {'.pdf', '.epub', '.doc', '.docx', '.txt', '.rtf', '.odt'}
#: The component-id slot in the upload path. Not a component: the book belongs
#: to the module, so every module has exactly one of these folders.
AI_MATERIAL_UPLOAD_SLOT = 'ai-material'
#: The same slot idea for module artwork. One cover per module.
MODULE_COVER_UPLOAD_SLOT = 'cover'
#: The image types the builder's picker produces, and the extension each is
#: stored as. Anything else is left exactly as it arrived.
MODULE_COVER_EXTENSIONS = {
    'image/jpeg': '.jpg', 'image/jpg': '.jpg', 'image/png': '.png',
    'image/gif': '.gif', 'image/webp': '.webp', 'image/avif': '.avif',
    'image/svg+xml': '.svg', 'image/bmp': '.bmp',
}
MODULE_COVER_DATA_URI = re.compile(r'^data:(image/[a-zA-Z0-9.+-]+);base64,([A-Za-z0-9+/=\s]+)$')
#: Where the book's metadata lives on ``curriculum.module_details``.
AI_MATERIAL_COLUMN = 'ai_material'


def safe_upload_segment(value, fallback):
    text = get_valid_filename(clean_str(value)).strip('._-')
    return text[:96] or fallback


def stored_module_cover_image(module_catalogue_id, value):
    """A module cover as a URL, storing the bytes first when it arrives inline.

    The builder's picker reads the chosen file and sends it as a
    ``data:image/...;base64,...`` URL, and that string used to be written
    straight into ``curriculum.modules.cover_image_url`` -- up to 3 MB of base64
    in a column every module list selects. Five modules doing it was 1.52 MB of a
    1.79 MB ``/curriculum/modules/?compact=true`` response, 83% of it, and the
    column is also read whole by the payload build and by My Learning. The
    picture is the same size either way; what changes is that a list of 281
    modules stops carrying it.

    So the bytes go where every other authoring upload goes -- Azure when it is
    configured, local disk when it is not -- and the column keeps the same
    ``/curriculum_api/curriculum/uploads/...`` URL shape a component upload
    stores. One cover per module, so the path has a fixed slot and a new upload
    simply replaces the old one.

    Anything that is not an inline image is returned untouched: an https:// URL
    a curator pasted is already a URL, and '' still means "remove the cover".
    Storage failing returns the value unchanged rather than raising -- a saved
    module with an oversized cover is better than a module that would not save.
    """
    value = clean_str(value)
    match = MODULE_COVER_DATA_URI.match(value)
    if not match:
        return value
    content_type = match.group(1).lower()
    try:
        raw = base64.b64decode(re.sub(r'\s+', '', match.group(2)), validate=True)
    except Exception:
        logger.warning('Module %s sent a cover image that is not valid base64.', module_catalogue_id)
        return value
    if not raw:
        return ''
    module_segment = safe_upload_segment(module_catalogue_id, 'module')
    extension = MODULE_COVER_EXTENSIONS.get(content_type, '.img')
    timestamp = datetime.utcnow().strftime('%Y%m%d%H%M%S%f')
    relative_path = (
        f'{COMPONENT_UPLOAD_ROOT}/{module_segment}/{MODULE_COVER_UPLOAD_SLOT}/cover-{timestamp}{extension}'
    )
    try:
        saved_path = upload_storage.store(ContentFile(raw), relative_path, content_type)
    except Exception:
        logger.exception('Unable to store the cover image for module %s.', module_catalogue_id)
        return value
    public_path = saved_path.removeprefix(f'{COMPONENT_UPLOAD_ROOT}/')
    return f'/curriculum_api/curriculum/uploads/{public_path}'


def component_upload_metadata(
    module_catalogue_id, component_id, component_type, uploaded_file,
    allowed_extensions=None,
):
    """Store one authoring upload and describe where it landed.

    ``allowed_extensions`` overrides the per-component-type list for uploads that
    are not a week component at all -- the module's AI material book is stored
    through the same container, path shape and serving route, but its own file
    types have nothing to do with a component type.
    """
    module_catalogue_id = safe_upload_segment(module_catalogue_id, 'module')
    component_id = safe_upload_segment(component_id, 'component')
    component_type = frontend_component_type(component_type)
    original_name = get_valid_filename(uploaded_file.name or 'upload')
    suffix = Path(original_name).suffix.lower()
    allowed = set(allowed_extensions) if allowed_extensions else COMPONENT_UPLOAD_EXTENSIONS.get(component_type, set())
    if suffix not in allowed:
        return None, f'{component_type} uploads must use one of: {", ".join(sorted(allowed))}.'
    if uploaded_file.size > COMPONENT_UPLOAD_MAX_BYTES:
        return None, 'File is too large. Maximum upload size is 300 MB.'

    # Microseconds make the path unique even when the same component retries or
    # replaces a same-named resource within one second.
    timestamp = datetime.utcnow().strftime('%Y%m%d%H%M%S%f')
    stem = safe_upload_segment(Path(original_name).stem, 'resource')
    stored_name = f'{stem}-{timestamp}{suffix}'
    relative_path = f'{COMPONENT_UPLOAD_ROOT}/{module_catalogue_id}/{component_id}/{stored_name}'
    # Azure when it is configured, local disk when it is not — see upload_storage.
    saved_path = upload_storage.store(
        uploaded_file, relative_path, uploaded_file.content_type or '',
    )
    public_path = saved_path.removeprefix(f'{COMPONENT_UPLOAD_ROOT}/')
    return {
        'fileName': original_name,
        'storedPath': saved_path,
        'url': f'/curriculum_api/curriculum/uploads/{public_path}',
        'size': uploaded_file.size,
        'contentType': uploaded_file.content_type or '',
        'componentType': component_type,
    }, ''


def update_component_upload_settings(component_id, component_type, metadata):
    # The row is rewritten whole below, so it is read under a row lock in the
    # same transaction as the write: read first and written later, a structure
    # save landing in between had its component content written back over.
    with transaction.atomic():
        if connection.vendor == 'postgresql':
            with connection.cursor() as cursor:
                cursor.execute(
                    f'select 1 from {authoring_table_name(AUTHORING_COMPONENTS_TABLE)} where id = %s for update',
                    [component_id],
                )
                cursor.fetchall()
        return _update_component_upload_settings(component_id, component_type, metadata)


def _update_component_upload_settings(component_id, component_type, metadata):
    rows = authoring_fetch_all(AUTHORING_COMPONENTS_TABLE, 'id = %s', [component_id])
    if not rows:
        return False
    row = rows[0]
    settings_payload = normalise_component_settings_payload(component_type, parse_json_value(row.get('settings'), {}))
    updates = {
        'uploadedFileName': metadata['fileName'],
        'uploadedFileUrl': metadata['url'],
        'uploadedFileSize': metadata['size'],
        'uploadedFileContentType': metadata['contentType'],
        'uploadSource': 'Device upload',
    }
    if component_type == 'podcast':
        updates.update({'podcastSource': 'Device upload', 'podcastUrl': metadata['url']})
    if component_type == 'powerpoint':
        updates.update({'fileName': metadata['fileName'], 'presentationUrl': metadata['url']})
    if component_type == 'reading':
        updates.update({'readingSource': 'LMS resource', 'resourceUrl': metadata['url']})
    if component_type == 'assignment':
        updates.update({'assignmentFileName': metadata['fileName'], 'assignmentFileUrl': metadata['url']})
    authoring_upsert(AUTHORING_COMPONENTS_TABLE, ['id'], {
        **row,
        'settings': json_db_value({**settings_payload, **updates}),
    })
    invalidate_curriculum_cache()
    return True


def json_error(message, status=400, **extra):
    payload = {'error': message}
    payload.update(extra)
    return JsonResponse(payload, status=status)


