# The reflection question an author writes for a component has its own column on
# ``curriculum.components``. It was created as a quoted mixed-case identifier, so
# it has to be spelled exactly this way everywhere: Postgres folds an unquoted
# ``Reflection_Question`` to lower case and would then miss the column entirely.
REFLECTION_QUESTION_COLUMN = 'Reflection_Question'
# Where the same text lived before the column existed. Still written on save, so
# the learner-side readers that look it up in settings keep working unchanged.
LEGACY_REFLECTION_QUESTION_SETTING = 'reflectionPrompt'
# The week-template copy of the column. That table is created by this module, so
# it follows the snake_case convention the rest of the schema uses.
WEEK_TEMPLATE_REFLECTION_QUESTION_COLUMN = 'reflection_question'


def canonical_authoring_id(prefix, value=''):
    return unique_prefixed_id(prefix, value)


def unique_module_catalogue_id(value=''):
    requested = clean_str(value)
    try:
        existing = [row.get('module_catalogue_id') for row in authoring_fetch_all(AUTHORING_MODULES_TABLE)]
    except Exception:
        existing = []
    if re.match(r'^MOD-[A-Z0-9][A-Z0-9_-]*$', requested, re.I) and requested not in existing:
        return requested
    if requested in existing:
        return requested
    return unique_prefixed_id('MOD', '', existing)


def first_clean_payload_value(payload, *keys):
    for key in keys:
        value = clean_str(payload.get(key))
        if value:
            return value
    return ''


def identity_values_overlap(left_values, right_values):
    left = {normalise(value) for value in left_values if normalise(value)}
    right = {normalise(value) for value in right_values if normalise(value)}
    if left and right:
        return bool(left & right)
    return True


def identity_values_match_context(left_values, context_values):
    left = {normalise(value) for value in left_values if normalise(value)}
    context = {normalise(value) for value in context_values if normalise(value)}
    if context and not left:
        return False
    if left and context:
        return bool(left & context)
    return True


def identity_ids_conflict(left_id, context_ids):
    """True when both sides name a canonical id and none of them agree.

    ``identity_values_match_context`` pools ids and display names into one set,
    so a shared name (two cohorts each with a group called "G1-Wed") satisfies
    the match even when the ids point at different rows. Callers that hold a
    canonical id on both sides use this to reject that cross-row collision
    before it silently reuses another group's module.
    """
    # normalise(None) returns the string 'none', which is truthy, so None must be
    # discarded before normalising or a missing id becomes a bogus candidate that
    # every real id "conflicts" with.
    left = normalise(left_id) if left_id is not None else ''
    if not left:
        return False
    candidates = {
        normalise(value)
        for value in context_ids
        if value is not None and normalise(value)
    }
    if not candidates:
        return False
    return left not in candidates


def authoring_component_counts_by_catalogue():
    """How many live components each module has, counted in the database.

    This used to read every column of every component row - 39 MB and ~175 s
    against the remote database - and then throw all of it away except the
    module id. The predicate below is the SQL form of ``active_component_rows``:
    not soft-deleted, not detached into the library, and not a retired type.
    """
    counts = Counter()
    try:
        ensure_module_authoring_tables()
        clauses = [f"coalesce({quote_ident('module_catalogue_id')}, '') <> ''"]
        params = []
        deleted = deleted_sql_condition(AUTHORING_COMPONENTS_TABLE)
        if deleted != 'false':
            clauses.append(f'not ({deleted})')
        if has_column(AUTHORING_COMPONENTS_TABLE, 'library_state'):
            clauses.append(f"coalesce({quote_ident('library_state')}, '') <> %s")
            params.append(LIBRARY_STATE_DETACHED)
        retired = sorted(RETIRED_COMPONENT_TYPES)
        if retired:
            placeholders = ', '.join(['%s'] * len(retired))
            clauses.append(f'type not in ({placeholders})')
            params.extend(retired)
        rows = fetch_all(
            f'select {quote_ident("module_catalogue_id")} as catalogue_id, count(*) as total '
            f'from {authoring_table_name(AUTHORING_COMPONENTS_TABLE)} '
            f'where {" and ".join(clauses)} '
            f'group by {quote_ident("module_catalogue_id")}',
            params,
        )
        for row in rows:
            catalogue_id = clean_str(row.get('catalogue_id'))
            if catalogue_id:
                counts[catalogue_id] = parse_int(row.get('total'), 0)
    except Exception:
        logger.debug('Unable to count authoring components by module.', exc_info=True)
    return counts


def find_existing_authoring_catalogue_id_for_payload(payload):
    requested_catalogue_id = first_clean_payload_value(payload, 'catalogueId', 'moduleCatalogueId', 'module_catalogue_id')
    if requested_catalogue_id:
        resolved = resolve_authoring_catalogue_id(requested_catalogue_id)
        if resolved:
            return resolved

    try:
        ensure_module_authoring_tables()
        title = first_clean_payload_value(payload, 'title', 'name')
        if not title:
            return ''

        programme_values = [
            payload.get('programmeId'),
            payload.get('programme_id'),
            payload.get('programmeName'),
            payload.get('programme'),
        ]
        cohort_values = [
            payload.get('cohortId'),
            payload.get('cohort_id'),
            payload.get('cohortName'),
            payload.get('cohort'),
        ]
        group_values = [
            payload.get('groupId'),
            payload.get('group_id'),
            payload.get('groupName'),
            payload.get('group'),
        ]
        component_counts = authoring_component_counts_by_catalogue()
        rows = sorted(
            authoring_fetch_all(AUTHORING_MODULES_TABLE, order_sql='updated_at desc, module_catalogue_id'),
            key=lambda row: (component_counts.get(clean_str(row.get('module_catalogue_id')), 0), row.get('updated_at') or ''),
            reverse=True,
        )
        for row in rows:
            if normalise(row.get('title')) != normalise(title):
                continue
            # An archived module is not "the same module" a create is asking
            # for. Adopting it handed a fresh copy the archived row's id, the
            # next save cleared the archive on the module row alone, and the
            # weeks archived with it stayed stamped with that id -- so the
            # module then ran with two sets of weeks.
            if module_withdrawn_on_its_own(row):
                continue
            if not identity_values_match_context([row.get('programme_id'), row.get('programme_name')], programme_values):
                continue
            if not identity_values_match_context([row.get('cohort_id'), row.get('cohort_name')], cohort_values):
                continue
            if not identity_values_match_context([row.get('group_id'), row.get('group_name')], group_values):
                continue
            return clean_str(row.get('module_catalogue_id'))
    except Exception:
        logger.debug('Unable to find existing authoring module for payload.', exc_info=True)
    return ''


def authoring_table_name(table):
    if connection.vendor == 'postgresql':
        return table_name(table)
    return quote_ident(table)


def authoring_json_type():
    return 'jsonb' if connection.vendor == 'postgresql' else 'text'


AUTHORING_REQUIRED_TABLES = (
    AUTHORING_MODULES_TABLE,
    AUTHORING_WEEKS_TABLE,
    AUTHORING_COMPONENTS_TABLE,
    COHORT_AUTHORING_DETAILS_TABLE,
    GROUPS_TABLE,
)


def ensure_module_authoring_tables():
    """Verify the module-authoring tables exist.

    Schema is owned by migrations. In production this is a cached read-only
    probe that raises SchemaNotProvisioned if a table is missing; it never
    creates or alters anything. Test/local runs delegate to the provisioning
    path below, which still owns the DDL.
    """
    global _AUTHORING_TABLES_READY
    if _AUTHORING_TABLES_READY:
        return
    if not schema_gate.runtime_bootstrap_allowed():
        schema_gate.require_tables(*AUTHORING_REQUIRED_TABLES)
        _AUTHORING_TABLES_READY = True
        return
    provision_module_authoring_tables()


# Columns that let a week or component be detached from its parent and kept for
# reuse instead of destroyed. Mirrors migration 0053; kept in sync by hand
# because these tables are ``managed = False`` and this bootstrap is what the
# SQLite test runner provisions from.
LIBRARY_COLUMN_DDL = (
    ('library_state', "varchar(16) not null default ''"),
    ('detached_at', 'timestamp with time zone'),
    ('origin_module_catalogue_id', 'varchar(128)'),
    # text, not varchar(n): a component or week label is authored prose (a whole
    # KSB statement, routinely), and a copy that outgrows the column fails the
    # save outright. See 2026-09-22_widen_curriculum_titles.sql.
    ('origin_module_title', 'text'),
    ('origin_week_id', 'varchar(128)'),
    ('origin_week_label', 'text'),
    ('copied_from_id', 'varchar(128)'),
)


def provision_library_columns(cursor, table):
    """Add the library/detach columns to a weeks-or-components table.

    The column cache is dropped afterwards: every detach helper decides what to
    write through ``has_column``, so a cache entry captured before these columns
    landed would make the detach silently skip them.
    """
    if connection.vendor == 'postgresql':
        for column, column_type in LIBRARY_COLUMN_DDL:
            cursor.execute(
                f'alter table {authoring_table_name(table)} '
                f'add column if not exists {quote_ident(column)} {column_type}'
            )
    else:
        cursor.execute(f'pragma table_info({quote_ident(table)})')
        existing = {row[1] for row in cursor.fetchall()}
        for column, column_type in LIBRARY_COLUMN_DDL:
            if column in existing:
                continue
            cursor.execute(
                f'alter table {authoring_table_name(table)} '
                f'add column {quote_ident(column)} {column_type}'
            )
    _TABLE_COLUMNS_CACHE.pop(table, None)
    _TABLE_COLUMNS_CACHE.pop(f'{CURRICULUM_SCHEMA}.{table}', None)


def provision_module_authoring_tables():
    """Create/upgrade the module-authoring schema. NOT for request paths.

    Only reached from the SQLite test runner or an explicit local opt-in
    (CURRICULUM_ALLOW_RUNTIME_SCHEMA_BOOTSTRAP). Production provisions the same
    objects through migrations.
    """
    global _AUTHORING_TABLES_READY
    if _AUTHORING_TABLES_READY:
        return
    json_type = authoring_json_type()
    with connection.cursor() as cursor:
        if connection.vendor == 'postgresql':
            cursor.execute(f'create schema if not exists {quote_ident(CURRICULUM_SCHEMA)}')
        cursor.execute(f'''
            create table if not exists {authoring_table_name(AUTHORING_MODULES_TABLE)} (
                module_catalogue_id varchar(128) primary key,
                programme_id varchar(255),
                programme_name varchar(255),
                is_programme_deleted boolean not null default false,
                cohort_id varchar(255),
                cohort_name varchar(255),
                group_id varchar(255),
                group_name varchar(255),
                learner_roster_mode varchar(32) not null default 'inherited',
                teams_shared_source_module_id varchar(128),
                ksb_remap_report text,
                tutor_name varchar(255),
                tutor_email varchar(320),
                title text not null,
                description text,
                color varchar(32),
                cover_image_url text,
                sessions_number integer not null default 0,
                weeks_number integer,
                start_date date,
                end_date date,
                total_otjh numeric(8,2) not null default 0,
                quality_score integer not null default 0,
                ksb_profile_source_id varchar(128),
                session_week_day varchar(255),
                session_start_time varchar(32),
                session_end_time varchar(32),
                weekly_schedule {json_type},
                source_type varchar(64),
                source_id varchar(255),
                created_at timestamp not null default current_timestamp,
                updated_at timestamp not null default current_timestamp
            )
        ''')
        if connection.vendor == 'postgresql':
            cursor.execute(f'alter table {authoring_table_name(AUTHORING_MODULES_TABLE)} add column if not exists sessions_number integer not null default 0')
            cursor.execute(f'alter table {authoring_table_name(AUTHORING_MODULES_TABLE)} add column if not exists weeks_number integer')
            cursor.execute(f'alter table {authoring_table_name(AUTHORING_MODULES_TABLE)} add column if not exists start_date date')
            cursor.execute(f'alter table {authoring_table_name(AUTHORING_MODULES_TABLE)} add column if not exists end_date date')
            cursor.execute(f'alter table {authoring_table_name(AUTHORING_MODULES_TABLE)} add column if not exists cohort_id varchar(255)')
            cursor.execute(f'alter table {authoring_table_name(AUTHORING_MODULES_TABLE)} add column if not exists cohort_name varchar(255)')
            cursor.execute(f'alter table {authoring_table_name(AUTHORING_MODULES_TABLE)} add column if not exists group_id varchar(255)')
            cursor.execute(f'alter table {authoring_table_name(AUTHORING_MODULES_TABLE)} add column if not exists group_name varchar(255)')
            cursor.execute(f"alter table {authoring_table_name(AUTHORING_MODULES_TABLE)} add column if not exists learner_roster_mode varchar(32) not null default 'inherited'")
