@scoped_curriculum_read
def authoring_fetch_all(table, where_sql='', params=None, order_sql='', *, ensure_tables=True, columns=None, exclude_columns=None):
    """Read authoring rows. Pass ``columns`` to avoid ``select *``.

    Narrowing matters on ``curriculum.components``: it holds ~18k rows and
    39 MB, 24 MB of which is ``settings_json``, and the database is remote.
    A caller that only needs titles and counts pays ~90 s for ``select *``
    against well under a second for the columns it actually reads. ``columns``
    is part of the memo key, so a narrow read and a full read never collide.

    ``exclude_columns`` is the inverse and is the safer choice for a caller that
    reads most of the row: it drops only what is named, so a column added later
    still arrives.
    """
    query = authoring_select_sql(
        table, where_sql, order_sql,
        ensure_tables=ensure_tables, columns=columns, exclude_columns=exclude_columns,
    )
    with connection.cursor() as cursor:
        cursor.execute(query, params or [])
        return rows_as_dicts(cursor)


def authoring_select_sql(table, where_sql='', order_sql='', *, ensure_tables=True, columns=None, exclude_columns=None):
    """The statement authoring_fetch_all() runs; shared so a prefetch sends the same SQL."""
    if ensure_tables:
        ensure_module_authoring_tables()
    if columns:
        wanted = [column for column in columns if has_column(table, column)]
        select_list = ', '.join(quote_ident(column) for column in wanted) if wanted else '*'
    elif exclude_columns:
        # Everything but the named columns. Safer than an allow-list for a
        # caller that reads most of the row: a column added later is included
        # automatically instead of silently arriving as None.
        wanted = sorted(column_names(table) - {column for column in exclude_columns})
        select_list = ', '.join(quote_ident(column) for column in wanted) if wanted else '*'
    else:
        select_list = '*'
    query = f'select {select_list} from {authoring_table_name(table)}'
    if where_sql:
        query += f' where {where_sql}'
    if order_sql:
        query += f' order by {order_sql}'
    return query


# Off unless set: measured 2026-10-21 against a Neon branch through the pooler,
# it cut ~9 round trips from a PROG-PCP-L6 rebuild but showed no wall-clock gain
# beyond Neon's run-to-run noise, and three of eighteen page bursts with it on
# stalled (19-48s) where none did without. Enable only with fresh evidence.
CURRICULUM_PIPELINED_READS = os.environ.get('CURRICULUM_PIPELINED_READS', 'false').lower() in {'true', '1', 'yes'}


def prefetch_authoring_reads(calls):
    """Send independent authoring_fetch_all() reads to the database together.

    ``calls`` is ``[(args, kwargs), ...]``, exactly as the caller below will
    make them. Each result goes into the read scope under the key that call is
    memoised with, so the call itself then costs nothing. A builder's reads go
    out one round trip at a time, and from a remote database each round trip,
    not the rows, is most of what a programme build waits on; psycopg's
    pipeline mode sends them all and waits once.

    Only ever an optimisation: the SQL is authoring_select_sql()'s own, and a
    call whose key does not match what was prefetched -- arguments spelled
    differently, a pipeline that failed -- just reads as it always did. Outside
    a read scope, inside an atomic block (a failed statement there would poison
    the caller's transaction) or off PostgreSQL, nothing is sent.
    """
    memo = getattr(_CURRICULUM_READ_SCOPE, 'memo', None)
    if (
        memo is None or not CURRICULUM_PIPELINED_READS
        or connection.vendor != 'postgresql' or connection.in_atomic_block
    ):
        return
    try:
        signature = inspect.signature(authoring_fetch_all.__wrapped__)
    except (AttributeError, TypeError, ValueError):
        return
    pending = {}
    for args, kwargs in calls:
        try:
            key = authoring_fetch_all.memo_key(*args, **kwargs)
            if key in memo or key in pending:
                continue
            bound = signature.bind(*args, **kwargs)
            bound.apply_defaults()
            options = bound.arguments
            query = authoring_select_sql(
                options['table'], options['where_sql'], options['order_sql'],
                ensure_tables=options['ensure_tables'], columns=options['columns'],
                exclude_columns=options['exclude_columns'],
            )
        except Exception:
            logger.debug('Skipping a curriculum read prefetch.', exc_info=True)
            continue
        pending[key] = (query, options['params'] or [])
    if len(pending) < 2:
        # One read gains nothing from a pipeline; let the call make it.
        return
    cursors = []
    try:
        connection.ensure_connection()
        with connection.connection.pipeline():
            for query, params in pending.values():
                cursor = connection.cursor()
                cursors.append(cursor)
                cursor.execute(query, params)
        results = [rows_as_dicts(cursor) for cursor in cursors]
    except Exception:
        logger.warning('Pipelined curriculum reads failed; they will be read one by one.', exc_info=True)
        return
    finally:
        for cursor in cursors:
            try:
                cursor.close()
            except Exception:
                pass
    for key, rows in zip(pending, results):
        memo.setdefault(key, rows)


def safe_authoring_module_rows():
    try:
        return authoring_fetch_all(AUTHORING_MODULES_TABLE)
    except (Exception, AssertionError):
        logger.debug('Unable to read authoring module rows for relationship sync.', exc_info=True)
        return []


def surviving_authoring_module_rows(module_rows=None):
    """Module rows that are not soft-deleted, directly or through a parent.

    ``safe_authoring_module_rows`` deliberately reads every row so archive views
    can still show withdrawn curriculum. Anything that rebuilds a *surviving*
    parent's denormalized child list has to filter first, otherwise an archived
    module keeps being written back into it.
    """
    rows = module_rows if module_rows is not None else safe_authoring_module_rows()
    return [row for row in rows if row and not curriculum_row_effectively_deleted(row)]


def archived_authoring_ids(table, id_column):
    """Ids of the soft-deleted rows in an authoring table.

    Archiving stamps ``deleted_at`` and leaves the row where it is, and the
    ``*_authoring_detail_rows`` readers deliberately return every row so archive
    views can still show withdrawn curriculum. Anything that matches a *new*
    record against the stored ones has to skip these ids first: treating an
    archived row as a duplicate turns "create it again" into an update of a
    tombstone, so the write lands on a row nothing lists and the caller is told
    the record already exists while no record appears.
    """
    ident = clean_str(id_column)
    try:
        rows = authoring_fetch_all(
            table,
            columns=[ident, 'deleted_at', 'is_programme_deleted', 'is_archived'],
        )
    except (Exception, AssertionError) as exc:
        logger.warning('Could not read archived ids for %s: %s', table, exc)
        return set()
    return {
        clean_str(row.get(ident))
        for row in rows
        if clean_str(row.get(ident)) and curriculum_row_effectively_deleted(row)
    }


def refresh_group_module_cache(group_id, module_rows=None):
    """Rebuild ``groups.module_ids``/``module_names`` from surviving modules.

    A surviving parent's denormalized child arrays list only surviving children
    — the rule ``repair_curriculum_parent_links`` documents — so the rebuild
    drops deleted module rows. Without that filter an archived module stayed in
    the cached list, and because ``build_cohorts_and_groups`` falls back to the
    stored list when a group has no live module rows, the wizard rendered it as
    a real attachment.
    """
    identifier = clean_str(group_id)
    if not identifier:
        return None
    rows = [
        row for row in surviving_authoring_module_rows(module_rows)
        if clean_str(row.get('group_id')) == identifier
    ]
    return update_group_fields(identifier, {
        'module_ids': json_db_value(unique([
            clean_str(row.get('module_catalogue_id')) for row in rows if row.get('module_catalogue_id')
        ])),
        'module_names': json_db_value(unique([
            clean_str(row.get('title')) for row in rows if row.get('title')
        ])),
    })


def programme_archived_for_authoring(programme_id):
    """Is the programme a module is being saved against archived or deleted?

    Used to re-derive ``modules.is_programme_deleted`` on save instead of
    trusting the flag already on the row: the flag records *the programme's*
    state, so a module moved onto a live programme has to lose it.
    """
    identifier = clean_str(programme_id)
    if not identifier:
        return False
    try:
        config = program_config_by_id(get_program_config_rows()).get(identifier)
    except (Exception, AssertionError):
        logger.debug('Unable to resolve programme %s for delete-flag derivation.', identifier, exc_info=True)
        return False
    return bool(config) and is_archived_program_config(config)


def module_withdrawn_on_its_own(row):
    """Was this module withdrawn by the module DELETE, rather than by a parent?

    A programme or group archive stamps its children with ``deleted_via_parent``
    (and ``deleted_by='programme-delete'``); a module archived on its own
    carries neither. The difference matters because the two are undone
    differently: a parent's children come back with the parent, while a module
    withdrawn deliberately stays withdrawn until someone restores it.
    """
    return (
        row_has_deleted_at(row)
        and not clean_str((row or {}).get('deleted_via_parent'))
        and clean_str((row or {}).get('deleted_by')) == 'module-delete'
    )


def module_recovered_by_move_to_live(existing_module_row, programme_id):
    """Is this save moving an already-withdrawn module onto a live programme?

    That move is the recovery route, and the backend owns its outcome rather
    than reading it back off the payload. The drawer PATCH rebuilds its body
    from ``get_authoring_structure_payload``, which reports
    ``isProgrammeDeleted``, so a module being rescued sent its own stale
    ``true`` straight back and pinned itself withdrawn: ``programme_id`` moved
    to the live programme and the module stayed hidden from every list. The
    Builder's structure PATCH sends the same key from the same source, so both
    paths carried the same stale flag -- derived here, once, they recover a
    module identically.

    Not for a module withdrawn on its own: restoring that stays an explicit
    operation, and re-parenting it must not quietly undo it.
    """
    if not programme_deleted_row(existing_module_row):
        return False
    target = clean_str(programme_id)
    # Only a real move. Saving a withdrawn module where it already sits changes
    # nothing about why it was withdrawn -- under an archived programme it must
    # stay withdrawn, which is what keeps it editable there without reviving it.
    if not target or target == clean_str((existing_module_row or {}).get('programme_id')):
        return False
    if programme_archived_for_authoring(target):
        return False
    return not module_withdrawn_on_its_own(existing_module_row)


def authoring_programme_config_for_save(programme_id, programme_name=''):
    """The programme row a module save would attach the module to.

    Mirrors how ``ensure_programme_config_for_authoring`` picks its row -- id
    first, then name -- minus the write. A payload that carries only a programme
    *name* (an id that no longer resolves, or a module left unassigned) is still
    attached by name on save, so anything judging that save has to resolve it
    the same way or it judges a different programme than the one written.
    """
    identifier = persistable_programme_id(programme_id)
    name = clean_str(programme_name)
    try:
        configs = get_program_config_rows()
    except (Exception, AssertionError):
        logger.debug('Unable to resolve the programme a module save would attach to.', exc_info=True)
        return None
    if identifier:
        match = next((
            config for config in configs if programme_config_identity(config) == identifier
        ), None)
        if match:
            return match
    if name and normalise(name) not in {'unassignedprogramme', 'unassigned'}:
        return next((
            config for config in configs if normalise(config.get('name')) == normalise(name)
        ), None)
    return None


def archived_programme_module_edit_error(existing_module_row, *, title, programme_id, programme_name=''):
    """The one archived-programme rule, shared by both module edit paths.

    Saving re-derives ``modules.is_programme_deleted`` from the programme the
    module is attached to, so a module sitting under an archived programme is
    flagged as deleted the moment anything about it is saved -- and it
    disappears from every list while the response still reads ``updated: True``.
    That is the "I edited it and it vanished" report. Refused outright rather
    than saved-and-warned: the edit is not what the person wanted if its effect
    is to withdraw the module.

    Applied identically by the drawer PATCH (``curriculum_module_detail``) and
    the Module Builder's structure PATCH (``curriculum_module_structure``), so
    the two cannot drift into two slightly different rules -- the Builder used
    to save happily and leave the module hidden.

    Only for a module that is still visible. One already withdrawn is left
    editable on purpose -- moving it onto a live programme is how it is brought
    back, and blocking that would strand it.

    Returns a ready-to-send 400 response, or ``None`` when the save may proceed.
    """
    if programme_deleted_row(existing_module_row):
        return None
    target_programme = authoring_programme_config_for_save(programme_id, programme_name)
    if not target_programme or not is_archived_program_config(target_programme):
        return None
    name = clean_str(title)
    label = f'"{name}"' if name else 'This module'
    return json_error(
        f'{label} belongs to an archived programme, so saving it '
        'would withdraw it from every list. Restore the programme, or move the module to a live '
        'one, before editing it.',
        fields=['programmeId'],
        status=400,
    )


@scoped_curriculum_read
def free_programme_fetch_all(table, where_sql='', params=None, order_sql='', columns=None):
    """Free-course rows. `columns` names the ones to read.

    Default is every column, which is what the payload builders want. Callers
    that only need identifiers should name them: free_course_weeks.
    cover_image_url and free_courses.cover_image_url hold base64 `data:` image
    payloads on some rows -- hundreds of kilobytes each -- and a `select *` for
    an id list drags all of them across the wire.
    """
    ensure_free_programme_tables()
    selection = ', '.join(quote_ident(column) for column in columns) if columns else '*'
    query = f'select {selection} from {authoring_table_name(table)}'
    if where_sql:
        query += f' where {where_sql}'
    if order_sql:
        query += f' order by {order_sql}'
    with connection.cursor() as cursor:
        cursor.execute(query, params or [])
        return rows_as_dicts(cursor)


def authoring_delete(table, where_sql='1 = 1', params=None):
    """Hard-delete authoring rows, recording what they held before they went.

    ``returning *`` is asked for only when the table is one history covers, so
    the sweeps that clear rows nothing has ever pointed at do not pay to
    serialise them. On sqlite, which has no DELETE ... RETURNING, the rows are
    read back inside the same transaction first.
    """
    ensure_module_authoring_tables()
    versioned = table in versioning.VERSIONED_TABLES
    if not versioned:
        with connection.cursor() as cursor:
            cursor.execute(f'delete from {authoring_table_name(table)} where {where_sql}', params or [])
        return
    if connection.vendor == 'postgresql':
        with connection.cursor() as cursor:
            cursor.execute(
                f'delete from {authoring_table_name(table)} where {where_sql} returning *',
                params or [],
            )
            rows = rows_as_dicts(cursor)
    else:
        rows = authoring_fetch_all(table, where_sql, params or [], ensure_tables=False)
        with connection.cursor() as cursor:
            cursor.execute(f'delete from {authoring_table_name(table)} where {where_sql}', params or [])
    versioning.record_deleted_rows(table, rows)
    note_live_rows(table, rows)


def free_programme_delete(table, where_sql, params=None):
    ensure_free_programme_tables()
    with connection.cursor() as cursor:
        cursor.execute(f'delete from {authoring_table_name(table)} where {where_sql}', params or [])


def authoring_upsert(table, key_columns, payload, allow_null_columns=None):
    """Insert-or-update one authoring row.

    ``None`` normally means "leave this column alone", which is what every
    caller that builds a partial payload relies on. ``allow_null_columns``
    opts specific columns out of that rule so a value can be cleared — mirroring
    the same argument on ``update_rows``.
    """
    ensure_module_authoring_tables()
    writable = column_names(table)
    nullable = set(SOFT_DELETE_COLUMNS) | set(allow_null_columns or ())
    values = {
        key: value
        for key, value in payload.items()
        if key in writable and (value is not None or key in nullable)
    }
    values['updated_at'] = datetime.utcnow()
    if 'created_at' not in values:
        values['created_at'] = datetime.utcnow()
    columns = list(values.keys())
    placeholders = ', '.join(['%s'] * len(columns))
    update_columns = [column for column in columns if column not in set(key_columns) | {'created_at'}]
    if connection.vendor == 'postgresql' or table in (AUTHORING_MODULES_TABLE, LIVE_SESSION_OCCURRENCES_TABLE):
        # REPLACE deletes the old SQLite row, cascading away the module's
        # calendar or the occurrence's attendance. These identities must survive edits.
        conflict = ', '.join(quote_ident(column) for column in key_columns)
        assignments = ', '.join(f'{quote_ident(column)} = excluded.{quote_ident(column)}' for column in update_columns)
        query = (
            f'insert into {authoring_table_name(table)} ({", ".join(quote_ident(column) for column in columns)}) '
            f'values ({placeholders}) on conflict ({conflict}) do update set {assignments}'
            + (' returning *' if connection.vendor == 'postgresql' else '')
        )
    else:
        query = (
            f'insert or replace into {authoring_table_name(table)} ({", ".join(quote_ident(column) for column in columns)}) '
            f'values ({placeholders})'
        )
    key_value = ' '.join(clean_str(values.get(column)) for column in key_columns)
    with connection.cursor() as cursor:
        cursor.execute(query, [values[column] for column in columns])
        if connection.vendor == 'postgresql':
            row = rows_as_dicts(cursor)[0]
            log_curriculum_storage('upsert', table, rows=1, entity_id=key_value)
            # The row the write returned is the snapshot, so history costs no
            # extra read of the record.
            versioning.record_rows(table, [row])
            note_live_rows(table, [row])
            return row
    where = ' and '.join(f'{quote_ident(column)} = %s' for column in key_columns)
    log_curriculum_storage('upsert', table, rows=1, entity_id=key_value)
    saved = authoring_fetch_all(table, where, [values[column] for column in key_columns])[0]
    versioning.record_rows(table, [saved])
    note_live_rows(table, [saved])
    return saved


def authoring_bulk_upsert(table, key_columns, payloads, batch_size=100):
    ensure_module_authoring_tables()
    writable = column_names(table)
    payloads = [
        {
            key: value
            for key, value in payload.items()
            if key in writable and (value is not None or key in SOFT_DELETE_COLUMNS)
        }
        for payload in payloads
        if payload
    ]
    payloads = [payload for payload in payloads if payload]
    if not payloads:
        return
    now = datetime.utcnow()
    all_columns = []
    seen_columns = set()
    for payload in payloads:
        for column in payload.keys():
            if column not in seen_columns:
                all_columns.append(column)
                seen_columns.add(column)
    if 'updated_at' not in seen_columns:
        all_columns.append('updated_at')
        seen_columns.add('updated_at')
    if 'created_at' not in seen_columns:
        all_columns.append('created_at')
        seen_columns.add('created_at')
    update_columns = [column for column in all_columns if column not in set(key_columns) | {'created_at'}]
    quoted_columns = ', '.join(quote_ident(column) for column in all_columns)
    # One statement shape on both vendors. SQLite's `insert or replace` deleted
    # the old row and wrote a fresh `created_at`, so an edit could not be told
    # from a create; `on conflict ... do update` keeps the stored `created_at`
    # (it is never in `update_columns`), and SQLite has supported it and
    # `returning` since 3.24 / 3.35.
    conflict = ', '.join(quote_ident(column) for column in key_columns)
    assignments = ', '.join(f'{quote_ident(column)} = excluded.{quote_ident(column)}' for column in update_columns)
    row_placeholder = f'({", ".join(["%s"] * len(all_columns))})'
    prefix = f'insert into {authoring_table_name(table)} ({quoted_columns}) values '
    suffix = f' on conflict ({conflict}) do update set {assignments} returning *'
    saved = []
    with connection.cursor() as cursor:
        for start in range(0, len(payloads), batch_size):
            batch = payloads[start:start + batch_size]
            values = []
            for payload in batch:
                row = {key: value for key, value in payload.items()}
                row.setdefault('updated_at', now)
                row.setdefault('created_at', now)
                values.extend(row.get(column) for column in all_columns)
            placeholders = ', '.join([row_placeholder] * len(batch))
            cursor.execute(f'{prefix}{placeholders}{suffix}', values)
            saved.extend(rows_as_dicts(cursor))
    # Deliberately one line for the whole call, not one per row: a tree save
    # bulk-writes thousands of components and a per-row trace would bury
    # everything else in the request.
    log_curriculum_storage('bulk_upsert', table, rows=len(payloads))
    # The rows the statement returned are the snapshots, so history still costs
    # no extra read. They have to be the stored rows and not the payloads: only
    # the stored row carries the `created_at` / `updated_at` pair that tells a
    # record made by this save from one that predates history and is merely
    # being edited. The payloads carry neither, so every create read as "first
    # recorded". record_rows drops the rows whose content is unchanged, which
    # on this path is nearly all of them: a tree save rewrites every component
    # in the module whether or not the author touched it.
    versioning.record_rows(table, saved)
    note_live_rows(table, saved)


def free_programme_upsert(table, key_columns, payload):
    ensure_free_programme_tables()
    return authoring_upsert(table, key_columns, payload)


def as_json_value(value, fallback):
    parsed = parse_json_value(value, fallback)
    return parsed if parsed is not None else fallback


def json_db_value(value):
    return json.dumps(value if value is not None else [])


# ---------------------------------------------------------------------------
# Normalized curriculum source-of-truth helpers.
#
# The Curriculum feature reads and writes its cohorts and groups directly from
# the normalized ``curriculum.cohorts`` (COHORT_AUTHORING_DETAILS_TABLE) and
# ``curriculum.groups`` (GROUPS_TABLE) tables. These helpers look entities up by
# their stored canonical id and apply targeted field updates.
# ---------------------------------------------------------------------------

def fetch_cohort_row(cohort_id):
    """Return the raw normalized ``curriculum.cohorts`` row for a canonical id."""
    ident = clean_str(cohort_id)
    if not ident:
        return None
    rows = authoring_fetch_all(COHORT_AUTHORING_DETAILS_TABLE, 'cohort_id = %s', [ident])
    return rows[0] if rows else None


def fetch_group_row(group_id):
    """Return the raw normalized ``curriculum.groups`` row for a canonical id."""
    ident = clean_str(group_id)
    if not ident:
        return None
    rows = authoring_fetch_all(GROUPS_TABLE, 'group_id = %s', [ident])
    return rows[0] if rows else None


def resolve_cohort_row(identifier):
    """Look up a cohort row by canonical id first, then fall back to name match.

    Name matching is used only for validation/lookup tolerance (e.g. legacy
    clients passing a name); the returned row always carries its stored
    canonical ``cohort_id``, which is what callers use for updates.
    """
    ident = clean_str(identifier)
    if not ident:
        return None
    row = fetch_cohort_row(ident)
    if row:
        return row
    for candidate in authoring_fetch_all(COHORT_AUTHORING_DETAILS_TABLE):
        if matches_curriculum_identifier(candidate.get('cohort_id'), ident):
            return candidate
    # A name can now be shared by a live cohort and an archived namesake, so
    # the live one wins; the tombstone is only returned when nothing else holds
    # the name.
    name_matches = [
        candidate for candidate in authoring_fetch_all(COHORT_AUTHORING_DETAILS_TABLE)
        if normalise(candidate.get('cohort_name')) == normalise(ident)
    ]
    surviving = [row for row in name_matches if not curriculum_row_effectively_deleted(row)]
    for candidate in surviving or name_matches:
        return candidate
    return None


def resolve_group_row(identifier):
    """Look up a group row by canonical id first, then fall back to name match."""
    ident = clean_str(identifier)
    if not ident:
        return None
    row = fetch_group_row(ident)
    if row:
        return row
    for candidate in authoring_fetch_all(GROUPS_TABLE):
        if matches_curriculum_identifier(candidate.get('group_id'), ident):
            return candidate
    # Group names are only unique within a cohort, so a bare-name lookup can be
    # ambiguous. Returning an arbitrary match writes modules into whichever row
    # the scan happened to reach first; refuse instead and let the caller supply
    # a canonical id (or a cohort-scoped lookup).
    # Archived namesakes do not make a name ambiguous: recreating a group under
    # an archived group's name is legal, and the live row is unmistakably the
    # one meant. Only fall back to the archived rows when no live row holds the
    # name at all.
    name_matches = [
        candidate for candidate in authoring_fetch_all(GROUPS_TABLE)
        if normalise(candidate.get('group_name')) == normalise(ident)
    ]
    surviving = [row for row in name_matches if not curriculum_row_effectively_deleted(row)]
    name_matches = surviving or name_matches
    if len(name_matches) == 1:
        return name_matches[0]
    if len(name_matches) > 1:
        logger.warning(
            'Ambiguous group name %r matches %d rows (%s); refusing to guess.',
            ident,
            len(name_matches),
            ', '.join(clean_str(row.get('group_id')) for row in name_matches),
        )
    return None


def update_cohort_fields(cohort_id, fields, allow_null_columns=None):
    """Apply a targeted field update to a single normalized cohort row.

    Only the provided columns are written; the canonical ``cohort_id`` and all
    unrelated columns (programme_id, group_ids, dates, status, …) are preserved.
    ``None`` means "leave this column alone" unless the column is named in
    ``allow_null_columns``, which lets a value be cleared outright.
    """
    ident = clean_str(cohort_id)
    if not ident:
        return None
    nullable = set(allow_null_columns or ())
    values = {key: value for key, value in fields.items() if value is not None or key in nullable}
    if not values:
        return fetch_cohort_row(ident)
    values['updated_at'] = datetime.utcnow()
    rows = update_authoring_rows(COHORT_AUTHORING_DETAILS_TABLE, 'cohort_id = %s', [ident], values)
    return rows[0] if rows else fetch_cohort_row(ident)


def update_group_fields(group_id, fields):
    """Apply a targeted field update to a single normalized group row."""
    ident = clean_str(group_id)
    if not ident:
        return None
    values = {key: value for key, value in fields.items() if value is not None}
    if not values:
        return fetch_group_row(ident)
    values['updated_at'] = datetime.utcnow()
    rows = update_authoring_rows(GROUPS_TABLE, 'group_id = %s', [ident], values)
    return rows[0] if rows else fetch_group_row(ident)


def update_authoring_rows(table, where_sql, where_params, payload):
    """Update rows in a ``curriculum`` schema authoring table and return them."""
    ensure_module_authoring_tables()
    columns = [column for column in payload if column in column_names(table)]
    if not columns:
        return authoring_fetch_all(table, where_sql, where_params)
    assignments = ', '.join(f'{quote_ident(column)} = %s' for column in columns)
    params = [payload[column] for column in columns] + list(where_params)
    key_value = ' '.join(clean_str(value) for value in where_params)
    with connection.cursor() as cursor:
        if connection.vendor == 'postgresql':
            cursor.execute(
                f'update {authoring_table_name(table)} set {assignments} where {where_sql} returning *',
                params,
            )
            rows = rows_as_dicts(cursor)
            log_curriculum_storage('update', table, rows=rows, entity_id=key_value)
            versioning.record_rows(table, rows)
            note_live_rows(table, rows)
            return rows
        cursor.execute(
            f'update {authoring_table_name(table)} set {assignments} where {where_sql}',
            params,
        )
    rows = authoring_fetch_all(table, where_sql, where_params)
    log_curriculum_storage('update', table, rows=rows, entity_id=key_value)
    versioning.record_rows(table, rows)
    note_live_rows(table, rows)
    return rows


def json_array_remove(raw_value, target):
    """Remove ``target`` from a JSON-array column value, returning a JSON string."""
    values = as_json_value(raw_value, [])
    if not isinstance(values, list):
        values = []
    target = clean_str(target)
    return json_db_value([value for value in values if clean_str(value) != target])


def json_array_add(raw_value, target):
    """Append ``target`` to a JSON-array column value if absent."""
    values = as_json_value(raw_value, [])
    if not isinstance(values, list):
        values = []
    target = clean_str(target)
    if target and target not in {clean_str(value) for value in values}:
        values = [*values, target]
    return json_db_value(values)


def repair_curriculum_parent_links(programme_id='', *, allow_writes=True):
    """Keep denormalized parent arrays and child links coherent.

    True foreign keys are risky for existing installations because legacy rows
    can pre-date the normalized tables. These guards repair relationships that
    are in scope for a save and clean obvious authoring orphans.

    ``allow_writes=False`` makes this a no-op, which is what GET handlers pass.
    Two reasons this must not run on a read:

    1. It writes, so it breaks any read-only connection and hides a mutation
       behind an apparently read-only endpoint.
    2. It sets ``groups.programme_id = ''`` when a group's cohort is missing.
       That is the most likely origin of the empty-string programme_id rows
       still present in production, and once migration 0038 adds the foreign
       key such a write is rejected outright ('' is not NULL and has no parent),
       which would turn a plain GET into a 500.

    Write paths keep the default and still repair what they are saving.

    Soft delete
    -----------
    Repair is a coherence pass over *surviving* curriculum, and it obeys two
    rules so it cannot undo a delete by accident:

    1. It never writes to an effectively deleted row. An archived cohort, group
       or module keeps exactly the lineage it was archived with.
    2. It never points a surviving row at an effectively deleted one. A
       surviving group does not inherit a deleted cohort's programme, a
       surviving module does not inherit a deleted group's names, and a
       surviving parent's denormalized child arrays (``cohorts.group_ids``,
       ``groups.module_ids``) list only surviving children.

    Deletion is read here, never written: no branch touches ``deleted_at``,
    ``deleted_by`` or ``deleted_via_parent``, so a surviving child holding an
    old parent id can never restore that parent. Restoring stays an explicit
    operation (``restore_soft_delete_payload``).
    """
    if not allow_writes:
        return
    programme_id = clean_str(programme_id)
    # The programme's own name, pushed down onto the children that carry a copy
    # of it. The rename endpoint already does this (propagate_programme_name),
    # but a child written before that existed -- or by any other path -- keeps the
    # old name, and a module with no group has no parent to inherit the new one
    # from further down this pass. A stale copy is not cosmetic: it is read as an
    # identity wherever a row carries no programme_id, so it made one programme's
    # cohorts, groups and modules count towards whichever programme now answers
    # to the old name.
    # Scoped to the programme being saved: the update below is conditional, so it
    # is a no-op when nothing drifted, but a whole-estate sweep on every save is
    # round trips nobody asked for.
    if programme_id:
        try:
            config = next((
                item for item in get_program_config_rows()
                if clean_str(programme_config_identity(item)) == programme_id
            ), None)
            if config:
                propagate_programme_name(programme_id, clean_str(config.get('name')))
        except (Exception, AssertionError):
            logger.debug('Could not refresh denormalized programme names for %s.', programme_id, exc_info=True)
    try:
        cohorts = authoring_fetch_all(COHORT_AUTHORING_DETAILS_TABLE)
        groups = authoring_fetch_all(GROUPS_TABLE)
        modules = safe_authoring_module_rows()
        cohort_by_id = {clean_str(row.get('cohort_id')): row for row in cohorts if clean_str(row.get('cohort_id'))}
        group_by_id = {clean_str(row.get('group_id')): row for row in groups if clean_str(row.get('group_id'))}

        for group in groups:
            group_id = clean_str(group.get('group_id'))
            cohort_id = clean_str(group.get('cohort_id'))
            cohort = cohort_by_id.get(cohort_id)
            if not group_id or curriculum_row_effectively_deleted(group):
                continue
            if not cohort:
                if not programme_id or clean_str(group.get('programme_id')) == programme_id:
                    update_group_fields(group_id, {
                        'cohort_id': '',
                        'cohort_name': '',
                        'programme_id': '',
                        'programme_name': '',
                    })
                continue
            # The cohort row is still there but withdrawn. Leave the group's
            # stored lineage alone: copying a deleted cohort's programme down
            # would reconnect a surviving group to deleted curriculum, and
            # blanking it would destroy the archive relationship instead.
            if curriculum_row_effectively_deleted(cohort):
                continue
            updates = {}
            if clean_str(group.get('cohort_name')) != clean_str(cohort.get('cohort_name')):
                updates['cohort_name'] = clean_str(cohort.get('cohort_name'))
            if clean_str(group.get('programme_id')) != clean_str(cohort.get('programme_id')):
                updates['programme_id'] = clean_str(cohort.get('programme_id'))
            if clean_str(group.get('programme_name')) != clean_str(cohort.get('programme_name')):
                updates['programme_name'] = clean_str(cohort.get('programme_name'))
            if updates:
                update_group_fields(group_id, updates)

        groups = authoring_fetch_all(GROUPS_TABLE)
        group_by_id = {clean_str(row.get('group_id')): row for row in groups if clean_str(row.get('group_id'))}
        group_ids_by_cohort = defaultdict(list)
        module_ids_by_group = defaultdict(list)
        module_names_by_group = defaultdict(list)
        for group in groups:
            group_id = clean_str(group.get('group_id'))
            cohort_id = clean_str(group.get('cohort_id'))
            if curriculum_row_effectively_deleted(group):
                continue
            if group_id and cohort_id and (not programme_id or clean_str(group.get('programme_id')) == programme_id):
                group_ids_by_cohort[cohort_id].append(group_id)

        for module in modules:
            module_id = clean_str(module.get('module_catalogue_id'))
            group_id = clean_str(module.get('group_id'))
            if not module_id or not group_id or curriculum_row_effectively_deleted(module):
                continue
            group = group_by_id.get(group_id)
            if not group:
                update_authoring_rows(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [module_id], {
                    'cohort_id': '',
                    'cohort_name': '',
                    'group_id': '',
                    'group_name': '',
                })
                continue
            if programme_id and clean_str(group.get('programme_id')) != programme_id:
                continue
            # Same reasoning as the cohort branch: a withdrawn group must not
            # push its lineage onto a module that is still live, and the module
            # must not appear in that group's surviving-children arrays.
            if curriculum_row_effectively_deleted(group):
                continue
            updates = {}
            for column, group_column in (
                ('group_name', 'group_name'),
                ('cohort_id', 'cohort_id'),
                ('cohort_name', 'cohort_name'),
                ('programme_id', 'programme_id'),
                ('programme_name', 'programme_name'),
            ):
                if clean_str(module.get(column)) != clean_str(group.get(group_column)):
                    updates[column] = clean_str(group.get(group_column))
            if updates:
                update_authoring_rows(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [module_id], updates)
            module_ids_by_group[group_id].append(module_id)
            if clean_str(module.get('title')):
                module_names_by_group[group_id].append(clean_str(module.get('title')))

        for cohort in cohorts:
            cohort_id = clean_str(cohort.get('cohort_id'))
            if not cohort_id or (programme_id and clean_str(cohort.get('programme_id')) != programme_id):
                continue
            if curriculum_row_effectively_deleted(cohort):
                continue
            update_cohort_fields(cohort_id, {'group_ids': json_db_value(unique(group_ids_by_cohort.get(cohort_id, [])))})
        for group in groups:
            group_id = clean_str(group.get('group_id'))
            if not group_id or (programme_id and clean_str(group.get('programme_id')) != programme_id):
                continue
            if curriculum_row_effectively_deleted(group):
                continue
            update_group_fields(group_id, {
                'module_ids': json_db_value(unique(module_ids_by_group.get(group_id, []))),
                'module_names': json_db_value(unique(module_names_by_group.get(group_id, []))),
            })

        # Authoring orphans only: these match a child whose parent ROW is
        # physically gone. A soft-deleted week/module/component still has its
        # row, so an archived branch of curriculum is never swept up here and
        # historical learner progress stays joinable to it.
        #
        # Detached library content is excluded twice over. Its parent ids are
        # the empty string, which the coalesce guards below already skip, and
        # the explicit library_state check makes that protection independent of
        # the sentinel - a detach that forgot to clear a parent id would
        # otherwise have its content swept away here.
        authoring_delete(AUTHORING_WEEKS_TABLE, library_sweep_guard(AUTHORING_WEEKS_TABLE, "coalesce(module_catalogue_id, '') <> '' and module_catalogue_id not in (select module_catalogue_id from " + authoring_table_name(AUTHORING_MODULES_TABLE) + ")"))
        authoring_delete(AUTHORING_COMPONENTS_TABLE, library_sweep_guard(AUTHORING_COMPONENTS_TABLE, "coalesce(module_catalogue_id, '') <> '' and module_catalogue_id not in (select module_catalogue_id from " + authoring_table_name(AUTHORING_MODULES_TABLE) + ")"))
        authoring_delete(AUTHORING_COMPONENTS_TABLE, library_sweep_guard(AUTHORING_COMPONENTS_TABLE, "coalesce(week_id, '') <> '' and week_id not in (select id from " + authoring_table_name(AUTHORING_WEEKS_TABLE) + ")"))
        authoring_delete(AUTHORING_KSB_MAPPINGS_TABLE, "coalesce(module_catalogue_id, '') <> '' and module_catalogue_id not in (select module_catalogue_id from " + authoring_table_name(AUTHORING_MODULES_TABLE) + ")")
        authoring_delete(AUTHORING_KSB_MAPPINGS_TABLE, "coalesce(week_id, '') <> '' and week_id not in (select id from " + authoring_table_name(AUTHORING_WEEKS_TABLE) + ")")
        authoring_delete(AUTHORING_KSB_MAPPINGS_TABLE, "coalesce(component_id, '') <> '' and component_id not in (select id from " + authoring_table_name(AUTHORING_COMPONENTS_TABLE) + ")")
    except (Exception, AssertionError):
        logger.warning('Could not repair curriculum parent links.', exc_info=True)


def unassign_authoring_modules_from_group(group_id, keep_catalogue_ids=None):
    """Clear this group's omitted module links from ``curriculum.modules``.

    Module Builder content is preserved; only the delivery relationship columns
    are cleared for modules no longer present in the group's saved draft.
    """
    group_id = clean_str(group_id)
    keep = {clean_str(value) for value in (keep_catalogue_ids or []) if clean_str(value)}
    if not group_id:
        return []
    rows = authoring_fetch_all(AUTHORING_MODULES_TABLE, 'group_id = %s', [group_id])
    removed = []
    for row in rows:
        module_id = clean_str(row.get('module_catalogue_id'))
        if module_id in keep:
            continue
        update_authoring_rows(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [module_id], {
            'cohort_id': None,
            'cohort_name': '',
            'group_id': None,
            'group_name': '',
        })
        removed.append(module_id)
    return removed


def normalise_component_type(value):
    return str(value or '').replace('-', '_')


RETIRED_COMPONENT_TYPES = {'workplace_evidence'}


def is_retired_component_type(value):
    return normalise_component_type(value) in RETIRED_COMPONENT_TYPES


def active_component_rows(rows):
    # Detached library rows are excluded too. A detach deliberately clears the
    # soft-delete stamps, so without this they would read as live content and
    # surface in the component list belonging to no module at all. They are
    # reachable only through the reuse library.
    return [
        row for row in rows
        if not is_retired_component_type(row.get('type'))
        and not programme_deleted_row(row)
        and not is_library_row(row)
    ]


def active_week_rows(rows):
    return [row for row in rows if not programme_deleted_row(row) and not is_library_row(row)]


def active_mapping_rows(rows):
    return [row for row in rows if not programme_deleted_row(row)]


def active_components_payload(components):
    return [
        component
        for component in (components or [])
        if isinstance(component, dict) and not is_retired_component_type(component.get('type'))
    ]


def without_retired_components(weeks):
    clean_weeks = []
    for week in weeks if isinstance(weeks, list) else []:
        if not isinstance(week, dict):
            clean_weeks.append(week)
            continue
        clean_weeks.append({
            **week,
            'components': active_components_payload(week.get('components')),
        })
    return clean_weeks


def frontend_component_type(value):
    return str(value or '').replace('_', '-')


def display_component_type(value):
    raw = frontend_component_type(value)
    labels = {
        'live-session': 'Live Session',
        'recording-placeholder': 'Recording Placeholder',
        'video': 'Self-study',
        'podcast': 'Self-study',
        'reading': 'Self-study',
        'powerpoint': 'Self-study',
        'quiz': 'Quiz',
        'monthly-ksb-quiz': 'Quiz',
        'assignment': 'Assignment',
        'workshop': 'Workshop',
        'reflection': 'Self-study',
        'checkpoint': 'Quiz',
        'coaching-preparation': 'Self-study',
    }
    return labels.get(raw, clean_str(value).replace('-', ' ').replace('_', ' ').title() or 'Self-study')


def stored_component_type(value):
    label = clean_str(value).lower()
    mapping = {
        'live session': 'live_session',
        'recording placeholder': 'recording_placeholder',
        'video': 'video',
        'podcast': 'podcast',
        'reading': 'reading',
        'reading material': 'reading',
        'powerpoint': 'powerpoint',
        'power point': 'powerpoint',
        'self-study': 'reading',
        'self study': 'reading',
        'quiz': 'quiz',
        'checkpoint': 'checkpoint',
        'checkpoint quiz': 'checkpoint',
        'monthly ksb quiz': 'monthly_ksb_quiz',
        'assignment': 'assignment',
        'reflection': 'reflection',
        'coaching preparation': 'coaching_preparation',
        'workshop': 'workshop',
    }
    return mapping.get(label, normalise_component_type(value) or 'reading')


def normalise_ksb_classification(value):
    return coverage_normalise_classification(value)


def normalise_ksb_weight_class(value, fallback='soft'):
    raw = clean_str(value).lower().replace('_', '-')
    if raw in SUPPORTED_KSB_WEIGHT_CLASSES:
        return raw
    return fallback if fallback in SUPPORTED_KSB_WEIGHT_CLASSES else 'soft'


def legacy_weight_class_from_classification(value):
    legacy = normalise_ksb_classification(value)
    if legacy == 'main':
        return 'hard'
    if legacy == 'possible':
        return 'possible'
    return 'soft'


def normalise_ksb_weight(value):
    return max(0, parse_float(value, 0))


