    return {
        'quizzesCompletedRequired': False,
        'checkpointsCompletedRequired': False,
        'averageScoreRequiredEnabled': False,
        'averageScoreRequired': 70,
        'totalScoreRequiredEnabled': False,
        'totalScoreRequired': 100,
        'additionalNotes': '',
    }


