def mapping_response(row):
    classification = normalise_ksb_classification(row.get('classification'))
    # weight_class is the canonical delivery weighting and is REQUIRED by
    # validate_ksb_mapping_payload. Emitting it here is what lets a stored
    # structure survive a read/write round trip: the module PATCH and the
    # metadata-only reattachment both re-submit what this serializer returned,
    # so dropping the field made the server reject its own valid data.
    weight_class = normalise_ksb_weight_class(
        row.get('weight_class'),
        legacy_weight_class_from_classification(classification),
    )
    return {
        'id': str(row.get('id')),
        'ksbId': str(row.get('ksb_id') or row.get('ksb_code') or ''),
        'code': row.get('ksb_code') or '',
        'description': row.get('ksb_description') or '',
        'sourceType': row.get('source_type') or '',
        'sourceId': row.get('source_id') or '',
        'type': classification,
        'classification': classification,
        'weight': normalise_ksb_weight(row.get('weight')),
        'weightClass': weight_class,
        'weight_class': weight_class,
    }


def authoring_module_exists(module_catalogue_id):
    rows = authoring_fetch_all(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [module_catalogue_id])
    return rows[0] if rows else None


def resolve_stored_module_catalogue_id(identifier):
    """Resolve any public module identifier to the stored MOD-* primary key.

    The existence check first is what makes this cheap.
    ``resolve_authoring_catalogue_id`` is the general answer, but it summarises
    every module in the database to give it -- five round trips, four of them
    whole-table reads and one of them every component row -- because it has to
    search modules by source id, training id and delivery signature. That search
    only means anything for an identifier that is *not* a stored module: a legacy
    ``training-module-`` id, a ``catalogue-module-`` alias, a delivery source id.
    An identifier that already names a stored module is its own answer, and one
    indexed lookup settles it.

    Named for what it returns rather than for a caller: reads want the same
    resolution writes do, and the previous ``_for_write`` name had the module
    structure endpoint reaching for the expensive resolver on every GET rather
    than this one.
    """
    ident = clean_str(identifier)
    if not ident:
        return ''
    if ident.startswith('catalogue-module-'):
        ident = ident.replace('catalogue-module-', '', 1)
    if authoring_module_exists(ident):
        return ident
    return resolve_authoring_catalogue_id(ident) or ''


def training_module_identifier(training_id):
    return f'training-module-{clean_str(training_id)}'


def training_rows_by_id():
    return cached_curriculum_value(
        'training_rows_by_id',
        lambda: {clean_str(row.get('id')): row for row in get_training_rows() if clean_str(row.get('id'))},
    )


def training_row_by_id(training_id):
    ident = clean_str(training_id).replace('training-module-', '', 1)
    for row in authoring_modules_as_training_rows():
        candidates = {
            clean_str(row.get('id')),
            clean_str(row.get(TRAINING_MODULE_CATALOGUE_COLUMN)),
            clean_str(row.get('_meta', {}).get(TRAINING_MODULE_CATALOGUE_COLUMN)),
        }
        if ident in candidates or clean_str(training_id) in candidates:
            return row
    return None


def catalogue_for_training_row(row):
    catalogue_id = training_row_module_catalogue_id(row)
    module_name = normalise(row.get('module_name'))
    for module in get_module_rows():
        if catalogue_id and clean_str(module.get('Module ID')) == catalogue_id:
            return module
        if module_name and normalise(module.get('Module_name')) == module_name:
            return module
    return None


def authoring_row_for_training_source(training_id):
    return None


def attach_training_source_metadata(module_row, training_id):
    return


def authoring_row_for_training_legacy_ids(row):
    training_id = clean_str(row.get('id'))
    candidate_ids = [
        training_module_identifier(training_id),
        training_id,
        training_row_module_catalogue_id(row),
    ]
    for candidate_id in [item for item in candidate_ids if item]:
        existing = authoring_module_exists(candidate_id)
        if existing:
            if candidate_id in {training_module_identifier(training_id), training_id}:
                attach_training_source_metadata(existing, training_id)
                return authoring_row_for_training_source(training_id) or existing
            return existing
    return None


def ksb_mappings_from_codes(codes, scope):
    return [
        {
            'id': canonical_authoring_id('KSBMAP'),
            'ksbId': code,
            'code': code,
            'description': f'Mapped KSB {code}',
            'type': 'main' if index < 3 else 'secondary',
            'weight': 40 if index < 3 else 20,
        }
        for index, code in enumerate(sorted(codes))
    ]


def imported_training_module_payload(row):
    training_id = clean_str(row.get('id'))
    meta = row.get('_meta') or extract_notes_meta(row.get('notes'))
    catalogue = catalogue_for_training_row(row)
    session_count = max(parse_int(row.get('sessions_number'), parse_int((catalogue or {}).get('Number of sessions'), 1)), 1)
    session_names = get_module_session_names(catalogue or {})
    ksb_codes = codes_from_session_ksb(row.get('session_ksb_json')) or codes_from_session_ksb((catalogue or {}).get('session_ksb_json'))
    module_mappings = ksb_mappings_from_codes(ksb_codes, training_module_identifier(training_id))
    week_structure = []
    module_catalogue_id = unique_module_catalogue_id(training_row_module_catalogue_id(row))
    for index in range(session_count):
        week_id = canonical_authoring_id('WEEK')
        title = session_names[index] if index < len(session_names) else f'Week {index + 1}'
        component_mappings = module_mappings[:2]
        week_structure.append({
            'id': week_id,
            'moduleId': module_catalogue_id,
            'weekNumber': index + 1,
            'title': title or f'Week {index + 1}',
            'summary': '',
            'learningOutcomes': [],
            'ksbMappings': [],
            'components': [
                {
                    'id': canonical_authoring_id('COMP'),
                    'weekId': week_id,
                    'type': 'live-session',
                    'title': title or f'{row.get("module_name") or "Session"} #{index + 1}',
                    'description': 'Placeholder lesson derived from the existing delivery module.',
                    'expectedOtjh': 2,
                    'points': 10,
                    'reflectionRequired': False,
                    'workplaceEvidenceRequired': False,
                    'tutorValidationRequired': False,
                    'ksbMappings': component_mappings,
                    'settings': {'recordingExpected': True},
                }
            ],
        })

    try:
        programme_name = canonical_programme_name(row, program_config_by_id(get_program_config_rows()))
    except Exception:
        programme_name = row.get('Program') or 'Unassigned programme'
    cohort_identity = actual_cohort_identity(row, programme_name)
    group_identity = actual_group_identity(row, cohort_identity['id']) if cohort_identity else None

    return {
        'catalogueId': module_catalogue_id,
        'programmeId': row.get('Program') or programme_name,
        'programmeName': programme_name,
        'cohortId': (cohort_identity or {}).get('id') or '',
        'cohortName': (cohort_identity or {}).get('name') or '',
        'groupId': (group_identity or {}).get('id') or '',
        'groupName': (group_identity or {}).get('name') or '',
        'title': row.get('module_name') or (catalogue or {}).get('Module_name') or f'Module {training_id}',
        'description': visible_notes(row.get('notes') or (catalogue or {}).get('Notes') or ''),
        'status': 'published',
        'sessionsNumber': session_count,
        'startDate': row.get('start_date') or '',
        'endDate': row.get('end_date') or '',
        'declaredTotalOtjh': 0,
        'moduleKsbMappings': module_mappings,
        'completionCriteria': default_completion_payload(),
        'advancedDetails': {},
        'background': '',
        'epaRequirements': [],
        'qualificationOutcomes': [],
        'weekStructure': week_structure,
        'deliveryStatus': delivery_status_for_training_row(row),
        'deliveryMetadata': {
            'cohortId': (cohort_identity or {}).get('id') or '',
            'cohort': (cohort_identity or {}).get('name') or row.get('Cohort_name') or '',
            'groupId': (group_identity or {}).get('id') or '',
            'group': (group_identity or {}).get('name') or row.get('group_name') or meta.get('group_name') or '',
            'tutor': row.get('Tutor_name') or '',
            'coach': row.get('coach_name') or '',
        },
    }


def ensure_canonical_module_for_training_row(row, overrides=None):
    """Resolve or create the canonical authoring module for a delivery row."""
    overrides = overrides or {}
    module_name = clean_str(overrides.get('title') or overrides.get('moduleName') or row.get('module_name'))
    if not module_name:
        return ''
    invalid_explicit_id = training_row_invalid_explicit_module_catalogue_id(row)
    if invalid_explicit_id:
        raise ValueError(f'training_plan {row.get("id")} has invalid explicit module_catalogue_id {invalid_explicit_id}.')
    existing_catalogue_id = training_row_module_catalogue_id(row)
    if existing_catalogue_id:
        if authoring_module_exists(existing_catalogue_id):
            return existing_catalogue_id
        raise ValueError(f'training_plan {row.get("id")} references missing canonical module {existing_catalogue_id}.')

    base_payload = imported_training_module_payload({**row, 'module_name': module_name})
    payload = {
        **base_payload,
        **overrides,
        'title': module_name,
    }
    existing = find_existing_authoring_catalogue_id_for_payload(payload)
    if existing:
        link_training_row_to_catalogue(row.get('id'), existing)
        return existing

    saved = save_module_authoring_structure(payload.get('catalogueId') or '', payload)
    catalogue_id = clean_str(saved.get('catalogueId') or payload.get('catalogueId'))
    if catalogue_id:
        link_training_row_to_catalogue(row.get('id'), catalogue_id)
    return catalogue_id


def resolve_authoring_catalogue_id(identifier):
    ident = clean_str(identifier)
    if not ident:
        return ''
    summaries = authoring_catalogue_summaries(include_programme_deleted=True)
    if not summaries:
        return ''

    candidates = []

    def add_candidate(summary):
        if summary and summary not in candidates:
            candidates.append(summary)

    for summary in summaries.values():
        summary_identifiers = {
            clean_str(summary.get('catalogueId')),
            clean_str(summary.get('sourceId')),
        }
        if summary.get('sourceId'):
            summary_identifiers.add(training_module_identifier(summary.get('sourceId')))
        if ident in summary_identifiers:
            add_candidate(summary)

    if ident.startswith('training-module-'):
        training_id = ident.replace('training-module-', '', 1)
        row = training_row_by_id(training_id)
        if row:
            meta = row.get('_meta') or extract_notes_meta(row.get('notes'))
            legacy_ids = {
                training_id,
                training_module_identifier(training_id),
                training_row_module_catalogue_id(row),
            }
            try:
                programme_name = canonical_programme_name(row, program_config_by_id(get_program_config_rows()))
            except Exception:
                programme_name = row.get('Program') or 'Unassigned programme'
            cohort_identity = actual_cohort_identity(row, programme_name)
            group_identity = actual_group_identity(row, cohort_identity['id']) if cohort_identity else None
            delivery_signature = '|'.join([
                normalise(programme_name),
                normalise(row.get('module_name')),
                normalise((cohort_identity or {}).get('id') or (cohort_identity or {}).get('name')),
                normalise((group_identity or {}).get('id') or (group_identity or {}).get('name')),
            ])
            for summary in summaries.values():
                summary_identifiers = {
                    clean_str(summary.get('catalogueId')),
                    clean_str(summary.get('sourceId')),
                }
                if summary_identifiers.intersection(legacy_ids):
                    add_candidate(summary)
                    continue
                if delivery_signature and authoring_summary_delivery_signature(summary) == delivery_signature:
                    add_candidate(summary)

    best = best_authoring_summary(candidates)
    return clean_str(best.get('catalogueId')) if best else ''


def ensure_training_module_authoring_structure(module_identifier):
    if not clean_str(module_identifier).startswith('training-module-'):
        return None
    training_id = clean_str(module_identifier).replace('training-module-', '', 1)
    row = training_row_by_id(training_id)
    if not row:
        return None

    source_row = authoring_row_for_training_source(training_id)
    if source_row:
        return get_authoring_structure_payload(source_row.get('module_catalogue_id'))

    existing_catalogue_id = resolve_authoring_catalogue_id(module_identifier)
    if existing_catalogue_id:
        return get_authoring_structure_payload(existing_catalogue_id)

    payload = imported_training_module_payload(row)
    return save_module_authoring_structure(payload['catalogueId'], payload)


def component_builder_settings(row):
    settings = as_json_value(row.get('settings_json'), {})
    settings = settings if isinstance(settings, dict) else {}
    if frontend_component_type(row.get('type')) == 'live-session':
        from .teams_external_calendar import meeting_settings
        settings = meeting_settings(settings)
    stored_live_link = clean_str(row.get('live_sessions_link'))
    if stored_live_link and not clean_str(settings.get('liveSessionUrl')):
        settings = {**settings, 'liveSessionUrl': stored_live_link}
    return settings


def component_reflection_question(row, settings=None):
    """The reflection question stored against a component row.

    The column is the source of truth. Rows written before it existed kept the
    same text under ``settings_json.reflectionPrompt``, so that is the fallback
    - and a narrowed read that skipped ``settings_json`` simply falls back to
    nothing rather than reporting the question as cleared.
    """
    stored = clean_str(row.get(REFLECTION_QUESTION_COLUMN))
    if stored:
        return stored
    if settings is None:
        settings = component_builder_settings(row)
    settings = settings if isinstance(settings, dict) else {}
    return clean_str(settings.get(LEGACY_REFLECTION_QUESTION_SETTING))


def payload_reflection_question(component, settings=None):
    """The reflection question a component payload is asking us to store.

    ``reflectionQuestion`` is what the builders send, and an explicit empty
    string there clears the question. A payload that names neither spelling is
    older than the field, so its legacy ``settings.reflectionPrompt`` stands in.
    """
    if 'reflectionQuestion' in component or 'reflection_question' in component:
        return clean_str(component.get('reflectionQuestion') or component.get('reflection_question'))
    if settings is None:
        settings = component.get('settings')
    settings = settings if isinstance(settings, dict) else {}
    return clean_str(settings.get(LEGACY_REFLECTION_QUESTION_SETTING))


def component_coach_validation(row):
    """Whether a coach has to validate this component.

    On unless the row says otherwise. The column arrived after the table, so a
    row written before it - or a narrowed read that never selected it - reports
    ``None``, and that means "nobody turned it off", not "off".
    """
    value = row.get('coach_validation_required')
    return True if value is None else bool_payload(value)


def payload_coach_validation(component, default=True):
    """What a component payload is asking us to store for coach validation.

    Either spelling counts, and an explicit ``False`` turns it off. A payload
    naming neither is older than the field, so the default stands rather than
    silently clearing a flag the author never saw.
    """
    for key in ('coachValidationRequired', 'coach_validation_required'):
        if key in component:
            return bool_payload(component.get(key))
    return default


def component_assurance_flag(component, stored_row, camel_key, column, default):
    """One assurance flag, resolved without inventing an answer.

    The three flags - reflection, tutor validation, coach validation - are
    authored on one screen and written by two different save paths, and the
    module-structure save rewrites every component in the module whether or not
    the author touched it. So the only safe reading of a payload that does not
    mention a flag is "not supplied", and the only safe response is to keep what
    the row already held.

    It used to read ``bool_payload(component.get('reflectionRequired'))``, which
    cannot tell an explicit ``false`` from an absent key and answered ``False``
    to both, while coach validation defaulted the other way and answered
    ``True``. A component object that had lost the two keys therefore came back
    from a save with reflection cleared and coach validation switched on -- and
    because the two defaults point in opposite directions, the pair flipped
    together in opposite directions, over and over, as the author moved between
    a screen that carried the flags and one that did not. It is visible in the
    revision log as ~1,100 paired flips across 600 components.

    The schema default is used only when there is no stored row to preserve,
    which is to say only when this component is being created.
    """
    for key in (camel_key, column):
        if key in component:
            return bool_payload(component.get(key))
    if stored_row is None:
        return default
    stored = stored_row.get(column)
    # A row written before the column existed reports None, and that means
    # "nobody ever set this", not "off" - the same reading component_coach_validation
    # applies to a narrowed read.
    return default if stored is None else bool_payload(stored)


def component_week_label(row):
    week_number = parse_int(row.get('week_number'), 0)
    return f'Week {week_number}' if week_number else (row.get('title') or 'Week 1')


def parse_week_number(value):
    match = re.search(r'\d+', str(value or ''))
    return max(1, parse_int(match.group(0), 1)) if match else 1


def component_context_for_payload(payload):
    ensure_module_authoring_tables()
    module_catalogue_id = clean_str(payload.get('moduleCatalogueId') or payload.get('module_catalogue_id'))
    module_title = clean_str(payload.get('module') or payload.get('moduleTitle') or payload.get('title'))
    programme_name = clean_str(payload.get('programme') or payload.get('programmeName')) or 'Unassigned programme'
    if module_catalogue_id:
        module_row = authoring_module_exists(module_catalogue_id)
    else:
        candidates = authoring_fetch_all(AUTHORING_MODULES_TABLE)
        module_row = next(
            (
                row for row in candidates
                if normalise(row.get('title')) == normalise(module_title)
                and normalise(row.get('programme_name')) == normalise(programme_name)
            ),
            None,
        )
        module_catalogue_id = clean_str((module_row or {}).get('module_catalogue_id'))

    if not module_catalogue_id:
        module_catalogue_id = unique_module_catalogue_id()

    if not module_row:
        authoring_upsert(AUTHORING_MODULES_TABLE, ['module_catalogue_id'], {
            'module_catalogue_id': module_catalogue_id,
            'programme_id': programme_name,
            'programme_name': programme_name,
            'title': module_title or f'Module {module_catalogue_id}',
            'description': '',
            'status': 'draft',
            'sessions_number': 0,
            'total_otjh': 0,
            'quality_score': 0,
            'source_type': 'component_builder',
        })

    week_number = parse_week_number(payload.get('week') or payload.get('weekLabel') or payload.get('weekNumber'))
    week_rows = authoring_fetch_all(
        AUTHORING_WEEKS_TABLE,
        'module_catalogue_id = %s and week_number = %s',
        [module_catalogue_id, week_number],
    )
    week_id = clean_str(payload.get('weekId') or payload.get('week_id') or (week_rows[0].get('id') if week_rows else ''))
    if not week_id:
        week_id = canonical_authoring_id('WEEK')

    if not week_rows:
        authoring_upsert(AUTHORING_WEEKS_TABLE, ['id'], {
            'id': week_id,
            'module_catalogue_id': module_catalogue_id,
            'week_number': week_number,
            'title': f'Week {week_number}',
            'summary': '',
            'learning_outcomes': json_db_value([]),
            'display_order': week_number - 1,
        })

    return module_catalogue_id, week_id, week_number


def component_builder_response(row, module_by_id=None, week_by_id=None, mappings_by_component=None):
    module_by_id = module_by_id or {}
    week_by_id = week_by_id or {}
    mappings_by_component = mappings_by_component or {}
    component_id = str(row.get('id'))
    module = module_by_id.get(str(row.get('module_catalogue_id')), {})
    week = week_by_id.get(str(row.get('week_id')), {})
    settings = component_builder_settings(row)
    duration = parse_int(settings.get('durationMinutes'), 0) or round(float(row.get('expected_otjh') or 0) * 60)
    expected_otjh = float(row.get('expected_otjh') or 0)
    mapping_rows = mappings_by_component.get(component_id, [])
    ksb_mappings = [component_ksb_mapping_api_item(mapping) for mapping in component_ksb_mappings_from_row(row, mapping_rows)]
    ksb_refs = [mapping.get('code') for mapping in ksb_mappings if mapping.get('code')]
    return {
        'id': component_id,
        'moduleCatalogueId': str(row.get('module_catalogue_id') or ''),
        'moduleId': str(row.get('module_catalogue_id') or ''),
        'weekId': str(row.get('week_id') or ''),
        'title': row.get('title') or '',
        'description': row.get('description') or '',
        'type': settings.get('displayType') or display_component_type(row.get('type')),
        'displayOrder': parse_int(row.get('display_order'), 0),
        'module': module.get('title') or '',
        'programme': module.get('programme_name') or 'Unassigned programme',
        'week': component_week_label(week),
        'weekTitle': week.get('title') or component_week_label(week),
        'duration': duration,
        'expectedOtjh': expected_otjh,
        'reflectionRequired': bool(row.get('reflection_required')),
        'workplaceEvidenceRequired': bool(row.get('workplace_evidence_required')),
        'tutorValidationRequired': bool(row.get('tutor_validation_required')),
        'expectedOtjh': float(row.get('expected_otjh') or 0),
        'points': parse_int(row.get('points'), 0),
        'isDeleted': programme_deleted_row(row),
        'deletedAt': row.get('deleted_at'),
        'deletedViaParent': row.get('deleted_via_parent') or '',
        'reflectionRequired': bool_payload(row.get('reflection_required')),
        'reflectionQuestion': component_reflection_question(row, settings),
        'workplaceEvidenceRequired': bool_payload(row.get('workplace_evidence_required')),
        'tutorValidationRequired': bool_payload(row.get('tutor_validation_required')),
        'coachValidationRequired': component_coach_validation(row),
        'ksbRefs': ksb_refs,
        'ksbMappings': ksb_mappings,
        'status': settings.get('componentBuilderStatus') or 'draft',
        'lastEdited': format_date(row.get('updated_at')),
        'contentSections': parse_int(settings.get('contentSections'), 0),
        'quizQuestions': parse_int(settings.get('quizQuestions'), 0) or None,
        'hasResources': bool_payload(settings.get('hasResources')),
        'settings': settings,
    }


def sort_rows_by_updated_at_desc(rows):
    """Reproduce ``order by updated_at desc`` on rows already sorted by the
    remaining ``order by`` terms.

    Two details make this equal to the database rather than merely similar.
    Postgres sorts ``desc`` as NULLS FIRST, so a row that has never been
    stamped leads; the key below puts ``None`` in its own group that ranks
    above every real timestamp. And ``sorted`` is stable, so rows sharing an
    ``updated_at`` keep the ``display_order, id`` order they arrived in --
    which is exactly what the trailing sort terms did.
    """
    return sorted(
        rows,
        key=lambda row: (1, None) if row.get('updated_at') is None else (0, row.get('updated_at')),
        reverse=True,
    )


def component_builder_rows(module_catalogue_ids=None, omit_content=False):
    """The component builder rows, whole; or with ``omit_content``, exactly as
    component_rows_without_content() would project them, with the long text
    stripped in the database where it can be (live_component_rows_without_content).
    """
    catalogue_ids = [clean_str(value) for value in (module_catalogue_ids or []) if clean_str(value)]
    stripped_rows = live_component_rows_without_content(catalogue_ids) if omit_content else None
    if stripped_rows is None:
        rows = _component_builder_rows(catalogue_ids)
        return component_rows_without_content(rows) if omit_content else rows
    db_omitted_by_id = {
        str(row.get('id')): list(row.pop(COMPONENT_DB_OMITTED_KEYS_COLUMN, None) or [])
        for row in stripped_rows
    }
    projected = []
    for row in _component_builder_rows(catalogue_ids, stripped_rows):
        db_omitted = db_omitted_by_id.get(str(row.get('id'))) or []
        # Anything the database could not strip (a settings document stored
        # as a JSON string) is still taken out here, so the result never
        # depends on which path removed the text.
        row = component_rows_without_content([row])[0]
        omitted = [
            key for key in COMPONENT_CONTENT_SETTING_KEYS
            if key in db_omitted or key in (row.get(COMPONENT_SETTINGS_OMITTED_FLAG) or [])
        ]
        if omitted:
            row = {**row, COMPONENT_SETTINGS_OMITTED_FLAG: omitted}
        projected.append(row)
    return projected


def _component_builder_rows(catalogue_ids, component_rows=None):
    ensure_module_authoring_tables()
    where_sql = ''
    params = []
    if catalogue_ids:
        where_sql = f'module_catalogue_id in ({", ".join(["%s"] * len(catalogue_ids))})'
        params = catalogue_ids
    # Read in the same order as get_authoring_structure_payloads() and re-sort
    # here. order_sql is part of the read memo key, so asking for a second sort
    # of the identical rows made the programme detail build fetch every
    # component for the programme twice -- ~28 s of a 64 s build. Ordering the
    # list is this reader's own concern, not the database's.
    # Paged and live-only on the database side; see live_component_rows_paged.
    # Same arguments as the structure reader, so a detail build shares the read.
    if component_rows is None:
        component_rows = live_component_rows_paged(catalogue_ids or None, 'display_order, id')
    component_rows = active_component_rows(component_rows)
    component_rows = sort_rows_by_updated_at_desc(component_rows)
    module_rows = authoring_fetch_all(AUTHORING_MODULES_TABLE, where_sql, params) if catalogue_ids else authoring_fetch_all(AUTHORING_MODULES_TABLE)
    week_rows = active_week_rows(authoring_fetch_all(AUTHORING_WEEKS_TABLE, where_sql, params) if catalogue_ids else authoring_fetch_all(AUTHORING_WEEKS_TABLE))
    mapping_rows = active_mapping_rows(authoring_fetch_all(AUTHORING_KSB_MAPPINGS_TABLE, where_sql, params) if catalogue_ids else authoring_fetch_all(AUTHORING_KSB_MAPPINGS_TABLE))
    mapping_rows = mappings_with_inferred_sources(mapping_rows, module_rows)
    module_by_id = {str(row.get('module_catalogue_id')): row for row in module_rows}
    week_by_id = {str(row.get('id')): row for row in week_rows}
    mappings_by_component = defaultdict(list)
    for row in mapping_rows:
        if row.get('component_id'):
            mappings_by_component[str(row.get('component_id'))].append(row)
    return [
        component_builder_response(row, module_by_id, week_by_id, mappings_by_component)
        for row in component_rows
    ]


# The component columns the summary reads: what active_component_rows() filters
# on, what component_builder_response() derives week/OTJH/order from, and no
# more. settings_json is reduced to its one status key in the query itself.
COMPONENT_SUMMARY_COLUMNS = (
    'id', 'module_catalogue_id', 'week_id', 'type', 'title', 'display_order',
    'expected_otjh', 'deleted_at', 'is_programme_deleted', 'is_deleted',
    'library_state',
)
COMPONENT_SUMMARY_WEEK_COLUMNS = (
    'id', 'module_catalogue_id', 'week_number', 'title',
    'deleted_at', 'is_programme_deleted', 'is_deleted', 'library_state',
)
COMPONENT_SUMMARY_MODULE_COLUMNS = ('module_catalogue_id', 'title', 'programme_name')


def js_round(value):
    """``Math.round`` exactly: halves go up, towards +infinity, never to even."""
    whole = math.floor(value)
    return whole + 1 if value - whole >= 0.5 else whole


def component_summary_source_rows(catalogue_ids):
    """The live component rows of ``catalogue_ids``, reduced to what the summary reads.

    The same rows component_builder_rows() returns -- the Postgres-side filter
    of live_component_rows_paged(), then active_component_rows() -- without
    the authored content, the KSB mappings, or any column the summary never
    looks at. Each row stands for ``_count`` components (1 unless grouped)
    and says how many of them are published in ``_published``.

    On Postgres identical rows are grouped by the database, so the largest
    programme's ~17k components arrive as roughly one row per week instead of
    one per component: the statement itself runs in ~0.2 s there, and shipping
    every row to the application was most of a multi-second read. Two things
    stay per component on purpose: ``expected_otjh`` is grouped on its stored
    value and converted to minutes here, so the rounding is the browser's
    double arithmetic and never Postgres numeric's; and a settings document
    stored as a JSON string (not an object) is read row by row and parsed by
    component_builder_settings(), exactly as the full read parses it.
    """
    columns = column_names(AUTHORING_COMPONENTS_TABLE)
    placeholders = ', '.join(['%s'] * len(catalogue_ids))
    clauses = [f'module_catalogue_id in ({placeholders})']
    if connection.vendor != 'postgresql' or 'settings_json' not in columns:
        wanted = [column for column in COMPONENT_SUMMARY_COLUMNS if column in columns]
        rows = authoring_fetch_all(
            AUTHORING_COMPONENTS_TABLE, clauses[0], list(catalogue_ids),
            columns=[*wanted, 'settings_json'] if 'settings_json' in columns else wanted,
        )
        return [
            {**row, '_count': 1, '_published': component_is_published(row)}
            for row in active_component_rows(rows)
        ]
    if 'deleted_at' in columns:
        clauses.append(f'{quote_ident("deleted_at")} is null')
    if 'is_programme_deleted' in columns:
        clauses.append(f'{quote_ident("is_programme_deleted")} is not true')
    where = ' and '.join(f'({clause})' for clause in clauses)
    table = authoring_table_name(AUTHORING_COMPONENTS_TABLE)
    settings = quote_ident('settings_json')
    # Every column active_component_rows() and the bucket key read; a column
    # this table does not carry is selected as null, as a row without it reads.
    key_columns = [
        'module_catalogue_id', 'week_id', 'type', 'library_state',
        'is_programme_deleted', 'is_deleted', 'expected_otjh',
    ]
    key_select = ', '.join(
        f'{quote_ident(column)} as {quote_ident(column)}' if column in columns else f'null as {quote_ident(column)}'
        for column in key_columns
    )
    group_by = ', '.join(str(index) for index in range(1, len(key_columns) + 2))
    published = f"coalesce(({settings} ->> 'componentBuilderStatus') = 'published', false)"
    rows = fetch_all(
        f'select {key_select}, {published} as {quote_ident("_published_flag")},'
        f' count(*) as {quote_ident("_count")},'
        f' min(display_order) as {quote_ident("display_order")},'
        f' (array_agg(title order by display_order, title))[1] as {quote_ident("title")}'
        f' from {table} where {where}'
        f" and ({settings} is null or jsonb_typeof({settings}) = 'object')"
        f' group by {group_by}',
        list(catalogue_ids),
    )
    grouped = []
    for row in rows:
        count = int(row.pop('_count') or 0)
        flag = bool(row.pop('_published_flag'))
        grouped.append({**row, '_count': count, '_published': count if flag else 0})
    wanted = [column for column in COMPONENT_SUMMARY_COLUMNS if column in columns]
    loose = fetch_all(
        f'select {", ".join(quote_ident(column) for column in wanted)}, {settings}'
        f' from {table} where {where}'
        f" and {settings} is not null and jsonb_typeof({settings}) <> 'object'",
        list(catalogue_ids),
    )
    loose = [{**row, '_count': 1, '_published': component_is_published(row)} for row in loose]
    return active_component_rows(grouped + loose)


def component_is_published(row):
    """1 when component_builder_response() would report this row 'published', else 0."""
    return 1 if (component_builder_settings(row).get('componentBuilderStatus') or 'draft') == 'published' else 0


def component_summary_rows(module_catalogue_ids):
    """Programme-page component figures, one row per module/week/programme bucket.

    Every figure the programme Overview derives from its component list -- how
    many components, how many published, the Expected OTJH, which weeks hold
    any -- without sending the ~17k components of the largest programme to
    the browser to be counted there. Each row carries the fields the page
    matches and buckets a component by (moduleCatalogueId/moduleId, module,
    programme, weekId, week, weekTitle), with the same values
    component_builder_response() gives every component in it, plus:

    ``count``          components in the bucket;
    ``publishedCount`` of those, the ones whose builder status is 'published';
    ``otjhMinutes``    sum over them of ``max(0, Math.round(expectedOtjh * 60))``,
                       the per-component minute rounding the page applies;
    ``displayOrder`` / ``title``  of the bucket's first component in the order
                       the page sorts a week by, so a week's fallback title can
                       be taken from the same component.
    """
    catalogue_ids = sorted({clean_str(value) for value in (module_catalogue_ids or []) if clean_str(value)})
    if not catalogue_ids:
        return []
    ensure_module_authoring_tables()
    where_sql = f'module_catalogue_id in ({", ".join(["%s"] * len(catalogue_ids))})'
    component_rows = component_summary_source_rows(catalogue_ids)
    module_rows = authoring_fetch_all(AUTHORING_MODULES_TABLE, where_sql, catalogue_ids, columns=list(COMPONENT_SUMMARY_MODULE_COLUMNS))
    week_rows = active_week_rows(authoring_fetch_all(AUTHORING_WEEKS_TABLE, where_sql, catalogue_ids, columns=list(COMPONENT_SUMMARY_WEEK_COLUMNS)))
    module_by_id = {str(row.get('module_catalogue_id')): row for row in module_rows}
    week_by_id = {str(row.get('id')): row for row in week_rows}
    buckets = {}
    for row in component_rows:
        module = module_by_id.get(str(row.get('module_catalogue_id')), {})
        week = week_by_id.get(str(row.get('week_id')), {})
        catalogue_id = str(row.get('module_catalogue_id') or '')
        key = (
            catalogue_id,
            str(row.get('week_id') or ''),
            component_week_label(week),
            week.get('title') or component_week_label(week),
            module.get('title') or '',
            module.get('programme_name') or 'Unassigned programme',
        )
        bucket = buckets.get(key)
        if bucket is None:
            bucket = buckets[key] = {
                'moduleCatalogueId': key[0], 'moduleId': key[0], 'weekId': key[1],
                'week': key[2], 'weekTitle': key[3], 'module': key[4], 'programme': key[5],
                'count': 0, 'publishedCount': 0, 'otjhMinutes': 0,
                'displayOrder': None, 'title': '',
            }
        count = int(row.get('_count') or 0)
        bucket['count'] += count
        bucket['publishedCount'] += int(row.get('_published') or 0)
        bucket['otjhMinutes'] += count * max(0, js_round(float(row.get('expected_otjh') or 0) * 60))
        order = parse_int(row.get('display_order'), 0)
        title = row.get('title') or ''
        if bucket['displayOrder'] is None or (order, title) < (bucket['displayOrder'], bucket['title']):
            bucket['displayOrder'] = order
            bucket['title'] = title
    return list(buckets.values())


LIBRARY_ORIGIN_ACTIVE = 'active'
LIBRARY_ORIGIN_ARCHIVED = 'archived'
LIBRARY_ORIGIN_LIBRARY = 'library'
LIBRARY_ORIGINS = (LIBRARY_ORIGIN_ACTIVE, LIBRARY_ORIGIN_ARCHIVED, LIBRARY_ORIGIN_LIBRARY)


def library_component_origin(row):
    """Which bucket of the reuse library this component sits in.

    ``library`` wins over ``archived``: a detached row has its soft-delete
    stamps cleared on purpose, so the two are mutually exclusive in practice,
    but ordering the checks makes that explicit rather than incidental.
    """
    if is_library_row(row):
        return LIBRARY_ORIGIN_LIBRARY
    if programme_deleted_row(row):
        return LIBRARY_ORIGIN_ARCHIVED
    return LIBRARY_ORIGIN_ACTIVE


# Columns the picker list needs. Deliberately excludes settings_json, which
# holds inlined authoring content - up to 200 kB on a single reading component
# and 24 MB across the table. The picker shows titles; only the components
# actually being copied need their settings, and those are fetched by id.
LIBRARY_LIST_COLUMNS = (
    'id', 'week_id', 'module_catalogue_id', 'type', 'title', 'display_order',
    'expected_otjh', 'points', 'reflection_required', 'workplace_evidence_required',
    'tutor_validation_required', 'coach_validation_required',
    'updated_at', 'deleted_at', 'is_programme_deleted',
    'library_state', 'detached_at', 'copied_from_id',
    'origin_module_catalogue_id', 'origin_module_title',
    'origin_week_id', 'origin_week_label',
)
LIBRARY_PAGE_SIZE_DEFAULT = 50
LIBRARY_PAGE_SIZE_MAX = 200


def library_component_where(*, search='', types=None, origins=None, ids=None):
    """The SQL predicate for a library search. Everything filters in the database.

    Origin is expressed in SQL rather than in Python so that the LIMIT applies
    to the rows the caller actually asked for. ``library_state`` and the
    soft-delete columns are what separate the three buckets.
    """
    clauses = []
    params = []
    wanted_ids = sorted({clean_str(value) for value in (ids or []) if clean_str(value)})
    if wanted_ids:
        placeholders = ', '.join(['%s'] * len(wanted_ids))
        clauses.append(f'id in ({placeholders})')
        params.extend(wanted_ids)
    search = clean_str(search).lower()
    if search:
        # lower(...) like ... rather than ilike, so the same SQL runs on the
        # SQLite test database as on Postgres.
        clauses.append(
            "(lower(coalesce(title, '')) like %s or lower(coalesce(description, '')) like %s)"
        )
        params.extend([f'%{search}%'] * 2)
    wanted_types = sorted({normalise_component_type(value) for value in (types or []) if clean_str(value)})
    if wanted_types:
        placeholders = ', '.join(['%s'] * len(wanted_types))
        clauses.append(f'type in ({placeholders})')
        params.extend(wanted_types)
    retired = sorted(RETIRED_COMPONENT_TYPES)
    if retired:
        # Retired types cannot be authored any more, so reusing one is a dead end.
        placeholders = ', '.join(['%s'] * len(retired))
        clauses.append(f'type not in ({placeholders})')
        params.extend(retired)

    wanted_origins = {clean_str(value).lower() for value in (origins or []) if clean_str(value)}
    wanted_origins = wanted_origins & set(LIBRARY_ORIGINS) or set(LIBRARY_ORIGINS)
    if wanted_origins != set(LIBRARY_ORIGINS):
        # Only the 'library' bucket needs library_state. Active-vs-archived is
        # decided by the soft-delete columns alone, so this must NOT be gated on
        # that column: before migration 0053 it made the whole filter a no-op and
        # unticking a bucket appeared to do nothing at all.
        if has_column(AUTHORING_COMPONENTS_TABLE, 'library_state'):
            detached = f"coalesce({quote_ident('library_state')}, '') = '{LIBRARY_STATE_DETACHED}'"
        else:
            # No column means nothing can be detached yet.
            detached = 'false'
        archived = deleted_sql_condition(AUTHORING_COMPONENTS_TABLE)
        origin_sql = {
            LIBRARY_ORIGIN_LIBRARY: f'({detached})',
            LIBRARY_ORIGIN_ARCHIVED: f'(not ({detached}) and ({archived}))',
            LIBRARY_ORIGIN_ACTIVE: f'(not ({detached}) and not ({archived}))',
        }
        # No placeholders here on purpose: every fragment is built from module
        # constants, so there is nothing to bind and nothing to get out of order
        # with the clauses appended above.
        clauses.append('(' + ' or '.join(
            origin_sql[origin] for origin in sorted(wanted_origins) if origin in origin_sql
        ) + ')')
    return ' and '.join(clauses), params


def rows_for_ids(table, column, values):
    """Fetch just the rows these ids name. No ids means no query at all."""
    wanted = sorted({clean_str(value) for value in (values or []) if clean_str(value)})
    if not wanted or not table_exists(table):
        return []
    placeholders = ', '.join(['%s'] * len(wanted))
    return fetch_all(
        f'select * from {authoring_table_name(table)} where {quote_ident(column)} in ({placeholders})',
        wanted,
    )


def library_component_rows(*, search='', types=None, programme_ids=None, origins=None,
                           ids=None, page=1, page_size=LIBRARY_PAGE_SIZE_DEFAULT, detail=False):
    """Components available for reuse, across every programme ever authored.

    Deliberately does NOT go through ``active_component_rows``: archived and
    detached content is the point of this read, and that filter is exactly what
    removes it.

    Every filter and the page window are pushed into SQL, and the list omits
    ``settings_json``. That is not a micro-optimisation. ``curriculum.components``
    holds ~18k rows and 39 MB, 24 MB of it ``settings_json``, and the database is
    remote: reading the table in full measured ~90 s against ~190 ms for a
    narrow, limited read.

    ``detail=True`` returns the heavy authoring fields (``settings``,
    ``ksbMappings``) and is meant to be called with ``ids``, for the handful of
    components actually being copied.
    """
    ensure_module_authoring_tables()
    where_sql, params = library_component_where(search=search, types=types, origins=origins, ids=ids)
    page = max(1, parse_int(page, 1))
    page_size = min(LIBRARY_PAGE_SIZE_MAX, max(1, parse_int(page_size, LIBRARY_PAGE_SIZE_DEFAULT)))

    if detail:
        columns = '*'
    else:
        columns = ', '.join(
            quote_ident(column) for column in LIBRARY_LIST_COLUMNS
            if has_column(AUTHORING_COMPONENTS_TABLE, column)
        )
    query = f'select {columns} from {authoring_table_name(AUTHORING_COMPONENTS_TABLE)}'
    if where_sql:
        query += f' where {where_sql}'
    query += ' order by updated_at desc, display_order, id limit %s offset %s'
    component_rows = fetch_all(query, [*params, page_size, (page - 1) * page_size])
    if not component_rows:
        return []

    # Look up only the parents this page refers to. A detached component's module
    # row may be long gone and an archived one's module is archived too, so these
    # cannot go through the active-only helpers.
    module_by_id = {
        str(row.get('module_catalogue_id')): row
        for row in rows_for_ids(
            AUTHORING_MODULES_TABLE, 'module_catalogue_id',
            {clean_str(row.get('module_catalogue_id')) for row in component_rows},
        )
    }
    week_by_id = {
        str(row.get('id')): row
        for row in rows_for_ids(
            AUTHORING_WEEKS_TABLE, 'id',
            {clean_str(row.get('week_id')) for row in component_rows},
        )
    }
    mappings_by_component = defaultdict(list)
    if detail:
        for row in rows_for_ids(
            AUTHORING_KSB_MAPPINGS_TABLE, 'component_id',
            {clean_str(row.get('id')) for row in component_rows},
        ):
            mappings_by_component[str(row.get('component_id'))].append(row)

    wanted_programmes = {clean_str(value) for value in (programme_ids or []) if clean_str(value)}
    results = []
    for row in component_rows:
        module = module_by_id.get(str(row.get('module_catalogue_id')), {})
        week = week_by_id.get(str(row.get('week_id')), {})
        # Once the parents are gone the denormalised origin stamps are the only
        # source. Note this cannot be written as ``payload['week'] or fallback``:
        # component_week_label({}) returns a plausible-looking "Week 1" for a
        # missing week, which would quietly mislabel every detached component.
        module_title = clean_str(module.get('title')) if module else clean_str(row.get('origin_module_title'))
        week_label = component_week_label(week) if week else clean_str(row.get('origin_week_label'))
        module_id = clean_str(row.get('module_catalogue_id')) or clean_str(row.get('origin_module_catalogue_id'))
        if wanted_programmes and clean_str(module.get('programme_id')) not in wanted_programmes:
            continue
        payload = component_builder_response(row, module_by_id, week_by_id, mappings_by_component)
        payload.update({
            'origin': library_component_origin(row),
            # component_builder_response puts a human label in `type`
            # ("Self-study"), which cannot be copied into a new component.
            # The authoring type is the hyphenated machine value.
            'componentType': frontend_component_type(row.get('type')),
            'originModuleCatalogueId': module_id,
            'originModuleTitle': module_title,
            'originWeekId': clean_str(row.get('week_id')) or clean_str(row.get('origin_week_id')),
            'originWeekLabel': week_label,
            'detachedAt': row.get('detached_at'),
            'copiedFromId': clean_str(row.get('copied_from_id')),
            'module': module_title,
            'week': week_label,
            'weekTitle': clean_str(week.get('title')) if week else week_label,
        })
        results.append(payload)
    return results


@csrf_exempt
def curriculum_component_library(request):
    """Read-only search over every component that could be reused.

    Two modes. Without ``ids`` this is the picker list: narrow columns, one page
    at a time. With ``ids`` it returns full authoring detail for those
    components only - what a caller needs to copy them. The split exists because
    ``settings_json`` is 24 MB across this table and the list never shows it.

    Paging is applied in SQL here, so the response is built without going
    through ``paginate_curriculum_results`` (which slices an already-built list).
    """
    if request.method != 'GET':
        return json_error('Method not allowed.', status=405)
    ids = csv_param(request, 'ids', 'id')
    page = parse_int(request.GET.get('page'), 1)
    page_size = parse_int(
        request.GET.get('page_size') or request.GET.get('pageSize'),
        LIBRARY_PAGE_SIZE_DEFAULT,
    )
    try:
        rows = library_component_rows(
            search=request.GET.get('search') or request.GET.get('q') or '',
            types=csv_param(request, 'types', 'type'),
            programme_ids=csv_param(request, 'programme_ids', 'programmeIds'),
            origins=csv_param(request, 'origins', 'origin'),
            ids=ids,
            page=page,
            # An ids request wants exactly those rows, not a page of them.
            page_size=len(ids) if ids else page_size,
            detail=bool(ids) or truthy(request.GET.get('detail')),
        )
    except Exception:
        logger.exception('Unable to load the component reuse library.')
        return json_error('Unable to load the component library.', status=500)
    return JsonResponse({
        'schema': CURRICULUM_SCHEMA,
        'count': len(rows),
        'results': rows,
        'page': max(1, page),
        'pageSize': page_size,
        # A full page back suggests there is more; the alternative is a count(*)
        # over the same predicate on every keystroke.
        'hasNext': not ids and len(rows) >= min(LIBRARY_PAGE_SIZE_MAX, max(1, page_size)),
    })


def csv_param(request, *names):
    """Read a repeated-or-comma-separated query parameter."""
    values = []
    for name in names:
        for raw in request.GET.getlist(name):
            values.extend(clean_str(part) for part in str(raw).split(',') if clean_str(part))
    return values


def save_component_builder_payload(payload, component_id=None):
    if is_retired_component_type(payload.get('type')):
        raise ModuleAuthoringValidationError([{
            'path': 'type',
            'message': 'This component type has been removed from the module builder.',
        }])
    # Settings merge key by key below, so a missing key keeps the stored value;
    # refused anyway, so a partial read can never be the source of a save.
    partial_errors = partial_read_errors(payload)
    if partial_errors:
        raise ModuleAuthoringValidationError(partial_errors)
    component_id = canonical_authoring_id('COMP', component_id or payload.get('id'))
    module_catalogue_id, week_id, week_number = component_context_for_payload(payload)
    duration_minutes = max(0, parse_int(payload.get('duration'), 0))
    component_rows = authoring_fetch_all(AUTHORING_COMPONENTS_TABLE, 'id = %s', [component_id])
    existing_row = component_rows[0] if component_rows else {}
    existing_expected_otjh = parse_float(existing_row.get('expected_otjh'), 2)
    expected_otjh = (
        parse_float(payload.get('expectedOtjh') or payload.get('expected_otjh'), existing_expected_otjh)
        if payload.get('expectedOtjh') not in (None, '') or payload.get('expected_otjh') not in (None, '')
        else existing_expected_otjh
    )
    payload_settings = payload.get('settings') if isinstance(payload.get('settings'), dict) else {}
    existing_settings = {}
    component_rows = authoring_fetch_all(AUTHORING_COMPONENTS_TABLE, 'id = %s', [component_id])
    if component_rows:
        existing_settings = component_builder_settings(component_rows[0])
    incoming_settings = payload.get('settings') if isinstance(payload.get('settings'), dict) else {}
    # The question has its own column now. The legacy settings key is kept in
    # step with it so the learner-side readers that still look there agree with
    # the column instead of serving whatever text they were last saved with.
    reflection_question = payload_reflection_question(
        payload,
        {**component_builder_settings(existing_row), **incoming_settings},
    )
    settings = {
        **component_builder_settings(existing_row),
        **payload_settings,
        **existing_settings,
        **incoming_settings,
        LEGACY_REFLECTION_QUESTION_SETTING: reflection_question,
        'displayType': payload.get('type') or 'Self-study',
        'componentBuilderStatus': clean_str(payload.get('status') or 'draft').lower(),
        'durationMinutes': duration_minutes,
        'contentSections': max(0, parse_int(payload.get('contentSections'), 0)),
        'quizQuestions': max(0, parse_int(payload.get('quizQuestions'), 0)) if payload.get('quizQuestions') not in (None, '') else 0,
        'hasResources': bool_payload(payload.get('hasResources')),
    }
    reflection_required = (
        bool_payload(payload.get('reflectionRequired')) if 'reflectionRequired' in payload
        else bool_payload(payload.get('reflection_required')) if 'reflection_required' in payload
        else bool_payload(existing_row.get('reflection_required'))
    )
    workplace_evidence_required = False
    tutor_validation_required = (
        bool_payload(payload.get('tutorValidationRequired')) if 'tutorValidationRequired' in payload
        else bool_payload(payload.get('tutor_validation_required')) if 'tutor_validation_required' in payload
        else bool_payload(existing_row.get('tutor_validation_required'))
    )
    # A payload that says nothing keeps what the row already had, and a row that
    # predates the column counts as on - see component_coach_validation().
    coach_validation_required = payload_coach_validation(payload, component_coach_validation(existing_row))
    display_order = parse_int(existing_row.get('display_order'), 0)
    display_order = parse_int((component_rows[0] if component_rows else {}).get('display_order'), 0)
    if not component_rows:
        sibling_rows = authoring_fetch_all(AUTHORING_COMPONENTS_TABLE, 'module_catalogue_id = %s and week_id = %s', [module_catalogue_id, week_id])
        display_order = len(sibling_rows)
    module_row = (authoring_fetch_all(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [module_catalogue_id]) or [{}])[0]
    incoming_mappings = payload.get('ksbMappings') if isinstance(payload.get('ksbMappings'), list) else None
    if incoming_mappings is None and 'ksbRefs' in payload:
        incoming_mappings = [
            {
                'ksbId': clean_str(code).upper(),
                'code': clean_str(code).upper(),
                'description': f'Mapped KSB {clean_str(code).upper()}',
                'type': 'secondary',
                'classification': 'secondary',
                'weight': 20,
                'weightClass': 'soft',
            }
            for code in (payload.get('ksbRefs') or [])
            if clean_str(code)
        ]
    if incoming_mappings is None:
        incoming_mappings = component_ksb_mappings_from_row(existing_row)
    component_ksb_items, mapping_payloads = normalise_component_ksb_mappings(
        module_catalogue_id,
        incoming_mappings,
        week_id=week_id,
        component_id=component_id,
        module_row=module_row,
        enforce_unique=False,
    )

    with transaction.atomic():
        authoring_upsert(AUTHORING_COMPONENTS_TABLE, ['id'], {
            'id': component_id,
            'week_id': week_id,
            'module_catalogue_id': module_catalogue_id,
            'type': stored_component_type(payload.get('type')),
            'title': payload.get('title') or '',
            'description': payload.get('description') or '',
            'expected_otjh': expected_otjh,
            'points': parse_int(payload.get('points'), 0),
            'ksb_mappings': json_db_value(component_ksb_items),
            'reflection_required': reflection_required,
            REFLECTION_QUESTION_COLUMN: reflection_question,
            'workplace_evidence_required': workplace_evidence_required,
            'tutor_validation_required': tutor_validation_required,
            'coach_validation_required': coach_validation_required,
            'display_order': display_order,
            'settings_json': json_db_value(settings),
            'live_sessions_link': clean_str(settings.get('liveSessionUrl') or settings.get('teamsMeetingUrl')),
            'deleted_at': None,
            'deleted_by': None,
            'deleted_via_parent': None,
            'is_programme_deleted': False,
        })
        authoring_soft_delete(AUTHORING_KSB_MAPPINGS_TABLE, 'component_id = %s', [component_id], deleted_by='component-save')
        authoring_bulk_upsert(AUTHORING_KSB_MAPPINGS_TABLE, ['id'], mapping_payloads)

    invalidate_curriculum_cache()
    row = authoring_fetch_all(AUTHORING_COMPONENTS_TABLE, 'id = %s', [component_id])[0]
    module = authoring_fetch_all(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [module_catalogue_id])
    week = authoring_fetch_all(AUTHORING_WEEKS_TABLE, 'id = %s', [week_id])
    mappings = authoring_fetch_all(AUTHORING_KSB_MAPPINGS_TABLE, 'component_id = %s', [component_id])
    return component_builder_response(
        row,
        {module_catalogue_id: module[0] if module else {}},
        {week_id: week[0] if week else {'week_number': week_number}},
        {component_id: mappings},
    )


def teams_delivery_metadata_from_weeks(weeks):
    for week in weeks or []:
        for component in week.get('components') or []:
            if clean_str(component.get('type')).lower().replace('_', '-') != 'live-session':
                continue
            settings = component.get('settings') if isinstance(component.get('settings'), dict) else {}
            live_session_id = clean_str(settings.get('teamsLiveSessionId'))
            event_id = clean_str(settings.get('teamsEventId'))
            join_url = clean_str(settings.get('teamsMeetingUrl') or settings.get('liveSessionUrl'))
            if not (live_session_id or event_id or join_url):
                continue
            return {
                'teamsMeetingUrl': join_url,
                'liveSessionUrl': join_url,
                'teamsLiveSessionId': live_session_id,
                'teamsOnlineMeetingId': clean_str(settings.get('teamsOnlineMeetingId')),
                'teamsEventId': event_id,
                'teamsWebLink': clean_str(settings.get('teamsWebLink')),
                'teamsMeetingOptionsUrl': clean_str(settings.get('teamsMeetingOptionsUrl')),
                'teamsOrganizerEmail': clean_str(settings.get('teamsOrganizerEmail')),
                'teamsAttendees': settings.get('teamsAttendees') or [],
                'teamsPresenters': settings.get('teamsPresenters') or [],
                'teamsCoOrganizers': settings.get('teamsCoOrganizers') or [],
                'teamsStartDateTimeUtc': clean_str(settings.get('teamsStartDateTimeUtc') or settings.get('sessionDateTimeUtc')),
                'teamsDurationMinutes': clean_str(settings.get('teamsDurationMinutes') or settings.get('durationMinutes')),
                'teamsRepeat': clean_str(settings.get('teamsRepeat')),
                'teamsRepeatOccurrences': clean_str(settings.get('teamsRepeatOccurrences')),
                'teamsLobbyBypass': clean_str(settings.get('teamsLobbyBypass')),
                'teamsRecording': clean_str(settings.get('teamsRecording')),
                'teamsSpokenLanguage': clean_str(settings.get('teamsSpokenLanguage')),
                'teamsMeetingType': clean_str(settings.get('teamsMeetingType')),
                'teamsRequestResponses': settings.get('teamsRequestResponses'),
                'teamsAllowTimeProposals': settings.get('teamsAllowTimeProposals'),
                'teamsHideAttendees': settings.get('teamsHideAttendees'),
            }
    return {}


def teams_delivery_metadata_from_live_session_row(session_row):
    """Teams metadata for one live_sessions row, or {} when there is none.

    Split out from the single-module reader below so a caller that has already
    batch-read the table for many modules maps the row exactly the same way,
    rather than growing a second copy of this field list that can drift.
    """
    if not session_row:
        return {}
    settings = live_session_row_to_component_settings(session_row)
    return {
        'teamsMeetingUrl': settings.get('teamsMeetingUrl') or '',
        'liveSessionUrl': settings.get('liveSessionUrl') or '',
        'teamsLiveSessionId': settings.get('teamsLiveSessionId') or '',
        'teamsOnlineMeetingId': settings.get('teamsOnlineMeetingId') or '',
        'teamsEventId': settings.get('teamsEventId') or '',
        'teamsWebLink': settings.get('teamsWebLink') or '',
        'teamsMeetingOptionsUrl': settings.get('teamsMeetingOptionsUrl') or '',
        'teamsOrganizerEmail': settings.get('teamsOrganizerEmail') or '',
        'teamsAttendees': settings.get('teamsAttendees') or [],
        'teamsPresenters': settings.get('teamsPresenters') or [],
        'teamsCoOrganizers': settings.get('teamsCoOrganizers') or [],
        'teamsStartDateTimeUtc': settings.get('teamsStartDateTimeUtc') or '',
        'teamsDurationMinutes': settings.get('teamsDurationMinutes') or '',
        'teamsRepeat': settings.get('teamsRepeat') or '',
        'teamsRepeatOccurrences': settings.get('teamsRepeatOccurrences') or '',
        'teamsLobbyBypass': settings.get('teamsLobbyBypass') or '',
        'teamsRecording': settings.get('teamsRecording') or '',
        'teamsSpokenLanguage': settings.get('teamsSpokenLanguage') or '',
        'teamsMeetingType': settings.get('teamsMeetingType') or '',
        'teamsRequestResponses': settings.get('teamsRequestResponses'),
        'teamsAllowTimeProposals': settings.get('teamsAllowTimeProposals'),
        'teamsHideAttendees': settings.get('teamsHideAttendees'),
    }


def teams_module_owner_id(module_catalogue_id):
    """Resolve a shared-Teams module alias to its canonical module owner.

    A duplicate that shares a meeting deliberately has no ``live_sessions`` row
    of its own.  Following this small, bounded chain keeps all Teams reads and
    writes on the original record without copying its provider identifiers or
    allowing an alias to take ownership of the calendar.
    """
    current = clean_str(module_catalogue_id)
    seen = set()
    while current and current not in seen:
        seen.add(current)
        row = (authoring_fetch_all(
            AUTHORING_MODULES_TABLE,
            'module_catalogue_id = %s',
            [current],
        ) or [{}])[0]
        source = clean_str(row.get('teams_shared_source_module_id'))
        if not source or source in seen:
            break
        current = source
    return current


def shared_teams_component_settings(module_catalogue_id):
    """Return booked live-session settings in authored component order."""
    module_catalogue_id = clean_str(module_catalogue_id)
    if not module_catalogue_id:
        return []
    week_rows = active_week_rows(authoring_fetch_all(
        AUTHORING_WEEKS_TABLE,
        'module_catalogue_id = %s',
        [module_catalogue_id],
        'display_order, week_number, id',
    ))
    week_order = {
        clean_str(row.get('id')): index
        for index, row in enumerate(week_rows)
    }
    rows = authoring_fetch_all(
        AUTHORING_COMPONENTS_TABLE,
        f'module_catalogue_id = %s and {LIVE_SESSION_TYPE_SQL}',
        [module_catalogue_id],
        'display_order, id',
    )
    rows = sorted(
        active_component_rows(rows),
        key=lambda row: (
            week_order.get(clean_str(row.get('week_id')), 999999),
            parse_int(row.get('display_order'), 999999),
            clean_str(row.get('id')),
        ),
    )
    return [
        component_builder_settings(row)
        for row in rows
        if normalise_component_type(row.get('type')) == 'live_session'
    ]


def apply_shared_teams_settings_to_weeks(module, weeks):
    """Project the source meeting onto an alias for read-only display.

    The alias keeps its own component rows and stores no provider IDs.  The
    source settings are overlaid only in the response so the builder, calendar
    and Teams dialogs show the same meeting.  The save path strips these keys
    again before persisting an alias.
    """
    source_id = clean_str((module or {}).get('teams_shared_source_module_id'))
    if not source_id:
        return weeks
    source_id = teams_module_owner_id(source_id)
    source_settings = shared_teams_component_settings(source_id)
    if not source_settings:
        return weeks
    index = 0
    for week in weeks or []:
        for component in week.get('components') or []:
            if normalise_component_type(component.get('type')) != 'live_session':
                continue
            if index >= len(source_settings):
                return weeks
            current = component.get('settings') if isinstance(component.get('settings'), dict) else {}
            source = source_settings[index]
            merged = {
                **current,
                **{
                    key: value for key, value in source.items()
                    if key in SHARED_TEAMS_DELIVERY_SETTING_KEYS and value not in (None, '')
                },
            }
            # A shared card opens the source's meeting. Its displayed clock
            # must travel with that identity even when reading weeks differ.
            for key in ('sessionDate', 'sessionTime', 'durationMinutes'):
                if source.get(key) not in (None, ''):
                    merged[key] = source[key]
            own_link = clean_str(current.get('liveSessionLinkOverride'))
            if own_link:
                merged['liveSessionUrl'] = own_link
                merged['teamsMeetingUrl'] = own_link
            component['settings'] = merged
            index += 1
    return weeks


def teams_delivery_metadata_from_live_session(module_catalogue_id):
    ensure_live_session_tracking_tables()
    owner_resolver = globals().get('teams_module_owner_id')
    owner_id = owner_resolver(module_catalogue_id) if callable(owner_resolver) else clean_str(module_catalogue_id)
    sessions = authoring_fetch_all(
        LIVE_SESSIONS_TABLE,
        "module_catalogue_id = %s and status = 'active'",
        [owner_id],
        'updated_at desc, created_at desc',
    )
    return teams_delivery_metadata_from_live_session_row(sessions[0] if sessions else None)


def live_session_row_to_component_settings(row):
    # An offset-less start reads as the learner's own local time in the browser,
    # so the join time drifts by whatever zone the learner happens to sit in.
    start_value = utc_iso_value(row.get('start_datetime'))
    join_url = clean_str(row.get('join_url'))
    return {
        'teamsMeetingUrl': join_url,
        'liveSessionUrl': join_url,
        'teamsLiveSessionId': clean_str(row.get('id')),
        'teamsOnlineMeetingId': clean_str(row.get('online_meeting_id')),
        'teamsEventId': clean_str(row.get('graph_event_id')),
        'teamsWebLink': clean_str(row.get('web_link')),
        'teamsMeetingOptionsUrl': clean_str(row.get('meeting_options_url')),
        'teamsOrganizerEmail': clean_str(row.get('organizer_email')),
        'teamsAttendees': as_json_value(row.get('attendees'), []),
        'teamsPresenters': as_json_value(row.get('presenters'), []),
        'teamsCoOrganizers': as_json_value(row.get('co_organizers'), []),
        'teamsStartDateTimeUtc': start_value,
        'sessionDateTimeUtc': start_value,
        'teamsDurationMinutes': parse_int(row.get('duration_minutes'), 60),
        'durationMinutes': parse_int(row.get('duration_minutes'), 60),
        'teamsProvider': clean_str(row.get('provider')) or 'Microsoft Teams',
        'sessionTimeZone': GRAPH_WINDOWS_TO_IANA.get(clean_str(row.get('timezone')), graph_timezone_iana({})),
        'teamsRepeat': clean_str(row.get('repeat_pattern')) or 'none',
        'teamsRepeatOccurrences': parse_int(row.get('repeat_occurrences'), 1),
        'teamsLobbyBypass': clean_str(row.get('lobby_bypass')) or 'invited',
        'teamsRecording': clean_str(row.get('recording')) or 'none',
        'teamsSpokenLanguage': clean_str(row.get('spoken_language')) or 'en-GB',
        'teamsMeetingType': clean_str(row.get('meeting_type')) or 'live-session',
        'teamsRequestResponses': bool(row.get('request_responses')),
        'teamsAllowTimeProposals': bool(row.get('allow_time_proposals')),
        'teamsHideAttendees': bool(row.get('hide_attendees')),
    }


def occurrence_local_start(occurrence, series_settings):
    """When one booked session starts, read in its own time zone."""
    start_at = parse_graph_datetime((occurrence or {}).get('scheduled_start'))
    if not start_at:
        return None
    zone = ZoneInfo(clean_str((series_settings or {}).get('sessionTimeZone')) or graph_timezone_iana({}))
    return start_at.replace(tzinfo=start_at.tzinfo or timezone.utc).astimezone(zone)


def occurrence_local_date(occurrence, series_settings):
    """The calendar date one booked session runs on, in its own time zone.

    The pairing key between a module's live-session components and the sessions
    Microsoft holds. A date survives what a number does not: cancelling a
    session leaves its number behind, a week with no live session still consumes
    a delivery slot number, and the two numbering schemes that produced a series
    over its lifetime need not agree. The day a session runs on is the same fact
    on both sides, and it is the one the author reads off the screen.
    """
    local_start = occurrence_local_start(occurrence, series_settings)
    return local_start.date().isoformat() if local_start else ''


def live_occurrence_component_settings(occurrence, series_settings):
    """The settings that belong to one session rather than to the whole series.

    A plain recurring series shares one join link, event series and online meeting,
    while every LMS session keeps its own occurrence id and date. This lets the
    sync attach each report/artifact to the correct session without changing the
    learner's join URL.
    """
    if not occurrence:
        return {}
    start_value = utc_iso_value(occurrence.get('scheduled_start'))
    end_value = occurrence.get('scheduled_end')
    settings = {
        'teamsOccurrenceId': clean_str(occurrence.get('id')),
        'teamsSessionNumber': parse_int(occurrence.get('session_number'), 0),
    }
    join_url = clean_str(occurrence.get('join_url')) or clean_str(series_settings.get('liveSessionUrl'))
    if join_url:
        settings['teamsMeetingUrl'] = join_url
        settings['liveSessionUrl'] = join_url
    for column, key in (('graph_event_id', 'teamsEventId'), ('online_meeting_id', 'teamsOnlineMeetingId')):
        value = clean_str(occurrence.get(column))
        if value:
            settings[key] = value
    if start_value:
        settings['teamsStartDateTimeUtc'] = start_value
        settings['sessionDateTimeUtc'] = start_value
    start_at = parse_graph_datetime(occurrence.get('scheduled_start'))
    # The calendar DATE that confirmed instant falls on, in the session's own
    # time zone -- written here because the instant above is.
    #
    # Moving a series through the schedule endpoint rewrites the occurrence, so
    # `sessionDateTimeUtc` followed Microsoft to the new day while `sessionDate`
    # stayed on the day the session was first booked on. The two then disagreed
    # permanently: the component read as still running on its old date, the
    # Course structure compared that date against the week's plan and reported a
    # drift that no update could ever clear, because every update moved the
    # instant and left the date behind. One occurrence, one date.
    local_start = occurrence_local_start(occurrence, series_settings)
    if local_start:
        settings['sessionDate'] = local_start.date().isoformat()
        settings['sessionDay'] = local_start.strftime('%A')
        settings['sessionTime'] = local_start.strftime('%H:%M')
    end_at = parse_graph_datetime(end_value)
    if start_at and end_at and end_at > start_at:
        minutes = int((end_at - start_at).total_seconds() // 60)
        if minutes:
            settings['teamsDurationMinutes'] = minutes
            settings['durationMinutes'] = minutes
    return settings


def live_session_component_points(default=10):
    """What a live-session component is worth, from the Engagement points rule.

    The component editor tells the author points are fixed by the
    ``live_session_attended`` rule and refuses to let them be typed, so a
    component created on their behalf has to be worth what that rule says. The
    fallback is only for a deployment that has not configured the rule.
    """
    try:
        from engagement_api.models import PointsRule
        rule = PointsRule.objects.filter(key='live_session_attended', active=True).only('points').first()
    except Exception:
        logger.debug('Unable to read the live-session points rule.', exc_info=True)
        return default
    return parse_int(getattr(rule, 'points', None), default) if rule else default


#: Everything an additional week meeting stores on its live-session component.
#: Written only by `teams_week_meeting.py`; never by a module save, and never by
#: the module's own calendar. `liveSessionUrl`/`teamsMeetingUrl` are the mirror
#: that makes the component's link point at this meeting and are restored with
#: them, because the module series skips this session and writes neither.
ADDITIONAL_MEETING_SETTING_KEYS = (
    'extraTeamsMeetingUrl', 'extraTeamsLiveSessionId', 'extraTeamsEventId',
    'extraTeamsOnlineMeetingId', 'extraTeamsWebLink', 'extraTeamsMeetingOptionsUrl',
    'extraTeamsOrganizerEmail', 'extraTeamsAttendees', 'extraTeamsPresenters',
    'extraTeamsCoOrganizers', 'extraTeamsStartDateTimeUtc', 'extraTeamsDurationMinutes',
    'extraTeamsSubject',
)


#: Which calendar delivers a live session, as its author chose it: 'main' is
#: the module's own Teams series, 'additional' a one-off meeting of its own.
#: Stored on the live-session component -- see `live_session_meeting_scope`.
LIVE_SESSION_MEETING_SCOPE_KEY = 'teamsMeetingScope'
LIVE_SESSION_MEETING_SCOPES = ('main', 'additional')


def live_session_booked_on_module_calendar(settings):
    """Whether the module series already holds a booked occurrence for this live session.

    ``teamsOccurrenceId``/``teamsSessionNumber`` are written only when a real
    Graph occurrence is paired to the component, unlike ``liveSessionUrl``,
    which the series can stamp on a live session without a confirmed booking.
    """
    settings = settings if isinstance(settings, dict) else {}
    return bool(clean_str(settings.get('teamsOccurrenceId')) or parse_int(settings.get('teamsSessionNumber'), 0) > 0)


def module_has_booked_series(settings_list):
    """Whether new sessions must choose a calendar instead of defaulting to main.

    A pasted main link establishes that context without proving any occurrence
    is booked. Keep the strict booking check separate for booking permissions.
    """
    for settings in settings_list or []:
        settings = settings if isinstance(settings, dict) else {}
        if clean_str(settings.get('extraTeamsMeetingUrl')):
            continue
        if live_session_booked_on_module_calendar(settings):
            return True
        if clean_str(settings.get(LIVE_SESSION_MEETING_SCOPE_KEY)).lower() == 'additional':
            continue
        if any(clean_str(settings.get(key)) for key in ('liveSessionUrl', 'teamsMeetingUrl', 'liveSessionLinkOverride')):
            return True
    return False


def live_session_meeting_scope(settings, module_has_series=True):
    """Which calendar delivers this live session: 'main', 'additional' or 'pending'.

    A confirmed booking outranks the stored choice: a live session that holds
    an additional meeting is 'additional', one the module series has booked is
    'main'. Otherwise the author's stored choice decides, and a legacy normal
    meeting link fills in the display when no choice was stored.

    With neither, it depends on whether the module already has a calendar.
    Before it has one every live session is the module's -- there is nothing to
    overwrite. After, a live session nobody has assigned (a week added later)
    is 'pending': the module calendar must not book it until someone decides,
    because the series and an additional meeting on the same week would deliver
    it twice, and the next Update would put the series' link over the other's.

    The frontend reads the same rule in `liveSessionMeetingScope`.
    """
    settings = settings if isinstance(settings, dict) else {}
    if clean_str(settings.get('extraTeamsMeetingUrl')):
        return 'additional'
    if live_session_booked_on_module_calendar(settings):
        return 'main'
    chosen = clean_str(settings.get(LIVE_SESSION_MEETING_SCOPE_KEY)).lower()
    if chosen in LIVE_SESSION_MEETING_SCOPES:
        return chosen
    # Legacy rows can retain a normal join link without occurrence metadata.
    # The link settles what the dialog displays; it is not treated as a
    # confirmed booking by `live_session_booked_on_module_calendar`.
    if any(clean_str(settings.get(key)) for key in ('liveSessionUrl', 'teamsMeetingUrl', 'liveSessionLinkOverride')):
        return 'main'
    return 'pending' if module_has_series else 'main'


def preserve_additional_meeting_settings(payload_settings, stored_row):
    """Keep a component's booked additional meeting across a full structure save.

    Returns the settings to store: the payload's, with the stored additional
    meeting put back on top when there is one. A component that has never had
    one is returned untouched, so this costs nothing for every other component.

    The author's main/additional choice is the stored row's too: it is set from
    the Teams dialog and by booking, never by the builder, so a builder tab
    opened before it was made can neither erase it nor put an old one back, and
    a copied component starts undecided rather than inheriting its source's.
    """
    payload_settings = {key: value for key, value in (payload_settings or {}).items()
                        if key not in {LIVE_SESSION_MEETING_SCOPE_KEY, 'teamsMainLinkInherited'}}
    if not stored_row:
        return payload_settings
    stored = component_builder_settings(stored_row)
    if not isinstance(stored, dict):
        return payload_settings
    stored_scope = clean_str(stored.get(LIVE_SESSION_MEETING_SCOPE_KEY))
    if stored_scope:
        payload_settings[LIVE_SESSION_MEETING_SCOPE_KEY] = stored_scope
    if 'teamsMainLinkInherited' in stored:
        for key in ('teamsMainLinkInherited', 'teamsCalendarBinding', 'liveSessionUrl', 'teamsMeetingUrl', 'liveSessionLinkOverride'):
            if key in stored:
                payload_settings[key] = stored[key]
            else:
                payload_settings.pop(key, None)
    if not clean_str(stored.get('extraTeamsMeetingUrl')):
        return payload_settings
    kept = {key: stored[key] for key in ADDITIONAL_MEETING_SETTING_KEYS if key in stored}
    join_url = clean_str(stored.get('extraTeamsMeetingUrl'))
    return {**payload_settings, **kept, 'liveSessionUrl': join_url, 'teamsMeetingUrl': join_url}


def attach_teams_meeting_to_module_weeks(module_catalogue_id, series_row, series_settings, occurrence_rows, *, create_missing=False, dry_run=False):
    """Write a tracked Teams meeting onto the weeks of a module.

    A module's live sessions and its meeting's sessions are one list, read in
    the same order: the Nth live session of the module is the Nth session of the
    series. So each component carries its own session's date -- and its own join
    link, when Graph would only accept a holiday-shifted session as an event of
    its own -- rather than the whole series' first one.

    Walking the weeks is what makes ``create_missing`` possible: each week is
    topped up to the module's delivery-day count, taking consecutive sessions
    from the list. That is what makes re-attaching enough to put a whole created
    series in front of the learner, instead of only the weeks somebody had
    already authored a session into. Returns ``(updated, created)``.

    ``dry_run`` counts what the call *would* do and writes nothing. It exists so
    a caller can ask "is there anything here to re-attach?" using this very
    walk, rather than a second implementation of the same rule that could drift
    from it. The ``created`` count is the one that answers that question: the
    update pass rewrites every existing live-session component every time, so it
    is never zero and never means work is outstanding.
    """
    module_row = (authoring_fetch_all(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [module_catalogue_id]) or [{}])[0]
    group_rows = authoring_fetch_all(GROUPS_TABLE, 'group_id = %s', [module_row.get('group_id')]) if module_row.get('group_id') else []
    group_row = group_rows[0] if group_rows else {}
    week_rows = active_week_rows(authoring_fetch_all(
        AUTHORING_WEEKS_TABLE,
        'module_catalogue_id = %s',
        [module_catalogue_id],
        'display_order, week_number, id',
    ))
    component_rows = active_component_rows(authoring_fetch_all(
        AUTHORING_COMPONENTS_TABLE,
        'module_catalogue_id = %s',
        [module_catalogue_id],
        'display_order, id',
    ))
    components_by_week = defaultdict(list)
    for row in component_rows:
        components_by_week[clean_str(row.get('week_id'))].append(row)
    # Read before anything below writes: an existing booking or pasted main
    # link means a new unassigned session must choose its calendar. With neither,
    # the first Create may take the module's unassigned sessions.
    series_already_booked = module_has_booked_series([
        component_builder_settings(row) for row in component_rows
        if frontend_component_type(row.get('type')) == 'live-session'
    ])

    structure_rows = [{**week, 'components': components_by_week.get(clean_str(week.get('id')), [])} for week in week_rows]
    session_rows = module_structure_uses_session_rows(structure_rows, module_stored_session_count(module_row), delivery_days_per_week(module_row))
    session_plan = module_week_session_plan(module_row, 0 if session_rows else len(week_rows))
    external_calendar = clean_str(series_row.get('meeting_type')) == 'linked-external'
    external_slots = []
    if external_calendar:
        # Imported occurrences already exist in Microsoft. Moving curriculum
        # content changes which occurrence delivers it, not that occurrence's
        # date, attendance or recordings.
        external_slots, _external_plan = module_week_delivery_slots(module_row, group_row, len(week_rows))
    session_start_time, _session_end_time, session_duration = module_session_clock(module_row, group_row)
    default_points = live_session_component_points() if create_missing else 0
    now = datetime.utcnow()
    updated = 0
    created = 0
    handled_component_ids = set()
    claimed_occurrence_ids = set()

    def free_occurrence_on(date_value):
        """The unclaimed session Microsoft holds on one date, if there is one."""
        if not date_value:
            return None
        return next((row for row in occurrence_rows
                     if clean_str(row.get('id')) not in claimed_occurrence_ids
                     and occurrence_local_date(row, series_settings) == date_value), None)

    def occurrence_for_component(existing_settings, slot_index):
        """Which booked session a live-session component owns.

        Paired by DATE, never by counting. Session numbers cannot carry this:
        cancelling a session leaves its number in place, a week with no live
        session still consumes a delivery slot number, and a series that has
        been renumbered once holds both schemes at the same time. Counting
        components against those numbers slid every session after the first gap
        onto the previous one's meeting, and left the last real booking attached
        to nothing.

        In order of authority:

        1. The date this component itself currently runs on -- where its own
           meeting sits, which is what keeps a booked session with its invited
           attendees while a plan moves around it.
        2. The date its week is planned for, which is what dates a component
           that has never been booked, and what re-pairs one whose stored date
           was left on another session's day.
        3. For a component with no date at all -- neither its own nor a planned
           one for its week -- the next unclaimed session in order, which is
           what fills a freshly created series.

        A component that matches none of these keeps the meeting it already has
        rather than being handed an unrelated one. A week planned for a day the
        calendar holds no session on is simply not booked yet: handing it the
        next free session took the following week's meeting and left that week
        with none.
        """
        existing_settings = existing_settings if isinstance(existing_settings, dict) else {}
        tracked_id = clean_str(existing_settings.get('teamsOccurrenceId'))
        tracked_number = parse_int(existing_settings.get('teamsSessionNumber'), 0)
        tracked_series = clean_str(existing_settings.get('teamsLiveSessionId'))
        tracked = next((row for row in occurrence_rows if (
            clean_str(row.get('id')) not in claimed_occurrence_ids
            and (
                (tracked_id and clean_str(row.get('id')) == tracked_id)
                or (
                    tracked_series == clean_str(series_row.get('id'))
                    and tracked_number > 0
                    and parse_int(row.get('session_number'), 0) == tracked_number
                )
            )
        )), None)
        if tracked:
            return tracked
        stored_date = clean_str(existing_settings.get('sessionDate'))[:10]
        found = free_occurrence_on(stored_date)
        if found:
            return found
        planned = session_plan[slot_index] if slot_index < len(session_plan) else {}
        planned_date = format_date(planned.get('date'))
        found = free_occurrence_on(planned_date)
        if found or stored_date or planned_date:
            return found
        return next((row for row in occurrence_rows if clean_str(row.get('id')) not in claimed_occurrence_ids), None)

    def settings_for_session(slot_index, occurrence, existing_settings=None):
        """Everything that belongs to one live session.

        ``slot_index`` is the position in the module's dated plan. A
        content-only week still occupies one, so week N stays on delivery slot
        N -- that is what dates a live session nobody has dated by hand.
        ``occurrence`` is the booked session this component owns, chosen by
        `occurrence_for_component`.
        """
        existing_settings = existing_settings if isinstance(existing_settings, dict) else {}
        if not occurrence and stored_calendar_series(series_row):
            empty_settings = {key: '' for key in ('teamsMeetingUrl', 'liveSessionUrl', 'teamsEventId', 'teamsOnlineMeetingId', 'teamsOccurrenceId', 'teamsLiveSessionId', 'teamsSessionNumber', 'sessionDateTimeUtc', 'teamsStartDateTimeUtc')}
            if 'teamsCalendarBinding' in existing_settings:
                empty_settings['teamsCalendarBinding'] = 'missing'
            override = clean_str(existing_settings.get('liveSessionLinkOverride'))
            if override:
                empty_settings['liveSessionUrl'] = override
                empty_settings['teamsMeetingUrl'] = override
            return empty_settings
        session_settings = live_occurrence_component_settings(occurrence, series_settings)
        # Imported defaults may still be stored on an unbooked component even
        # though Create used its group's current clock. Stamp the verified clock
        # when first attaching; subsequent restores keep confirmed overrides.
        if occurrence and not (clean_str(existing_settings.get('teamsLiveSessionId'))
                               and parse_int(existing_settings.get('teamsSessionNumber'), 0) > 0):
            start = parse_graph_datetime(occurrence.get('scheduled_start'))
            if start:
                zone = ZoneInfo(series_settings.get('sessionTimeZone') or graph_timezone_iana({}))
                local = start.replace(tzinfo=start.tzinfo or timezone.utc).astimezone(zone)
                session_settings['sessionTime'] = local.strftime('%H:%M')
        shared_series_settings = {
            key: value
            for key, value in series_settings.items()
            if key not in {'sessionDate', 'sessionDay', 'sessionTime', 'sessionDateTimeUtc', 'teamsStartDateTimeUtc'}
        }
        planned = session_plan[slot_index] if slot_index < len(session_plan) else {}
        session_date = format_date(planned.get('date'))
        slot_time, _slot_end, slot_duration = module_session_clock(module_row, group_row, session_date)
        planned_settings = {}
        tracked_occurrence = (
            clean_str(existing_settings.get('sessionDateTimeUtc'))
            or (
                clean_str(existing_settings.get('teamsLiveSessionId'))
                and parse_int(existing_settings.get('teamsSessionNumber'), 0) > 0
            )
        )
        if session_date and not (clean_str(existing_settings.get('sessionDate')) or tracked_occurrence):
            planned_settings['sessionDate'] = session_date
            planned_settings['sessionTime'] = slot_time
            planned_settings['durationMinutes'] = slot_duration
            planned_settings['teamsDurationMinutes'] = slot_duration
            # Only when the calendar holds no instant of its own for this
            # session: the occurrence's start is the one Teams will really run.
            if not clean_str(session_settings.get('sessionDateTimeUtc')):
                planned_instant = calendar_clock_to_utc_iso(session_date, slot_time, series_settings.get('sessionTimeZone'))
                if planned_instant:
                    planned_settings['sessionDateTimeUtc'] = planned_instant
                    planned_settings['teamsStartDateTimeUtc'] = planned_instant
        attached = {**shared_series_settings, **planned_settings, **session_settings}
        if 'teamsCalendarBinding' in existing_settings:
            attached['teamsCalendarBinding'] = 'matched' if occurrence else 'missing'
        # A bulk authoring replacement intentionally changes the join URL while
        # leaving the Teams meeting identity and occurrence metadata intact.
        # Keep that explicit override when the calendar is re-attached after a
        # normal module save; an ordinary edit without this marker remains
        # authoritative from the verified calendar occurrence.
        override = clean_str(existing_settings.get('liveSessionLinkOverride'))
        if override:
            attached['liveSessionUrl'] = override
            attached['teamsMeetingUrl'] = override
        return attached

    session_index = 0
    sessions_per_week = delivery_days_per_week(module_row)
    for week_index, week_row in enumerate(week_rows):
        week_id = clean_str(week_row.get('id'))
        live_rows = [row for row in components_by_week.get(week_id, []) if frontend_component_type(row.get('type')) == 'live-session']
        for live_index, row in enumerate(live_rows):
            existing_settings = component_builder_settings(row)
            # A live session delivered by its own additional meeting is not part
            # of this series. It is never sent to the module's calendar, so it
            # owns no occurrence here and must keep ITS meeting's link rather
            # than be handed the series'. The slot index still advances: the
            # week occupies its place in the dated plan either way, and the
            # sessions after it would otherwise all shift a week early.
            # See teams_week_meeting.py.
            additional_link = clean_str(existing_settings.get('extraTeamsMeetingUrl'))
            meeting_scope = live_session_meeting_scope(existing_settings, series_already_booked)
            if not additional_link and meeting_scope != 'main':
                # Reserved for an additional meeting not booked yet, or not yet
                # assigned to either calendar. Neither may be handed one of the
                # series' occurrences or its link -- that is how a week ends up
                # delivered twice. Left exactly as it is; the slot still advances
                # for the same reason as the branch below.
                session_index += 1
                handled_component_ids.add(clean_str(row.get('id')))
                continue
            if additional_link:
                session_index += 1
                handled_component_ids.add(clean_str(row.get('id')))
                if not dry_run:
                    update_authoring_rows(AUTHORING_COMPONENTS_TABLE, 'id = %s', [row.get('id')], {
                        'settings_json': json_db_value({
                            **existing_settings,
                            'liveSessionUrl': additional_link,
                            'teamsMeetingUrl': additional_link,
                        }),
                        'live_sessions_link': additional_link,
                        'updated_at': now,
                    })
                updated += 1
                continue
            if external_calendar:
                from .teams_external_calendar import external_calendar_settings
                slots = external_slots[week_index] if week_index < len(external_slots) else []
                planned = slots[live_index] if live_index < len(slots) else {}
                attached = external_calendar_settings(
                    existing_settings, series_row, planned, occurrence_rows, claimed_occurrence_ids,
                    series_settings.get('sessionTimeZone') or graph_timezone_iana({}),
                )
                session_index += 1
                handled_component_ids.add(clean_str(row.get('id')))
                if attached is not None:
                    attached_settings = {**existing_settings, **attached, LIVE_SESSION_MEETING_SCOPE_KEY: 'main'}
                    if attached_settings != existing_settings or clean_str(row.get('live_sessions_link')) != attached['liveSessionUrl']:
                        if not dry_run:
                            update_authoring_rows(AUTHORING_COMPONENTS_TABLE, 'id = %s', [row.get('id')], {
                                'settings_json': json_db_value(attached_settings),
                                'live_sessions_link': attached['liveSessionUrl'], 'updated_at': now,
                            })
                        updated += 1
                continue
            occurrence = occurrence_for_component(existing_settings, session_index)
            if occurrence:
                claimed_occurrence_ids.add(clean_str(occurrence.get('id')))
            settings_for_week = settings_for_session(session_index, occurrence, existing_settings)
            session_index += 1
            handled_component_ids.add(clean_str(row.get('id')))
            if not dry_run:
                # Recorded as the module calendar's whether or not Microsoft
                # booked it this time: a session the series took but Graph
                # failed to hold is retried by the next Update, rather than read
                # as a week nobody has assigned yet.
                update_authoring_rows(AUTHORING_COMPONENTS_TABLE, 'id = %s', [row.get('id')], {
                    'settings_json': json_db_value({**existing_settings, **settings_for_week,
                                                    LIVE_SESSION_MEETING_SCOPE_KEY: 'main'}),
                    'live_sessions_link': clean_str(settings_for_week.get('liveSessionUrl') or settings_for_week.get('teamsMeetingUrl')),
                    'updated_at': now,
                })
            updated += 1
        if not create_missing or external_calendar:
            if not live_rows and not session_rows:
                # A content-only week still occupies one dated slot, matching the
                # structure payload's backward-compatible week-header walk.
                session_index += 1
            continue
        missing_count = 0 if session_rows else max(0, sessions_per_week - len(live_rows))
        for offset in range(missing_count):
            occurrence = occurrence_for_component({}, session_index)
            if occurrence:
                claimed_occurrence_ids.add(clean_str(occurrence.get('id')))
            settings_for_week = settings_for_session(session_index, occurrence)
            session_index += 1
            join_url = clean_str(settings_for_week.get('liveSessionUrl') or settings_for_week.get('teamsMeetingUrl'))
            position = len(components_by_week.get(week_id, [])) + offset
            duration = parse_int(settings_for_week.get('durationMinutes'), session_duration) or session_duration
            if dry_run:
                created += 1
                continue
            authoring_upsert(AUTHORING_COMPONENTS_TABLE, ['id'], {
                'id': f'COMP-{uuid.uuid4().hex.upper()}',
                'week_id': week_id,
                'module_catalogue_id': module_catalogue_id,
                'type': 'live_session',
                # Never the week's own name: a live-session component titled after
                # its week reads as a generated placeholder and is filtered out of
                # the authoring model (isGeneratedWeekPlaceholderComponent).
                'title': f'Live Teams Session {position + 1}',
                'description': '',
                'expected_otjh': round(max(15, duration) / 60, 2),
                'points': default_points,
                'ksb_mappings': json_db_value([]),
                'reflection_required': False,
                'workplace_evidence_required': False,
                'tutor_validation_required': False,
                'display_order': position,
                'settings_json': json_db_value({
                    'completionRule': 'Attend or watch recording',
                    'evidenceRequired': 'Attendance or recording completion',
                    'contentStatus': 'Draft',
                    'version': '0.1',
                    'attendanceRequired': True,
                    'recordingExpected': True,
                    **settings_for_week,
                    LIVE_SESSION_MEETING_SCOPE_KEY: 'main',
                }),
                'live_sessions_link': join_url,
                'deleted_at': None,
                'deleted_by': None,
                'deleted_via_parent': None,
                'is_programme_deleted': False,
            })
            created += 1

    # A live-session component whose week is gone still holds a join link, and
    # what this endpoint promises is that every one of them points at the
    # tracked meeting.
    for row in component_rows:
        if frontend_component_type(row.get('type')) != 'live-session':
            continue
        if clean_str(row.get('id')) in handled_component_ids:
            continue
        if external_calendar:
            # No authored week means no delivery date to match safely.
            continue
        orphan_settings = component_builder_settings(row)
        # Its own additional meeting, for the same reason as above: losing its
        # week must not hand it the series' link. Nor one reserved for one.
        if (clean_str(orphan_settings.get('extraTeamsMeetingUrl'))
                or live_session_meeting_scope(orphan_settings, series_already_booked) == 'additional'):
            continue
        if not dry_run:
            attached_orphan_settings = {**orphan_settings, **series_settings}
            override = clean_str(orphan_settings.get('liveSessionLinkOverride'))
            if override:
                attached_orphan_settings['liveSessionUrl'] = override
                attached_orphan_settings['teamsMeetingUrl'] = override
            update_authoring_rows(AUTHORING_COMPONENTS_TABLE, 'id = %s', [row.get('id')], {
                'settings_json': json_db_value(attached_orphan_settings),
                'live_sessions_link': clean_str(attached_orphan_settings.get('liveSessionUrl') or attached_orphan_settings.get('teamsMeetingUrl')),
                'updated_at': now,
            })
        updated += 1

    if (updated or created) and not dry_run:
        invalidate_curriculum_cache()
    return updated, created


@csrf_exempt
def curriculum_module_teams_meeting_restore(request, module_catalogue_id):
    """Restore the last tracked Teams meeting into a module's live-session components."""
    if request.method not in ('GET', 'POST'):
        return json_error('Method not allowed.', status=405)
    ensure_module_authoring_tables()
    ensure_live_session_tracking_tables()
    requested_id = clean_str(module_catalogue_id)
    # The cheap resolver, for the same reason the module structure endpoint uses
    # it: an identifier that already names a stored module is its own answer,
    # and one indexed lookup settles it. `resolve_authoring_catalogue_id`
    # summarises every module in the database to give the general answer -- and
    # that search only means anything for an identifier that is NOT a stored
    # module, which the Module Builder never sends here. Measured on this
    # module, the general resolver was the whole of the dialog's stall: the
    # request cleared the table probes in 0.57s and was still inside the
    # resolver when the browser gave up 30s later. An alias still falls through
    # to the general resolver inside this helper, so nothing resolves differently.
    resolved_id = resolve_stored_module_catalogue_id(requested_id) or requested_id
    if not authoring_module_exists(resolved_id):
        return json_error('Module authoring structure not found.', status=404)
    owner_resolver = globals().get('teams_module_owner_id')
    owner_id = owner_resolver(resolved_id) if callable(owner_resolver) else resolved_id

    sessions = authoring_fetch_all(
        LIVE_SESSIONS_TABLE,
        "module_catalogue_id = %s and status = 'active'",
        [owner_id],
        'updated_at desc, created_at desc',
    )
    if not sessions:
        return json_error('No saved Teams meeting was found for this module.', status=404)

    settings_update = live_session_row_to_component_settings(sessions[0])
    # The module's live-session components are paired with the series' sessions in
    # order, which is the same pairing the Teams page shows its rows in.
    occurrence_rows = authoring_fetch_all(
        LIVE_SESSION_OCCURRENCES_TABLE,
        "live_session_id = %s and status not in ('cancelled', 'superseded')",
        [clean_str(sessions[0].get('id'))],
        'session_number asc',
    )
    warnings = parse_json_value(sessions[0].get('warnings'), [])
    if clean_str(sessions[0].get('meeting_type')) == 'linked-external':
        # Read-only access limits calendar edits, not attaching the occurrences
        # already imported from Microsoft. Other verification failures still block.
        warnings = [warning for warning in warnings
                    if not isinstance(warning, dict) or warning.get('code') != 'external_calendar_read_only']
    verification_pending = bool(warnings) or not occurrence_rows
    if request.method == 'POST' and verification_pending:
        return json_error('The calendar is saved, but verification is still incomplete. Review the existing calendar before restoring its links.',
                          status=409, code='teams_calendar_verification_pending')
    # Opt-in, because this endpoint is also the silent restore the Module Builder
    # runs when it opens a module whose saved join link has gone missing. That
    # path must never author anything: only a person pressing "re-attach" may.
    body = json_body(request) if request.method == 'POST' else None
    create_missing = truthy(body.get('createMissingComponents')) if isinstance(body, dict) else False

    updated_components = 0
    created_components = 0
    # Opt-in on GET, because GET is also the Module Builder's silent restore and
    # that path must stay as cheap as it is. ``?probe=1`` asks the same walk what
    # re-attaching would create, so the UI can hide the button when the answer
    # is nothing rather than offering an action with no effect.
    pending_components = None
    if request.method == 'POST':
        # Re-attach the canonical source components, not the alias.  This keeps
        # provider ids and occurrence links out of the duplicate while making
        # the explicit Teams edit visible to both modules through the owner.
        updated_components, created_components = attach_teams_meeting_to_module_weeks(
            owner_id,
            sessions[0],
            settings_update,
            occurrence_rows,
            create_missing=create_missing,
        )
    elif truthy(request.GET.get('probe')):
        _would_update, pending_components = attach_teams_meeting_to_module_weeks(
            resolved_id,
            sessions[0],
            settings_update,
            occurrence_rows,
            create_missing=True,
            dry_run=True,
        )

    # A second full structure build, on an endpoint the Module Builder calls
    # every time its Teams dialog opens -- roughly a dozen Neon round trips for
    # weeks, components, mappings, completion and the quality check, repeating
    # work the Builder has just paid for to load the very module it is showing.
    #
    # A GET here changes nothing, so it is served from the same entry, under the
    # same invalidation, as the module-structure endpoint -- same key, same
    # factory, so the two can never disagree. The POST path always rebuilds: it
    # has just rewritten the components this payload describes, and the revision
    # stamped into it is what the Builder's next save is checked against.
    if request.method == 'POST':
        module_payload = stamp_revision_after_write(get_authoring_structure_payload(resolved_id), resolved_id)
    else:
        with curriculum_read_scope(targeted_child_reads=True):
            module_payload = cached_curriculum_value(
                f'module-structure:{resolved_id}',
                lambda: structure_payload_with_revision(lambda: get_authoring_structure_payload(resolved_id), resolved_id),
                force=request_bypasses_curriculum_cache(request),
            )
    body = {
        'restored': request.method == 'POST',
        'verificationPending': verification_pending,
        'updatedComponents': updated_components,
        'createdComponents': created_components,
        'meeting': settings_update,
        'calendar': {
            'title': clean_str(sessions[0].get('module_title')),
            'meetingType': clean_str(sessions[0].get('meeting_type')),
            'calendarManagement': 'external' if clean_str(sessions[0].get('meeting_type')) == 'linked-external' else 'lms',
            'calendarSource': 'stored',
            'seriesMode': 'per_day' if stored_calendar_series(sessions[0]) else 'shared',
            'occurrences': [{
                'sessionNumber': row['session_number'],
                'startDateTimeUtc': utc_iso_value(row.get('scheduled_start')),
                'durationMinutes': int((parse_graph_datetime(row['scheduled_end']) - parse_graph_datetime(row['scheduled_start'])).total_seconds() / 60),
                'joinUrl': clean_str(row.get('join_url')) or settings_update['teamsMeetingUrl'],
                'eventId': clean_str(row.get('graph_event_id')),
            } for row in occurrence_rows],
        },
        # Stamped the same way the structure GET stamps it. A POST here rewrote
        # the module's live-session components, so the revision the Module
        # Builder is holding is now behind -- and the Builder opens a module by
        # calling this endpoint whenever a join link has gone missing. Handing
        # back the pre-restore revision left that module permanently unsaveable:
        # every save was refused as stale, and reloading ran the same restore
        # again.
        'module': module_payload,
    }
    if pending_components is not None:
        # Weeks that have no live-session component yet, so re-attaching has
        # real work to do.
        body['pendingComponents'] = pending_components
    return JsonResponse(body)


def replaceable_live_session(row, *, shared=False):
    """May a bulk replacement overwrite this component's join link?

    The same rule the Module Builder's Replace Teams links dialog counts by: a
    live session (with or without a link), and is not an additional one-off meeting
    -- that one is booked separately and keeps its own link. A module sharing
    another module's meeting stores no link on its rows (it is read from the
    source), so for it every such live session carries one.
    """
    if frontend_component_type(row.get('type')) != 'live-session':
        return False
    settings = component_builder_settings(row)
    if clean_str(settings.get('extraTeamsMeetingUrl')):
        return False
    # A newly authored live session has no link yet.  It is still a legitimate
    # target for Replace Teams links; requiring an old link here made the
    # dialog unable to attach a copied meeting to a new module at all.
    return True


def active_teams_series_for_join_link(link, *, excluding_module_id=''):
    """The unambiguous module that already owns a saved Teams link, if any.

    A recording belongs to ``live_sessions`` / its occurrences, never to the
    text URL stored on a component.  When an author pastes that URL into a new
    module we can safely expose the existing evidence there only if exactly one
    active module owns it.  Do not guess when a tenant has reused a link.
    """
    link = clean_str(link)
    excluded = clean_str(excluding_module_id)
    if not link:
        return ''
    series = [
        row for row in authoring_fetch_all(LIVE_SESSIONS_TABLE, 'join_url = %s', [link])
        if clean_str(row.get('module_catalogue_id')) != excluded
        and clean_str(row.get('status')).lower() not in {'cancelled', 'canceled', 'deleted', 'failed', 'superseded'}
    ]
    # A recreated occurrence can own a distinct Teams URL from its series.
    # Include it, because its recordings are still held by the parent series.
    occurrences = authoring_fetch_all(LIVE_SESSION_OCCURRENCES_TABLE, 'join_url = %s', [link])
    series_ids = unique([clean_str(row.get('live_session_id')) for row in occurrences if clean_str(row.get('live_session_id'))])
    if series_ids:
        placeholders = ', '.join(['%s'] * len(series_ids))
        series.extend(authoring_fetch_all(LIVE_SESSIONS_TABLE, f'id in ({placeholders})', series_ids))
    owners = {
        clean_str(row.get('module_catalogue_id'))
        for row in series
        if clean_str(row.get('module_catalogue_id')) != excluded
        and clean_str(row.get('status')).lower() not in {'cancelled', 'canceled', 'deleted', 'failed', 'superseded'}
    }
    return next(iter(owners)) if len(owners) == 1 else ''


def module_has_active_teams_series(module_catalogue_id):
    """Whether a module already owns a calendar rather than sharing one."""
    return any(
        clean_str(row.get('status')).lower() not in {'cancelled', 'canceled', 'deleted', 'failed', 'superseded'}
        for row in authoring_fetch_all(LIVE_SESSIONS_TABLE, 'module_catalogue_id = %s', [module_catalogue_id])
    )


@csrf_exempt
def curriculum_module_teams_links_replace(request, module_catalogue_id):
    """Point the chosen weeks' live sessions at a new join link, and nothing else.

    Its own endpoint rather than the structure PATCH, because that one rewrites
    every week, component and KSB mapping in the module: on a large module the
    full save outran the browser's timeout for an edit that changes a dozen
    rows. This touches only the live-session components in the selected weeks.

    Stored links only. Nothing is sent to Microsoft: the Teams meetings, their
    invitations and attendees are left exactly as they are. The replacement is
    stamped as ``liveSessionLinkOverride`` so a later module save, which
    re-attaches the stored calendar, keeps the new link rather than restoring
    the meeting's own one.

    A module that shares another module's Teams meeting is changed on its own
    rows only: it keeps the source's calendar, the source and the other modules
    sharing it keep their link, and its own learners join through the new one.
    """
    if request.method != 'POST':
        return json_error('Method not allowed.', status=405)
    payload = json_body(request)
    if not isinstance(payload, dict):
        return json_error('Invalid JSON body.')
    link = clean_str(payload.get('link'))
    if not http_url(link):
        return json_error('Paste a full http:// or https:// link.', fields=['link'])
    raw_week_ids = payload.get('weekIds')
    week_ids = unique([clean_str(value) for value in raw_week_ids if clean_str(value)]) if isinstance(raw_week_ids, list) else []
    if not week_ids:
        return json_error('Choose at least one week to update.', fields=['weekIds'])

    ensure_module_authoring_tables()
    requested_id = clean_str(module_catalogue_id)
    resolved_id = resolve_stored_module_catalogue_id(requested_id) or requested_id
    module_row = authoring_module_exists(resolved_id)
    if not module_row:
        return json_error('Module authoring structure not found.', status=404)
    archived_error = archived_programme_module_edit_error(
        module_row,
        title=module_row.get('title'),
        programme_id=module_row.get('programme_id'),
        programme_name=module_row.get('programme_name'),
    )
    if archived_error:
        return archived_error
    shared = bool(clean_str(module_row.get('teams_shared_source_module_id')))

    expected_revision = clean_str(payload.get('expectedRevision'))
    updated_ids = []
    try:
        with transaction.atomic():
            lock_module_structure_row(resolved_id)
            # Not a refusal: this write changes only the link fields of the rows
            # it names, so it cannot destroy another writer's work the way a full
            # structure save can. The answer only tells the Builder whether it
            # may take the new revision as its own (nothing else moved) or must
            # merge the stored module first, as for any other outside write.
            revision_was_current = bool(expected_revision) and module_structure_revision(resolved_id) == expected_revision
            # A copied link can refer to a meeting whose files are already
            # tracked under another module.  Make this module a Teams alias in
            # that precise case, so the existing recordings and attendance are
            # read here too.  A module with its own active calendar keeps its
            # existing ownership; two calendars must never be silently merged.
            source_module_id = ''
            try:
                ensure_live_session_tracking_tables()
                if not module_has_active_teams_series(resolved_id):
                    source_module_id = active_teams_series_for_join_link(link, excluding_module_id=resolved_id)
            except SchemaNotProvisioned:
                # Linking the component itself must still work while an older
                # environment has not yet provisioned recording tracking.
                # There can be no saved recording to attach in that state.
                logger.info('Teams result tracking is not provisioned; saved link without recording association.')
            effective_shared = shared or bool(source_module_id)
            if source_module_id and source_module_id != clean_str(module_row.get('teams_shared_source_module_id')):
                update_authoring_rows(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [resolved_id], {
                    'teams_shared_source_module_id': source_module_id,
                    'updated_at': datetime.utcnow(),
                })
            placeholders = ', '.join(['%s'] * len(week_ids))
            rows = active_component_rows(authoring_fetch_all(
                AUTHORING_COMPONENTS_TABLE,
                f'module_catalogue_id = %s and week_id in ({placeholders})',
                [resolved_id, *week_ids],
                'display_order, id',
            ))
            now = datetime.utcnow()
            for row in rows:
                if not replaceable_live_session(row, shared=effective_shared):
                    continue
                settings = as_json_value(row.get('settings_json'), {})
                settings = settings if isinstance(settings, dict) else {}
                if source_module_id:
                    # Do not leave the former module's provider ids on this
                    # alias.  The source's current identity is projected on
                    # reads, while this component retains the chosen join URL.
                    settings = strip_shared_teams_delivery_settings(settings)
                update_authoring_rows(AUTHORING_COMPONENTS_TABLE, 'id = %s', [row.get('id')], {
                    'settings_json': json_db_value({
                        **settings,
                        'liveSessionUrl': link,
                        'teamsMeetingUrl': link,
                        'liveSessionLinkOverride': link,
                    }),
                    'live_sessions_link': link,
                    'updated_at': now,
                })
                updated_ids.append(clean_str(row.get('id')))
    except Exception as exc:
        logger.exception('Unable to replace Teams links for %s.', resolved_id)
        return json_error('The Teams links could not be saved. Nothing was changed.', status=500, detail=str(exc))

    if updated_ids:
        invalidate_curriculum_cache()
    return JsonResponse({
        'updated': len(updated_ids),
        'updatedComponentIds': updated_ids,
        'link': link,
        'recordingsSourceModuleId': source_module_id,
        # Read after the commit, so it describes the module as this write left it.
        'structureRevision': module_structure_revision(resolved_id) or STRUCTURE_REVISION_UNAVAILABLE,
        'revisionWasCurrent': revision_was_current,
    })


# --------------------------------------------------- Teams calendar sync state
#
# "Is this module's Teams calendar still the module's own plan?" used to be
# answered in the browser, by comparing the occurrence dates this endpoint
# returns against the session list from `/curriculum/sessions/`. That list is
# served from the shared curriculum payload cache, so a plan changed inside the
# TTL was compared against the *previous* plan -- and a calendar holding the old
# delivery days read as "In sync". The verdict belongs here, where the plan can
# be recomputed from the authoring rows themselves, with no cache in the way.
#
# Nothing in here writes: it never touches the stored occurrence dates, which
# stay the record of what the Teams calendar was last known to hold.

#: Occurrence statuses that no longer stand for a meeting on the calendar.
#: `replace_live_session_occurrences` marks a shrunk series' trailing rows
#: `cancelled` rather than deleting them, so counting those as extras would
#: report every shortened module as out of sync forever.
TEAMS_OFF_CALENDAR_OCCURRENCE_STATUSES = {'cancelled', 'canceled', 'declined', 'deleted', 'removed', 'superseded'}

#: How many differing dates a verdict names before it stops listing them. The
#: badge only needs the count; the list is for the drawer that shows them.
TEAMS_SYNC_REPORTED_DATE_LIMIT = 12


def module_expected_teams_occurrence_keys(module_row, holidays=None, group_row=None, live_sessions=None):
    """The UTC minutes the module's authored live sessions say Teams should hold.

    Read from the same place the session list is -- the module's live-session
    components, one per session, each on its own date -- so what this expects,
    what the calendar shows and what the push sends are one thing. Comparing a
    calendar built from the components against a plan generated from
    ``sessions_number`` would report every hand-dated session as a difference
    that pressing Update could never resolve.

    Only live sessions that carry a date of their own count. An undated one is
    an unfinished module, not a session Teams is expected to hold, and a module
    with none expects nothing -- the verdict then reads ``no-sessions``, which
    is the truth, rather than "out of sync" against a plan nobody authored.

    ``live_sessions`` is this module's entries from
    ``authoring_session_links_by_catalogue``. Pass them in from a caller that has
    already batched the read; leave it as ``None`` and this reads its own.

    Returns ``(keys, plan)``: the minute keys in course order, and the plan, so a
    caller can still see its warnings.
    """
    catalogue_id = clean_str((module_row or {}).get('module_catalogue_id'))
    if live_sessions is None and catalogue_id:
        live_sessions = authoring_session_links_by_catalogue(
            [catalogue_id], modules_by_catalogue={catalogue_id: module_row},
        ).get(catalogue_id) or []
    # A session delivered by its own additional meeting -- or not yet assigned
    # to either calendar -- is not part of this series: the module calendar
    # never books it, so judging the calendar against it would report a
    # difference that pressing Update could never resolve. See
    # `live_session_meeting_scope` and teams_week_meeting.py.
    dated = [link for link in (live_sessions or [])
             if format_date(link.get('date'))
             and not link.get('additionalMeeting')
             and link.get('meetingScope', 'main') == 'main']
    plan = module_session_plan_for_count(
        module_row,
        len(dated),
        holidays=holidays,
    )
    keys = []
    # The same walk `build_sessions_from_authoring_modules` makes, over the same
    # rows, with the same clock fallback. Any drift between the two reappears as
    # a permanent "Dates differ" on a calendar that is actually correct -- which
    # is why neither of them may invent a session the other does not have.
    for link in dated:
        session_date = format_date(link.get('date'))
        start_time, _end_time, _duration = module_live_session_clock(
            module_row, link.get('startTime'), link.get('durationMinutes'),
            booked=link.get('bookedAtMicrosoft', False), group_row=group_row, session_date=session_date,
        )
        key = teams_calendar_minute_key(calendar_clock_to_utc_iso(session_date, start_time, link.get('timeZone')))
        if key:
            keys.append(key)
    return keys, plan


def teams_calendar_sync_verdict(
    module_row,
    occurrence_rows,
    holidays=None,
    group_row=None,
    occurrences_readable=True,
    holidays_readable=True,
    live_sessions=None,
):
    """Whether the tracked Teams occurrences still match the module's own plan.

    Compared as multisets of UTC minutes, so the order the two sides arrive in
    never decides the answer and a duplicated occurrence is still an extra. That
    catches every way the two can drift -- a delivery day added or dropped, a
    date moved, a holiday newly ticked or untied, a start or end date changed,
    an occurrence Teams holds that the plan no longer has.

    The verdict is never optimistic. Anything that stops the comparison being
    real -- an unreadable occurrence read, a module row that is gone, a plan
    that cannot be dated, a series with nothing tracked against it -- returns
    ``unverified``, not ``in-sync``.
    """
    def verdict(state, reasons, **extra):
        return {
            'syncState': state,
            'syncReasons': reasons,
            'expectedOccurrenceCount': 0,
            'trackedOccurrenceCount': 0,
            'differingOccurrences': 0,
            'missingFromTeams': [],
            'extraInTeams': [],
            **extra,
        }

    if not occurrences_readable:
        return verdict('unverified', ['occurrences_unreadable'])
    if not holidays_readable:
        return verdict('unverified', ['cohort_holidays_unreadable'])
    if not module_row:
        # A live series whose module row has gone is an orphan: there is no plan
        # left to compare it against, so it cannot be called in sync.
        return verdict('unverified', ['module_missing'])

    active = [
        row for row in (occurrence_rows or [])
        if clean_str((row or {}).get('status')).lower() not in TEAMS_OFF_CALENDAR_OCCURRENCE_STATUSES
    ]
    actual_keys = []
    for row in active:
        key = teams_calendar_minute_key(row.get('scheduled_start'))
        if not key:
            # A tracked occurrence with no readable start cannot be matched, and
            # ignoring it would let a broken row pass as agreement.
            return verdict('unverified', ['occurrence_date_unreadable'])
        actual_keys.append(key)

    expected_keys, plan = module_expected_teams_occurrence_keys(module_row, holidays, group_row, live_sessions)
    if not expected_keys:
        if not active:
            return verdict('no-sessions', plan.get('warnings') or [])
        return verdict(
            'unverified',
            ['plan_unavailable', *(plan.get('warnings') or [])],
            trackedOccurrenceCount=len(active),
        )
    if not active:
        # The read succeeded and the series has nothing tracked against it, so
        # there is nothing to compare the plan with -- not an agreement.
        return verdict(
            'unverified',
            ['no_tracked_occurrences'],
            expectedOccurrenceCount=len(expected_keys),
        )

    expected_counts = Counter(expected_keys)
    actual_counts = Counter(actual_keys)
    missing = expected_counts - actual_counts
    extra = actual_counts - expected_counts
    missing_total = sum(missing.values())
    extra_total = sum(extra.values())

    reasons = []
    if missing_total:
        reasons.append('missing_from_teams')
    if extra_total:
        reasons.append('extra_in_teams')

    def as_instants(counts):
        # `teams_calendar_minute_key` already names a UTC minute
        # (`YYYY-MM-DDTHH:MM`); seconds and the offset are appended so a caller
        # can treat this the same as any other instant this endpoint returns.
        return [
            f'{key}:00Z'
            for key in sorted(counts.elements())
        ][:TEAMS_SYNC_REPORTED_DATE_LIMIT]

    return verdict(
        'out-of-sync' if reasons else 'in-sync',
        reasons,
        expectedOccurrenceCount=len(expected_keys),
        trackedOccurrenceCount=len(active),
        # The badge's caption counts sessions, not edits: a date that moved is
        # one session that differs, which is one missing key and one extra.
        differingOccurrences=max(missing_total, extra_total),
        missingFromTeams=as_instants(missing),
        extraInTeams=as_instants(extra),
    )


def teams_calendar_sync_verdicts(module_catalogue_ids, occurrences_by_module, occurrences_readable=True):
    """A sync verdict per module, in bulk reads rather than reads per module.

    Four reads for the whole page whatever its length: the module rows, their
    cohorts, the holiday table and the groups. Modules sharing a cohort share
    its holidays and modules sharing a group share its slot, so both are grouped
    once and reused -- the curriculum overview's own 13-second lesson.
    """
    wanted = list(dict.fromkeys(
        clean_str(value) for value in (module_catalogue_ids or []) if clean_str(value)
    ))
    if not wanted:
        return {}
    clause, params = curriculum_in_clause('module_catalogue_id', wanted)
    try:
        module_rows = authoring_fetch_all(AUTHORING_MODULES_TABLE, clause, params)
    except (Exception, AssertionError):
        logger.warning('Could not read modules for the Teams calendar sync verdict.', exc_info=True)
        # Fail closed: every module reports `unverified` rather than `in-sync`.
        return {
            module_id: teams_calendar_sync_verdict(None, [], occurrences_readable=occurrences_readable)
            for module_id in wanted
        }
    modules_by_id = {
        clean_str(row.get('module_catalogue_id')): row
        for row in module_rows
        if clean_str(row.get('module_catalogue_id'))
    }

    cohort_ids = list(dict.fromkeys(
        clean_str(row.get('cohort_id')) for row in module_rows if clean_str(row.get('cohort_id'))
    ))
    holidays_by_cohort = cohort_selected_holidays_by_cohort(cohort_ids)
    # Holidays move a module's dates, so a cohort read that came back with
    # nothing at all cannot be told apart from one that failed -- and a plan
    # dated without the ticked closures is not a plan worth comparing.
    holidays_readable = bool(holidays_by_cohort) or not cohort_ids

    groups_by_id = {}
    group_ids = list(dict.fromkeys(
        clean_str(row.get('group_id')) for row in module_rows if clean_str(row.get('group_id'))
    ))
    if group_ids:
        group_clause, group_params = curriculum_in_clause('group_id', group_ids)
        try:
            groups_by_id = {
                clean_str(row.get('group_id')): row
                for row in authoring_fetch_all(GROUPS_TABLE, group_clause, group_params)
                if clean_str(row.get('group_id'))
            }
        except (Exception, AssertionError):
            # Only the slot-time fallback is lost, and the module row's own slot
            # is the authority anyway -- a group edit writes it into these rows.
            logger.debug('Could not read groups for the Teams calendar sync verdict.', exc_info=True)

    # The authored live sessions of every module on the page, in one read. The
    # verdict is decided against them, so reading them per module would be the
    # per-row round trip this function exists to avoid. The module, group and
    # holiday rows read above are handed over with them, so dating each week's
    # primary live session adds no round trip of its own.
    live_sessions_by_module = authoring_session_links_by_catalogue(
        list(modules_by_id.keys()),
        modules_by_catalogue=modules_by_id,
        groups_by_id=groups_by_id,
        holidays_by_cohort=holidays_by_cohort,
    )

    verdicts = {}
    for module_id in wanted:
        module_row = modules_by_id.get(module_id)
        cohort_id = clean_str((module_row or {}).get('cohort_id'))
        try:
            verdicts[module_id] = teams_calendar_sync_verdict(
                module_row,
                occurrences_by_module.get(module_id) or [],
                holidays=holidays_by_cohort.get(cohort_id) or [],
                group_row=groups_by_id.get(clean_str((module_row or {}).get('group_id'))),
                occurrences_readable=occurrences_readable,
                holidays_readable=holidays_readable or not cohort_id,
                live_sessions=live_sessions_by_module.get(module_id) or [],
            )
        except Exception:
            logger.exception('Unable to compare the Teams calendar for %s.', module_id)
            verdicts[module_id] = teams_calendar_sync_verdict(None, [], occurrences_readable=False)
    return verdicts


@require_GET
def curriculum_teams_meeting_summary(request):
    """One row per module that has a tracked Teams meeting.

    The Teams record lives in ``curriculum.live_sessions``, keyed by module —
    never on the module row itself. A list that wants to show "does this module
    have a meeting, how many occurrences, when is the next one" would otherwise
    have to pull every module's full week structure and read the live-session
    component's settings, which is the single heaviest part of the module
    payload. This is one grouped read instead, and it changes nothing: it is
    additive and read-only.

    ``?module_catalogue_ids=A,B`` narrows it to the modules a page is showing, and
    ``?occurrence_dates=1`` adds each meeting's occurrence dates *and the sync
    verdict for them*: whether the tracked Teams occurrences still match the
    module's own plan, decided here against the authoring rows rather than in the
    browser against a cached session list (see the sync-state section above).
    """
    try:
        ensure_live_session_tracking_tables()
    except (Exception, AssertionError):
        return curriculum_results_response([], request=request)

    requested = [
        clean_str(item)
        for item in clean_str(
            request.GET.get('module_catalogue_ids') or request.GET.get('moduleCatalogueIds')
        ).split(',')
        if clean_str(item)
    ]
    want_occurrence_dates = clean_str(
        request.GET.get('occurrence_dates') or request.GET.get('occurrenceDates')
    ).lower() in {'1', 'true', 'yes'}
    where = "status = 'active' and module_catalogue_id is not null and module_catalogue_id <> ''"
    params = []
    if requested:
        clause, values = curriculum_in_clause('module_catalogue_id', requested)
        if clause:
            where += f' and {clause}'
            params.extend(values)

    try:
        sessions = authoring_fetch_all(
            LIVE_SESSIONS_TABLE, where, params, 'updated_at desc, created_at desc'
        )
    except (Exception, AssertionError):
        logger.warning('Could not read Teams meeting summaries.', exc_info=True)
        return curriculum_results_response([], request=request)

    occurrences_by_session = defaultdict(list)
    occurrences_readable = True
    session_ids = [clean_str(row.get('id')) for row in sessions if clean_str(row.get('id'))]
    if session_ids:
        clause, values = curriculum_in_clause('live_session_id', session_ids)
        try:
            # Session number first: every caller compares this list against the
            # module's own plan session by session, and that plan is in session
            # order. Ordered by date alone, a series whose tracked rows and
            # plan had drifted in *count* paired each row with its neighbour's
            # date, and every row after the first difference read as wrong.
            for row in authoring_fetch_all(
                LIVE_SESSION_OCCURRENCES_TABLE, clause, values, 'session_number, scheduled_start'
            ):
                occurrences_by_session[clean_str(row.get('live_session_id'))].append(row)
        except (Exception, AssertionError):
            logger.warning('Could not read Teams occurrences.', exc_info=True)
            # Remembered rather than swallowed: an empty read must report
            # `unverified`, never agreement with the plan.
            occurrences_readable = False

    now = datetime.utcnow()

    def occurrence_start(item):
        value = item.get('scheduled_start')
        if isinstance(value, datetime):
            return value.replace(tzinfo=None)
        parsed = parse_graph_datetime(value)
        return parsed.replace(tzinfo=None) if parsed else None

    iso_value = utc_iso_value

    results = []
    seen_modules = set()
    occurrences_by_module = {}
    for row in sessions:
        module_id = clean_str(row.get('module_catalogue_id'))
        # Ordered newest-first above, so the first row for a module is the live one.
        if not module_id or module_id in seen_modules:
            continue
        seen_modules.add(module_id)
        session_id = clean_str(row.get('id'))
        # A cancelled row is what the calendar *used* to hold. Shrinking a
        # series marks its leftover rows cancelled rather than deleting them
        # (see `replace_live_session_occurrences`), and the sync verdict has
        # always excluded them for exactly that reason -- but nothing reported
        # here excluded them anywhere. So one leftover row stayed in
        # `occurrenceDates` for ever, shifting the caller's session-by-session
        # comparison by a slot: the drawer said "Teams still holds <the
        # previous session's date>" on every row after it, and pressing Update
        # could never clear it, however correctly the push itself had run.
        occurrences = [
            item for item in occurrences_by_session.get(session_id, [])
            if clean_str(item.get('status')).lower() not in TEAMS_OFF_CALENDAR_OCCURRENCE_STATUSES
        ]
        occurrences_by_module[module_id] = occurrences
        # Sorted by date in its own right, now that the read above is in
        # session order: the next meeting is the soonest one, not the
        # lowest-numbered one.
        upcoming = sorted(
            (
                item for item in occurrences
                if occurrence_start(item) and occurrence_start(item) >= now
            ),
            key=occurrence_start,
        )
        synced = [item for item in occurrences if item.get('artifacts_synced_at')]
        entry = {
            'moduleCatalogueId': module_id,
            'liveSessionId': session_id,
            'status': clean_str(row.get('status')) or 'active',
            'moduleTitle': clean_str(row.get('module_title')),
            'meetingType': clean_str(row.get('meeting_type')),
            'calendarManagement': 'external' if clean_str(row.get('meeting_type')) == 'linked-external' else 'lms',
            'calendarSeries': stored_calendar_series(row),
            'verificationPending': bool(parse_json_value(row.get('warnings'), [])),
            # Saved / pending / failed for the meeting options, from the saved
            # marker; read only, no Graph call (see teams_options_retry).
            'microsoftUpdate': microsoft_update_summary(row.get('warnings')),
            'joinUrl': clean_str(row.get('join_url')),
            'webLink': clean_str(row.get('web_link')),
            'meetingOptionsUrl': clean_str(row.get('meeting_options_url')),
            'eventId': clean_str(row.get('graph_event_id')),
            'onlineMeetingId': clean_str(row.get('online_meeting_id')),
            'organizerEmail': clean_str(row.get('organizer_email')),
            'timeZone': GRAPH_WINDOWS_TO_IANA.get(clean_str(row.get('timezone')), graph_timezone_iana({})),
            'presenters': teams_series_email_list(row.get('presenters')),
            'coOrganizers': teams_series_email_list(row.get('co_organizers')),
            'attendees': teams_series_email_list(row.get('attendees')),
            'repeatPattern': clean_str(row.get('repeat_pattern')) or 'none',
            'startDateTime': iso_value(row.get('start_datetime')),
            'durationMinutes': parse_int(row.get('duration_minutes'), 0),
            'occurrenceCount': len(occurrences),
            'upcomingCount': len(upcoming),
            'syncedCount': len(synced),
            'nextOccurrence': iso_value(upcoming[0].get('scheduled_start')) if upcoming else '',
            'updatedAt': iso_value(row.get('updated_at')),
        }
        # The dates themselves are what a caller needs to say whether the Teams
        # calendar still agrees with the module's own session plan. They cost this
        # endpoint nothing -- the occurrence rows are already read to count them --
        # but they are opt-in so the list pages that only want the counts keep the
        # small payload they have today.
        if want_occurrence_dates:
            entry['occurrenceDates'] = [iso_value(item.get('scheduled_start')) for item in occurrences]
        results.append(entry)

    if want_occurrence_dates and results:
        # One grouped comparison for every module in the page rather than one
        # per row: see `teams_calendar_sync_verdicts` for the reads it groups.
        verdicts = teams_calendar_sync_verdicts(
            (entry['moduleCatalogueId'] for entry in results),
            occurrences_by_module,
            occurrences_readable=occurrences_readable,
        )
        for entry in results:
            verdict = verdicts.get(entry['moduleCatalogueId']) or teams_calendar_sync_verdict(
                None, [], occurrences_readable=False,
            )
            entry['syncState'] = verdict['syncState']
            entry['syncReasons'] = verdict['syncReasons']
            entry['expectedOccurrenceCount'] = verdict['expectedOccurrenceCount']
            entry['differingOccurrenceCount'] = verdict['differingOccurrences']
            entry['missingFromTeams'] = verdict['missingFromTeams']
            entry['extraInTeams'] = verdict['extraInTeams']
            if any(item.get('verified') is False for item in entry.get('calendarSeries') or []):
                entry['syncState'] = 'unverified'
                entry['syncReasons'] = [*entry['syncReasons'], 'weekday_series_unverified']
            if entry.get('verificationPending'):
                entry['syncState'] = 'unverified'
                entry['syncReasons'] = [*entry['syncReasons'], 'calendar_verification_pending']

    return curriculum_results_response(results, request=request)


@require_GET
def curriculum_live_session_occurrences(request):
    """Real per-occurrence state for a set of modules or live-session series.

    The Sessions tab lists a whole programme's live sessions and must show each
    one's true status (``scheduled`` / ``completed`` / ``cancelled``), which lives
    only on ``curriculum.live_session_occurrences`` and is written by the Graph
    artifact-sync -- never derived from a date here. The programme-detail payload
    carries the components (with their ``teamsLiveSessionId``/``teamsOccurrenceId``)
    but no occurrence status, so this is the one extra read that turns the tab from
    a date guess into the sync service's actual record.

    Narrow it with ``?module_catalogue_ids=A,B`` and/or ``?live_session_ids=X,Y``
    (the caller already holds both from the components it rendered). Read-only,
    additive, and deliberately light: attendance/transcripts/recordings are NOT
    included -- those load lazily per series from the artifacts endpoint only when
    a completed row is expanded.
    """
    try:
        ensure_live_session_tracking_tables()
    except (Exception, AssertionError):
        return JsonResponse({'series': [], 'occurrences': []})

    module_ids = [
        clean_str(item)
        for item in clean_str(
            request.GET.get('module_catalogue_ids') or request.GET.get('moduleCatalogueIds')
        ).split(',')
        if clean_str(item)
    ]
    requested_session_ids = [
        clean_str(item)
        for item in clean_str(
            request.GET.get('live_session_ids') or request.GET.get('liveSessionIds')
        ).split(',')
        if clean_str(item)
    ]
    if not module_ids and not requested_session_ids:
        return JsonResponse({'series': [], 'occurrences': []})

    where = "status = 'active'"
    params = []
    id_clauses = []
    if module_ids:
        clause, values = curriculum_in_clause('module_catalogue_id', module_ids)
        if clause:
            id_clauses.append(clause)
            params.extend(values)
    if requested_session_ids:
        clause, values = curriculum_in_clause('id', requested_session_ids)
        if clause:
            id_clauses.append(clause)
            params.extend(values)
    if not id_clauses:
        return JsonResponse({'series': [], 'occurrences': []})
    where += ' and (' + ' or '.join(id_clauses) + ')'

    try:
        series_rows = authoring_fetch_all(
            LIVE_SESSIONS_TABLE, where, params, 'updated_at desc, created_at desc'
        )
    except (Exception, AssertionError):
        logger.warning('Could not read live-session series.', exc_info=True)
        return JsonResponse({'series': [], 'occurrences': []})

    module_by_session = {}
    series_payload = []
    for row in series_rows:
        session_id = clean_str(row.get('id'))
        if not session_id:
            continue
        module_by_session[session_id] = clean_str(row.get('module_catalogue_id'))
        series_payload.append({
            'liveSessionId': session_id,
            'moduleCatalogueId': clean_str(row.get('module_catalogue_id')),
            'moduleTitle': clean_str(row.get('module_title')),
            'status': clean_str(row.get('status')) or 'active',
            'joinUrl': clean_str(row.get('join_url')),
            'provider': clean_str(row.get('provider')),
        })

    occurrences_payload = []
    session_ids = list(module_by_session.keys())
    if session_ids:
        clause, values = curriculum_in_clause('live_session_id', session_ids)
        try:
            occurrence_rows = authoring_fetch_all(
                LIVE_SESSION_OCCURRENCES_TABLE, clause, values, 'live_session_id, session_number'
            )
        except (Exception, AssertionError):
            logger.warning('Could not read live-session occurrences.', exc_info=True)
            occurrence_rows = []
        iso_value = utc_iso_value
        for row in occurrence_rows:
            live_session_id = clean_str(row.get('live_session_id'))
            occurrences_payload.append({
                'occurrenceId': clean_str(row.get('id')),
                'liveSessionId': live_session_id,
                'moduleCatalogueId': module_by_session.get(live_session_id, ''),
                'sessionNumber': parse_int(row.get('session_number'), 0),
                'status': clean_str(row.get('status')) or 'scheduled',
                'scheduledStart': iso_value(row.get('scheduled_start')),
                'scheduledEnd': iso_value(row.get('scheduled_end')),
                'actualStart': iso_value(row.get('actual_start')),
                'actualEnd': iso_value(row.get('actual_end')),
                'participantCount': parse_int(row.get('participant_count'), 0),
                'joinUrl': clean_str(row.get('join_url')),
                'attendanceReportId': clean_str(row.get('attendance_report_id')),
                'artifactsSyncedAt': iso_value(row.get('artifacts_synced_at')),
            })

    return JsonResponse({'series': series_payload, 'occurrences': occurrences_payload})


def module_structure_live_session_counts(weeks):
    """Count authored live sessions per row, excluding reading-only rows."""
    return [
        sum(
            normalise_component_type(component.get('type')) == 'live_session'
            for component in week.get('components') or []
        )
        for week in weeks or []
    ]


def module_structure_uses_session_rows(weeks, session_count, delivery_day_count):
    """Recognise a complete imported structure with one row per session.

    These rows can include a separate holiday/reading row. They must not each
    consume every delivery day, as true calendar-week rows do. Requiring every
    planned session to be authored leaves partial and empty week shells on the
    existing calendar-week mapping.
    """
    counts = module_structure_live_session_counts(weeks)
    count = max(0, parse_int(session_count, 0))
    per_week = max(1, parse_int(delivery_day_count, 1))
    return (
        count > 0
        and sum(counts) == count
        and all(value <= 1 for value in counts)
        and len(counts) > (count + per_week - 1) // per_week
    )


def module_delivery_week_count(module, weeks):
    count = module_stored_session_count(module)
    days = delivery_days_per_week(module)
    if module_structure_uses_session_rows(weeks, count, days):
        return (count + days - 1) // days
    return module_stored_week_count(module, len(weeks))


def apply_module_session_plan_to_weeks(module, group_row, weeks, *, holidays=None):
    """Stamp the module's planned session date/day/time onto its weeks in place.

    Shared by the single-module and batched structure readers so the two cannot
    drift: the batched one lacked this entirely, which silently dropped
    sessionDate/sessionDay/sessionStartTime/sessionDurationMinutes from every
    week it returned. With ``holidays`` supplied it issues no queries;
    otherwise it reads the cohort's selected holidays through the shared
    session planner.

    Authored week N is calendar week N. Weeks run Monday to Sunday from the
    module's own starting week, and a week owns the group's delivery days that
    fall inside its window -- so a Mon+Fri module gives every full week two
    dates because the calendar holds two, not because a session count was
    divided by a week count. That division could only ever give every week the
    same number, which is wrong the moment a module starts mid-week: such a
    module's first week owns only the delivery days from its start date on, and
    the run must not slide by the days it never had.

    A week over-authored with more live sessions than its window has delivery
    days leaves the extras undated. There is no date to give them -- the group
    does not deliver again that week -- and no caller may invent one, because an
    invented date becomes a real calendar entry and a real Teams meeting.
    """
    # Planned on the group's delivery days and clock, falling back to the
    # module's own only where the group states none -- so moving the group
    # re-dates the weeks of every module delivered to it.
    #
    # One slot per delivery day the week runs: a Monday group gives each week
    # one, a Mon+Fri group two, and the week's Nth live session takes the Nth of
    # them. Authored week N takes window N, so a week with no delivery day in
    # its own window (a module whose group pauses a week) simply gets nothing
    # rather than borrowing the next week's date.
    slots_by_week, session_plan = module_week_delivery_slots(
        module, group_row, len(weeks), holidays=holidays,
    )
    session_start_time, _session_end_time, session_duration = module_session_clock(module, group_row)
    for week_index, week in enumerate(weeks):
        live_components = [component for component in week.get('components') or [] if component.get('type') == 'live-session']
        slots = slots_by_week[week_index] if week_index < len(slots_by_week) else []
        # The week itself runs on the first of its delivery days.
        first_planned = slots[0] if slots else {}
        if live_components:
            for offset, component in enumerate(live_components):
                settings = component.get('settings') if isinstance(component.get('settings'), dict) else {}
                # A separately booked meeting retains its own date, clock and
                # link when weeks move, including when it is the first session.
                if clean_str(settings.get('extraTeamsMeetingUrl')):
                    continue
                # A live session runs on the day its week runs on. The date on
                # the component is a copy of the plan's, so it follows the plan
                # when the plan moves -- a changed start date, a week dragged up
                # the rail, a week inserted ahead of this one. Keeping the
                # first-stamped date instead left this week's header and the
                # session inside it naming different days, and the session's was
                # the one `authoring_session_links_by_catalogue` handed to the
                # calendar and to Teams.
                #
                # The one date this may not touch is an occurrence Microsoft has
                # confirmed: that is where a meeting real people were invited to
                # actually sits, and it moves through the reschedule endpoint,
                # not silently underneath them -- unless a saved override has
                # already rescheduled it, which is that endpoint's own record of
                # the move and the one thing this follows. `sessionDateTimeUtc`
                # is deliberately not part of that test -- it is written below on
                # every stamp, so counting it froze every date this ever set.
                #
                # Mirrors `applyModuleWeekSessionPlan` in
                # module-builder/moduleAuthoringData.ts. The two walks must agree:
                # where they have drifted before, the builder spent its first
                # render silently rewriting what this had just sent.
                booked_at_microsoft = (
                    clean_str(settings.get('teamsLiveSessionId'))
                    and parse_int(settings.get('teamsSessionNumber'), 0) > 0
                )
                # The Nth live session of the week takes the Nth delivery slot.
                # A live session beyond them is an ADDITIONAL one: the group
                # does not deliver again that week, so there is no planned date
                # to give it and the `continue` below leaves it on whatever its
                # author stored -- which may be nothing at all.
                planned = slots[offset] if offset < len(slots) else {}
                # A component that already names a session number is matched to
                # THAT session rather than to its position in the week, so a
                # booked session keeps hold of its own plan entry when the weeks
                # around it move. A number the plan no longer has falls back to
                # the week's own slot: the week walk stays the answer of last
                # resort, never `{}`, which would have left the session undated.
                explicit_number = parse_int(settings.get('teamsSessionNumber'), 0)
                if explicit_number:
                    planned = next(
                        (item for item in session_plan if item.get('sessionNumber') == explicit_number),
                        planned,
                    )
                if booked_at_microsoft and not planned.get('rescheduled'):
                    continue
                session_date = format_date(planned.get('date'))
                if not session_date:
                    continue
                planned_day = clean_str(planned.get('day'))
                planned_rescheduled = bool(planned.get('rescheduled'))
                slot_time, _slot_end, slot_duration = module_live_session_clock(
                    module, settings.get('sessionTime'), settings.get('durationMinutes'),
                    booked=booked_at_microsoft, group_row=group_row, session_date=session_date,
                )
                planned_settings = {
                    **settings,
                    'sessionDate': session_date,
                    'sessionDay': planned_day,
                    'sessionTime': slot_time,
                    'durationMinutes': slot_duration,
                    'teamsDurationMinutes': slot_duration,
                }
                planned_instant = calendar_clock_to_utc_iso(session_date, slot_time, settings.get('sessionTimeZone'))
                if planned_instant:
                    planned_settings['sessionDateTimeUtc'] = planned_instant
                    planned_settings['teamsStartDateTimeUtc'] = planned_instant
                if settings.get('teamsCalendarBinding') in {'missing', 'ambiguous'}:
                    # A planned delivery time does not confirm a Microsoft
                    # occurrence. Also clear a stamp left by an older planner.
                    planned_settings['teamsStartDateTimeUtc'] = ''
                if planned_rescheduled:
                    planned_settings['sessionRescheduled'] = True
                component['settings'] = planned_settings
            first_settings = live_components[0].get('settings')
            first_settings = first_settings if isinstance(first_settings, dict) else {}
            first_number = parse_int(first_settings.get('teamsSessionNumber'), 0)
            first_numbered = next(
                (item for item in session_plan if first_number > 0 and item.get('sessionNumber') == first_number),
                None,
            )
            if first_numbered:
                # Teams numbering can omit orientation and additional events.
                # Keep a confirmed date that already fits this authored week's
                # slots; a changed plan still moves the header when it no
                # longer fits. Mirrors applyModuleWeekSessionPlan.
                confirmed_date = (
                    format_date(first_settings.get('sessionDate'))
                    if clean_str(first_settings.get('teamsLiveSessionId')) else ''
                )
                first_planned = next(
                    (slot for slot in slots if slot.get('date') == confirmed_date),
                    first_numbered,
                )
        # The week runs on the day its live session is delivered on. A closed
        # delivery slot is not this week -- it is a reading week of its own,
        # which the plan's `slots` spine keeps in the curriculum at the closed
        # date -- so the authored week and everything in it moves down to the
        # next open slot together with the session it holds. Dating the week
        # from `slotDate` instead put the week on a day the module is shut and
        # disagreed with the frontend's `applyModuleWeekSessionPlan`, which has
        # walked the delivered date all along.
        session_date = format_date(first_planned.get('date'))
        session_start_time, _session_end_time, session_duration = module_session_clock(module, group_row, session_date)
        week['sessionDate'] = session_date
        week['sessionDay'] = clean_str(first_planned.get('day'))
        week['sessionStartTime'] = session_start_time if session_date else ''
        week['sessionDurationMinutes'] = session_duration if session_date else 0
        if first_planned.get('rescheduled'):
            week['sessionRescheduled'] = True
    return weeks


def persist_group_module_session_dates(module_rows, group_row):
    """Persist a group's new delivery dates onto its unbooked live sessions.

    The group PATCH updates the module rows that own the session plan.  Learner
    delivery, however, reads the concrete ``sessionDate`` stored on each live
    component, so leaving those copies behind makes Curriculum say Friday while
    the learner still says Thursday.  Reuse the same planner the structure
    readers use, then write only settings that actually moved.

    ``apply_module_session_plan_to_weeks`` deliberately leaves a Microsoft-
    confirmed occurrence alone.  Those meetings continue through the explicit
    Teams reschedule flow (and the group PATCH response still reports their
    calendars as stale), so this helper cannot silently move an invitation.
    """
    modules = [row for row in (module_rows or []) if clean_str(row.get('module_catalogue_id'))]
    if not modules:
        return 0

    holidays_by_cohort = cohort_selected_holidays_by_cohort([
        clean_str(row.get('cohort_id'))
        for row in modules
        if clean_str(row.get('cohort_id'))
    ])
    now = datetime.utcnow()
    updated = 0

    for module in modules:
        catalogue_id = clean_str(module.get('module_catalogue_id'))
        week_rows = active_week_rows(authoring_fetch_all(
            AUTHORING_WEEKS_TABLE,
            'module_catalogue_id = %s',
            [catalogue_id],
            'display_order, week_number, id',
        ))
        component_rows = active_component_rows(authoring_fetch_all(
            AUTHORING_COMPONENTS_TABLE,
            'module_catalogue_id = %s',
            [catalogue_id],
            'display_order, id',
        ))

        components_by_week = defaultdict(list)
        stored_settings = {}
        for row in component_rows:
            if frontend_component_type(row.get('type')) != 'live-session':
                continue
            component_id = clean_str(row.get('id'))
            settings = as_json_value(row.get('settings_json'), {})
            settings = settings if isinstance(settings, dict) else {}
            stored_settings[component_id] = settings
            components_by_week[clean_str(row.get('week_id'))].append({
                'id': component_id,
                'type': 'live-session',
                'settings': settings,
            })

        weeks = [{
            'id': clean_str(row.get('id')),
            'weekNumber': parse_int(row.get('week_number'), index + 1),
            'components': components_by_week.get(clean_str(row.get('id')), []),
        } for index, row in enumerate(week_rows)]
        apply_module_session_plan_to_weeks(
            module,
            group_row or {},
            weeks,
            holidays=holidays_by_cohort.get(clean_str(module.get('cohort_id'))) or [],
        )

        for week in weeks:
            for component in week.get('components') or []:
                component_id = clean_str(component.get('id'))
                planned_settings = component.get('settings') if isinstance(component.get('settings'), dict) else {}
                if planned_settings == stored_settings.get(component_id, {}):
                    continue
                update_authoring_rows(
                    AUTHORING_COMPONENTS_TABLE,
                    'id = %s',
                    [component_id],
                    {
                        'settings_json': json_db_value(planned_settings),
                        'updated_at': now,
                    },
                )
                updated += 1

    return updated


# ---------------------------------------------------------------------------
# Structure revisions
#
# ``curriculum_module_structure`` PATCH is a whole-structure REPLACEMENT: it
# soft-deletes every week, component and KSB mapping the module owns and writes
# back what the payload carries. That makes "which version was this payload
# built from" a safety question rather than a nicety -- a browser holding a
# five-minute-old copy of the module does not just show stale weeks, its next
# save writes them over whatever was authored in the meantime.
#
# The revision is a fingerprint of the stored material rather than a counter,
# for two reasons. It needs no column, so no migration and no backfill -- the
# authoring tables are ``managed = False`` and externally owned. And it is
# derived from the rows themselves, so it moves for EVERY write that reaches
# them, whichever endpoint made it: the structure PATCH, the settings PATCH, the
# component PATCH, a week delete, the programme tree save, a Teams attach. A
# counter would only move where somebody remembered to increment it, and the
# write this is guarding against is precisely the one nobody remembered.
#
# A save that rewrites the same content therefore leaves the revision alone,
# which is correct: two tabs that agree cannot conflict.
# ---------------------------------------------------------------------------

# Columns that move when the row is rewritten to the values it already held.
# Including them would turn every no-op save into a conflict for everyone else.
STRUCTURE_REVISION_VOLATILE_COLUMNS = ('created_at', 'updated_at', 'detached_at')

# The tables one structure save replaces, with the filter that decides which of
# their rows the module currently owns and the column each is ordered by. Read
# in this order so the fingerprint does not depend on dictionary iteration.
STRUCTURE_REVISION_SOURCES = (
    ('module', AUTHORING_MODULES_TABLE, None, 'module_catalogue_id'),
    ('weeks', AUTHORING_WEEKS_TABLE, active_week_rows, 'id'),
    ('components', AUTHORING_COMPONENTS_TABLE, active_component_rows, 'id'),
    ('mappings', AUTHORING_KSB_MAPPINGS_TABLE, active_mapping_rows, 'id'),
    ('completion', AUTHORING_COMPLETION_TABLE, None, 'module_catalogue_id'),
    ('advanced', AUTHORING_ADVANCED_TABLE, None, 'module_catalogue_id'),
)


def module_structure_revision(module_catalogue_id, *, source_rows=None):
    """Fingerprint of everything a structure PATCH would replace.

    Six indexed single-module reads, or the exact source rows already read for
    an editor GET. PATCH always uses fresh reads. A module that is not stored
    fingerprints as the empty structure, so a fresh draft is never a conflict.

    Rows are sorted by their own key rather than trusted in database order: a
    fingerprint that depended on which order Postgres happened to return the
    components in would refuse saves at random.
    """
    catalogue_id = clean_str(module_catalogue_id)
    if not catalogue_id:
        return ''
    ensure_module_authoring_tables()
    material = []
    # Match the payload reader's queries, including ordering, so its read scope
    # reuses these rows. Excluding timestamps in SQL gave the revision a separate
    # memo key and downloaded all component content twice on every fresh open.
    payload_order = {
        'weeks': 'display_order, week_number, id',
        'components': 'display_order, id',
        'mappings': 'created_at, id',
    }
    for label, table, keep, sort_column in STRUCTURE_REVISION_SOURCES:
        try:
            if source_rows is not None:
                rows = source_rows[table]
            elif connection.vendor == 'postgresql' and table in (AUTHORING_COMPONENTS_TABLE, AUTHORING_KSB_MAPPINGS_TABLE):
                from .authoring_read_transport import compact_authoring_rows
                # Verify every current row in SQL, sharing only unchanged raw
                # content with the editor read. This remains a fresh revision,
                # including external writes that never bump the response epoch.
                rows = compact_authoring_rows(
                    table, 'module_catalogue_id = %s', [catalogue_id],
                    'display_order, id' if table == AUTHORING_COMPONENTS_TABLE else 'created_at, id',
                    reuse_unchanged=True,
                )
            else:
                rows = authoring_fetch_all(
                    table,
                    'module_catalogue_id = %s',
                    [catalogue_id],
                    order_sql=payload_order.get(label, ''),
                )
        except Exception:
            # A table that cannot be read must not fail the request it was asked
            # about. Returning '' turns the guard off for this save rather than
            # refusing it, which matches how every other optional protection in
            # this module degrades -- and the caller only enforces a non-empty
            # revision.
            logger.warning('Unable to fingerprint %s for module %s.', table, catalogue_id, exc_info=True)
            return ''
        if keep:
            rows = keep(rows)
        # Copy rather than mutate: the payload still needs the complete rows.
        # The fingerprint's material remains identical to the previous SQL
        # projection, including columns introduced by future migrations.
        rows = [
            {key: value for key, value in row.items()
             if key not in STRUCTURE_REVISION_VOLATILE_COLUMNS}
            for row in rows
        ]
        material.append([
            label,
            sorted(rows, key=lambda row: clean_str(row.get(sort_column))),
        ])
    return hashlib.sha256(
        json.dumps(material, sort_keys=True, default=str).encode()
    ).hexdigest()[:32]


# Stamped on a payload whose revision could not be read at all. It can never
# equal a real fingerprint, so a save built on such a payload is refused rather
# than run unchecked. '' would have meant "no revision", which the save path
# reads as "this caller is not asking to be checked" -- the opposite.
STRUCTURE_REVISION_UNAVAILABLE = 'unverified'


def structure_payload_with_revision(build_payload, module_catalogue_id, *, source_rows=None):
    """Build a structure payload and stamp the revision it was built from.

    The revision is read BEFORE the payload, and that order is the whole point.
    These reads run in autocommit, so each statement sees its own snapshot and
    another writer can commit in the middle of the build. Whichever of the two
    is read second describes the later state:

    - payload first, revision second (how this used to work): pre-write weeks
      carrying the post-write fingerprint. The caller saves its stale structure,
      the revision matches, the guard lets it through, and the other writer's
      work is gone with no error raised anywhere. That is precisely the silent
      overwrite this mechanism exists to make impossible.
    - revision first: a payload that may contain a write the revision predates.
      The revision is then already superseded, so the save built on it is
      refused with 409 and the caller reloads. Wrong in the harmless direction.

    So the pair is never certified as a snapshot it is not. It is either exactly
    consistent, or provably stale and fails closed.

    ``build_payload`` is a callable rather than an already-built payload so that
    the ordering cannot be quietly undone at a call site. A caller that has just
    written the structure itself and needs the revision of its own write uses
    ``stamp_revision_after_write``.
    """
    revision = module_structure_revision(
        module_catalogue_id, **({'source_rows': source_rows} if source_rows is not None else {}),
    ) or STRUCTURE_REVISION_UNAVAILABLE
    payload = build_payload()
    if not payload:
        return payload
    return {**payload, 'structureRevision': revision}


def stamp_revision_after_write(payload, module_catalogue_id):
    """Stamp a payload whose content this request has just written itself.

    The revision has to describe the state *after* that write, so it is read
    afterwards. Only for a caller that provisioned or saved the structure a
    moment ago; anything that merely reads must use
    ``structure_payload_with_revision`` instead.
    """
    if not payload:
        return payload
    return {
        **payload,
        'structureRevision': module_structure_revision(module_catalogue_id) or STRUCTURE_REVISION_UNAVAILABLE,
    }


def lock_module_structure_row(module_catalogue_id):
    """Hold this module's row for the rest of the transaction.

    Without it the revision check is a read followed by a write, and two saves
    that both read revision 41 both pass it -- the second overwriting the first
    with the very payload the check exists to refuse. The lock makes
    check-and-write one operation: the second save blocks here until the first
    commits, then reads the revision the first one produced and is refused.

    SQLite (the test runner) has no row locks and needs none: a write
    transaction takes the whole database.
    """
    if connection.vendor != 'postgresql':
        return
    with connection.cursor() as cursor:
        cursor.execute(
            'select 1 from %s where %s = %%s for update'
            % (
                authoring_table_name(AUTHORING_MODULES_TABLE),
                quote_ident('module_catalogue_id'),
            ),
            [clean_str(module_catalogue_id)],
        )
        cursor.fetchall()


# ---------------------------------------------------------------------------
# The same guard, for the records that are not a module structure.
#
# Everything from here to `curriculum_record_revisions` generalises what
# `module_structure_revision` and `lock_module_structure_row` do for the Module
# Builder. The other authoring surfaces -- the programme, cohort, group and
# module drawers, and the Week Builder -- each hold a record open in a browser
# for as long as somebody is working in it, and each used to write blind:
# whichever save landed second replaced the first, and nothing anywhere said so.
#
# Their only protection was that a poll usually reached the second editor first,
# which makes correctness a matter of timing. These give them the mechanism the
# Module Builder already has: one token, one lock, one refusal, so the behaviour
# only has to be learned once and there is one place to correct it.
# ---------------------------------------------------------------------------


def record_revision(sources):
    """Fingerprint the rows a guarded write would replace.

    ``sources`` is one ``(label, table, where_sql, params, sort_column)`` per
    table, in a fixed order so the fingerprint never depends on dictionary
    iteration. Volatile columns are dropped and rows are sorted by their own
    key, for the two reasons ``module_structure_revision`` gives: a timestamp
    the write itself bumps would make every fingerprint differ from the last,
    and one that trusted database order would refuse saves at random.

    Returns '' when a table cannot be read at all, and also when the FIRST
    source -- by convention the record's own row -- matches nothing. Callers
    treat '' as "this could not be checked" and refuse the guarded save rather
    than run it unchecked, the same fail-closed rule the structure endpoint
    follows. The missing-row case earns its own answer because these records
    are all edited in place: a record that is not stored has no version to be
    stale against, and hashing its absence would mint a real-looking token that
    every unstored record shared. (``module_structure_revision`` deliberately
    does the opposite, because a module's first save is a legitimate write of
    something not yet stored.)
    """
    material = []
    for index, (label, table, where_sql, params, sort_column) in enumerate(sources):
        try:
            rows = authoring_fetch_all(
                table,
                where_sql,
                params,
                ensure_tables=False,
                exclude_columns=STRUCTURE_REVISION_VOLATILE_COLUMNS,
            )
        except Exception:
            # A table that cannot be read must not fail the request it was asked
            # about; the caller decides what an unreadable fingerprint means.
            logger.warning('Unable to fingerprint %s.', table, exc_info=True)
            return ''
        if index == 0 and not rows:
            return ''
        material.append([
            label,
            sorted(rows, key=lambda row: clean_str(row.get(sort_column))),
        ])
    return hashlib.sha256(
        json.dumps(material, sort_keys=True, default=str).encode()
    ).hexdigest()[:32]


def lock_record_row(table, where_sql, params):
    """Hold this record's row for the rest of the transaction.

    The single-table counterpart of ``lock_module_structure_row``, and it exists
    for exactly the same reason: without it the guard is a read followed by a
    write, and two saves that both read revision 41 both pass it -- the second
    overwriting the first with the very payload the check exists to refuse. The
    lock makes check-and-write one operation, so the second save waits here,
    then reads the revision the first one produced and is refused.

    SQLite (the test runner) has no row locks and needs none: a write
    transaction takes the whole database.
    """
    if connection.vendor != 'postgresql':
        return
    with connection.cursor() as cursor:
        cursor.execute(
            'select 1 from %s where %s for update' % (table_name(table), where_sql),
            list(params or []),
        )
        cursor.fetchall()


def programme_record_revision(identifier):
    """Fingerprint of the ``programmes`` row a programme PATCH rewrites.

    The name cascade onto cohorts, groups and modules is deliberately left out.
    It is derived from this row rather than authored, so folding it in would
    make a rename of the programme look like a change to every child -- and
    would refuse a colleague's unrelated cohort edit.
    """
    ensure_module_authoring_tables()
    config = programme_config_by_identifier(identifier)
    if not config:
        return ''
    try:
        key_column = programme_config_key_column()
    except Exception:
        logger.warning('Unable to resolve the programmes key column.', exc_info=True)
        return ''
    key_value = config.get(key_column)
    if not clean_str(key_value):
        return ''
    return record_revision((
        ('programme', 'programmes', quote_ident(key_column) + ' = %s', [key_value], key_column),
    ))


def cohort_record_revision(cohort_id):
    """Fingerprint of the single ``curriculum.cohorts`` row a cohort PATCH writes."""
    ident = clean_str(cohort_id)
    if not ident:
        return ''
    ensure_module_authoring_tables()
    return record_revision((
        ('cohort', COHORT_AUTHORING_DETAILS_TABLE, 'cohort_id = %s', [ident], 'cohort_id'),
    ))


def group_record_revision(group_id):
    """Fingerprint of the single ``curriculum.groups`` row a group PATCH writes.

    The delivery-slot cascade onto the group's module rows is left out for the
    reason the programme rename is: those rows inherit the slot, so including
    them would report a module's own schedule edit as a change to the group.
    The group row is what the group drawer authors, and it moves whenever the
    cascade has anything to do.
    """
    ident = clean_str(group_id)
    if not ident:
        return ''
    ensure_module_authoring_tables()
    return record_revision((
        ('group', GROUPS_TABLE, 'group_id = %s', [ident], 'group_id'),
    ))


def week_template_revision(template_id):
    """Fingerprint of the week template and the components it owns.

    Both tables, because a week template PATCH deletes every component row and
    re-inserts the list it was sent: the components are the part of the record
    an author spends an afternoon on, and a token that only covered the header
    row would let a colleague's whole component list be replaced unnoticed.
    """
    ident = clean_str(template_id)
    if not ident:
        return ''
    ensure_week_template_tables()
    return record_revision((
        ('template', WEEK_TEMPLATES_TABLE, 'id = %s', [ident], 'id'),
        ('components', WEEK_TEMPLATE_COMPONENTS_TABLE, 'week_template_id = %s', [ident], 'id'),
    ))


def module_record_revision(identifier):
    """Fingerprint of the module a drawer PATCH writes.

    Shared with the Module Builder rather than its own: the drawer writes
    through ``save_module_authoring_structure``, the same helper the structure
    PATCH uses, so one token means a drawer edit and a Builder save can never
    be told apart -- and either one refuses a stale copy of the other.
    """
    ident = clean_str(identifier)
    if not ident:
        return ''
    return module_structure_revision(resolve_stored_module_catalogue_id(ident) or ident)


#: How a caller names each guarded record kind, and how to fingerprint it.
CURRICULUM_RECORD_REVISIONS = {
    'programme': programme_record_revision,
    'cohort': cohort_record_revision,
    'group': group_record_revision,
    'module': module_record_revision,
    'weekTemplate': week_template_revision,
}


def curriculum_record_revision(kind, identifier):
    """The current token for one record, or '' if it cannot be read."""
    read = CURRICULUM_RECORD_REVISIONS.get(kind)
    if not read:
        return ''
    try:
        return read(identifier) or ''
    except Exception:
        logger.warning('Unable to read the %s revision for %s.', kind, identifier, exc_info=True)
        return ''


#: What a 409 hands back for each record kind: the stored values of the fields
#: that drawer authors, so the editor can rebase its outstanding changes onto
#: them without a second call. Deliberately not the whole record -- the counts
#: and rollups a drawer displays are derived from other tables, and shipping
#: them here would invite a merge to treat a colleague's unrelated edit as a
#: change to this one.
def cohort_conflict_record(cohort_id):
    row = fetch_cohort_row(cohort_id)
    if not row:
        return None
    return curriculum_cohort_from_authoring_detail({
        **row,
        # Stored as JSON text; the payload builder passes whatever it is handed
        # straight through, and the drawer merges these as lists.
        'holiday_ids': parse_json_value(row.get('holiday_ids'), []),
        'excluded_holiday_ids': parse_json_value(row.get('excluded_holiday_ids'), []),
    })


def group_conflict_record(group_id):
    row = fetch_group_row(group_id)
    return curriculum_group_from_authoring_detail(row) if row else None


def programme_conflict_record(identifier):
    """The programme drawer's own fields, read from the ``programmes`` row.

    Not ``programme_response``: that assembles the whole curriculum payload with
    ``force=True``, which is seconds of work against a remote database -- and
    this runs while the record's row is locked. The drawer authors the name,
    level, description and colour, and they all live on the row already read.
    """
    config = programme_config_by_identifier(identifier)
    if not config:
        return None
    return {
        'id': programme_config_identity(config),
        'sourceId': programme_config_identity(config),
        'name': config.get('name') or '',
        'level': config.get('level') or '',
        'description': config.get('description') or '',
        'color': config.get('color') or '',
    }


def requested_expected_revision(request, payload):
    """The revision this caller is asking to be checked against, if any.

    Absent means "do not check me", which is what every unguarded caller sends:
    the Excel import, the structure wizard, the programme tree save, a record's
    first save. Only a caller that read a token and sent it back is refused on
    a mismatch -- the same opt-in the structure endpoint uses, and for the same
    reason: the callers that write here without ever having read a revision are
    legitimate and have to keep working.
    """
    payload = payload if isinstance(payload, dict) else {}
    return clean_str(
        payload.get('expectedRevision')
        or payload.get('expected_revision')
        or request.headers.get('If-Match')
    )


def record_conflict_response(expected_revision, current_revision, **extra):
    """The 409 a stale guarded save is refused with.

    Deliberately not a merge and not a server-side retry. The second editor is
    the one who can see both versions and decide, so their work stays in their
    browser and the stored record travels back for them to rebase onto. Nothing
    has been written when this is returned.
    """
    if not current_revision:
        # '' means the fingerprint could not be read at all, never that the
        # record is empty -- an empty record still hashes to a real value.
        # Carrying on would run this save unchecked, which is the overwrite the
        # caller asked to be protected from by sending a revision. No record
        # travels with this refusal: nothing was compared, so there is no other
        # version to show.
        return json_error(
            'This record could not be checked against the saved version, so nothing was '
            'written. Your changes are still here - try again in a moment.',
            status=409,
            conflict=True,
            expectedRevision=expected_revision,
            currentRevision='',
        )
    return json_error(
        'Someone else saved this while you were editing it. Nothing of yours has been '
        'overwritten - your changes are being merged with theirs.',
        status=409,
        conflict=True,
        expectedRevision=expected_revision,
        currentRevision=current_revision,
        **extra,
    )


@require_GET
def curriculum_record_revisions(request):
    """Current tokens for the records named in the query string.

    The drawers open their record from the curriculum overview, which is a
    cached payload shared by every screen; a token minted there would be one
    more thing to keep fresh, and would go stale exactly when a colleague saved.
    So they ask for it here instead -- one indexed read per record, off the
    cache entirely, when the drawer opens and again whenever it adopts a stored
    version.

    ``?cohort=COHORT-1&cohort=COHORT-2&group=GROUP-9`` answers
    ``{"revisions": {"cohort": {"COHORT-1": "..."}, "group": {...}}}``. A record
    that cannot be fingerprinted is answered with '' rather than left out, so a
    caller can tell "unreadable" from "not asked for": a drawer holding ''
    sends no token and saves unguarded, which is what it did before any of this.
    """
    revisions = {}
    for kind in CURRICULUM_RECORD_REVISIONS:
        wanted = unique([
            clean_str(value) for value in request.GET.getlist(kind) if clean_str(value)
        ])
        if not wanted:
            continue
        revisions[kind] = {
            identifier: curriculum_record_revision(kind, identifier)
            for identifier in wanted
        }
    return JsonResponse({'revisions': revisions})


def module_archive_parent_markers(module_row, module_catalogue_id):
    """Which ``deleted_via_parent`` markers belong to this module's archive.

    A module archived on its own stamps its children with its own catalogue id,
    which is what ``restore_rows_via_parent`` matches. A module that came here on
    a programme's cascade did not stamp anything: that cascade wrote the
    *programme* id onto the module and onto every week and component under it, so
    matching on the catalogue id alone would report an archived programme's
    modules as empty. Whatever marker the module itself carries is therefore
    accepted alongside its own id.
    """
    markers = {clean_str(module_catalogue_id)}
    via_parent = clean_str((module_row or {}).get('deleted_via_parent'))
    if via_parent:
        markers.add(via_parent)
    return {marker for marker in markers if marker}


# One archive writes all of its rows inside a single request. The same window
# decides which deleted children learners may see (curriculum_api.week_visibility)
# and which recordings stay with an archived module (recordings_library).
MODULE_ARCHIVE_EVENT_WINDOW = timedelta(minutes=5)


def stamp_datetime(value):
    """A stored ``deleted_at`` as a datetime, or None when it is not one."""
    if isinstance(value, datetime):
        return value
    text = clean_str(value)
    if not text:
        return None
    try:
        return datetime.fromisoformat(text.replace('Z', '+00:00'))
    except ValueError:
        return None


def module_archive_event_bounds(module_row):
    """The (earliest, latest) ``deleted_at`` a child of this archive can carry.

    None when the module carries no usable stamp, which leaves the marker as the
    only test -- exactly the behaviour before the window existed.
    """
    archived_at = stamp_datetime((module_row or {}).get('deleted_at'))
    if archived_at is None:
        return None
    return archived_at - MODULE_ARCHIVE_EVENT_WINDOW, archived_at + MODULE_ARCHIVE_EVENT_WINDOW


def row_in_module_archive(row, markers, bounds=None):
    """Would restoring this module bring this child row back?

    A live row is kept -- the caller is reading an archived module, but a child
    that was never soft-deleted is still part of it. A deleted one is kept only
    when its ``deleted_via_parent`` marker is one of this module's, so a
    component deleted by hand before the module was archived stays out: reading
    an archived module must show what a restore returns, not everything the table
    has ever held under that id.

    ``bounds`` (``module_archive_event_bounds``) also requires the row to have
    been archived in the same moment as the module. A module once archived and
    then brought back by a save keeps the children of that earlier archive
    stamped with its id; they belong to no archive the module is in now.
    """
    if not curriculum_row_effectively_deleted(row):
        return True
    if clean_str(row.get('deleted_via_parent')) not in markers:
        return False
    if bounds is None:
        return True
    deleted_at = stamp_datetime(row.get('deleted_at'))
    if deleted_at is None:
        return True
    try:
        return bounds[0] <= deleted_at <= bounds[1]
    except TypeError:
        # Naive against aware: the two stamps came from different writers.
        # Fall back to the marker rather than guess an offset.
        return True


def read_module_structure_with_revision(module_catalogue_id):
    """Read each owned row once for both the editable payload and its guard.

    A revision and payload assembled from the same rows cannot certify newer
    data than the editor received. PATCH still fingerprints fresh database rows
    before accepting a save. Reused raw rows are verified against their current
    SQL fingerprints on every rebuild, independently of response-cache epochs.
    """
    source_rows = module_structure_source_rows(module_catalogue_id)
    payload = structure_payload_with_revision(
        lambda: get_authoring_structure_payload(module_catalogue_id, source_rows=source_rows),
        module_catalogue_id, source_rows=source_rows,
    )
    return with_item_fingerprints(payload)


def module_structure_source_rows(module_catalogue_id):
    """Every row one module's structure is built from, one read per table.

    The rows a structure payload and its revision are both computed from, so
    the two describe the same moment. The structure GET, the changes feed and
    the item-merging save all read through this.
    """
    from .authoring_read_transport import compact_authoring_rows
    orders = {
        AUTHORING_WEEKS_TABLE: 'display_order, week_number, id',
        AUTHORING_COMPONENTS_TABLE: 'display_order, id',
        AUTHORING_KSB_MAPPINGS_TABLE: 'created_at, id',
    }
    return {
        table: compact_authoring_rows(
            table, 'module_catalogue_id = %s', [module_catalogue_id], orders.get(table, sort_column),
            reuse_unchanged=table in (AUTHORING_COMPONENTS_TABLE, AUTHORING_KSB_MAPPINGS_TABLE),
        ) for _label, table, _keep, sort_column in STRUCTURE_REVISION_SOURCES
    }


def with_item_fingerprints(payload):
    """Stamp the per-week and per-component fingerprints the editor merges by.

    Kept beside the content rather than computed in the browser: the browser
    normalises what it reads, and a fingerprint has to describe the server's
    copy exactly for "has anyone changed this since I read it?" to be exact.
    See module_merge.
    """
    if not payload:
        return payload
    from .module_merge import structure_fingerprints
    return {**payload, 'itemFingerprints': structure_fingerprints(payload)}


def get_authoring_structure_payload(module_catalogue_id, include_archived=False, *, source_rows=None):
    """The module's authored structure.

    ``include_archived`` is for reading a module that is *in* the archive. The
    archive cascade soft-deletes every week, component and mapping under the
    module, so the ``active_*`` filters below -- correct for every live read --
    return the module with an empty week list. The archive view has to show what
    is actually sitting inside it, which is the set a restore would bring back;
    see ``row_in_module_archive``. Nothing else about the payload changes, so the
    archive renders the same shape the builder does.
    """
    def owned_rows(table, order=''):
        if source_rows is not None:
            return source_rows[table]
        return authoring_fetch_all(table, 'module_catalogue_id = %s', [module_catalogue_id], order)

    module_rows = owned_rows(AUTHORING_MODULES_TABLE)
    if not module_rows:
        return None
    module = module_rows[0]
    group_rows = authoring_fetch_all(GROUPS_TABLE, 'group_id = %s', [module.get('group_id')]) if module.get('group_id') else []
    group_row = group_rows[0] if group_rows else {}
    # Read through the group's pattern, so every screen shows the days and clock
    # this module is actually delivered on rather than a stale copy of them.
    delivery_module = module_delivery_row(module, group_row)
    group_coach_name = clean_str(group_row.get('coach_name'))
    is_programme_deleted = programme_deleted_row(module) or programme_deleted_row(group_row)
    stored_week_rows = owned_rows(AUTHORING_WEEKS_TABLE, 'display_order, week_number, id')
    stored_component_rows = owned_rows(AUTHORING_COMPONENTS_TABLE, 'display_order, id')
    stored_mapping_rows = owned_rows(AUTHORING_KSB_MAPPINGS_TABLE, 'created_at, id')
    if include_archived:
        # The type and library exclusions stay: a retired component type and a
        # detached library row are not this module's content either way, and a
        # restore does not make them so.
        markers = module_archive_parent_markers(module, module_catalogue_id)
        bounds = module_archive_event_bounds(module)
        week_rows = [
            row for row in stored_week_rows
            if not is_library_row(row) and row_in_module_archive(row, markers, bounds)
        ]
        component_rows = [
            row for row in stored_component_rows
            if not is_retired_component_type(row.get('type'))
            and not is_library_row(row)
            and row_in_module_archive(row, markers, bounds)
        ]
        mapping_source_rows = [
            row for row in stored_mapping_rows if row_in_module_archive(row, markers, bounds)
        ]
    else:
        week_rows = active_week_rows(stored_week_rows)
        component_rows = active_component_rows(stored_component_rows)
        mapping_source_rows = active_mapping_rows(stored_mapping_rows)
    mapping_rows = mappings_with_inferred_sources(mapping_source_rows, module_rows)
    completion_rows = owned_rows(AUTHORING_COMPLETION_TABLE)
    advanced_rows = owned_rows(AUTHORING_ADVANCED_TABLE)

    mappings_by_week = defaultdict(list)
    mappings_by_component = defaultdict(list)
    module_mappings = []
    for row in mapping_rows:
        if row.get('component_id'):
            mappings_by_component[str(row.get('component_id'))].append(mapping_response(row))
        elif row.get('week_id'):
            mappings_by_week[str(row.get('week_id'))].append(mapping_response(row))
        else:
            module_mappings.append(mapping_response(row))

    components_by_week = defaultdict(list)
    for row in component_rows:
        component_id = str(row.get('id'))
        week_id = str(row.get('week_id'))
        component_mappings = [
            component_ksb_mapping_api_item(mapping)
            for mapping in component_ksb_mappings_from_row(row, mappings_by_component.get(component_id, []))
        ]
        components_by_week[week_id].append({
            'id': component_id,
            'moduleId': module_catalogue_id,
            'weekId': week_id,
            'type': frontend_component_type(row.get('type')),
            'title': row.get('title') or '',
            'description': row.get('description') or '',
            'expectedOtjh': float(row.get('expected_otjh') or 0),
            'points': parse_int(row.get('points'), 0),
            'reflectionRequired': bool(row.get('reflection_required')),
            'reflectionQuestion': component_reflection_question(row),
            'workplaceEvidenceRequired': bool(row.get('workplace_evidence_required')),
            'tutorValidationRequired': bool(row.get('tutor_validation_required')),
            'coachValidationRequired': component_coach_validation(row),
            'ksbMappings': component_mappings,
            'settings': component_builder_settings(row),
        })

    weeks = []
    for row in week_rows:
        week_id = str(row.get('id'))
        weeks.append({
            'id': week_id,
            'moduleId': module_catalogue_id,
            'weekNumber': parse_int(row.get('week_number'), len(weeks) + 1),
            'title': row.get('title') or '',
            'summary': row.get('summary') or '',
            'learningOutcomes': as_json_value(row.get('learning_outcomes'), []),
            'copiedFromId': clean_str(row.get('copied_from_id')),
            'holidayNoteEnabled': bool(row.get('holiday_note_enabled')),
            'holidayNote': clean_str(row.get('holiday_note')),
            'components': components_by_week.get(week_id, []),
            'ksbMappings': mappings_by_week.get(week_id, []),
        })

    # Live components consume the module's flat plan in display order. A week may
    # therefore consume several dates; its header uses the first one. Content-only
    # weeks retain the legacy one-week/one-session behavior.
    apply_module_session_plan_to_weeks(module, group_row, weeks)
    apply_shared_teams_settings_to_weeks(module, weeks)

    advanced = advanced_response(advanced_rows[0] if advanced_rows else None)
    payload = {
        'id': f'module-{module_catalogue_id}',
        'moduleId': module_catalogue_id,
        'moduleCatalogueId': module_catalogue_id,
        'structureId': module_catalogue_id,
        'catalogueId': module_catalogue_id,
        'programmeId': module.get('programme_id') or module.get('programme_name') or '',
        'programmeName': module.get('programme_name') or 'Unassigned programme',
        'cohortId': module.get('cohort_id') or '',
        'cohort': module.get('cohort_name') or '',
        'groupId': module.get('group_id') or '',
        'group': module.get('group_name') or '',
        'learnerRosterMode': clean_str(module.get('learner_roster_mode') or 'inherited').lower() or 'inherited',
        'teamsSharedSourceModuleId': clean_str(module.get('teams_shared_source_module_id')),
        'ksbRemapReport': parse_json_value(module.get('ksb_remap_report'), {}) or None,
        'title': module.get('title') or '',
        'description': module.get('description') or '',
        'color': module.get('color') or '#6941c6',
        'coverImage': module.get('cover_image_url') or '',
        'status': module.get('status') or 'draft',
        'sourceType': module.get('source_type') or '',
        'sourceId': module.get('source_id') or '',
        'isProgrammeDeleted': is_programme_deleted,
        'ksbProfileSourceId': normalise_ksb_profile_source_value(module.get('ksb_profile_source_id') or ''),
        'tutor': module.get('tutor_name') or '',
        'coach': group_coach_name,
        'sessionsNumber': parse_int(module.get('sessions_number'), len(weeks)),
        'startDate': format_date(module.get('start_date')),
        'endDate': format_date(module.get('end_date')),
        'weeklySchedule': module_weekly_schedule(delivery_module),
        'sessionHolidays': parse_json_value(module.get('session_holidays'), []),
        'deliveryWeeks': module_delivery_week_count(module, weeks),
        # The pattern this module actually runs to: its group's, and its own
        # only where the group states none.
        'weekDays': delivery_module.get('session_week_day') or '',
        'startTime': delivery_module.get('session_start_time') or '',
        'endTime': delivery_module.get('session_end_time') or '',
        'weeks': module_stored_week_count(module, len(weeks)),
        'weeksNumber': module_stored_week_count(module, len(weeks)),
        'totalOtjh': float(module.get('total_otjh') or 0),
        'declaredTotalOtjh': float(module.get('total_otjh') or 0),
        'ksbCount': len({mapping['code'] for mapping in module_mappings + [m for week in weeks for m in week['ksbMappings']] + [m for week in weeks for component in week['components'] for m in component['ksbMappings']]}),
        'lessonCount': len(component_rows),
        'quizCount': len([row for row in component_rows if normalise_component_type(row.get('type')) == 'quiz']),
        'qualityScore': parse_int(module.get('quality_score'), 0),
        'moduleKsbMappings': module_mappings,
        'completionCriteria': completion_response(completion_rows[0] if completion_rows else None),
        'weekStructure': weeks,
        **advanced,
    }
    if payload.get('cohort') or payload.get('group') or payload.get('cohortId') or payload.get('groupId'):
        payload['deliveryMetadata'] = {
            'cohortId': payload.get('cohortId') or '',
            'cohort': payload.get('cohort') or '',
            'groupId': payload.get('groupId') or '',
            'group': payload.get('group') or '',
            'coach': payload.get('coach') or '',
            'tutor': payload.get('tutor') or '',
            'color': payload.get('color') or '',
            'weeklySchedule': payload.get('weeklySchedule') or [],
            'weekDays': payload.get('weekDays') or '',
            'startTime': payload.get('startTime') or '',
            'endTime': payload.get('endTime') or '',
        }
    teams_metadata = teams_delivery_metadata_from_weeks(weeks) or teams_delivery_metadata_from_live_session(module_catalogue_id)
    if teams_metadata:
        payload['deliveryMetadata'] = {**(payload.get('deliveryMetadata') or {}), **teams_metadata}
    if module.get('source_type') == 'training_plan' and module.get('source_id'):
        training_row = training_row_by_id(module.get('source_id'))
        if training_row:
            payload['deliveryStatus'] = delivery_status_for_training_row(training_row)
            payload['deliveryMetadata'] = {
                **(payload.get('deliveryMetadata') or {}),
                'cohort': training_row.get('Cohort_name') or '',
                'group': training_row.get('group_name') or training_row.get('_meta', {}).get('group_name') or '',
                'tutor': training_row.get('Tutor_name') or '',
                'coach': training_row.get('coach_name') or '',
            }
    checklist, score = module_authoring_quality_check(payload)
    payload['qualityChecklist'] = checklist
    payload['qualityScore'] = score
    return payload


def structure_payloads_cache_key(module_catalogue_ids, **options):
    """Cache key covering every input that can change get_authoring_structure_payloads().

    The identifier list is cleaned and sorted first, so two requests naming the same
    modules in a different order (or with duplicates, or with surrounding whitespace)
    share one entry — the function's own result is keyed by catalogue id, so order in
    never affects the mapping out.

    Every shaping option is rendered into the key from its actual value rather than
    being summarised by a hand-written label. A caller that adds an option, or flips
    one, gets a different key automatically; there is no constant left to forget to
    update, which is what makes two semantically different requests unable to collide.
    """
    catalogue_ids = sorted(unique([clean_str(value) for value in (module_catalogue_ids or []) if clean_str(value)]))
    flags = ','.join(f'{name}={bool(value)}' for name, value in sorted(options.items()))
    # Hash the identifier list: a resolve request can name hundreds of modules, and an
    # unbounded key would sit in the process cache dict for the whole TTL. The joiner is
    # a separator that cannot occur in a cleaned identifier, so [MOD-A, B] and [MOD-AB]
    # cannot hash alike.
    ids_digest = hashlib.sha256(''.join(catalogue_ids).encode()).hexdigest()[:32]
    return f'module-structure-payloads:{flags}:{len(catalogue_ids)}:{ids_digest}'


# Rows per statement for full-width reads of curriculum.components.
#
# A full row carries settings_json, and one programme can own ~17k live
# components (~36 MB of settings). Read in one statement that ran past the
# database's 15s statement timeout -- the server counts the time spent pushing
# rows to a remote client -- so the programme detail build failed every time
# and, failing, was never cached. Pages of this size finish in a few seconds
# each.
COMPONENT_FULL_READ_PAGE_ROWS = 2000


def live_component_rows_paged(module_ids=None, order_sql='display_order, id'):
    """Every column of the live component rows of ``module_ids`` (all when None), in pages.

    Returns the same rows, in the same order, that
    ``active_component_rows(authoring_fetch_all(components, 'module_catalogue_id in (...)', ids, order_sql))``
    would -- callers still apply that filter -- by two changes to how they are
    fetched:

    * Soft-deleted rows are left out by the query (Postgres only). They are a
      third of the table and the Python filter drops them anyway: a non-null
      ``deleted_at`` timestamp is always truthy and ``is not true`` is exactly
      truthy() on a boolean, so the SQL drops a subset of what
      active_component_rows() drops, never more. sqlite (tests) can hold an
      empty-string ``deleted_at`` that the Python filter treats as live, so the
      filter is not applied there.
    * The read is paged with LIMIT/OFFSET over the caller's ``order_sql``. The
      order must be total -- ``id`` is the primary key and ends the default --
      so the pages concatenate into exactly the single statement's order, in the
      database's own collation, which Python could not reproduce by re-sorting.

    The ids are de-duplicated and sorted before the memoised read, so the
    structure reader and the component-builder reader of one detail build share
    one fetch whatever order each holds its ids in; the row order comes from
    ``order_sql`` alone.
    """
    ids = None if module_ids is None else tuple(sorted({clean_str(value) for value in module_ids if clean_str(value)}))
    if ids is not None and not ids:
        return []
    return _live_component_rows_paged(ids, order_sql)


@scoped_curriculum_read
def _live_component_rows_paged(module_ids, order_sql):
    clauses = []
    params = []
    if module_ids is not None:
        clauses.append(f'module_catalogue_id in ({", ".join(["%s"] * len(module_ids))})')
        params = list(module_ids)
    if connection.vendor == 'postgresql':
        if has_column(AUTHORING_COMPONENTS_TABLE, 'deleted_at'):
            clauses.append(f'{quote_ident("deleted_at")} is null')
        if has_column(AUTHORING_COMPONENTS_TABLE, 'is_programme_deleted'):
            clauses.append(f'{quote_ident("is_programme_deleted")} is not true')
    where = ' and '.join(f'({clause})' for clause in clauses)
    rows = []
    seen_ids = set()
    offset = 0
    while True:
        page = authoring_fetch_all(
            AUTHORING_COMPONENTS_TABLE, where, params,
            f'{order_sql} limit {COMPONENT_FULL_READ_PAGE_ROWS} offset {offset}',
        )
        for row in page:
            # A row inserted between two pages shifts the offset by one and can
            # repeat the previous page's last row; never return it twice.
            row_id = str(row.get('id'))
            if row_id in seen_ids:
                continue
            seen_ids.add(row_id)
            rows.append(row)
        if len(page) < COMPONENT_FULL_READ_PAGE_ROWS:
            return rows
        offset += COMPONENT_FULL_READ_PAGE_ROWS


# Carries, per row, which content keys the database stripped from settings_json.
COMPONENT_DB_OMITTED_KEYS_COLUMN = 'settings_content_omitted__'


def live_component_rows_without_content(module_ids):
    """``live_component_rows_paged(module_ids)`` with the authored long text
    (COMPONENT_CONTENT_SETTING_KEYS) stripped from ``settings_json`` by Postgres.

    ``omit=content`` used to drop that text in Python, after the database had
    already shipped it: ~24 MB of the components table's 39 MB is settings_json,
    nearly all of it these keys, and the largest programme holds ~17k of the
    table's ~18k rows. Stripping in the query keeps it on the database side.

    Each row also carries COMPONENT_DB_OMITTED_KEYS_COLUMN: the stripped keys
    whose value was not empty, in COMPONENT_CONTENT_SETTING_KEYS order -- what
    component_rows_without_content() would have named.

    Returns None where this read does not apply (not Postgres, no module ids,
    no settings_json column); the caller then takes the full read.
    """
    ids = tuple(sorted({clean_str(value) for value in (module_ids or []) if clean_str(value)}))
    if not ids or connection.vendor != 'postgresql':
        return None
    ensure_module_authoring_tables()
    columns = column_names(AUTHORING_COMPONENTS_TABLE)
    if 'settings_json' not in columns:
        return None
    keys = list(COMPONENT_CONTENT_SETTING_KEYS)
    settings = f'component.{quote_ident("settings_json")}::jsonb'
    omitted = f'omitted.{quote_ident(COMPONENT_DB_OMITTED_KEYS_COLUMN)}'
    select_list = ', '.join(f'component.{quote_ident(column)}' for column in sorted(columns - {'settings_json'}))
    # Only non-empty values go, as in component_rows_without_content(): an
    # empty one stays in settings and is not named as omitted.
    select_list += (
        f", case when jsonb_typeof({settings}) = 'object' then {settings} - {omitted} else {settings} end"
        f' as {quote_ident("settings_json")}, {omitted}'
    )
    omitted_keys = (
        f"select case when jsonb_typeof({settings}) = 'object' then array("
        f'select entry.key from jsonb_each({settings}) as entry'
        f' where entry.key = any(%s::text[])'
        f""" and entry.value not in ('null'::jsonb, '""'::jsonb, '[]'::jsonb, '{{}}'::jsonb)"""
        f' order by array_position(%s::text[], entry.key)'
        f') else array[]::text[] end as {quote_ident(COMPONENT_DB_OMITTED_KEYS_COLUMN)}'
    )
    # Same filter as _live_component_rows_paged: live rows of these modules only.
    clauses = [f'component.module_catalogue_id in ({", ".join(["%s"] * len(ids))})']
    if 'deleted_at' in columns:
        clauses.append(f'component.{quote_ident("deleted_at")} is null')
    if 'is_programme_deleted' in columns:
        clauses.append(f'component.{quote_ident("is_programme_deleted")} is not true')
    where = ' and '.join(f'({clause})' for clause in clauses)
    table = f'{authoring_table_name(AUTHORING_COMPONENTS_TABLE)} as component'
    # The order first, from the ids alone, then the rows in id batches. Paging
    # the row query with LIMIT/OFFSET made Postgres sort -- and so strip --
    # every row ahead of the offset again on each page: ~21 s for the largest
    # programme against ~10 s for the same rows read once each.
    with connection.cursor() as cursor:
        cursor.execute(f'select component.id from {table} where {where} order by component.display_order, component.id', list(ids))
        ordered_ids = [row[0] for row in cursor.fetchall()]
    rows_by_id = {}
    for start in range(0, len(ordered_ids), COMPONENT_FULL_READ_PAGE_ROWS):
        batch = ordered_ids[start:start + COMPONENT_FULL_READ_PAGE_ROWS]
        with connection.cursor() as cursor:
            cursor.execute(
                f'select {select_list} from {table} cross join lateral ({omitted_keys}) as omitted'
                f' where ({where}) and component.id in ({", ".join(["%s"] * len(batch))})',
                [keys, keys, *ids, *batch],
            )
            for row in rows_as_dicts(cursor):
                rows_by_id[row.get('id')] = row
    # A row archived between the two reads is simply absent; one added is not
    # in the order and waits for the next read, as it would on a later page.
    return [rows_by_id[row_id] for row_id in ordered_ids if row_id in rows_by_id]


def get_authoring_structure_payloads(
    module_catalogue_ids,
    include_staff=True,
    include_quality=True,
    include_extra=True,
    component_columns=None,
    child_rows=None,
):
    catalogue_ids = unique([clean_str(value) for value in (module_catalogue_ids or []) if clean_str(value)])
    if not catalogue_ids:
        return {}
    placeholders = ', '.join(['%s'] * len(catalogue_ids))
    # A caller that already read a superset of these modules and their weeks
    # (programme_structure_child_rows) hands them in rather than paying for
    # the same two reads again. Neither read's order reaches the payload except
    # the weeks', which is total, so a filtered slice is the same rows in the
    # same order.
    shared_parents = child_rows is not None and 'modules' in child_rows and 'weeks' in child_rows
    if shared_parents:
        requested_ids = set(catalogue_ids)
        module_rows = [row for row in child_rows['modules'] if clean_str(row.get('module_catalogue_id')) in requested_ids]
    else:
        module_rows = authoring_fetch_all(AUTHORING_MODULES_TABLE, f'module_catalogue_id in ({placeholders})', catalogue_ids)
    if not module_rows:
        return {}

    found_ids = [clean_str(row.get('module_catalogue_id')) for row in module_rows if clean_str(row.get('module_catalogue_id'))]
    wanted_ids = set(found_ids)
    placeholders = ', '.join(['%s'] * len(found_ids))
    if shared_parents:
        week_rows = active_week_rows([row for row in child_rows['weeks'] if clean_str(row.get('module_catalogue_id')) in wanted_ids])
    else:
        week_rows = active_week_rows(authoring_fetch_all(AUTHORING_WEEKS_TABLE, f'module_catalogue_id in ({placeholders})', found_ids, 'display_order, week_number, id'))
    if child_rows is not None:
        component_rows = active_component_rows([
            row for row in child_rows['components'] if clean_str(row.get('module_catalogue_id')) in wanted_ids
        ])
    elif component_columns is None:
        component_rows = active_component_rows(live_component_rows_paged(found_ids, 'display_order, id'))
    else:
        component_rows = active_component_rows(authoring_fetch_all(
            AUTHORING_COMPONENTS_TABLE,
            f'module_catalogue_id in ({placeholders})',
            found_ids,
            'display_order, id',
            columns=component_columns,
        ))
    mapping_rows = mappings_with_inferred_sources(
        active_mapping_rows([
            row for row in child_rows['mappings'] if clean_str(row.get('module_catalogue_id')) in wanted_ids
        ] if child_rows is not None else authoring_fetch_all(AUTHORING_KSB_MAPPINGS_TABLE, f'module_catalogue_id in ({placeholders})', found_ids, 'created_at, id')),
        module_rows,
    )
    if include_extra:
        ensure_live_session_tracking_tables()
        shared_source_by_module = {
            clean_str(row.get('module_catalogue_id')): clean_str(row.get('teams_shared_source_module_id'))
            for row in module_rows
            if clean_str(row.get('module_catalogue_id')) and clean_str(row.get('teams_shared_source_module_id'))
        }
        session_lookup_ids = unique([*found_ids, *shared_source_by_module.values()])
        session_placeholders = ', '.join(['%s'] * len(session_lookup_ids))
        # The three reads below in one round trip; each still runs as written.
        prefetch_authoring_reads([
            ((AUTHORING_COMPLETION_TABLE, f'module_catalogue_id in ({placeholders})', found_ids), {}),
            ((AUTHORING_ADVANCED_TABLE, f'module_catalogue_id in ({placeholders})', found_ids), {}),
            ((LIVE_SESSIONS_TABLE, f"module_catalogue_id in ({session_placeholders}) and status = 'active'", session_lookup_ids, 'updated_at desc, created_at desc'), {}),
        ])
    completion_rows = authoring_fetch_all(AUTHORING_COMPLETION_TABLE, f'module_catalogue_id in ({placeholders})', found_ids) if include_extra else []
    advanced_rows = authoring_fetch_all(AUTHORING_ADVANCED_TABLE, f'module_catalogue_id in ({placeholders})', found_ids) if include_extra else []
    # Newest active live session per module, read once for the whole set. The
    # single-module reader falls back to this when a module's weeks carry no
    # Teams metadata, so a batched caller that skipped it would silently lose
    # the meeting details for exactly those modules.
    live_session_by_module = {}
    if include_extra:
        for row in authoring_fetch_all(
            LIVE_SESSIONS_TABLE,
            f"module_catalogue_id in ({session_placeholders}) and status = 'active'",
            session_lookup_ids,
            'updated_at desc, created_at desc',
        ):
            key = clean_str(row.get('module_catalogue_id'))
            # Ordered newest first, so the first row seen for a module is the one
            # the single-module reader would have taken as sessions[0].
            if key and key not in live_session_by_module:
                live_session_by_module[key] = row
        for alias_id, source_id in shared_source_by_module.items():
            if alias_id not in live_session_by_module and source_id in live_session_by_module:
                live_session_by_module[alias_id] = live_session_by_module[source_id]
    group_ids = unique([clean_str(row.get('group_id')) for row in module_rows])
    group_rows_by_id = {}
    if group_ids:
        # Keyed by the primary key, so where the rows come from cannot change
        # what this holds; inside a programme build it is the groups read the
        # cohort/group lists already made.
        group_rows_by_id = {
            clean_str(row.get('group_id')): row
            for row in authoring_rows_by_id(GROUPS_TABLE, 'group_id', group_ids, GROUP_ROWS_ORDER)
        }

    # Every cohort's ticked holidays in one pair of reads, because the session
    # plan below runs per module. Left unsupplied, each module would read its own
    # cohort row and the whole holiday table again -- the per-module cost
    # cohort_selected_holidays_by_cohort() exists to spare a caller planning a
    # page of modules, and the last per-module read in this otherwise batched
    # reader. A 122-module programme paid ~250 round trips for it.
    holidays_by_cohort = cohort_selected_holidays_by_cohort(
        [clean_str(row.get('cohort_id')) for row in module_rows]
    ) if include_extra else {}

    week_rows_by_module = defaultdict(list)
    for row in week_rows:
        week_rows_by_module[clean_str(row.get('module_catalogue_id'))].append(row)

    components_by_week = defaultdict(list)
    component_rows_by_module = defaultdict(list)
    mappings_by_week = defaultdict(list)
    mappings_by_component = defaultdict(list)
    module_mappings_by_module = defaultdict(list)
    completion_by_module = {clean_str(row.get('module_catalogue_id')): row for row in completion_rows}
    advanced_by_module = {clean_str(row.get('module_catalogue_id')): row for row in advanced_rows}

    for row in mapping_rows:
        catalogue_id = clean_str(row.get('module_catalogue_id'))
        if row.get('component_id'):
            mappings_by_component[str(row.get('component_id'))].append(mapping_response(row))
        elif row.get('week_id'):
            mappings_by_week[str(row.get('week_id'))].append(mapping_response(row))
        else:
            module_mappings_by_module[catalogue_id].append(mapping_response(row))

    for row in component_rows:
        catalogue_id = clean_str(row.get('module_catalogue_id'))
        component_id = str(row.get('id'))
        week_id = str(row.get('week_id'))
        component_mappings = [
            component_ksb_mapping_api_item(mapping)
            for mapping in component_ksb_mappings_from_row(row, mappings_by_component.get(component_id, []))
        ]
        component = {
            'id': component_id,
            'moduleId': catalogue_id,
            'weekId': week_id,
            'type': frontend_component_type(row.get('type')),
            'title': row.get('title') or '',
            'description': row.get('description') or '',
            'expectedOtjh': float(row.get('expected_otjh') or 0),
            'points': parse_int(row.get('points'), 0),
            'reflectionRequired': bool(row.get('reflection_required')),
            'reflectionQuestion': component_reflection_question(row),
            'workplaceEvidenceRequired': bool(row.get('workplace_evidence_required')),
            'tutorValidationRequired': bool(row.get('tutor_validation_required')),
            'coachValidationRequired': component_coach_validation(row),
            'ksbMappings': component_mappings,
            'settings': as_json_value(row.get('settings_json'), {}),
        }
        components_by_week[week_id].append(component)
        component_rows_by_module[catalogue_id].append(row)

    payloads = {}
    for module in module_rows:
        catalogue_id = clean_str(module.get('module_catalogue_id'))
        if not catalogue_id:
            continue
        weeks = []
        for row in week_rows_by_module.get(catalogue_id, []):
            week_id = str(row.get('id'))
            weeks.append({
                'id': week_id,
                'moduleId': catalogue_id,
                'weekNumber': parse_int(row.get('week_number'), len(weeks) + 1),
                'title': row.get('title') or '',
                'summary': row.get('summary') or '',
                'learningOutcomes': as_json_value(row.get('learning_outcomes'), []),
                'copiedFromId': clean_str(row.get('copied_from_id')),
                'holidayNoteEnabled': bool(row.get('holiday_note_enabled')),
                'holidayNote': clean_str(row.get('holiday_note')),
                'components': components_by_week.get(week_id, []),
                'ksbMappings': mappings_by_week.get(week_id, []),
            })
        module_mappings = module_mappings_by_module.get(catalogue_id, [])
        module_components = component_rows_by_module.get(catalogue_id, [])
        module_total_otjh = otjh_hours_from_minutes(sum(
            otjh_rounded_minutes(row.get('expected_otjh'))
            for row in module_components
        ))
        group_row = group_rows_by_id.get(clean_str(module.get('group_id')), {})
        # The days and clock this module is delivered on: its group's first.
        delivery_module = module_delivery_row(module, group_row)
        group_coach_name = clean_str(group_row.get('coach_name'))
        is_programme_deleted = programme_deleted_row(module) or programme_deleted_row(group_row)
        if include_extra:
            # Gated with the other full-detail extras: this rewrites live-session
            # component settings, and the lean caller (resolve) asked not to pay
            # for -- or be changed by -- that. The single-module reader always
            # applies it, so parity holds wherever include_extra is on.
            apply_module_session_plan_to_weeks(
                module,
                group_row,
                weeks,
                holidays=holidays_by_cohort.get(clean_str(module.get('cohort_id'))) or [],
            )
            # A shared duplicate has no live_sessions row of its own. Project
            # the canonical source's links into this response so every Live
            # Session still shows the shared meeting without copying ownership.
            apply_shared_teams_settings_to_weeks(module, weeks)
        payload = {
            'id': f'module-{catalogue_id}',
            'moduleId': catalogue_id,
            'moduleCatalogueId': catalogue_id,
            'structureId': catalogue_id,
            'catalogueId': catalogue_id,
            'programmeId': module.get('programme_id') or module.get('programme_name') or '',
            'programmeName': module.get('programme_name') or 'Unassigned programme',
            'cohortId': module.get('cohort_id') or '',
            'cohort': module.get('cohort_name') or '',
            'groupId': module.get('group_id') or '',
            'group': module.get('group_name') or '',
            'learnerRosterMode': clean_str(module.get('learner_roster_mode') or 'inherited').lower() or 'inherited',
            'teamsSharedSourceModuleId': clean_str(module.get('teams_shared_source_module_id')),
            'ksbRemapReport': parse_json_value(module.get('ksb_remap_report'), {}) or None,
            'title': module.get('title') or '',
            'description': module.get('description') or '',
            'color': module.get('color') or '#6941c6',
            'coverImage': module.get('cover_image_url') or '',
            'status': module.get('status') or 'draft',
            'sourceType': module.get('source_type') or '',
            'sourceId': module.get('source_id') or '',
            'isProgrammeDeleted': is_programme_deleted,
            'ksbProfileSourceId': normalise_ksb_profile_source_value(module.get('ksb_profile_source_id') or ''),
            'tutor': module.get('tutor_name') or '',
            'coach': group_coach_name,
            'sessionsNumber': parse_int(module.get('sessions_number'), len(weeks)),
            'startDate': format_date(module.get('start_date')),
            'endDate': format_date(module.get('end_date')),
            'weeklySchedule': module_weekly_schedule(delivery_module),
            'sessionHolidays': parse_json_value(module.get('session_holidays'), []),
            'deliveryWeeks': module_delivery_week_count(module, weeks),
            # The group's pattern first; the module's own only where it states none.
            'weekDays': delivery_module.get('session_week_day') or '',
            'startTime': delivery_module.get('session_start_time') or '',
            'endTime': delivery_module.get('session_end_time') or '',
            'weeks': module_stored_week_count(module, len(weeks)),
            'weeksNumber': module_stored_week_count(module, len(weeks)),
            'totalOtjh': module_total_otjh,
            'declaredTotalOtjh': module_total_otjh,
            'ksbCount': len({mapping['code'] for mapping in module_mappings + [m for week in weeks for m in week['ksbMappings']] + [m for week in weeks for component in week['components'] for m in component['ksbMappings']]}),
            'lessonCount': len(module_components),
            'quizCount': len([row for row in module_components if normalise_component_type(row.get('type')) == 'quiz']),
            'qualityScore': parse_int(module.get('quality_score'), 0),
            'moduleKsbMappings': module_mappings,
            'weekStructure': weeks,
        }
        if include_extra:
            payload['completionCriteria'] = completion_response(completion_by_module.get(catalogue_id))
            payload.update(advanced_response(advanced_by_module.get(catalogue_id)))
        if payload.get('cohort') or payload.get('group') or payload.get('cohortId') or payload.get('groupId'):
            payload['deliveryMetadata'] = {
                'cohortId': payload.get('cohortId') or '',
                'cohort': payload.get('cohort') or '',
                'groupId': payload.get('groupId') or '',
                'group': payload.get('group') or '',
                'coach': payload.get('coach') or '',
                'tutor': payload.get('tutor') or '',
                'color': payload.get('color') or '',
                'weeklySchedule': payload.get('weeklySchedule') or [],
            'weekDays': payload.get('weekDays') or '',
                'startTime': payload.get('startTime') or '',
                'endTime': payload.get('endTime') or '',
            }
        teams_metadata = teams_delivery_metadata_from_weeks(weeks) or teams_delivery_metadata_from_live_session_row(
            live_session_by_module.get(catalogue_id)
        )
        if teams_metadata:
            payload['deliveryMetadata'] = {**(payload.get('deliveryMetadata') or {}), **teams_metadata}
        if module.get('source_type') == 'training_plan' and module.get('source_id'):
            training_row = training_row_by_id(module.get('source_id'))
            if training_row:
                payload['deliveryStatus'] = delivery_status_for_training_row(training_row)
                payload['deliveryMetadata'] = {
                    **(payload.get('deliveryMetadata') or {}),
                    'cohort': training_row.get('Cohort_name') or '',
                    'group': training_row.get('group_name') or training_row.get('_meta', {}).get('group_name') or '',
                    'tutor': training_row.get('Tutor_name') or '',
                    'coach': training_row.get('coach_name') or '',
                }
        if include_quality:
            checklist, score = module_authoring_quality_check(payload)
            payload['qualityChecklist'] = checklist
            payload['qualityScore'] = score
        payloads[catalogue_id] = payload
    return payloads


def live_authoring_rows_sql(table, flag_columns):
    """A where clause that drops rows the Python active_*_rows() filters drop.

    Only ever a subset of what those filters drop, never more: ``deleted_at`` is
    a timestamp and ``is_programme_deleted`` a boolean, so ``is null`` and
    ``is not true`` are exactly row_has_deleted_at() and truthy(), and
    ``library_state <> 'library'`` misses only padded spellings that
    is_library_row() would still catch. Callers keep running the Python filter
    on what comes back, which is what makes the two agree row for row. Columns
    the table does not have are left out, as authoring_fetch_all() leaves them
    out of its select list.
    """
    clauses = []
    params = []
    for column in flag_columns:
        if not has_column(table, column):
            continue
        name = quote_ident(column)
        if column == 'deleted_at':
            # sqlite (tests) has no timestamp type, so an empty string can be
            # stored there; row_has_deleted_at() reads it as not deleted.
            clauses.append(f'{name} is null' if connection.vendor == 'postgresql' else f"({name} is null or {name} = '')")
        elif column == 'library_state':
            clauses.append(f'({name} is null or {name} <> %s)')
            params.append(LIBRARY_STATE_DETACHED)
        else:
            clauses.append(f'({name} is null or {name} = %s)')
            params.append(False)
    return ' and '.join(clauses), params


def authoring_module_content_counts():
    """``(lesson_counts, ksb_counts)`` per module catalogue id, without row reads.

    The same two figures authoring_catalogue_summaries() derives from every
    component and mapping row, grouped by the database instead: the live
    components of each module (retired types and detached rows excluded, as
    active_component_rows() excludes them) and the distinct KSB codes on its live
    mappings. A few hundred grouped rows cross the network instead of ~90k.
    """
    lesson_counts = Counter()
    component_flags = ('deleted_at', 'is_programme_deleted', 'library_state')
    where_sql, params = live_authoring_rows_sql(AUTHORING_COMPONENTS_TABLE, component_flags)
    group_columns = [
        quote_ident(column)
        for column in ('module_catalogue_id', 'type', 'library_state')
        if has_column(AUTHORING_COMPONENTS_TABLE, column)
    ]
    query = (
        f'select {", ".join(group_columns)}, count(*) as {quote_ident("row_count")} '
        f'from {authoring_table_name(AUTHORING_COMPONENTS_TABLE)}'
        + (f' where {where_sql}' if where_sql else '')
        + f' group by {", ".join(group_columns)}'
    )
    for row in fetch_all(query, params):
        if is_retired_component_type(row.get('type')) or is_library_row(row):
            continue
        lesson_counts[str(row.get('module_catalogue_id'))] += parse_int(row.get('row_count'), 0)

    ksb_codes = defaultdict(set)
    where_sql, params = live_authoring_rows_sql(
        AUTHORING_KSB_MAPPINGS_TABLE, ('deleted_at', 'is_programme_deleted', 'is_deleted'),
    )
    query = (
        f'select {quote_ident("module_catalogue_id")}, {quote_ident("ksb_code")} '
        f'from {authoring_table_name(AUTHORING_KSB_MAPPINGS_TABLE)}'
        + (f' where {where_sql}' if where_sql else '')
        + f' group by {quote_ident("module_catalogue_id")}, {quote_ident("ksb_code")}'
    )
    for row in fetch_all(query, params):
        code = clean_str(row.get('ksb_code'))
        if code:
            ksb_codes[str(row.get('module_catalogue_id'))].add(code)
    return dict(lesson_counts), {catalogue_id: len(codes) for catalogue_id, codes in ksb_codes.items()}


# Every component column authoring_catalogue_summaries() reads, plus the three
# the active-row filters need (deleted_at, is_programme_deleted, library_state).
# settings_json and ksb_mappings are excluded on purpose - see the call site.
CATALOGUE_SUMMARY_COMPONENT_COLUMNS = (
    'id', 'week_id', 'module_catalogue_id', 'type', 'title', 'description',
    'expected_otjh', 'points', 'display_order',
    'reflection_required', REFLECTION_QUESTION_COLUMN,
    'workplace_evidence_required', 'tutor_validation_required',
    'coach_validation_required',
    'deleted_at', 'is_programme_deleted', 'library_state',
)


def authoring_catalogue_summaries(include_programme_deleted=False, include_content=True, *, list_only=False):
    """Per-module authoring summaries, keyed by module catalogue id.

    ``include_content=False`` is for a caller that only counts modules. It skips
    the two heaviest reads in the curriculum -- every component and every KSB
    mapping, ~28 MB between them on a remote database -- and fills in only the
    two content figures best_authoring_summary() ranks candidates by,
    ``lessonCount`` and ``ksbCount``, from grouped reads. Everything else
    content-derived (week components, quiz count, OTJH, session names, KSB codes,
    and ``deliveryWeeks``, which reads the week components) is left empty or
    unresolved, so such a summary must never stand in for a full one.
    """
    content_counts = None
    try:
        module_rows = authoring_fetch_all(AUTHORING_MODULES_TABLE, order_sql='updated_at desc, title')
        week_rows = active_week_rows(authoring_fetch_all(AUTHORING_WEEKS_TABLE, columns=WEEK_INDEX_COLUMNS))
        if include_content and list_only and connection.vendor == 'postgresql':
            from .catalogue_summary_reads import grouped_catalogue_content_rows
            component_rows, mapping_rows = grouped_catalogue_content_rows()
        elif include_content:
            # Narrow deliberately. This builds per-module summaries and week outlines
            # and never reads settings_json (24 MB across this table) or ksb_mappings
            # - the summary sets 'ksbMappings': [] outright. With select * this one
            # call dominated every non-compact overview request.
            #
            # Soft-deleted and detached rows are dropped by the query as well as by
            # active_component_rows(): they are about a third of the table and were
            # crossing the network only to be thrown away here.
            where_sql, params = live_authoring_rows_sql(
                AUTHORING_COMPONENTS_TABLE, ('deleted_at', 'is_programme_deleted', 'library_state'),
            )
            component_rows = active_component_rows(authoring_fetch_all(
                AUTHORING_COMPONENTS_TABLE, where_sql, params,
                columns=(
                    ('id', 'module_catalogue_id', 'week_id', 'type', 'title', 'expected_otjh',
                     'deleted_at', 'is_programme_deleted', 'library_state')
                    if list_only else CATALOGUE_SUMMARY_COMPONENT_COLUMNS
                ),
            ))
            mapping_rows = active_mapping_rows(authoring_fetch_all(
                AUTHORING_KSB_MAPPINGS_TABLE,
                **({'columns': ('module_catalogue_id', 'ksb_code', 'deleted_at', 'is_programme_deleted', 'is_deleted', 'isDeleted', 'isProgrammeDeleted')} if list_only else {}),
            ))
        else:
            component_rows, mapping_rows = [], []
            content_counts = authoring_module_content_counts()
    except Exception:
        logger.exception('Unable to read module authoring catalogue rows.')
        return {}

    group_ids = unique([clean_str(row.get('group_id')) for row in module_rows])
    group_rows_by_id = {}
    if group_ids:
        # Keyed by the primary key, so where the rows come from cannot change
        # what this holds; inside a read scope it is the groups read the
        # list builders share (the training rows read it too).
        group_rows_by_id = {
            clean_str(row.get('group_id')): row
            for row in authoring_rows_by_id(GROUPS_TABLE, 'group_id', group_ids, GROUP_ROWS_ORDER)
        }
    if not include_programme_deleted:
        module_rows = [
            row for row in module_rows
            if not (
                programme_deleted_row(row)
                or programme_deleted_row(group_rows_by_id.get(clean_str(row.get('group_id')), {}))
            )
        ]

    summaries = {}
    module_rows_by_catalogue_id = {}
    for row in module_rows:
        catalogue_id = str(row.get('module_catalogue_id'))
        module_rows_by_catalogue_id[catalogue_id] = row
        group_row = group_rows_by_id.get(clean_str(row.get('group_id')), {})
        group_coach_name = clean_str(group_row.get('coach_name'))
        is_programme_deleted = programme_deleted_row(row) or programme_deleted_row(group_row)
        summaries[catalogue_id] = {
            'catalogueId': catalogue_id,
            'title': row.get('title') or f'Module {catalogue_id}',
            'programmeId': row.get('programme_id') or '',
            'programmeName': row.get('programme_name') or 'Unassigned programme',
            'cohortId': row.get('cohort_id') or '',
            'cohort': row.get('cohort_name') or '',
            'groupId': row.get('group_id') or '',
            'group': row.get('group_name') or '',
            'learnerRosterMode': clean_str(row.get('learner_roster_mode') or 'inherited').lower() or 'inherited',
            'teamsSharedSourceModuleId': clean_str(row.get('teams_shared_source_module_id')),
            'ksbRemapReport': parse_json_value(row.get('ksb_remap_report'), {}) or None,
            'description': row.get('description') or '',
            'coverImage': row.get('cover_image_url') or '',
            'status': row.get('status') or 'draft',
            'sourceType': row.get('source_type') or '',
            'sourceId': row.get('source_id') or '',
            'ksbProfileSourceId': normalise_ksb_profile_source_value(row.get('ksb_profile_source_id') or ''),
            'tutor': row.get('tutor_name') or '',
            'coach': group_coach_name,
            'sessionsNumber': parse_int(row.get('sessions_number'), 0),
            'weeklySchedule': module_weekly_schedule(row),
            'sessionHolidays': parse_json_value(row.get('session_holidays'), []),
            'weekDays': row.get('session_week_day') or '',
            'startTime': row.get('session_start_time') or '',
            'endTime': row.get('session_end_time') or '',
            'startDate': format_date(row.get('start_date')),
            'endDate': format_date(row.get('end_date')),
            'qualityScore': parse_int(row.get('quality_score'), 0),
            'isProgrammeDeleted': is_programme_deleted,
            'lastUpdated': format_date(row.get('updated_at')),
            'createdAt': format_created_at(row.get('created_at')),
            # Seeded at zero because the week loop below counts up as it appends,
            # and uses the running total as the week-number/display-order fallback.
            # The stored count is applied once, after the loop -- seeding it here
            # made the list serve `weeks_number` PLUS the authored week rows, so a
            # 14-week module read back as 28 in the catalogue and in the drawer.
            'weeks': 0,
            'weeksNumber': 0,
            'weekStructure': [],
            'ksbCount': 0,
            'lessonCount': 0,
            'quizCount': 0,
            'totalOtjh': 0,
            'totalOtjhMinutes': 0,
            'sessionNames': [],
            'ksbCodes': set(),
        }

    for row in sorted(week_rows, key=lambda item: (
        parse_int(item.get('display_order'), 9999),
        parse_int(item.get('week_number'), 9999),
        clean_str(item.get('id')),
    )):
        catalogue_id = str(row.get('module_catalogue_id'))
        if catalogue_id in summaries:
            summaries[catalogue_id]['weeks'] += 1
            summaries[catalogue_id]['weekStructure'].append({
                'id': clean_str(row.get('id')),
                'weekNumber': parse_int(row.get('week_number'), summaries[catalogue_id]['weeks']),
                'title': row.get('title') or '',
                'displayOrder': parse_int(row.get('display_order'), summaries[catalogue_id]['weeks'] - 1),
            })

    for row in component_rows:
        catalogue_id = str(row.get('module_catalogue_id'))
        summary = summaries.get(catalogue_id)
        if not summary:
            continue
        component_id = clean_str(row.get('id'))
        week_id = clean_str(row.get('week_id'))
        component_type = normalise_component_type(row.get('type'))
        row_count = parse_int(row.get('row_count'), 1) if list_only else 1
        summary['lessonCount'] += row_count
        summary['totalOtjhMinutes'] += otjh_rounded_minutes(row.get('expected_otjh')) * row_count
        summary['totalOtjh'] = otjh_hours_from_minutes(summary['totalOtjhMinutes'])
        if component_type == 'quiz':
            summary['quizCount'] += row_count
        if component_type == 'live_session':
            summary['sessionNames'].extend([row.get('title') or ''] * row_count)
        if list_only:
            # Delivery-week detection needs only the live-session count per
            # week. Do not construct every discarded component's edit payload.
            if component_type == 'live_session':
                for week in summary['weekStructure']:
                    if clean_str(week.get('id')) == week_id:
                        week.setdefault('components', []).extend({'type': 'live-session'} for _ in range(row_count))
                        break
            continue
        for week in summary['weekStructure']:
            if clean_str(week.get('id')) != week_id:
                continue
            week.setdefault('components', []).append({
                'id': component_id,
                'moduleCatalogueId': catalogue_id,
                'moduleId': catalogue_id,
                'weekId': week_id,
                'type': frontend_component_type(row.get('type')),
                'title': row.get('title') or '',
                'description': row.get('description') or '',
                'expectedOtjh': float(row.get('expected_otjh') or 0),
                'points': parse_int(row.get('points'), 0),
                'reflectionRequired': bool(row.get('reflection_required')),
                'reflectionQuestion': component_reflection_question(row),
                'workplaceEvidenceRequired': bool(row.get('workplace_evidence_required')),
                'tutorValidationRequired': bool(row.get('tutor_validation_required')),
                'coachValidationRequired': component_coach_validation(row),
                'ksbMappings': [],
                'settings': component_builder_settings(row),
            })
            break

    for row in mapping_rows:
        catalogue_id = str(row.get('module_catalogue_id'))
        summary = summaries.get(catalogue_id)
        code = clean_str(row.get('ksb_code'))
        if summary and code:
            summary['ksbCodes'].add(code)

    for catalogue_id, summary in summaries.items():
        summary['ksbCount'] = len(summary['ksbCodes'])
        summary['ksbCodes'] = sorted(summary['ksbCodes'])
        # The authored week count the module actually holds, resolved the same way
        # the structure endpoint resolves it: the stored `weeks_number` wins, and
        # rows written before that column existed fall back to the weeks that were
        # counted above. The two reads have to agree -- the catalogue card and the
        # placement drawer read this one, the Module Builder rail reads the other.
        authored_week_count = module_stored_week_count(
            module_rows_by_catalogue_id.get(catalogue_id, {}),
            len(summary.get('weekStructure') or []),
        )
        summary['weeks'] = authored_week_count
        summary['weeksNumber'] = authored_week_count
        summary['deliveryWeeks'] = module_delivery_week_count(module_rows_by_catalogue_id.get(catalogue_id, {}), summary['weekStructure'])

    if content_counts is not None:
        lesson_counts, ksb_counts = content_counts
        for catalogue_id, summary in summaries.items():
            summary['lessonCount'] = lesson_counts.get(catalogue_id, 0)
            summary['ksbCount'] = ksb_counts.get(catalogue_id, 0)

    # The tutor is already on the module row. The coach belongs to the group, so
    # it is read from the group rather than from the person: staff carry no
    # assignment of their own for this to disagree with.
    try:
        coach_by_group = {
            clean_str(row.get('group_id')): clean_str(row.get('coach_name'))
            for row in authoring_fetch_all(GROUPS_TABLE)
            if clean_str(row.get('group_id'))
        }
        for summary in summaries.values():
            coach_name = coach_by_group.get(clean_str(summary.get('groupId')), '')
            if coach_name and not summary.get('coach'):
                summary['coach'] = coach_name
    except Exception:
        logger.debug('Unable to enrich authoring summaries with the group coach.', exc_info=True)

    return summaries


