@csrf_exempt
def curriculum_module_week_detail(request, module_catalogue_id, week_id):
    if request.method != 'DELETE':
        return json_error('Method not allowed.', status=405)
    module_catalogue_id = clean_str(module_catalogue_id)
    week_id = clean_str(week_id)
    payload = json_body(request) if request.body else {}
    with transaction.atomic():
        refused = refuse_stale_module_write(request, payload or {}, module_catalogue_id)
        if refused is not None:
            return refused
        # Read under the lock: a component added to this week after the caller
        # read it is part of what the caller's version check just accepted.
        component_rows = authoring_fetch_all(AUTHORING_COMPONENTS_TABLE, 'module_catalogue_id = %s and week_id = %s', [module_catalogue_id, week_id])
        component_ids = [str(row.get('id')) for row in component_rows]
        if component_ids:
            placeholders = ', '.join(['%s'] * len(component_ids))
            authoring_soft_delete(AUTHORING_KSB_MAPPINGS_TABLE, f'module_catalogue_id = %s and component_id in ({placeholders})', [module_catalogue_id, *component_ids], via_parent=week_id, deleted_by='week-delete')
        authoring_soft_delete(AUTHORING_KSB_MAPPINGS_TABLE, 'module_catalogue_id = %s and week_id = %s', [module_catalogue_id, week_id], via_parent=week_id, deleted_by='week-delete')
        authoring_soft_delete(AUTHORING_COMPONENTS_TABLE, 'module_catalogue_id = %s and week_id = %s', [module_catalogue_id, week_id], via_parent=week_id, deleted_by='week-delete')
        authoring_soft_delete(AUTHORING_WEEKS_TABLE, 'module_catalogue_id = %s and id = %s', [module_catalogue_id, week_id], deleted_by='week-delete')
    log_curriculum_decision(
        'week.archive', outcome='soft_deleted', entity_id=week_id,
        parent_id=module_catalogue_id, row_count=len(component_ids),
    )
    invalidate_curriculum_cache()
    return JsonResponse({'deleted': True, 'permanent': False, 'moduleCatalogueId': module_catalogue_id, 'weekId': week_id})


@require_role('admin', 'staff')
def _update_module_cover(request, identifier, payload):
    """Update artwork without resaving weeks, delivery dates or components."""
    from learner_api.student_activity import _builder_cover_url
    image = payload.get('coverImage')
    if not isinstance(image, str) or len(image) > 4 * 1024 * 1024 + 256:
        return json_error('Choose an image up to 3 MB.', status=400)
    image = image.strip()
    if image and not _builder_cover_url(image):
        return json_error('Choose a valid module image.', status=400)
    # Validated as an image first, then stored: the column keeps a URL, never
    # the picture. See stored_module_cover_image().
    image = stored_module_cover_image(identifier, image)
    try:
        with connection.cursor() as cursor:
            cursor.execute('''UPDATE curriculum.modules SET cover_image_url=%s,updated_at=CURRENT_TIMESTAMP
                              WHERE module_catalogue_id=%s AND deleted_at IS NULL
                                AND NOT coalesce(is_programme_deleted,false)
                              RETURNING module_catalogue_id''', [image, identifier])
            updated_row = cursor.fetchone()
            if not updated_row:
                return json_error('Module not found.', status=404)
        note_live_rows(AUTHORING_MODULES_TABLE, [{'module_catalogue_id': updated_row[0]}])
    except DatabaseError:
        return json_error('Could not save the module image. Please try again.', status=503)
    invalidate_curriculum_cache()
    return JsonResponse({'updated': True, 'coverImage': image})


@csrf_exempt
def curriculum_module_detail(request, identifier):
    if request.method not in {'PATCH', 'DELETE'}:
        return json_error('Method not allowed.', status=405)

    if request.method == 'PATCH':
        cover_payload = json_body(request)
        if isinstance(cover_payload, dict) and set(cover_payload) == {'coverImage'}:
            return _update_module_cover(request, identifier, cover_payload)

    ident = clean_str(identifier)
    if ident.startswith('training-module-'):
        return json_error('Delivery module rows are not available. Use the module catalogue record instead.', status=404)

    module_catalogue_id = resolve_stored_module_catalogue_id(ident)
    existing_authoring = authoring_module_exists(module_catalogue_id) if module_catalogue_id else None
    if existing_authoring:
        if request.method == 'DELETE':
            # Opt-in per request, exactly as the programme, cohort and group
            # deletes read it: a bare DELETE still archives.
            if request_wants_permanent_delete(request):
                return permanent_module_delete_response(existing_authoring)
            # Never archive past a running Teams calendar, and never cancel it
            # on the author's behalf: they cancel it, then archive.
            blocked = module_teams_calendar_block_response(module_catalogue_id)
            if blocked is not None:
                return blocked
            delete_module_authoring_structure(module_catalogue_id)
            log_curriculum_decision(
                'module.archive', outcome='soft_deleted', entity_id=module_catalogue_id,
                parent_id=clean_str(existing_authoring.get('group_id')),
            )
            repair_curriculum_parent_links(clean_str(existing_authoring.get('programme_id')))
            invalidate_curriculum_cache()
            return JsonResponse({'deleted': True, 'deletedAuthoring': True, 'id': identifier})
        payload = json_body(request)
        if payload is None:
            return json_error('Invalid JSON body.')
        try:
            module_weekly_schedule(payload)
        except ValueError as exc:
            return json_error(str(exc), fields=['weeklySchedule'])
        # A caller that sends no revision still writes back the whole structure
        # read just below. Pin the version that read describes -- read first, so
        # it can only be older than the payload, never newer -- and refuse under
        # the lock if a save landed in between, rather than write its weeks back.
        implicit_revision = '' if requested_expected_revision(request, payload) else module_structure_revision(module_catalogue_id)
        current = get_authoring_structure_payload(module_catalogue_id)
        current_delivery_metadata = current.get('deliveryMetadata') if isinstance(current.get('deliveryMetadata'), dict) else {}
        current_week_structure = current.get('weekStructure') or []
        # This PATCH only ever carries the scalar counts, never a new week list
        # (that is the structure-save endpoint's job) -- so a `weeks` edit here
        # has to resize the stored weeks itself, or the count changes while the
        # actual week rows silently stay whatever they were. Growing appends
        # empty weeks after the last one; shrinking only ever drops trailing
        # week shells that hold nothing, so no scalar sent from a form can
        # delete authored weeks and the components inside them.
        requested_weeks_number = parse_int(
            payload.get('weeks') or payload.get('weeksNumber') or current.get('weeksNumber') or current.get('weeks'),
            len(current_week_structure),
        )
        if payload.get('weekStructure') is not None:
            resolved_week_structure = payload.get('weekStructure')
            resolved_weeks_number = requested_weeks_number
        else:
            resolved_week_structure = resize_authoring_week_structure_preserving_content(
                current_week_structure, requested_weeks_number,
            )
            # Re-derived from what survived: storing the requested number while
            # keeping more week rows than that is what left `weeks_number` at 1
            # on a twelve-week module, and every later save then tried to shrink
            # to it again.
            resolved_weeks_number = len(resolved_week_structure) or requested_weeks_number
        structure_payload = {
            **current,
            'catalogueId': module_catalogue_id,
            'programmeId': payload.get('programmeId') or current.get('programmeId'),
            'programmeName': payload.get('programmeName') or payload.get('programme') or current.get('programmeName') or current.get('programme'),
            'title': payload.get('title') or payload.get('name') or current.get('title') or current.get('name'),
            'description': payload.get('description') if 'description' in payload else payload.get('notes') if 'notes' in payload else current.get('description'),
            'color': payload.get('color') or current.get('color') or '',
            'coverImage': payload.get('coverImage') if 'coverImage' in payload else current.get('coverImage') or '',
            'status': payload.get('status') or current.get('status') or 'draft',
            # Kept apart: `weeks` is the authored week count the week builder
            # owns, `sessionsNumber` is the calendar/Teams session count. Folding
            # `weeks` into `sessionsNumber` here is what made the drawer read back
            # a weeks value multiplied by the group's delivery days per week.
            'sessionsNumber': payload.get('sessionsNumber') or current.get('sessionsNumber') or len(current_week_structure),
            'weeksNumber': resolved_weeks_number,
            'startDate': payload.get('startDate') or payload.get('start_date') or current.get('startDate') or '',
            'endDate': payload.get('endDate') or payload.get('end_date') or current.get('endDate') or '',
            # An explicitly blank tutor clears the assignment. Passing '' straight
            # through would not: save_module_authoring_structure resolves the
            # tutor with an `or` chain that falls back to the stored name, so a
            # blank read as "unsent". 'Unassigned' is the sentinel that chain
            # already understands, and is what the tree save sends for the same
            # intent. An absent key still keeps whatever is stored.
            'tutor': (payload.get('tutor') or 'Unassigned') if 'tutor' in payload else current.get('tutor') or '',
            'coach': payload.get('coach') if 'coach' in payload else current.get('coach') or '',
            'cohortId': payload.get('cohortId') or current.get('cohortId') or '',
            'cohortName': payload.get('cohortName') or payload.get('cohort') or current.get('cohortName') or current.get('cohort') or '',
            'groupId': payload.get('groupId') or current.get('groupId') or '',
            'groupName': payload.get('groupName') or payload.get('group') or current.get('groupName') or current.get('group') or '',
            'weeklySchedule': merged_weekly_schedule(payload, current),
            'weekDays': payload.get('weekDays') or current.get('weekDays') or current_delivery_metadata.get('weekDays') or '',
            'startTime': payload.get('startTime') or current.get('startTime') or current_delivery_metadata.get('startTime') or '',
            'endTime': payload.get('endTime') or current.get('endTime') or current_delivery_metadata.get('endTime') or '',
            'sourceType': payload.get('sourceType') or payload.get('source_type') or current.get('sourceType') or '',
            'sourceId': payload.get('sourceId') or payload.get('source_id') or current.get('sourceId') or '',
            'moduleKsbMappings': payload.get('ksbMappings') if 'ksbMappings' in payload else payload.get('moduleKsbMappings') or current.get('moduleKsbMappings') or [],
            'ksbProfileSourceId': normalise_ksb_profile_source_value(payload.get('ksbProfileSourceId') if 'ksbProfileSourceId' in payload else payload.get('ksb_profile_source_id') if 'ksb_profile_source_id' in payload else current.get('ksbProfileSourceId') or ''),
            'completionCriteria': payload.get('completionCriteria') or current.get('completionCriteria') or default_completion_payload(),
            'advancedDetails': payload.get('advancedDetails') or current.get('advancedDetails') or {},
            'weekStructure': resolved_week_structure,
        }
        # One authoritative rule, shared with the Builder's structure PATCH.
        archived_error = archived_programme_module_edit_error(
            existing_authoring,
            title=structure_payload.get('title'),
            programme_id=structure_payload.get('programmeId'),
            programme_name=structure_payload.get('programmeName'),
        )
        if archived_error:
            return archived_error
        # The cohort window is only re-checked when the request actually touches
        # the dates or the placement: a PATCH that just cascades a KSB profile or
        # renames the module must not fail on a stored date it never sent.
        if any(key in payload for key in (
            'startDate', 'start_date', 'endDate', 'end_date', 'cohortId', 'cohort_id', 'groupId', 'group_id',
        )):
            parent_cohort = module_parent_cohort(structure_payload.get('cohortId'), structure_payload.get('groupId'))
            if parent_cohort:
                date_error = module_cohort_date_error(
                    structure_payload.get('title'),
                    structure_payload.get('startDate'),
                    structure_payload.get('endDate'),
                    parent_cohort,
                )
                if date_error:
                    return json_error(date_error[0], fields=[date_error[1]], status=400)
        # Validated against the merged result rather than the payload: a request
        # that only moves the start date still has to be checked against the
        # tutor the module already carries, and one that only changes the tutor
        # against the schedule it already has.
        candidate = {**module_schedule_view(structure_payload), 'module_catalogue_id': module_catalogue_id}
        delivery_day_error = tutor_assignment_delivery_day_error(
            candidate, before=module_schedule_view(existing_authoring),
        )
        if delivery_day_error:
            return delivery_day_error
        if (
            not tutor_conflict_override_requested(payload)
            and module_schedule_assignment_changed(module_schedule_view(existing_authoring), candidate)
        ):
            conflicts = tutor_schedule_conflicts_created(module_schedule_view(existing_authoring), candidate)
            if conflicts:
                return tutor_conflict_error(candidate, conflicts)
        # Optimistic concurrency, opt-in, and deliberately the SAME token the
        # Module Builder's structure PATCH uses: this drawer writes through
        # save_module_authoring_structure too, so one fingerprint covers both
        # and either one refuses a stale copy of the other's work.
        #
        # `current` above was read before this lock. That is safe in the only
        # direction that matters: a write landing between that read and the lock
        # moves the revision, so the save is refused rather than performed on a
        # structure it no longer matches.
        expected_revision = requested_expected_revision(request, payload)
        with transaction.atomic():
            if expected_revision or implicit_revision:
                lock_module_structure_row(module_catalogue_id)
                current_revision = module_structure_revision(module_catalogue_id)
                if current_revision != (expected_revision or implicit_revision):
                    return record_conflict_response(
                        expected_revision or implicit_revision,
                        current_revision,
                        module=curriculum_module_from_authoring_payload(
                            get_authoring_structure_payload(module_catalogue_id)
                        ),
                    )
            result = save_module_authoring_structure(module_catalogue_id, structure_payload)
        # A tutor change made straight against one module has to mirror onto the
        # raise the assignment notification, exactly as the tree save and the
        # group-modules endpoint do. Without this the module row carried the new
        # tutor_name while the notification queue never moved.
        if 'tutor' in payload or 'tutorName' in payload or 'tutor_name' in payload:
            notify_staff_assignment_change()
        # Same as the group PATCH: a date, week-count or delivery-day edit moves
        # the generated plan out from under the Teams series it was sent to, and
        # the drawer needs to be able to say so while the reader is still there.
        schedule_changed = any(key in payload for key in (
            'startDate', 'start_date', 'endDate', 'end_date',
            'weeks', 'weeksNumber', 'weeks_number',
            'sessionsNumber', 'sessions_number',
            'weekDays', 'week_days', 'deliveryDays', 'sessionWeekDay', 'session_week_day',
            'startTime', 'start_time', 'endTime', 'end_time',
        ))
        return JsonResponse({
            'updated': True,
            'module': result,
            # Read after the commit, so the token handed back is the one a
            # reader would fingerprint now.
            'revision': module_structure_revision(module_catalogue_id),
            'teamsCalendarsToUpdate': (
                stale_teams_calendar_modules([module_catalogue_id]) if schedule_changed else []
            ),
        })

    if request.method == 'DELETE' and module_catalogue_id and delete_module_authoring_structure(module_catalogue_id):
        return JsonResponse({'deleted': True, 'deletedAuthoring': True, 'id': identifier})
    return json_error('Module not found.', status=404)


@require_GET
def curriculum_ksb_frameworks(request):
    return curriculum_collection_response(get_cached_payload(request, compact=True), 'ksbFrameworks')


@csrf_exempt
def curriculum_ksb_framework_collection(request):
    if request.method == 'GET':
        return curriculum_ksb_frameworks(request)
    if request.method != 'POST':
        return json_error('Method not allowed.', status=405)
    payload = json_body(request)
    if payload is None:
        return json_error('Invalid JSON body.')
    missing = require_fields(payload, ['name'])
    if missing:
        return json_error('Missing required fields.', fields=missing)
    ensure_ksb_profile_identity_columns()
    name = clean_str(payload.get('name'))
    duplicate = next((row for row in get_ksb_profile_rows() if normalise(row.get('name')) == normalise(name)), None)
    if duplicate:
        return json_error('KSB framework already exists.', status=409)
    programme_id = canonical_programme_id(payload.get('programmeId') or payload.get('programme_id'), payload.get('programmeName') or payload.get('programme'))
    existing_profile_ids = [row.get('ksb_profile_id') for row in get_ksb_profile_rows()]
    ksb_profile_id = unique_ksb_profile_id(payload.get('ksbProfileId') or payload.get('ksb_profile_id') or programme_id, existing_profile_ids)
    standard_source_id = clean_str(payload.get('standardSourceId') or payload.get('standard_source_id')).replace('standard:', '', 1)
    if standard_source_id and not find_skills_england_standard(standard_source_id):
        return json_error('Skills England standard not found.', fields=['standardSourceId'], status=400)
    row = insert_row('ksb_profiles', {
        'id': ksb_profile_id,
        'name': name,
        'ksb_profile_id': ksb_profile_id,
        'standard_source_id': standard_source_id,
        'programme_ids': json.dumps(unique([
            programme_id,
            payload.get('programmeName'),
            payload.get('programme'),
            *payload_context_ids(payload, 'programmeIds', 'programme_ids', ('programmeId', 'programme_id')),
        ])),
        'description': payload.get('description') or '',
        'knowledge_codes': json.dumps(payload.get('knowledgeCodes') or []),
        'skill_codes': json.dumps(payload.get('skillCodes') or []),
        'behaviour_codes': json.dumps(payload.get('behaviourCodes') or []),
        'ksb_items': json.dumps(payload.get('ksbItems') or []),
        'is_active': True,
        'created_by': payload.get('createdBy') or '',
        'created_at': datetime.utcnow(),
        'updated_at': datetime.utcnow(),
    })
    invalidate_curriculum_cache()
    return JsonResponse({'created': True, 'framework': row}, status=201)


@csrf_exempt
def curriculum_ksb_framework_detail(request, identifier):
    if request.method not in {'GET', 'PATCH', 'DELETE'}:
        return json_error('Method not allowed.', status=405)
    ensure_ksb_profile_identity_columns()
    ident = clean_str(identifier).replace('ksb-', '', 1)
    rows = fetch_all(
        f'''
        select *
        from {table_name("ksb_profiles")}
        where cast(id as text) = %s or ksb_profile_id = %s
        ''',
        [ident, clean_str(identifier)],
    )
    if not rows:
        rows = [
            row for row in get_ksb_profile_rows()
            if clean_str(identifier) in ksb_profile_context_ids(row, 'programme_ids')
            or ident in ksb_profile_context_ids(row, 'programme_ids')
            or slugify(identifier) in {slugify(value) for value in ksb_profile_context_ids(row, 'programme_ids')}
        ][:1]
    if not rows:
        return json_error('KSB framework not found.', status=404)
    profile_id = clean_str(rows[0].get('id'))
    framework_source_id = ksb_profile_source_id(rows[0])
    if request.method == 'GET':
        payload = get_cached_payload(request)
        framework_id = framework_source_id
        framework = next((item for item in payload.get('ksbFrameworks', []) if item.get('id') == framework_id), None)
        ksb_set = next((item for item in payload.get('ksbSets', []) if item.get('frameworkId') == framework_id), None)
        if not framework:
            return json_error('KSB framework not found.', status=404)
        return JsonResponse({**framework, 'definitions': (ksb_set or {}).get('ksbs', [])})
    if request.method == 'DELETE':
        delete_rows('ksb_profiles', 'id = %s', [profile_id])
        invalidate_curriculum_cache()
        return JsonResponse({'deleted': True, 'id': identifier})
    payload = json_body(request)
    if payload is None:
        return json_error('Invalid JSON body.')
    standard_source_sent = 'standardSourceId' in payload or 'standard_source_id' in payload
    standard_source_id = clean_str(
        payload.get('standardSourceId') if 'standardSourceId' in payload else payload.get('standard_source_id')
    ).replace('standard:', '', 1)
    if standard_source_sent and standard_source_id and not find_skills_england_standard(standard_source_id):
        return json_error('Skills England standard not found.', fields=['standardSourceId'], status=400)
    should_sync_programme_links = any(key in payload for key in ('programmeIds', 'programme_ids', 'programmeId', 'programme_id', 'programmeName', 'programme'))
    linked_programme_values = []
    if should_sync_programme_links:
        next_programme_id = canonical_programme_id(
            payload.get('programmeId') or payload.get('programme_id'),
            payload.get('programmeName') or payload.get('programme'),
        )
        next_programme_values = payload_context_ids(payload, 'programmeIds', 'programme_ids', ('programmeId', 'programme_id'))
        affected_programme_values = unique([
            next_programme_id,
            payload.get('programmeName'),
            payload.get('programme'),
            *next_programme_values,
        ])
        unlink_programmes_from_other_ksb_profiles(profile_id, affected_programme_values)
        linked_programme_values = unique([
            next_programme_id,
            payload.get('programmeName'),
            payload.get('programme'),
            *next_programme_values,
        ])
    updates = {
        'name': payload.get('name'),
        'ksb_profile_id': unique_ksb_profile_id(payload.get('ksbProfileId') or payload.get('ksb_profile_id'), [row.get('ksb_profile_id') for row in get_ksb_profile_rows() if clean_str(row.get('id')) != profile_id]) if any(key in payload for key in ('ksbProfileId', 'ksb_profile_id')) else None,
        'standard_source_id': standard_source_id if standard_source_sent else None,
        'programme_ids': json.dumps(unique([
            canonical_programme_id(payload.get('programmeId') or payload.get('programme_id'), payload.get('programmeName') or payload.get('programme')),
            payload.get('programmeName'),
            payload.get('programme'),
            *payload_context_ids(payload, 'programmeIds', 'programme_ids', ('programmeId', 'programme_id')),
        ])) if any(key in payload for key in ('programmeIds', 'programme_ids', 'programmeId', 'programme_id', 'programmeName', 'programme')) else None,
        'description': payload.get('description'),
        'knowledge_codes': json.dumps(payload.get('knowledgeCodes')) if 'knowledgeCodes' in payload else None,
        'skill_codes': json.dumps(payload.get('skillCodes')) if 'skillCodes' in payload else None,
        'behaviour_codes': json.dumps(payload.get('behaviourCodes')) if 'behaviourCodes' in payload else None,
        'ksb_items': json.dumps(payload.get('ksbItems')) if 'ksbItems' in payload else None,
        'is_active': payload.get('isActive'),
        'updated_at': datetime.utcnow(),
    }
    if updates.get('ksb_profile_id'):
        updates['id'] = updates['ksb_profile_id']
    update_rows('ksb_profiles', 'id = %s', [profile_id], updates)
    if should_sync_programme_links and linked_programme_values:
        cascade_ksb_profile_source_to_programme_modules(linked_programme_values, framework_source_id)
    invalidate_curriculum_cache()
    return JsonResponse({'updated': True, 'id': identifier})


@gzip_page
@require_GET
def curriculum_ksb_set_definitions(request, identifier):
    # A single profile's definitions, independently of curriculum coverage.
    # Keep archived assigned sources readable when visibility=all is requested.
    rows = fetch_all(
        f'select * from {table_name("ksb_profiles")} where cast(id as text) = %s or ksb_profile_id = %s',
        [identifier, identifier],
    )
    if not rows:
        # Older rows can have a generated public id rather than a stored one.
        rows = [row for row in get_ksb_profile_rows() if ksb_profile_source_id(row) == identifier]
    profile = next((row for row in rows if ksb_profile_source_id(row) == identifier or clean_str(row.get('id')) == identifier), None)
    if profile is None or (curriculum_visibility(request) != 'all' and not profile.get('is_active')):
        return json_error('KSB profile not found.', status=404)
    result = build_ksb_data([profile], [], [])[1][0]
    fields = {'id', 'code', 'rawCode', 'fullCode', 'parentCode', 'parentId', 'displayOrder', 'title', 'description', 'type'}
    result['ksbs'] = [{key: value for key, value in entry.items() if key in fields} for entry in result['ksbs']]
    return JsonResponse(result)


@gzip_page
@require_GET
def curriculum_ksb_sets(request):
    if request.GET.get('view') == 'summary':
        visibility = curriculum_visibility(request)

        def build():
            profiles = get_ksb_profile_rows()
            if visibility != 'all':
                profiles = [row for row in profiles if row.get('is_active')]
            # This list needs identities, programme links and definition counts,
            # not the curriculum tree or per-definition coverage/activity data.
            return build_ksb_data(profiles, [], [], summary_only=True)[1]

        results = cached_curriculum_value(
            f'ksb-source-summaries:{visibility}', build,
            force=request_bypasses_curriculum_cache(request),
        )
        return curriculum_collection_response({'schema': CURRICULUM_SCHEMA}, 'ksbSets', results)
    # Every set is one KSB profile in this visibility (see build_ksb_data), so
    # with none there is nothing to build: answer from the profiles table
    # instead of rebuilding the whole compact overview -- ~10 s on a cache miss
    # -- to return an empty list. That is the usual case since programmes take
    # their KSBs from standards.
    profiles = get_ksb_profile_rows()
    if curriculum_visibility(request) != 'all':
        profiles = [profile for profile in profiles if profile.get('is_active')]
    if not profiles:
        return curriculum_collection_response({'schema': CURRICULUM_SCHEMA}, 'ksbSets', [])
    return curriculum_collection_response(get_cached_payload(request, compact=True), 'ksbSets')


@require_GET
def curriculum_cohorts(request):
    payload = get_cached_payload(request)
    programme_id = request.GET.get('programme_id') or request.GET.get('programmeId') or request.GET.get('programme')
    results = payload['cohorts']
    if programme_id:
        expected = {
            clean_str(programme_id),
            slugify(programme_id),
            f'program-{slugify(programme_id)}',
        }
        results = [
            cohort for cohort in results
            if expected.intersection({
                clean_str(cohort.get('programmeId')),
                clean_str(cohort.get('programme')),
                slugify(cohort.get('programme')),
            })
        ]
    return curriculum_collection_response(payload, 'cohorts', results)


def curriculum_cohort_from_authoring_detail(detail):
    detail = detail or {}
    epa_months = parse_epa_months(
        detail.get('epaMonths') if detail.get('epaMonths') is not None else detail.get('epa_months')
    )
    override = format_date(
        detail.get('apprenticeshipEndOverride')
        if detail.get('apprenticeshipEndOverride') is not None
        else detail.get('apprenticeship_end_override')
    )
    practical_end_date, apprenticeship_end_date = cohort_epa_dates(
        detail.get('endDate') or detail.get('end_date') or detail.get('practicalEndDate') or '',
        epa_months,
        override,
    )
    return {
        'id': detail.get('cohortId') or detail.get('id') or detail.get('cohort_id'),
        'name': detail.get('cohortName') or detail.get('name') or detail.get('cohort_name') or '',
        'programmeId': detail.get('programmeId') or detail.get('programme_id') or '',
        'programme': detail.get('programmeName') or detail.get('programme') or detail.get('programme_name') or '',
        'startDate': detail.get('startDate') or detail.get('start_date') or '',
        'endDate': practical_end_date,
        'practicalEndDate': practical_end_date,
        'epaMonths': epa_months,
        'apprenticeshipEndDate': apprenticeship_end_date,
        'apprenticeshipEndOverride': override,
        'durationMonths': detail.get('durationMonths') or detail.get('duration_months') or 0,
        'color': detail.get('color') or '',
        'holidayIds': detail.get('holidayIds') or detail.get('holiday_ids') or [],
        'excludedHolidayIds': detail.get('excludedHolidayIds') or detail.get('excluded_holiday_ids') or [],
        'status': detail.get('status') or 'planned',
        'createdAt': detail.get('createdAt') or detail.get('created_at') or '',
        'updatedAt': detail.get('updatedAt') or detail.get('updated_at') or '',
    }


def curriculum_group_from_authoring_detail(detail):
    detail = detail or {}
    return {
        'id': detail.get('id') or detail.get('groupId') or detail.get('group_id'),
        'name': detail.get('name') or detail.get('groupName') or detail.get('group_name') or '',
        'cohortId': detail.get('cohortId') or detail.get('cohort_id') or '',
        'cohort': detail.get('cohort') or detail.get('cohortName') or detail.get('cohort_name') or '',
        'programmeId': detail.get('programmeId') or detail.get('programme_id') or '',
        'programme': detail.get('programme') or detail.get('programmeName') or detail.get('programme_name') or '',
        'coach': detail.get('coach') or detail.get('coach_name') or '',
        'tutor': detail.get('tutor') or '',
        'startDate': detail.get('startDate') or detail.get('start_date') or '',
        'endDate': detail.get('endDate') or detail.get('end_date') or '',
        # The delivery slot in its own fields, not only folded into `schedule`.
        # The group form edits these three directly, so a create response that
        # carried the schedule sentence alone came back to the form as no
        # delivery days and the default 09:00-11:00 -- losing what was just
        # saved. Parsed back out of `schedule` when a caller only has that.
        'weekDays': (
            detail.get('weekDays') or detail.get('week_days') or detail.get('session_week_day')
            or schedule_day_part(detail.get('schedule')) or ''
        ),
        'startTime': (
            detail.get('startTime') or detail.get('start_time') or detail.get('session_start_time')
            or schedule_time_parts(detail.get('schedule'))[0]
        ),
        'endTime': (
            detail.get('endTime') or detail.get('end_time') or detail.get('session_end_time')
            or schedule_time_parts(detail.get('schedule'))[1]
        ),
        'schedule': detail.get('schedule') or '',
        'color': detail.get('color') or '',
        'mode': detail.get('mode') or 'Live',
        'status': detail.get('status') or 'planned',
        'modules': detail.get('modules') or detail.get('module_names') or [],
        'moduleIds': detail.get('moduleIds') or detail.get('module_ids') or [],
        'createdAt': detail.get('createdAt') or detail.get('created_at') or '',
        'updatedAt': detail.get('updatedAt') or detail.get('updated_at') or '',
    }


def find_authoring_cohort(identifier):
    ident = clean_str(identifier)
    for detail in cohort_authoring_detail_rows():
        cohort = curriculum_cohort_from_authoring_detail(detail)
        if matches_curriculum_identifier(cohort.get('id'), ident) or matches_curriculum_identifier(cohort.get('name'), ident):
            return cohort
    return None


def find_authoring_group(identifier):
    ident = clean_str(identifier)
    for detail in group_authoring_detail_rows():
        group = curriculum_group_from_authoring_detail(detail)
        if matches_curriculum_identifier(group.get('id'), ident) or matches_curriculum_identifier(group.get('name'), ident):
            return group
    return None


def update_authoring_delivery_metadata(cohort=None, group=None):
    cohort = cohort or {}
    group = group or {}
    cohort_id = clean_str(cohort.get('id') or cohort.get('cohortId'))
    group_id = clean_str(group.get('id') or group.get('groupId'))

    try:
        if cohort_id:
            for stored_group in authoring_fetch_all(GROUPS_TABLE, 'cohort_id = %s', [cohort_id]):
                authoring_upsert(GROUPS_TABLE, ['group_id'], {
                    **stored_group,
                    'cohort_name': cohort.get('name') or stored_group.get('cohort_name') or '',
                    'programme_id': cohort.get('programmeId') or stored_group.get('programme_id') or '',
                    'programme_name': cohort.get('programme') or stored_group.get('programme_name') or '',
                })
            for module in authoring_fetch_all(AUTHORING_MODULES_TABLE, 'cohort_id = %s', [cohort_id]):
                authoring_upsert(AUTHORING_MODULES_TABLE, ['module_catalogue_id'], {
                    **module,
                    'cohort_name': cohort.get('name') or module.get('cohort_name') or '',
                    'programme_id': cohort.get('programmeId') or module.get('programme_id') or '',
                    'programme_name': cohort.get('programme') or module.get('programme_name') or '',
                })

        if group_id:
            for module in authoring_fetch_all(AUTHORING_MODULES_TABLE, 'group_id = %s', [group_id]):
                authoring_upsert(AUTHORING_MODULES_TABLE, ['module_catalogue_id'], {
                    **module,
                    'group_name': group.get('name') or module.get('group_name') or '',
                    'cohort_id': group.get('cohortId') or module.get('cohort_id') or '',
                    'cohort_name': group.get('cohort') or module.get('cohort_name') or '',
                    'programme_id': group.get('programmeId') or module.get('programme_id') or '',
                    'programme_name': group.get('programme') or module.get('programme_name') or '',
                })
    except (Exception, AssertionError) as exc:
        logger.warning('Could not update authoring delivery metadata: %s', exc)


def create_curriculum_cohort(payload):
    """Create a cohort directly in ``curriculum.cohorts`` (normalized only)."""
    missing = require_fields(payload, ['name', 'programme'])
    if missing:
        log_curriculum_decision('cohort.create', outcome='rejected', reason='missing-fields')
        return json_error('Missing required fields.', fields=missing)
    programme = clean_str(payload.get('programme'))
    programme_id = canonical_programme_id(
        payload.get('programmeId') or payload.get('programme_id') or payload.get('programId') or payload.get('program_id'),
        programme,
    )
    name = clean_str(payload.get('name'))
    cohort_id = unique_cohort_id(payload.get('id') or payload.get('cohortId') or payload.get('cohort_id'))
    duration_months = payload.get('durationMonths') or 24
    # Same rule as the editor's preview: cohort contract dates are fixed.
    # Applied holidays are stored for module session planning, not folded into
    # the cohort practical end date.
    end_date = payload.get('endDate') or format_date(cohort_practical_end_date(
        payload.get('startDate'),
        duration_months,
        payload.get('holidayIds') or payload.get('holiday_ids'),
        payload.get('holidays') or payload.get('holidayDetails'),
    ))
    epa_months = payload_epa_months(payload)
    apprenticeship_end_override = format_date(payload_apprenticeship_end_override(payload))
    apprenticeship_end_date = format_date(
        cohort_apprenticeship_end_date(end_date, epa_months, apprenticeship_end_override)
    )
    holiday_ids = parse_notes_id_list(payload.get('holidayIds') or payload.get('holiday_ids'))
    # The holidays unticked in the cohort drawer -- explicit key presence, not
    # ``or``, so an explicit empty list (nothing excluded, i.e. select all) is
    # never confused with the key simply being absent from an older caller.
    excluded_holiday_ids_sent = 'excludedHolidayIds' in payload or 'excluded_holiday_ids' in payload
    excluded_holiday_ids = parse_notes_id_list(
        payload.get('excludedHolidayIds') if 'excludedHolidayIds' in payload else payload.get('excluded_holiday_ids')
    ) if excluded_holiday_ids_sent else []

    # A cohort with the same canonical id, or the same name within the same
    # programme, is treated as the same cohort. Rather than failing the save,
    # update it in place and report created=False — mirroring the idempotent
    # programme create handler. This keeps wizard re-saves and retries safe:
    # a POST that repeats an already-persisted cohort (e.g. because the freshly
    # minted id was not written back into the client draft) updates the stored
    # row instead of forking a duplicate or dying with a user-facing 409.
    # An archived cohort is a soft-deleted row, not a missing one. It must not
    # answer the duplicate question, or recreating a cohort under a name that
    # was archived earlier would silently update the tombstone. Same rule, and
    # same reason, as create_curriculum_group.
    archived_cohort_ids = archived_authoring_ids(COHORT_AUTHORING_DETAILS_TABLE, 'cohort_id')
    if clean_str(cohort_id) in archived_cohort_ids:
        update_authoring_rows(
            COHORT_AUTHORING_DETAILS_TABLE,
            'cohort_id = %s',
            [clean_str(cohort_id)],
            restore_soft_delete_payload(COHORT_AUTHORING_DETAILS_TABLE),
        )
        archived_cohort_ids.discard(clean_str(cohort_id))
        log_curriculum_decision(
            'cohort.create', outcome='revived_archived', entity_id=cohort_id,
            parent_id=programme_id, reason='explicit-id-names-archived-row',
        )

    duplicate = next((
        detail for detail in cohort_authoring_detail_rows()
        if clean_str(detail.get('cohortId')) not in archived_cohort_ids
        and (
            clean_str(detail.get('cohortId')) == clean_str(cohort_id)
            or (
                normalise(detail.get('programmeId') or detail.get('programmeName')) in {normalise(programme_id), normalise(programme)}
                and normalise(detail.get('cohortName')) == normalise(name)
            )
        )
    ), None)
    if duplicate:
        existing_id = clean_str(duplicate.get('cohortId')) or cohort_id
        updates = {
            'cohort_name': name,
            'programme_id': programme_id or None,
            'programme_name': programme or None,
            'start_date': payload.get('startDate') or None,
            'end_date': end_date or None,
            'duration_months': parse_int(duration_months, duplicate.get('durationMonths') or 0),
            'epa_months': epa_months if epa_months is not None else parse_epa_months(duplicate.get('epaMonths')),
            # An unsent apprenticeship end date leaves the stored override alone;
            # an explicit blank clears it and restores the calculated date.
            'apprenticeship_end_override': (
                apprenticeship_end_override or None
                if apprenticeship_end_override_sent(payload)
                else format_date(duplicate.get('apprenticeshipEndOverride')) or None
            ),
            'color': payload.get('color') or None,
            'status': title_case_status(
                normalise(duplicate.get('status')) == 'archived',
                payload.get('startDate'),
                end_date,
            ),
        }
        # Recomputed from the end date being written, not from the payload, so a
        # POST that only moves the end date still lands a matching EPA window --
        # unless an authored apprenticeship end date stands, which wins outright.
        updates['apprenticeship_end_date'] = format_date(
            cohort_apprenticeship_end_date(
                end_date,
                updates['epa_months'],
                updates['apprenticeship_end_override'],
            )
        ) or None
        if 'holidayIds' in payload or 'holiday_ids' in payload:
            updates['holiday_ids'] = json_db_value(holiday_ids)
        if excluded_holiday_ids_sent:
            updates['excluded_holiday_ids'] = json_db_value(excluded_holiday_ids)
        nullable = ['apprenticeship_end_date', 'apprenticeship_end_override']
        if 'epaMonths' in payload or 'epa_months' in payload:
            nullable.append('epa_months')
        log_curriculum_decision(
            'cohort.create', outcome='matched_existing', entity_id=existing_id,
            parent_id=programme_id, matched_id=existing_id,
            reason='live-namesake-in-same-programme' if existing_id != clean_str(cohort_id) else 'same-id',
        )
        update_cohort_fields(existing_id, updates, allow_null_columns=tuple(nullable))
        invalidate_curriculum_cache()
        return JsonResponse({'created': False, 'cohort': curriculum_cohort_from_authoring_detail({
            'cohortId': existing_id,
            'cohortName': name,
            'programmeId': programme_id,
            'programmeName': programme,
            'startDate': payload.get('startDate'),
            'endDate': end_date,
            'epaMonths': updates['epa_months'],
            'apprenticeshipEndDate': updates['apprenticeship_end_date'] or '',
            'apprenticeshipEndOverride': updates['apprenticeship_end_override'] or '',
            'durationMonths': duration_months,
            'color': payload.get('color') or '',
            'holidayIds': holiday_ids,
            'excludedHolidayIds': excluded_holiday_ids if excluded_holiday_ids_sent else (duplicate.get('excludedHolidayIds') or []),
            'status': updates['status'],
        })})

    cohort = {
        'id': cohort_id,
        'name': name,
        'programme': programme,
        'programmeId': programme_id,
        'startDate': payload.get('startDate'),
        'endDate': end_date,
        'epaMonths': epa_months,
        'apprenticeshipEndDate': apprenticeship_end_override,
        'status': title_case_status(False, payload.get('startDate'), end_date),
        'color': payload.get('color') or '',
        'holidayIds': holiday_ids,
        'excludedHolidayIds': excluded_holiday_ids,
        'groups': [],
        'modules': [],
    }
    # The write is confirmed before this reports success, both ways it can fail
    # quietly. persist_* swallowed its exception and returned None, so a failed
    # insert used to answer 201 with a freshly minted id and no row behind it:
    # the wizard put that phantom cohort in its rail and its picker, and the next
    # step died on "Parent cohort not found" -- naming the step that could not
    # see the cohort rather than the one that failed to store it.
    try:
        persist_cohort_authoring_detail(
            cohort,
            [],
            [],
            payload.get('holidays') or payload.get('holidayDetails') or payload.get('linkedHolidays') or get_holiday_rows(),
            {'source_type': 'module_authoring', 'source_id': cohort_id},
            raise_on_error=True,
        )
    except (Exception, AssertionError) as exc:
        log_curriculum_decision(
            'cohort.create', outcome='failed', entity_id=cohort_id,
            parent_id=programme_id, reason='write-failed',
        )
        invalidate_curriculum_cache()
        return json_error(f'The cohort could not be stored: {exc}', status=500)
    # And read back, because a write can report success and still leave nothing
    # the id lookup behind every child create can find.
    if not fetch_cohort_row(cohort_id):
        log_curriculum_decision(
            'cohort.create', outcome='failed', entity_id=cohort_id,
            parent_id=programme_id, reason='row-not-stored',
        )
        invalidate_curriculum_cache()
        return json_error('The cohort could not be stored. Nothing was saved.', status=500)
    # Logged here rather than before the write, so the decision log cannot claim
    # a cohort was created and then report the same one failed.
    log_curriculum_decision(
        'cohort.create', outcome='created', entity_id=cohort_id, parent_id=programme_id,
        reason='archived-namesake-ignored' if archived_cohort_ids else '',
    )
    invalidate_curriculum_cache()
    return JsonResponse({'created': True, 'cohort': curriculum_cohort_from_authoring_detail({
        'cohortId': cohort_id,
        'cohortName': name,
        'programmeId': programme_id,
        'programmeName': programme,
        'startDate': payload.get('startDate'),
        'endDate': end_date,
        'epaMonths': epa_months,
        'apprenticeshipEndDate': apprenticeship_end_date,
        'apprenticeshipEndOverride': apprenticeship_end_override,
        'durationMonths': duration_months,
        'color': payload.get('color') or '',
        'holidayIds': holiday_ids,
        'excludedHolidayIds': excluded_holiday_ids,
        'status': cohort['status'],
    })}, status=201)


@csrf_exempt
def curriculum_cohort_collection(request):
    if request.method == 'GET':
        return curriculum_cohorts(request)
    if request.method != 'POST':
        return json_error('Method not allowed.', status=405)
    payload = json_body(request)
    if payload is None:
        return json_error('Invalid JSON body.')
    return create_curriculum_cohort(payload)


@csrf_exempt
def curriculum_cohort_detail(request, identifier):
    if request.method not in {'PATCH', 'DELETE'}:
        return json_error('Method not allowed.', status=405)

    # Look the cohort up by its stored canonical id in curriculum.cohorts. This
    # row is the only source of truth; updates target it in place so the
    # canonical cohort_id and every unrelated column are preserved.
    cohort_row = resolve_cohort_row(identifier)
    if not cohort_row:
        log_curriculum_decision(
            f'cohort.{request.method.lower()}', outcome='rejected',
            reason='not-found', entity_id=identifier,
        )
        return json_error('Cohort not found.', status=404)
    cohort_id = clean_str(cohort_row.get('cohort_id'))

    if request.method == 'DELETE':
        # An archived cohort can be removed for good, with the groups archived
        # alongside it. Archiving stays the default so a delete is never
        # irreversible by accident -- see permanent_cohort_delete_response.
        if request_wants_permanent_delete(request):
            log_curriculum_decision(
                'cohort.delete', outcome='permanent_requested', entity_id=cohort_id,
            )
            return permanent_cohort_delete_response(cohort_row)

        for stored_group in authoring_fetch_all(GROUPS_TABLE, 'cohort_id = %s', [cohort_id]):
            stored_group_id = clean_str(stored_group.get('group_id'))
            if not stored_group_id:
                continue
            unassign_authoring_modules_from_group(stored_group_id)
            authoring_soft_delete(GROUPS_TABLE, 'group_id = %s', [stored_group_id], via_parent=cohort_id, deleted_by='cohort-delete')
        # Any module row still naming this cohort directly, rather than through
        # one of its groups, is detached too: it has to be given a new cohort and
        # group from the module drawer, never left on an archived cohort.
        update_authoring_rows(AUTHORING_MODULES_TABLE, 'cohort_id = %s', [cohort_id], {
            'cohort_id': None,
            'cohort_name': '',
            'group_id': None,
            'group_name': '',
        })
        authoring_soft_delete(COHORT_AUTHORING_DETAILS_TABLE, 'cohort_id = %s', [cohort_id], deleted_by='cohort-delete')
        log_curriculum_decision(
            'cohort.archive', outcome='soft_deleted', entity_id=cohort_id,
            parent_id=clean_str(cohort_row.get('programme_id')),
        )
        invalidate_curriculum_cache()
        return JsonResponse({'deleted': True, 'permanent': False, 'id': cohort_id})

    payload = json_body(request)
    if payload is None:
        return json_error('Invalid JSON body.')

    duration_months = payload.get('durationMonths')
    start_date = payload.get('startDate') if 'startDate' in payload else format_date(cohort_row.get('start_date'))
    # An unsent holiday selection keeps the stored one. The selection is used by
    # module session planning; it does not change the cohort contract dates.
    patch_holiday_ids = (
        payload.get('holidayIds') if 'holidayIds' in payload
        else payload.get('holiday_ids') if 'holiday_ids' in payload
        else parse_json_value(cohort_row.get('holiday_ids'), [])
    )
    computed_end = (
        format_date(cohort_practical_end_date(start_date, duration_months, patch_holiday_ids))
        if duration_months else ''
    )
    end_date = payload.get('endDate') or computed_end or format_date(cohort_row.get('end_date'))
    # end_date is the practical period end; the apprenticeship end date is
    # re-derived from it on every PATCH so moving one moves the other.
    epa_months = payload_epa_months(payload, cohort_row)
    epa_sent = 'epaMonths' in payload or 'epa_months' in payload
    # An authored apprenticeship end date overrides that derivation. Unsent keeps
    # the stored one; an explicit blank clears it and the EPA rule takes over.
    override = format_date(payload_apprenticeship_end_override(payload, cohort_row))
    override_sent = apprenticeship_end_override_sent(payload)

    # Build a targeted update: only columns explicitly present in the payload
    # (or derived from them) are written. programme_id / group_ids / source_type
    # are never rebuilt from name-derived data.
    updates = {}
    if 'name' in payload and clean_str(payload.get('name')):
        updates['cohort_name'] = clean_str(payload.get('name'))
    if 'startDate' in payload:
        updates['start_date'] = payload.get('startDate') or None
    if end_date:
        updates['end_date'] = end_date or None
    if duration_months is not None:
        updates['duration_months'] = parse_int(duration_months, cohort_row.get('duration_months') or 0)
    if epa_sent:
        updates['epa_months'] = epa_months
    if override_sent:
        updates['apprenticeship_end_override'] = override or None
    if end_date or epa_sent or override_sent:
        updates['apprenticeship_end_date'] = format_date(
            cohort_apprenticeship_end_date(end_date, epa_months, override)
        ) or None
    if 'color' in payload and clean_str(payload.get('color')):
        updates['color'] = payload.get('color')
    if 'holidayIds' in payload or 'holiday_ids' in payload:
        updates['holiday_ids'] = json_db_value(parse_notes_id_list(
            payload.get('holidayIds') if 'holidayIds' in payload else payload.get('holiday_ids')
        ))
    # The holidays unticked in the cohort drawer. Unsent leaves the stored
    # exclusions alone -- checked the same way as holidayIds above, by key
    # presence rather than truthiness, so an explicit empty list (nothing
    # excluded, i.e. "Select all") is written rather than ignored.
    if 'excludedHolidayIds' in payload or 'excluded_holiday_ids' in payload:
        updates['excluded_holiday_ids'] = json_db_value(parse_notes_id_list(
            payload.get('excludedHolidayIds') if 'excludedHolidayIds' in payload else payload.get('excluded_holiday_ids')
        ))
    # Programme reassignment is only honoured when an explicit canonical id or a
    # resolvable programme name is supplied; otherwise the stored parent stands.
    explicit_programme_id = clean_str(payload.get('programmeId') or payload.get('programme_id'))
    if explicit_programme_id or clean_str(payload.get('programme')):
        resolved = canonical_programme_id(explicit_programme_id, clean_str(payload.get('programme')))
        if resolved:
            updates['programme_id'] = resolved
            if clean_str(payload.get('programme')):
                updates['programme_name'] = clean_str(payload.get('programme'))
    updates['status'] = title_case_status(
        clean_str(cohort_row.get('status')) == 'archived',
        start_date,
        end_date,
    )

    nullable = ['apprenticeship_end_date']
    if epa_sent:
        nullable.append('epa_months')
    if override_sent:
        nullable.append('apprenticeship_end_override')
    # Optimistic concurrency, opt-in, as on the module structure PATCH. The
    # drawer sends every field it renders, including the ones this reader never
    # touched, so a save built before a colleague's would put their work back to
    # what it was -- silently, because nothing here compared the two.
    expected_revision = requested_expected_revision(request, payload)
    # One transaction around the check and the write; see lock_record_row.
    from .cohort_rename import CohortRenameConflict, propagate_cohort_name
    try:
        with transaction.atomic():
            if expected_revision or 'cohort_name' in updates:
                lock_record_row(COHORT_AUTHORING_DETAILS_TABLE, 'cohort_id = %s', [cohort_id])
            if expected_revision:
                current_revision = cohort_record_revision(cohort_id)
                if current_revision != expected_revision:
                    return record_conflict_response(
                        expected_revision, current_revision, cohort=cohort_conflict_record(cohort_id),
                    )
            if 'cohort_name' in updates:
                propagate_cohort_name(fetch_cohort_row(cohort_id), updates['cohort_name'])
            update_cohort_fields(cohort_id, updates, allow_null_columns=tuple(nullable))
    except CohortRenameConflict as exc:
        return json_error(str(exc), status=409)
    invalidate_curriculum_cache()
    # Read after the commit, so the token handed back is the one a reader would
    # fingerprint now rather than one a rollback could take away.
    return JsonResponse({'updated': True, 'id': cohort_id, 'revision': cohort_record_revision(cohort_id)})


@require_GET
def curriculum_groups(request):
    payload = get_cached_payload(request)
    cohort_id = request.GET.get('cohort_id') or request.GET.get('cohortId') or request.GET.get('cohort')
    results = payload['groups']
    if cohort_id:
        results = [
            group for group in results
            if matches_curriculum_identifier(group.get('cohortId'), cohort_id)
            or matches_curriculum_identifier(group.get('cohort'), cohort_id)
        ]
    return curriculum_collection_response(payload, 'groups', results)


def create_curriculum_group(payload):
    """Create a group directly in ``curriculum.groups`` (normalized only).

    The parent cohort is resolved from ``curriculum.cohorts`` and the new group
    inherits the cohort's stored canonical programme_id/cohort_id. The cohort's
    ``group_ids`` array is updated to include the new group.
    """
    missing = require_fields(payload, ['name', 'cohortId'])
    if missing:
        log_curriculum_decision('group.create', outcome='rejected', reason='missing-fields')
        return json_error('Missing required fields.', fields=missing)
    cohort_row = resolve_cohort_row(payload.get('cohortId'))
    if not cohort_row:
        log_curriculum_decision(
            'group.create', outcome='rejected', reason='parent-cohort-not-found',
            parent_id=payload.get('cohortId'),
        )
        return json_error(
            f'Parent cohort not found: {clean_str(payload.get("cohortId")) or "(blank)"}.',
            status=404,
        )

    cohort_id = clean_str(cohort_row.get('cohort_id'))
    cohort_name = clean_str(cohort_row.get('cohort_name'))
    programme_id = clean_str(cohort_row.get('programme_id'))
    programme = clean_str(cohort_row.get('programme_name'))
    group_name = clean_str(payload.get('name'))
    group_id = unique_group_id(payload.get('id') or payload.get('groupId') or payload.get('group_id'))
    requested_week_day = clean_str(payload.get('weekDays') or payload.get('deliveryDays') or payload.get('sessionWeekDay') or payload.get('session_week_day'))
    requested_start_time = clean_str(payload.get('startTime') or payload.get('start_time') or payload.get('sessionStartTime') or payload.get('session_start_time'))
    requested_end_time = clean_str(payload.get('endTime') or payload.get('end_time') or payload.get('sessionEndTime') or payload.get('session_end_time'))

    # Archiving a group soft-deletes its row rather than removing it, so the
    # archived group is still in group_authoring_detail_rows(). Only a surviving
    # row counts as a duplicate: matching the tombstone used to turn "create the
    # same group again" into an update of the archived row, which is why the
    # group never reappeared in the list.
    archived_group_ids = archived_authoring_ids(GROUPS_TABLE, 'group_id')
    if clean_str(group_id) in archived_group_ids:
        # An explicit id naming an archived group is the caller asserting that
        # identity, so bring the row back rather than writing into the tombstone
        # or forking a second row under a minted id.
        update_authoring_rows(
            GROUPS_TABLE, 'group_id = %s', [clean_str(group_id)], restore_soft_delete_payload(GROUPS_TABLE),
        )
        archived_group_ids.discard(clean_str(group_id))
        log_curriculum_decision(
            'group.create', outcome='revived_archived', entity_id=group_id,
            parent_id=cohort_id, reason='explicit-id-names-archived-row',
        )

    duplicate = next((
        detail for detail in group_authoring_detail_rows()
        if clean_str(detail.get('id')) not in archived_group_ids
        and (
            clean_str(detail.get('id')) == clean_str(group_id)
            or (
                clean_str(detail.get('cohortId')) == cohort_id
                and normalise(detail.get('name')) == normalise(group_name)
            )
        )
    ), None)
    if duplicate:
        existing_id = clean_str(duplicate.get('id')) or group_id
        updates = {
            'group_name': group_name,
            'cohort_id': cohort_id,
            'cohort_name': cohort_name,
            'programme_id': programme_id,
            'programme_name': programme,
            'coach_name': canonical_staff_assignment_name('coach', payload.get('coach')) if 'coach' in payload else clean_str(duplicate.get('coach')),
            'session_week_day': requested_week_day if any(key in payload for key in ('weekDays', 'deliveryDays', 'sessionWeekDay', 'session_week_day')) else clean_str(duplicate.get('weekDays') or duplicate.get('session_week_day')),
            'session_start_time': requested_start_time if any(key in payload for key in ('startTime', 'start_time', 'sessionStartTime', 'session_start_time')) else clean_str(duplicate.get('startTime') or duplicate.get('session_start_time')),
            'session_end_time': requested_end_time if any(key in payload for key in ('endTime', 'end_time', 'sessionEndTime', 'session_end_time')) else clean_str(duplicate.get('endTime') or duplicate.get('session_end_time')),
            'color': clean_str(payload.get('color')) if 'color' in payload else clean_str(duplicate.get('color')),
            'status': clean_str(duplicate.get('status')) or 'planned',
        }
        log_curriculum_decision(
            'group.create', outcome='matched_existing', entity_id=existing_id,
            parent_id=cohort_id, matched_id=existing_id,
            reason='live-namesake-in-same-cohort' if existing_id != clean_str(group_id) else 'same-id',
        )
        update_group_fields(existing_id, updates)
        update_cohort_fields(cohort_id, {'group_ids': json_array_add(cohort_row.get('group_ids'), existing_id)})
        module_assignment_ids = [
            clean_str(row.get('module_catalogue_id'))
            for row in safe_authoring_module_rows()
            if clean_str(row.get('group_id')) == existing_id and row.get('module_catalogue_id')
        ]
        notify_staff_assignment_change()
        invalidate_curriculum_cache()
        return JsonResponse({'created': False, 'group': curriculum_group_from_authoring_detail({
            'id': existing_id,
            'name': group_name,
            'cohortId': cohort_id,
            'cohort': cohort_name,
            'programmeId': programme_id,
            'programme': programme,
            'coach': updates['coach_name'],
            'tutor': duplicate.get('tutor') or 'Unassigned',
            'weekDays': updates['session_week_day'],
            'startTime': updates['session_start_time'],
            'endTime': updates['session_end_time'],
            'schedule': build_group_schedule(updates['session_week_day'], updates['session_start_time'], updates['session_end_time']),
            'color': updates.get('color') or '',
            'status': updates['status'],
            'modules': parse_notes_id_list(duplicate.get('modules') or duplicate.get('moduleNames')),
        })})

    group = {
        'id': group_id,
        'name': group_name,
        'cohortId': cohort_id,
        'cohort': cohort_name,
        'programmeId': programme_id,
        'programme': programme,
        'coach': canonical_staff_assignment_name('coach', payload.get('coach')),
        'weekDays': requested_week_day,
        'startTime': requested_start_time,
        'endTime': requested_end_time,
        'color': payload.get('color') or '',
        'status': 'planned',
        'modules': [payload.get('moduleName')] if clean_str(payload.get('moduleName')) else [],
    }
    # Confirmed before reporting success, and before the cohort is told to point
    # at the group. See create_curriculum_cohort: a swallowed write here would
    # otherwise leave the cohort's group_ids naming a group that does not exist.
    try:
        persist_group_authoring_detail(
            group, [], safe_authoring_module_rows(),
            {'source_type': 'module_authoring', 'source_id': group_id},
            raise_on_error=True,
        )
    except (Exception, AssertionError) as exc:
        log_curriculum_decision(
            'group.create', outcome='failed', entity_id=group_id,
            parent_id=cohort_id, reason='write-failed',
        )
        invalidate_curriculum_cache()
        return json_error(f'The group could not be stored: {exc}', status=500)
    if not fetch_group_row(group_id):
        log_curriculum_decision(
            'group.create', outcome='failed', entity_id=group_id,
            parent_id=cohort_id, reason='row-not-stored',
        )
        invalidate_curriculum_cache()
        return json_error('The group could not be stored. Nothing was saved.', status=500)
    # Logged once the row is confirmed, for the reason given in the cohort create.
    log_curriculum_decision(
        'group.create', outcome='created', entity_id=group_id, parent_id=cohort_id,
        # Says out loud that an archived namesake was correctly stepped over,
        # which is the branch that used to silently swallow the create.
        reason='archived-namesake-ignored' if archived_group_ids else '',
    )
    # Link the group to its cohort by extending the cohort's group_ids array,
    # without touching any other cohort column.
    update_cohort_fields(cohort_id, {'group_ids': json_array_add(cohort_row.get('group_ids'), group_id)})
    notify_staff_assignment_change()
    invalidate_curriculum_cache()
    return JsonResponse({'created': True, 'group': curriculum_group_from_authoring_detail({
        'id': group_id,
        'name': group_name,
        'cohortId': cohort_id,
        'cohort': cohort_name,
        'programmeId': programme_id,
        'programme': programme,
        'coach': group['coach'],
        'tutor': 'Unassigned',
        'weekDays': group['weekDays'],
        'startTime': group['startTime'],
        'endTime': group['endTime'],
        'schedule': build_group_schedule(group['weekDays'], group['startTime'], group['endTime']),
        'color': group['color'],
        'status': group['status'],
        'modules': group['modules'],
    })}, status=201)


@csrf_exempt
def curriculum_group_collection(request):
    if request.method == 'GET':
        return curriculum_groups(request)
    if request.method != 'POST':
        return json_error('Method not allowed.', status=405)
    payload = json_body(request)
    if payload is None:
        return json_error('Invalid JSON body.')
    return create_curriculum_group(payload)


@csrf_exempt
def curriculum_cohort_group_collection(request, cohort_id):
    if request.method == 'GET':
        payload = get_cached_payload(request)
        results = [
            group for group in payload['groups']
            if matches_curriculum_identifier(group.get('cohortId'), cohort_id)
            or matches_curriculum_identifier(group.get('cohort'), cohort_id)
        ]
        return curriculum_collection_response(payload, 'groups', results)

    if request.method != 'POST':
        return json_error('Method not allowed.', status=405)

    payload = json_body(request)
    if payload is None:
        return json_error('Invalid JSON body.')
    payload['cohortId'] = cohort_id
    return create_curriculum_group(payload)


def stale_teams_calendar_modules(catalogue_ids):
    """Modules whose Teams calendar has been left behind by a schedule edit.

    Moving a module's dates -- or a group's delivery days, which moves every
    module under it -- changes the plan this system generates. It does not touch
    the Teams series that plan was sent to: that calendar lives in the
    organizer's mailbox, and only the Teams Meetings page writes to it. So a save
    that looks complete quietly leaves learners holding invitations for the old
    days, and nothing says so until somebody opens the Teams tab.

    Returned so the screen that made the change can say it at the moment it
    happens. Only modules that actually have a calendar are named: most have
    none, and warning about a calendar nobody created is noise.
    """
    ids = [clean_str(value) for value in (catalogue_ids or []) if clean_str(value)]
    if not ids:
        return []
    try:
        ensure_live_session_tracking_tables()
    except (Exception, AssertionError):
        return []
    clause, values = curriculum_in_clause('module_catalogue_id', ids)
    if not clause:
        return []
    try:
        rows = authoring_fetch_all(LIVE_SESSIONS_TABLE, f"status = 'active' and {clause}", values)
    except (Exception, AssertionError):
        logger.warning('Could not check Teams calendars after a schedule change.', exc_info=True)
        return []
    seen = set()
    results = []
    for row in rows:
        catalogue_id = clean_str(row.get('module_catalogue_id'))
        if not catalogue_id or catalogue_id in seen:
            continue
        seen.add(catalogue_id)
        results.append({
            'moduleCatalogueId': catalogue_id,
            'moduleName': clean_str(row.get('module_title')),
        })
    return results


def resync_group_module_delivery_counts(previous_rows, delivery_updates):
    """Re-derive session counts and end dates after a group's delivery days change.

    ``sessions_number`` is the authored week count times the delivery days: a
    group that starts running Mon+Thu delivers two sessions of every authored
    week, not the same total squeezed into half the calendar. Pushing the new day
    list onto the module rows without re-deriving the count left the figure from
    the old one-day pattern in place, so the generated plan -- and the Teams
    calendar fed from it -- still produced one date per authored week.

    The end date is re-derived too, from the start date and the same
    ``weeks`` this reads -- it is the module's calendar span, not a date the
    delivery pattern decides, so a delivery-day change never moves it; this
    only self-heals a stored value that had drifted from that formula.

    ``previous_rows`` are the module rows as they stood *before* the new delivery
    days were written. The week count is read from them on purpose: a legacy row
    with no ``weeks_number`` derives its weeks by dividing sessions by the
    delivery days, and doing that against the new day list would divide a
    one-day-a-week module's sessions in half and then multiply them straight back
    -- leaving the very count this is here to correct.
    """
    for previous_row in previous_rows or []:
        catalogue_id = clean_str(previous_row.get('module_catalogue_id'))
        weeks = module_stored_week_count(previous_row)
        if not catalogue_id or weeks <= 0:
            continue
        module_row = {**previous_row, **delivery_updates}
        sessions = weeks * delivery_days_per_week(module_row)
        end_date = module_calendar_end_date(module_row.get('start_date'), weeks) or format_date(module_row.get('end_date'))
        if (
            sessions == parse_int(previous_row.get('sessions_number'), 0)
            and weeks == parse_int(previous_row.get('weeks_number'), 0)
            and end_date == format_date(previous_row.get('end_date'))
        ):
            continue
        update_authoring_rows(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [catalogue_id], {
            'sessions_number': sessions,
            'weeks_number': weeks,
            'end_date': end_date or None,
            'updated_at': datetime.utcnow(),
        })


@csrf_exempt
def curriculum_group_detail(request, identifier):
    if request.method not in {'PATCH', 'DELETE'}:
        return json_error('Method not allowed.', status=405)

    # Resolve the group by its stored canonical id in curriculum.groups. Updates
    # target this row in place, preserving group_id, cohort_id, programme_id,
    # module relationships, status and any staff assignment not being explicitly
    # changed.
    group_row = resolve_group_row(identifier)
    if not group_row:
        log_curriculum_decision(
            f'group.{request.method.lower()}', outcome='rejected',
            reason='not-found', entity_id=identifier,
        )
        return json_error('Group not found.', status=404)
    group_id = clean_str(group_row.get('group_id'))

    if request.method == 'DELETE':
        # Same two operations behind one verb as the cohort above: archive by
        # default, remove for good only when the caller asks and the group is
        # already archived.
        if request_wants_permanent_delete(request):
            log_curriculum_decision(
                'group.delete', outcome='permanent_requested', entity_id=group_id,
            )
            return permanent_group_delete_response(group_row)

        cohort_id = clean_str(group_row.get('cohort_id'))
        if cohort_id:
            cohort_row = fetch_cohort_row(cohort_id) or {}
            update_cohort_fields(cohort_id, {'group_ids': json_array_remove(cohort_row.get('group_ids'), group_id)})
        unassign_authoring_modules_from_group(group_id)
        authoring_soft_delete(GROUPS_TABLE, 'group_id = %s', [group_id], deleted_by='group-delete')
        log_curriculum_decision(
            'group.archive', outcome='soft_deleted', entity_id=group_id, parent_id=cohort_id,
        )
        invalidate_curriculum_cache()
        return JsonResponse({'deleted': True, 'permanent': False, 'id': group_id})

    payload = json_body(request)
    if payload is None:
        return json_error('Invalid JSON body.')

    previous_coach = clean_str(group_row.get('coach_name'))
    stored_coach = clean_str(group_row.get('coach_name'))

    # Checked before the first write: a group tutor is pushed onto every module
    # in the group further down, and the group's own fields are updated before
    # that happens, so refusing later would leave a half-applied PATCH.
    if 'tutor' in payload:
        delivery_day_error = group_tutor_assignment_delivery_day_error(
            group_id,
            canonical_staff_assignment_name('tutor', payload.get('tutor')),
            next_week_day=payload.get('weekDays') or payload.get('deliveryDays')
            or payload.get('sessionWeekDay') or payload.get('session_week_day'),
        )
        if delivery_day_error:
            log_curriculum_decision(
                'group.patch', outcome='rejected', reason='missing-delivery-day', entity_id=group_id,
            )
            return delivery_day_error
    if 'tutor' in payload and not tutor_conflict_override_requested(payload):
        candidate, conflicts = group_tutor_assignment_conflict(
            group_id,
            canonical_staff_assignment_name('tutor', payload.get('tutor')),
        )
        if conflicts:
            log_curriculum_decision(
                'group.patch', outcome='rejected', reason='tutor-conflict', entity_id=group_id,
            )
            return tutor_conflict_error(candidate, conflicts)

    updates = {}
    if 'name' in payload and clean_str(payload.get('name')):
        updates['group_name'] = clean_str(payload.get('name'))
    if 'coach' in payload:
        updates['coach_name'] = canonical_staff_assignment_name('coach', payload.get('coach'))
    if any(key in payload for key in ('weekDays', 'deliveryDays', 'sessionWeekDay', 'session_week_day')):
        updates['session_week_day'] = clean_str(payload.get('weekDays') or payload.get('deliveryDays') or payload.get('sessionWeekDay') or payload.get('session_week_day'))
    if any(key in payload for key in ('startTime', 'start_time', 'sessionStartTime', 'session_start_time')):
        updates['session_start_time'] = clean_str(payload.get('startTime') or payload.get('start_time') or payload.get('sessionStartTime') or payload.get('session_start_time'))
    if any(key in payload for key in ('endTime', 'end_time', 'sessionEndTime', 'session_end_time')):
        updates['session_end_time'] = clean_str(payload.get('endTime') or payload.get('end_time') or payload.get('sessionEndTime') or payload.get('session_end_time'))
    if 'color' in payload:
        updates['color'] = clean_str(payload.get('color'))
    if 'status' in payload and clean_str(payload.get('status')):
        updates['status'] = clean_str(payload.get('status'))
    previous_cohort_id = clean_str(group_row.get('cohort_id'))
    target_cohort = None
    # Parent reassignment only on explicit, resolvable input.
    if clean_str(payload.get('cohortId') or payload.get('cohort_id')):
        target_cohort = resolve_cohort_row(payload.get('cohortId') or payload.get('cohort_id'))
        if target_cohort:
            updates['cohort_id'] = clean_str(target_cohort.get('cohort_id'))
            updates['cohort_name'] = clean_str(target_cohort.get('cohort_name'))
            updates['programme_id'] = clean_str(target_cohort.get('programme_id'))
            updates['programme_name'] = clean_str(target_cohort.get('programme_name'))
    explicit_programme_id = clean_str(payload.get('programmeId') or payload.get('programme_id'))
    if explicit_programme_id and 'programme_id' not in updates:
        resolved = canonical_programme_id(explicit_programme_id, clean_str(payload.get('programme')))
        if resolved:
            updates['programme_id'] = resolved
            if clean_str(payload.get('programme')):
                updates['programme_name'] = clean_str(payload.get('programme'))

    # Optimistic concurrency, opt-in, as on the module structure PATCH. The
    # check sits inside the transaction that already wraps this save, and takes
    # the row lock before the first write -- see lock_record_row. Placing it any
    # later would leave a half-applied PATCH, which is the same reason the tutor
    # conflict above is checked before anything is written.
    expected_revision = requested_expected_revision(request, payload)
    with transaction.atomic():
        if expected_revision:
            lock_record_row(GROUPS_TABLE, 'group_id = %s', [group_id])
            current_revision = group_record_revision(group_id)
            if current_revision != expected_revision:
                return record_conflict_response(
                    expected_revision, current_revision, group=group_conflict_record(group_id),
                )
        updated_group = update_group_fields(group_id, updates) or group_row
        if 'group_name' in updates:
            # Inside this save's transaction, from the row as it was before it.
            from .placement_rename import propagate_group_name_to_learners
            propagate_group_name_to_learners(group_row, updates['group_name'])
        module_delivery_updates = {
            key: updates[key]
            for key in ('session_week_day', 'session_start_time', 'session_end_time')
            if key in updates
        }
        # Read before the write: the session count is re-derived from the week
        # count these rows carried under the *old* delivery pattern.
        previous_module_rows = (
            authoring_fetch_all(AUTHORING_MODULES_TABLE, 'group_id = %s', [group_id])
            if module_delivery_updates else []
        )
        if module_delivery_updates:
            module_delivery_updates['weekly_schedule'] = json_db_value([])
            module_delivery_updates['updated_at'] = datetime.utcnow()
            # Module rows are the source used to derive the session calendar.
            # They inherit the group's slot when attached, so a later group edit
            # must move those inherited copies too or the calendar stays on the
            # day/time chosen when the group was first created.
            update_authoring_rows(
                AUTHORING_MODULES_TABLE,
                'group_id = %s',
                [group_id],
                module_delivery_updates,
            )
            # Adding a delivery day adds sessions -- it does not compress the
            # module into fewer weeks -- so the count derived from the old day
            # list has to be re-derived before anything reads the calendar off
            # these rows.
            if 'session_week_day' in module_delivery_updates:
                resync_group_module_delivery_counts(previous_module_rows, {
                    'session_week_day': module_delivery_updates['session_week_day'],
                })
            # The module row now owns the new plan, but learner delivery reads
            # each component's concrete date.  Persist the planner's answer for
            # unbooked sessions now; confirmed Teams occurrences are left for
            # the explicit calendar-update flow advertised in this response.
            persist_group_module_session_dates(
                authoring_fetch_all(AUTHORING_MODULES_TABLE, 'group_id = %s', [group_id]),
                updated_group,
            )
        next_cohort_id = clean_str(updated_group.get('cohort_id'))
        if next_cohort_id and next_cohort_id != previous_cohort_id:
            if previous_cohort_id:
                previous_cohort = fetch_cohort_row(previous_cohort_id) or {}
                update_cohort_fields(previous_cohort_id, {'group_ids': json_array_remove(previous_cohort.get('group_ids'), group_id)})
            next_cohort = fetch_cohort_row(next_cohort_id) or {}
            update_cohort_fields(next_cohort_id, {'group_ids': json_array_add(next_cohort.get('group_ids'), group_id)})
            for module in authoring_fetch_all(AUTHORING_MODULES_TABLE, 'group_id = %s', [group_id]):
                update_authoring_rows(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [module.get('module_catalogue_id')], {
                    'cohort_id': next_cohort_id,
                    'cohort_name': clean_str(updated_group.get('cohort_name')),
                    'programme_id': clean_str(updated_group.get('programme_id')),
                    'programme_name': clean_str(updated_group.get('programme_name')),
                    'group_name': clean_str(updated_group.get('group_name')),
                })
        repair_curriculum_parent_links(clean_str(updated_group.get('programme_id')))

    if 'coach' in payload or 'tutor' in payload:
        next_group_id = clean_str(updated_group.get('group_id')) or group_id
        module_assignment_ids = [
            clean_str(row.get('module_catalogue_id'))
            for row in safe_authoring_module_rows()
            if clean_str(row.get('group_id')) == next_group_id and row.get('module_catalogue_id')
        ]
        next_tutor = canonical_staff_assignment_name('tutor', payload.get('tutor')) if 'tutor' in payload else ''
        if next_tutor or 'tutor' in payload:
            for module_id in module_assignment_ids:
                update_authoring_rows(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [module_id], {
                    'tutor_name': next_tutor or None,
                    'updated_at': datetime.utcnow(),
                })
        notify_staff_assignment_change()
    log_curriculum_decision(
        'group.patch', outcome='updated', entity_id=group_id,
        parent_id=clean_str(updated_group.get('cohort_id')),
        # The columns that changed, never their values: a column list is enough
        # to see what a request touched without logging anyone's name.
        reason=','.join(sorted(updates)) or 'no-columns',
    )
    invalidate_curriculum_cache()
    # The slot moved, so every Teams calendar under this group is now on the old
    # days. Named back to the caller so the drawer that made the change can send
    # the reader to update them rather than leaving it to be discovered.
    return JsonResponse({
        'updated': True,
        'id': group_id,
        # Read after the commit, so the token handed back is the one a reader
        # would fingerprint now rather than one a rollback could take away.
        'revision': group_record_revision(group_id),
        'teamsCalendarsToUpdate': stale_teams_calendar_modules([
            clean_str(row.get('module_catalogue_id')) for row in previous_module_rows
        ]) if module_delivery_updates else [],
    })


# ============================================================================
# The cohort/group archive.
#
# DELETE on either detail endpoint soft-deletes: the row keeps its place in
# curriculum.cohorts / curriculum.groups and only picks up a ``deleted_at``
# stamp, which every list then filters out. Nothing in the app read that state
# back, so archiving was in practice a delete with no way to undo it and no way
# to finish it either -- the row was simply gone from the UI while still sitting
# in the database. These operations are both halves of the way out: list what is
# archived, put one back, or remove it for good.
#
# Deliberately the same shape as the programme archive above (see
# ``curriculum_programme_restore`` / ``permanent_programme_delete_response``):
# archiving stays reversible, a permanent delete is refused unless the record is
# already archived, and refused again while live learners still sit in it, so
# the irreversible step is never the first one anybody can take.
# ============================================================================


def request_wants_permanent_delete(request):
    """A permanent delete is opt-in per request; the default DELETE still archives."""
    return (
        truthy(request.GET.get('permanent'))
        or truthy(request.GET.get('hard'))
        or clean_str(request.GET.get('mode')).lower() in {'permanent', 'hard'}
    )


def curriculum_row_is_archived(row):
    """Is this cohort/group row one the active lists leave out?

    Deliberately the exact complement of what ``build_cohorts_and_groups`` skips:
    the soft-delete stamps ``curriculum_row_effectively_deleted`` already covers,
    plus a legacy row carrying only ``status = 'archived'``. Anything the live
    list hides has to be reachable from the archive or it is invisible in both,
    which is the state this whole section exists to end.
    """
    return curriculum_row_effectively_deleted(row) or clean_str((row or {}).get('status')).lower() == 'archived'


def archived_authoring_rows(table):
    """Every archived row in one authoring table, most recent archive first.

    Sorted on the *formatted* stamp rather than the column itself: ``deleted_at``
    comes back tz-aware from Postgres and naive from sqlite, and comparing the
    two kinds raises. ISO text orders identically either way.
    """
    rows = [row for row in authoring_fetch_all(table) if curriculum_row_is_archived(row)]
    rows.sort(key=lambda row: format_created_at(row.get('deleted_at')), reverse=True)
    return rows


def archive_stamp_fields(row):
    """How a row came to be archived, in the shape the archive view reads."""
    return {
        'archivedAt': format_created_at(row.get('deleted_at')),
        # 'cohort-delete' / 'group-delete' / 'programme-delete' -- the write
        # handler that archived it, never a person: no authoring table records
        # who made the request.
        'archivedBy': clean_str(row.get('deleted_by')),
        # Set only where a parent's archive took this row down with it, and then
        # it holds that parent's id -- which is the record that has to be
        # restored to bring this one back.
        'archivedViaParent': clean_str(row.get('deleted_via_parent')),
    }


def archived_parent_programme(programme_id):
    """The programme config for ``programme_id``, but only while it is archived.

    Used to refuse a restore that would produce an orphan: every cohort list is
    scoped by programme, so a cohort restored under an archived programme comes
    back invisible.
    """
    identifier = clean_str(programme_id)
    if not identifier:
        return None
    try:
        ensure_program_config_archive_columns()
        config = programme_config_by_identifier(identifier)
    except Exception:
        logger.warning('Could not read programme %s while checking the archive.', identifier, exc_info=True)
        return None
    return config if config and is_archived_program_config(config) else None


def archived_cohort_learners(cohort_row, counts=None):
    """Live learners still placed in an archived cohort, by id or by name."""
    if counts is None:
        counts, _group_counts = active_learner_delivery_counts()
    return delivery_learner_count(counts, clean_str(cohort_row.get('cohort_id')), (
        normalise(cohort_row.get('programme_name')),
        normalise(cohort_row.get('cohort_name')),
    ))


def archived_group_learners(group_row, counts=None):
    """Live learners still placed in an archived group, by id or by name."""
    if counts is None:
        _cohort_counts, counts = active_learner_delivery_counts()
    return delivery_learner_count(counts, clean_str(group_row.get('group_id')), (
        normalise(group_row.get('programme_name')),
        normalise(group_row.get('cohort_name')),
        normalise(group_row.get('group_name')),
    ))


def archived_cohort_payload(row, archived_group_rows, cohort_learner_counts, holiday_rows=None):
    # ``holiday_rows`` is the calendar read once for the whole list. Left out,
    # each cohort reads both holiday tables again -- two round trips per row,
    # ~33 s of a 40 s archive read with 47 archived cohorts.
    detail = serialize_cohort_authoring_detail(row, holiday_rows)
    cohort_id = clean_str(row.get('cohort_id'))
    return {
        'id': cohort_id,
        'name': clean_str(row.get('cohort_name')),
        'programme': clean_str(row.get('programme_name')),
        'programmeId': clean_str(row.get('programme_id')),
        'startDate': detail['startDate'],
        'endDate': detail['endDate'],
        'practicalEndDate': detail['practicalEndDate'],
        'apprenticeshipEndDate': detail['apprenticeshipEndDate'],
        'epaMonths': detail['epaMonths'],
        'durationMonths': detail['durationMonths'],
        'color': detail['color'],
        'status': 'archived',
        # Archived groups only. These are the rows a restore would bring back
        # and a permanent delete would remove, so they are the ones worth
        # counting in front of either button.
        'groups': len([
            group for group in archived_group_rows
            if clean_str(group.get('cohort_id')) == cohort_id
        ]),
        'learners': archived_cohort_learners(row, cohort_learner_counts),
        **archive_stamp_fields(row),
    }


def archived_group_payload(row, cohort_rows_by_id, group_learner_counts):
    detail = serialize_group_authoring_detail(row)
    group_id = clean_str(row.get('group_id'))
    cohort_id = clean_str(row.get('cohort_id'))
    parent = cohort_rows_by_id.get(cohort_id)
    return {
        'id': group_id,
        'name': clean_str(row.get('group_name')),
        'cohortId': cohort_id,
        'cohort': clean_str(row.get('cohort_name')),
        'programmeId': clean_str(row.get('programme_id')),
        'programme': clean_str(row.get('programme_name')),
        'coach': detail['coach'],
        'weekDays': detail['weekDays'],
        'startTime': detail['startTime'],
        'endTime': detail['endTime'],
        'schedule': detail['schedule'],
        'color': detail['color'],
        'status': 'archived',
        'learners': archived_group_learners(row, group_learner_counts),
        # Whether the parent cohort is itself archived decides what a restore
        # can do here: a group cannot come back into a cohort that is not in the
        # list. A group with no cohort at all has nothing to wait for.
        'cohortArchived': bool(cohort_id) and (
            parent is None or curriculum_row_is_archived(parent)
        ),
        **archive_stamp_fields(row),
    }


@require_GET
def curriculum_archived_cohorts(request):
    """Archived cohorts, each with what a restore or a delete would move."""
    archived_groups = archived_authoring_rows(GROUPS_TABLE)
    cohort_learner_counts, _group_learner_counts = active_learner_delivery_counts()
    # What serialize_cohort_authoring_detail() reads per row when given none.
    holiday_rows = get_holiday_rows_safe()
    results = [
        archived_cohort_payload(row, archived_groups, cohort_learner_counts, holiday_rows)
        for row in archived_authoring_rows(COHORT_AUTHORING_DETAILS_TABLE)
        if clean_str(row.get('cohort_id'))
    ]
    return JsonResponse({'schema': CURRICULUM_SCHEMA, 'count': len(results), 'results': results})


@require_GET
def curriculum_archived_groups(request):
    """Archived groups, each with what a restore or a delete would move."""
    cohort_rows_by_id = {
        clean_str(row.get('cohort_id')): row
        for row in authoring_fetch_all(COHORT_AUTHORING_DETAILS_TABLE)
        if clean_str(row.get('cohort_id'))
    }
    _cohort_learner_counts, group_learner_counts = active_learner_delivery_counts()
    results = [
        archived_group_payload(row, cohort_rows_by_id, group_learner_counts)
        for row in archived_authoring_rows(GROUPS_TABLE)
        if clean_str(row.get('group_id'))
    ]
    return JsonResponse({'schema': CURRICULUM_SCHEMA, 'count': len(results), 'results': results})


# What every restore has to say for itself. Archiving a cohort or a group
# detaches the modules beneath it (``unassign_authoring_modules_from_group``
# clears group_id/cohort_id on the module rows) and keeps no record of which
# module sat where, so a restore returns the record but not its timetable. That
# is the one thing coming back out of the archive cannot undo, so it is said on
# the way out rather than discovered afterwards.
ARCHIVE_MODULE_REATTACH_NOTE = (
    'Modules were detached when it was archived, so they have to be attached again by hand.'
)


@csrf_exempt
def curriculum_cohort_restore(request, identifier):
    """Take a cohort back out of the archive, with the groups archived with it."""
    if request.method != 'POST':
        return json_error('Method not allowed.', status=405)

    cohort_row = fetch_cohort_row(identifier) or resolve_cohort_row(identifier)
    if not cohort_row:
        log_curriculum_decision('cohort.restore', outcome='rejected', reason='not-found', entity_id=identifier)
        return json_error('Cohort not found.', status=404)
    cohort_id = clean_str(cohort_row.get('cohort_id'))
    if not curriculum_row_is_archived(cohort_row):
        return json_error(
            'Cohort is not archived.', status=409,
            reason='cohort-not-archived', restored=False, id=cohort_id,
        )

    programme_id = clean_str(cohort_row.get('programme_id'))
    archived_programme = archived_parent_programme(programme_id)
    if archived_programme:
        name = clean_str(archived_programme.get('name')) or 'The programme'
        return json_error(
            f'{name} is archived, so this cohort has no programme to come back to. Restore the '
            'programme instead - it brings back everything archived with it, this cohort included.',
            status=409, reason='programme-archived', restored=False, id=cohort_id,
        )

    with transaction.atomic():
        payload = restore_soft_delete_payload(COHORT_AUTHORING_DETAILS_TABLE)
        if has_column(COHORT_AUTHORING_DETAILS_TABLE, 'is_archived'):
            payload['is_archived'] = False
        if has_column(COHORT_AUTHORING_DETAILS_TABLE, 'status'):
            # Back to whatever the dates say it is now, not to a blanket
            # 'active': a cohort archived before it started is still planned.
            payload['status'] = title_case_status(
                False, cohort_row.get('start_date'), cohort_row.get('end_date'),
            )
        update_rows(
            COHORT_AUTHORING_DETAILS_TABLE, 'cohort_id = %s', [cohort_id], payload,
            allow_null_columns=RESTORE_NULLABLE_COLUMNS,
        )
        # Only the groups this cohort's own archive took down carry it as their
        # parent marker. A group archived on its own carries none and stays
        # archived - the same rule ``restore_rows_via_parent`` applies to a
        # programme, so restoring is never a way to resurrect an unrelated
        # deletion.
        groups = restore_rows_via_parent(GROUPS_TABLE, cohort_id)
    invalidate_curriculum_cache()
    log_curriculum_decision('cohort.restore', outcome='restored', entity_id=cohort_id, parent_id=programme_id)
    return JsonResponse({
        'restored': True,
        'id': cohort_id,
        'details': {'groups': len(groups)},
        'message': f'Cohort restored. {ARCHIVE_MODULE_REATTACH_NOTE}',
    })


@csrf_exempt
def curriculum_group_restore(request, identifier):
    """Take a group back out of the archive and back onto its cohort."""
    if request.method != 'POST':
        return json_error('Method not allowed.', status=405)

    group_row = fetch_group_row(identifier) or resolve_group_row(identifier)
    if not group_row:
        log_curriculum_decision('group.restore', outcome='rejected', reason='not-found', entity_id=identifier)
        return json_error('Group not found.', status=404)
    group_id = clean_str(group_row.get('group_id'))
    if not curriculum_row_is_archived(group_row):
        return json_error(
            'Group is not archived.', status=409,
            reason='group-not-archived', restored=False, id=group_id,
        )

    cohort_id = clean_str(group_row.get('cohort_id'))
    cohort_row = fetch_cohort_row(cohort_id) if cohort_id else None
    if cohort_id and (not cohort_row or curriculum_row_is_archived(cohort_row)):
        name = clean_str(group_row.get('cohort_name')) or 'The cohort'
        return json_error(
            f'{name} is archived, so this group has no cohort to come back to. Restore the cohort '
            'first - it brings back the groups archived with it.',
            status=409, reason='cohort-archived', restored=False, id=group_id,
        )

    with transaction.atomic():
        payload = restore_soft_delete_payload(GROUPS_TABLE)
        if has_column(GROUPS_TABLE, 'is_archived'):
            payload['is_archived'] = False
        if has_column(GROUPS_TABLE, 'status') and clean_str(group_row.get('status')).lower() == 'archived':
            # Only a legacy row carries this: archiving a group stamps
            # deleted_at and leaves status alone. Left as 'archived' the row
            # would come back and immediately read as archived again.
            payload['status'] = 'active'
        update_rows(
            GROUPS_TABLE, 'group_id = %s', [group_id], payload,
            allow_null_columns=RESTORE_NULLABLE_COLUMNS,
        )
        # The archive took this id out of the cohort's ``group_ids``; put it
        # back so the stored child list and the rows agree again.
        if cohort_row:
            update_cohort_fields(cohort_id, {
                'group_ids': json_array_add(cohort_row.get('group_ids'), group_id),
            })
    invalidate_curriculum_cache()
    log_curriculum_decision('group.restore', outcome='restored', entity_id=group_id, parent_id=cohort_id)
    return JsonResponse({
        'restored': True,
        'id': group_id,
        'message': f'Group restored. {ARCHIVE_MODULE_REATTACH_NOTE}',
    })


def permanent_cohort_delete_response(cohort_row):
    """HTTP outcome of a permanent cohort delete: the row and its archived groups.

    Module rows are never deleted with a cohort. Module content outlives the
    delivery it was scheduled into - that is what the plain archive already
    promises - so only the delivery link is cleared here.
    """
    cohort_id = clean_str(cohort_row.get('cohort_id'))
    if not curriculum_row_is_archived(cohort_row):
        return json_error(
            'Archive the cohort before deleting it permanently.',
            status=409, reason='cohort-not-archived', deleted=False, permanent=False, id=cohort_id,
        )

    learners = archived_cohort_learners(cohort_row)
    if learners:
        return json_error(
            f'{learners} active learner{"" if learners == 1 else "s"} are still placed in this cohort, '
            'so it cannot be deleted permanently. Move them to another cohort first.',
            status=409, reason='cohort-has-learner-delivery', deleted=False, permanent=False,
            id=cohort_id, blockers={'learners': learners},
        )

    group_rows = authoring_fetch_all(GROUPS_TABLE, 'cohort_id = %s', [cohort_id])
    live_groups = [row for row in group_rows if not curriculum_row_is_archived(row)]
    if live_groups:
        return json_error(
            f'{len(live_groups)} group{"" if len(live_groups) == 1 else "s"} under this cohort '
            'are still active, so it cannot be deleted permanently. Archive them first.',
            status=409, reason='cohort-has-live-groups', deleted=False, permanent=False,
            id=cohort_id, blockers={'groups': len(live_groups)},
        )

    try:
        with transaction.atomic():
            for group in group_rows:
                unassign_authoring_modules_from_group(clean_str(group.get('group_id')))
            # Any module row still naming this cohort directly, rather than
            # through one of its groups.
            update_authoring_rows(AUTHORING_MODULES_TABLE, 'cohort_id = %s', [cohort_id], {
                'cohort_id': None,
                'cohort_name': '',
            })
            removed = {
                'groups': len(delete_rows(GROUPS_TABLE, 'cohort_id = %s', [cohort_id])),
                'cohorts': len(delete_rows(COHORT_AUTHORING_DETAILS_TABLE, 'cohort_id = %s', [cohort_id])),
            }
    except (IntegrityError, DatabaseError) as exc:
        logger.warning('Permanent delete of cohort %s was refused: %s', cohort_id, exc)
        return json_error(
            'The database refused the permanent delete because other rows still reference this cohort.',
            status=409, reason='cohort-delete-restricted', deleted=False, permanent=False,
            id=cohort_id, detail=clean_str(str(exc)),
        )

    invalidate_curriculum_cache()
    log_curriculum_decision(
        'cohort.delete', outcome='permanent', entity_id=cohort_id,
        parent_id=clean_str(cohort_row.get('programme_id')),
        reason=','.join(f'{table}:{count}' for table, count in sorted(removed.items())),
    )
    return JsonResponse({
        'deleted': True,
        'permanent': True,
        'id': cohort_id,
        'removed': removed,
        'message': 'Cohort and the groups archived with it were removed from the database. Module content was kept.',
    })


def permanent_group_delete_response(group_row):
    """HTTP outcome of a permanent group delete. Module content is kept."""
    group_id = clean_str(group_row.get('group_id'))
    if not curriculum_row_is_archived(group_row):
        return json_error(
            'Archive the group before deleting it permanently.',
            status=409, reason='group-not-archived', deleted=False, permanent=False, id=group_id,
        )

    learners = archived_group_learners(group_row)
    if learners:
        return json_error(
            f'{learners} active learner{"" if learners == 1 else "s"} are still placed in this group, '
            'so it cannot be deleted permanently. Move them to another group first.',
            status=409, reason='group-has-learner-delivery', deleted=False, permanent=False,
            id=group_id, blockers={'learners': learners},
        )

    cohort_id = clean_str(group_row.get('cohort_id'))
    try:
        with transaction.atomic():
            unassign_authoring_modules_from_group(group_id)
            cohort_row = fetch_cohort_row(cohort_id) if cohort_id else None
            if cohort_row:
                update_cohort_fields(cohort_id, {
                    'group_ids': json_array_remove(cohort_row.get('group_ids'), group_id),
                })
            removed = {'groups': len(delete_rows(GROUPS_TABLE, 'group_id = %s', [group_id]))}
    except (IntegrityError, DatabaseError) as exc:
        logger.warning('Permanent delete of group %s was refused: %s', group_id, exc)
        return json_error(
            'The database refused the permanent delete because other rows still reference this group.',
            status=409, reason='group-delete-restricted', deleted=False, permanent=False,
            id=group_id, detail=clean_str(str(exc)),
        )

    invalidate_curriculum_cache()
    log_curriculum_decision(
        'group.delete', outcome='permanent', entity_id=group_id, parent_id=cohort_id,
        reason=','.join(f'{table}:{count}' for table, count in sorted(removed.items())),
    )
    return JsonResponse({
        'deleted': True,
        'permanent': True,
        'id': group_id,
        'removed': removed,
        'message': 'Group was removed from the database. Module content was kept.',
    })


# ---------------------------------------------------------------------------
# The module archive.
#
# A module DELETE has always been a soft delete: delete_module_authoring_structure
# stamps the module row and every week, component, KSB mapping, completion rule
# and advanced detail beneath it. Nothing ever read those rows back, though, so
# an archived module was hidden from every list and reachable from none of them
# -- the state the cohort and group archives above exist to end. These are the
# same three endpoints, applied to modules.
# ---------------------------------------------------------------------------

MODULE_CHILD_AUTHORING_TABLES = (
    AUTHORING_WEEKS_TABLE,
    AUTHORING_COMPONENTS_TABLE,
    AUTHORING_KSB_MAPPINGS_TABLE,
    AUTHORING_COMPLETION_TABLE,
    AUTHORING_ADVANCED_TABLE,
)

# Said on the way out, for the reason ARCHIVE_MODULE_REATTACH_NOTE is: archiving
# a module sends the quizzes only it owned to the Quiz Archive, and that archive
# is the Quiz Workspace's own state. A module restore cannot reach into it, so it
# says so rather than leaving it to be discovered.
ARCHIVE_MODULE_QUIZ_NOTE = (
    'Quizzes archived with it stay in the Quiz Archive - restore them from the Quiz Workspace.'
)


def archived_module_rows():
    """Every archived module row, most recent archive first.

    ``curriculum_row_effectively_deleted`` rather than the cohort/group
    ``curriculum_row_is_archived``: a module's ``status`` is authoring state
    ('draft', 'published'), and a legacy row carrying status 'archived' is still
    listed by the catalogue. Reading that as archived here would put one module
    in both lists at once.
    """
    rows = [row for row in safe_authoring_module_rows() if curriculum_row_effectively_deleted(row)]
    rows.sort(key=lambda row: format_created_at(row.get('deleted_at')), reverse=True)
    return rows


def archived_module_component_counts(module_catalogue_ids=None):
    """Component rows per module, counted by the database.

    ``module_catalogue_ids`` limits the count to those modules -- the archived
    ones are all the archive asks about -- and on Postgres the counting is a
    ``group by`` rather than shipping one row per component (~18k) to be
    counted here. A module absent from the result has no component rows.

    ``columns`` is not an optimisation here so much as the difference between an
    answer and a timeout: curriculum.components is the largest table in the
    schema and most of its bytes are ``settings_json``, which a count never looks
    at. Every row is counted, deleted or not -- an archived module's components
    are all soft-deleted with it, and the question this answers is how much
    authoring is sitting inside.
    """
    counts = defaultdict(int)
    ids = None if module_catalogue_ids is None else sorted({
        clean_str(value) for value in module_catalogue_ids if clean_str(value)
    })
    if ids is not None and not ids:
        return counts
    try:
        if connection.vendor == 'postgresql':
            ensure_module_authoring_tables()
            where = f' where module_catalogue_id in ({", ".join(["%s"] * len(ids))})' if ids else ''
            with connection.cursor() as cursor:
                cursor.execute(
                    f'select module_catalogue_id, count(*)'
                    f' from {authoring_table_name(AUTHORING_COMPONENTS_TABLE)}{where}'
                    ' group by module_catalogue_id',
                    ids or [],
                )
                for module_id, total in cursor.fetchall():
                    key = clean_str(module_id)
                    if key:
                        counts[key] += int(total)
            return counts
        rows = authoring_fetch_all(AUTHORING_COMPONENTS_TABLE, columns=['module_catalogue_id'])
    except (Exception, AssertionError):
        logger.debug('Unable to count components for the module archive.', exc_info=True)
        return counts
    for row in rows:
        key = clean_str(row.get('module_catalogue_id'))
        if key:
            counts[key] += 1
    return counts


def archived_module_payload(row, component_counts):
    """One archived module, with what a restore or a delete would move."""
    catalogue_id = clean_str(row.get('module_catalogue_id'))
    programme_id = clean_str(row.get('programme_id'))
    return {
        'id': catalogue_id,
        'catalogueId': catalogue_id,
        'title': clean_str(row.get('title')),
        'programmeId': programme_id,
        'programme': clean_str(row.get('programme_name')),
        'cohortId': clean_str(row.get('cohort_id')),
        'cohort': clean_str(row.get('cohort_name')),
        'groupId': clean_str(row.get('group_id')),
        'group': clean_str(row.get('group_name')),
        'tutor': clean_str(row.get('tutor_name')),
        'weeks': module_stored_week_count(row),
        'sessions': parse_int(row.get('sessions_number'), 0),
        'components': component_counts.get(catalogue_id, 0),
        'status': 'archived',
        # The catalogue is scoped by programme, so a module restored under an
        # archived programme comes back invisible. The view disables its Restore
        # on this rather than letting the endpoint refuse after the click.
        'programmeArchived': bool(archived_parent_programme(programme_id)),
        **archive_stamp_fields(row),
    }


@require_GET
def curriculum_archived_modules(request):
    """Archived modules, each with what a restore or a delete would move."""
    with curriculum_read_scope():
        rows = [row for row in archived_module_rows() if clean_str(row.get('module_catalogue_id'))]
        component_counts = archived_module_component_counts(
            [row.get('module_catalogue_id') for row in rows],
        )
        results = [archived_module_payload(row, component_counts) for row in rows]
    return JsonResponse({'schema': CURRICULUM_SCHEMA, 'count': len(results), 'results': results})


@require_GET
def curriculum_archived_module_structure(request, module_catalogue_id):
    """One archived module's weeks and the components inside them.

    The archive is the only place an archived module can be looked at. Every
    workspace in the app reads the curriculum overview payload, which excludes
    archived rows, and the live structure endpoint next to this one filters its
    children through ``active_*`` -- correct for a live read, and the reason an
    archived module read through it comes back with an empty week list.

    Read-only by design: an archived module is restored or removed, never edited,
    so there is no PATCH here. Uncached for the same reason the archive lists are
    revalidated -- this is opened in order to act on it, and the very next thing
    the reader does is restore or delete the module it belongs to.
    """
    identifier = clean_str(module_catalogue_id)
    catalogue_id = resolve_stored_module_catalogue_id(identifier)
    module_row = authoring_module_exists(catalogue_id) if catalogue_id else None
    if not module_row:
        return json_error('Module not found.', status=404)
    if not curriculum_row_effectively_deleted(module_row):
        # The live endpoint is this module's door, and it is the one that can
        # serve an editable structure. Saying so is better than quietly serving a
        # second, read-only copy of a module that is not in the archive at all.
        return json_error(
            'Module is not archived.', status=409,
            reason='module-not-archived', id=catalogue_id,
        )
    try:
        with curriculum_read_scope(targeted_child_reads=True):
            payload = get_authoring_structure_payload(catalogue_id, include_archived=True)
    except Exception:
        logger.exception('Unable to load archived module structure for %s.', identifier)
        return json_error('Unable to load archived module structure.', status=500)
    if not payload:
        return json_error('Module authoring structure not found.', status=404)
    return JsonResponse({**payload, **archive_stamp_fields(module_row), 'status': 'archived'})


@csrf_exempt
def curriculum_module_restore(request, identifier):
    """Take a module, and everything archived under it, back out of the archive."""
    if request.method != 'POST':
        return json_error('Method not allowed.', status=405)

    catalogue_id = resolve_stored_module_catalogue_id(clean_str(identifier))
    module_row = authoring_module_exists(catalogue_id) if catalogue_id else None
    if not module_row:
        log_curriculum_decision('module.restore', outcome='rejected', reason='not-found', entity_id=identifier)
        return json_error('Module not found.', status=404)
    if not curriculum_row_effectively_deleted(module_row):
        return json_error(
            'Module is not archived.', status=409,
            reason='module-not-archived', restored=False, id=catalogue_id,
        )

    programme_id = clean_str(module_row.get('programme_id'))
    archived_programme = archived_parent_programme(programme_id)
    if archived_programme:
        name = clean_str(archived_programme.get('name')) or 'The programme'
        return json_error(
            f'{name} is archived, so this module has no programme to come back to. Restore the '
            'programme instead - it brings back everything archived with it, this module included.',
            status=409, reason='programme-archived', restored=False, id=catalogue_id,
        )

    with transaction.atomic():
        # Matched on the marker this module's own archive stamped, so only that
        # cascade comes back: a component deleted by hand beforehand stays
        # deleted rather than being resurrected by an unrelated restore.
        # ...and only rows that archive stamped: an earlier archive of this
        # same module, undone by a save, left its children stamped with this
        # id too, and they are not part of what is being restored.
        bounds = module_archive_event_bounds(module_row)
        restored = {
            table: len(restore_rows_via_parent(table, catalogue_id, bounds))
            for table in MODULE_CHILD_AUTHORING_TABLES
        }
        update_rows(
            AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [catalogue_id],
            restore_soft_delete_payload(AUTHORING_MODULES_TABLE),
            allow_null_columns=RESTORE_NULLABLE_COLUMNS,
        )
    invalidate_curriculum_cache()
    log_curriculum_decision(
        'module.restore', outcome='restored', entity_id=catalogue_id,
        parent_id=clean_str(module_row.get('group_id')),
        reason=','.join(f'{table}:{count}' for table, count in sorted(restored.items())),
    )
    return JsonResponse({
        'restored': True,
        'id': catalogue_id,
        'details': {
            'weeks': restored.get(AUTHORING_WEEKS_TABLE, 0),
            'components': restored.get(AUTHORING_COMPONENTS_TABLE, 0),
        },
        'message': f'Module restored. {ARCHIVE_MODULE_QUIZ_NOTE}',
    })


MODULE_TEAMS_CALENDAR_BLOCKS_ARCHIVE = (
    'This module has an active Teams calendar with future sessions. Cancel the Teams calendar before archiving '
    'the module.'
)


def module_future_teams_sessions(module_catalogue_id, now=None):
    """Future Teams sessions still standing on this module's calendars.

    Every calendar the module owns -- its module series and its additional week
    meetings -- that has not been cancelled, and every session on it that has
    not been cancelled and has not ended yet. A session marked "not in plan"
    ('superseded') counts: its Teams slot is still in everyone's calendar, which
    is exactly what an archive must not leave running unseen. Past sessions
    never block: their attendance and history stay where they are.

    Read-only. Archiving never cancels anything; the author does, with Cancel.
    """
    now = utc_datetime(now or datetime.utcnow())
    series_rows = authoring_fetch_all(
        LIVE_SESSIONS_TABLE, "module_catalogue_id = %s and coalesce(status, '') not in ('cancelled', 'canceled')",
        [clean_str(module_catalogue_id)],
    )
    standing = []
    for series in series_rows:
        rows = authoring_fetch_all(
            LIVE_SESSION_OCCURRENCES_TABLE, "live_session_id = %s and coalesce(status, '') not in ('cancelled', 'canceled')",
            [clean_str(series.get('id'))],
        )
        if not rows and series.get('start_datetime'):
            # A calendar with no occurrence rows still has its own start.
            start = parse_graph_datetime(series.get('start_datetime'))
            minutes = parse_int(series.get('duration_minutes'), 60) or 60
            rows = [{'session_number': 1, 'scheduled_start': start,
                     'scheduled_end': start + timedelta(minutes=minutes) if start else None}]
        for row in rows:
            ends = row.get('scheduled_end') or row.get('scheduled_start')
            if ends and utc_datetime(ends) > now:
                standing.append({'liveSessionId': clean_str(series.get('id')),
                                 'sessionNumber': row.get('session_number'),
                                 'startDateTimeUtc': utc_iso_value(parse_graph_datetime(row.get('scheduled_start')))})
    return standing


def module_teams_calendar_block_response(module_catalogue_id):
    """409 when the module still has future Teams sessions, else None. Fails closed."""
    try:
        standing = module_future_teams_sessions(module_catalogue_id)
    except DatabaseError:
        logger.warning('Teams sessions of module %s could not be read before archiving.', module_catalogue_id)
        return json_error(
            'The module’s Teams calendar could not be checked, so it was not archived. Try again.',
            status=503, reason='module-teams-calendar-unchecked', deleted=False,
        )
    if not standing:
        return None
    return json_error(
        MODULE_TEAMS_CALENDAR_BLOCKS_ARCHIVE, status=409, reason='module-has-active-teams-calendar',
        code='module_has_active_teams_calendar', deleted=False,
        liveSessionIds=sorted({item['liveSessionId'] for item in standing}), futureSessions=len(standing),
    )


def permanent_module_delete_response(module_row):
    """HTTP outcome of a permanent module delete: the module and all its authoring."""
    catalogue_id = clean_str(module_row.get('module_catalogue_id'))
    if not curriculum_row_effectively_deleted(module_row):
        return json_error(
            'Archive the module before deleting it permanently.',
            status=409, reason='module-not-archived', deleted=False, permanent=False, id=catalogue_id,
        )
    # A module archived before this check existed can still own a running
    # calendar; deleting it would orphan that calendar's rows for good.
    blocked = module_teams_calendar_block_response(catalogue_id)
    if blocked is not None:
        return blocked

    try:
        with transaction.atomic():
            # Children first: the module row is what the rest point at, and a
            # database with the foreign keys in place refuses it the other way
            # round.
            removed = {
                table: len(delete_rows(table, 'module_catalogue_id = %s', [catalogue_id]))
                for table in MODULE_CHILD_AUTHORING_TABLES
            }
            removed[AUTHORING_MODULES_TABLE] = len(
                delete_rows(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [catalogue_id])
            )
    except (IntegrityError, DatabaseError) as exc:
        logger.warning('Permanent delete of module %s was refused: %s', catalogue_id, exc)
        return json_error(
            'The database refused the permanent delete because other rows still reference this module.',
            status=409, reason='module-delete-restricted', deleted=False, permanent=False,
            id=catalogue_id, detail=clean_str(str(exc)),
        )

    invalidate_curriculum_cache()
    log_curriculum_decision(
        'module.delete', outcome='permanent', entity_id=catalogue_id,
        parent_id=clean_str(module_row.get('group_id')),
        reason=','.join(f'{table}:{count}' for table, count in sorted(removed.items())),
    )
    return JsonResponse({
        'deleted': True,
        'permanent': True,
        'id': catalogue_id,
        'removed': removed,
        'message': 'Module and its authored weeks, components and mappings were removed from the database.',
    })


def module_attachment_authoring_payload(item, group, cohort, catalogue_id, module_name, session_count, start_date, end_date, current_structure=None, source_type='module_authoring', source_id=''):
    current_structure = current_structure or {}
    weekly = merged_weekly_schedule(item, current_structure)
    schedule = ', '.join(slot['day'] for slot in weekly) or clean_str(item.get('weekDays') or item.get('deliveryDays') or group.get('weekDays') or group.get('schedule'))
    has_explicit_tutor = 'tutor' in item or 'tutorName' in item or 'tutor_name' in item
    explicit_tutor = clean_str(item.get('tutor') or item.get('tutorName') or item.get('tutor_name'))
    group_tutor = '' if is_blank_staff_assignment(group.get('tutor')) else clean_str(group.get('tutor'))
    tutor = ''
    if has_explicit_tutor:
        tutor = '' if is_blank_staff_assignment(explicit_tutor) else explicit_tutor
    else:
        tutor = group_tutor
    return {
        **current_structure,
        'catalogueId': catalogue_id,
        'programmeId': clean_str(item.get('programmeId') or item.get('programme_id') or cohort.get('programmeId') or group.get('programmeId') or ''),
        'programmeName': cohort.get('programme') or group.get('programme') or 'Unassigned programme',
        'cohortId': cohort['id'],
        'cohortName': cohort.get('name') or '',
        'groupId': group['id'],
        'groupName': group.get('name') or '',
        'tutor': tutor,
        'title': module_name,
        'description': visible_notes(item.get('notes') or current_structure.get('description') or ''),
        'color': item.get('color') or current_structure.get('color') or '',
        'coverImage': item.get('coverImage') if 'coverImage' in item else current_structure.get('coverImage') or '',
        'status': item.get('status') or current_structure.get('status') or 'draft',
        'sessionsNumber': session_count,
        # The authored week count travels apart from the calendar session count:
        # a group delivering twice a week runs `session_count` sessions across
        # half that many weeks.
        'weeksNumber': attachment_week_count(item, session_count, schedule),
        'startDate': start_date,
        'endDate': end_date,
        'weeklySchedule': merged_weekly_schedule(item, current_structure),
        'weekDays': schedule,
        'startTime': item.get('startTime') or group.get('startTime') or '',
        'endTime': item.get('endTime') or group.get('endTime') or '',
        # Prefer a structure the caller authored; fall back to what is stored, or
        # pre-create the resolved week count so a metadata-only reattachment
        # never blanks existing weeks/components and a fresh attachment holds
        # the weeks it was asked for rather than none.
        'weekStructure': attachment_week_structure(item, current_structure, session_count=session_count, schedule=schedule),
        'moduleKsbMappings': item.get('moduleKsbMappings') or item.get('ksbMappings') or current_structure.get('moduleKsbMappings') or [],
        'completionCriteria': current_structure.get('completionCriteria') or default_completion_payload(),
        'advancedDetails': current_structure.get('advancedDetails') or {},
        'background': current_structure.get('background') or '',
        'epaRequirements': current_structure.get('epaRequirements') or [],
        'qualificationOutcomes': current_structure.get('qualificationOutcomes') or [],
        'sourceType': source_type,
        'sourceId': clean_str(source_id or item.get('sourceId') or catalogue_id),
        'ksbProfileSourceId': normalise_ksb_profile_source_value(item.get('ksbProfileSourceId') if 'ksbProfileSourceId' in item else item.get('ksb_profile_source_id') if 'ksb_profile_source_id' in item else current_structure.get('ksbProfileSourceId') or ''),
    }


def attachment_week_count(item, session_count, schedule):
    """The authored week count for an attachment, given its session count.

    An explicit scalar `weeks` on the item wins. Otherwise the count is derived
    back out of the sessions using the group's delivery days, so a Mon+Thu group
    asked for 10 sessions is recorded as 5 authored weeks rather than 10.
    """
    weeks_field = item.get('weeksNumber') if 'weeksNumber' in item else item.get('weeks')
    explicit = 0 if isinstance(weeks_field, (list, tuple, dict)) else parse_int(weeks_field, 0)
    if explicit > 0:
        return explicit
    authored = len(payload_week_list(item.get('weekStructure')) or payload_week_list(item.get('weeks')))
    if authored:
        return authored
    sessions = max(0, parse_int(session_count, 0))
    if not sessions:
        return 0
    return max(1, sessions // delivery_days_per_week({'session_week_day': schedule}))


def payload_week_list(value):
    """Return value only when it is a usable list of authored weeks.

    Attachment payloads overload `weeks`: the module catalogue shape carries an
    integer session count, while authored payloads carry a list of week dicts.
    Returning [] for anything that is not a list of dicts keeps an integer from
    being treated as a week structure (which would silently drop every week).
    """
    if not isinstance(value, list):
        return []
    return value if all(isinstance(item, dict) for item in value) else []


def empty_authoring_week(week_number):
    """An unauthored week shell, in the shape save_module_authoring_structure expects."""
    return {
        'weekNumber': week_number,
        'title': f'Week {week_number}',
        'summary': '',
        'learningOutcomes': [],
        'components': [],
        'ksbMappings': [],
    }


def resize_authoring_week_structure(weeks, target_count):
    """Grow or shrink an authored week list to a new count without touching what is built.

    Growing appends empty weeks after the last one; shrinking drops from the
    end -- the most recently added weeks -- so a person changing the weeks
    count on a module that already has authored content never has an earlier,
    already-built week rewritten or removed out from under them.
    """
    weeks = list(weeks or [])
    target = max(0, parse_int(target_count, len(weeks)))
    if target == len(weeks):
        return weeks
    if target > len(weeks):
        return weeks + [empty_authoring_week(index + 1) for index in range(len(weeks), target)]
    return weeks[:target]


def week_holds_authored_content(week):
    """Whether a week holds anything somebody actually put there.

    An untouched week shell -- the thing a week-count change creates -- is a
    default title and nothing else. Everything past that is authored work.
    """
    if not isinstance(week, dict):
        return False
    if week.get('components') or week.get('ksbMappings') or week.get('learningOutcomes'):
        return True
    if clean_str(week.get('summary')):
        return True
    title = clean_str(week.get('title'))
    if not title:
        return False
    week_number = parse_int(week.get('weekNumber') or week.get('week_number'), 0)
    return normalise(title) != normalise(f'Week {week_number}')


def resize_authoring_week_structure_preserving_content(weeks, target_count):
    """Resize a week list from a scalar count, but never delete authored weeks.

    The module PATCH carries the week *count* and never the week *list* -- the
    list belongs to the Module Builder. Shrinking straight to that number let a
    single scalar delete whole weeks and every component in them while the
    response still said ``updated: True``: the drawer seeds its Weeks box from
    the module's stored count and falls back to 1 when the module has none, so
    simply opening an imported module and pressing Save could cut it down to one
    week. Trailing shells hold nothing and are safe to drop; a week with
    authored content stops the shrink where it is, and the stored count is
    re-derived from what survived so the number and the rows never disagree.
    """
    weeks = list(weeks or [])
    target = max(0, parse_int(target_count, len(weeks)))
    if target >= len(weeks):
        return resize_authoring_week_structure(weeks, target)
    kept = list(weeks)
    while len(kept) > target and not week_holds_authored_content(kept[-1]):
        kept.pop()
    return kept


def attachment_week_structure(item, current_structure=None, week_count=None, session_count=0, schedule=''):
    """Pick the authored week structure for a module attachment.

    Prefers an explicitly supplied structure, then the legacy `weeks` list form,
    then whatever is already stored. Only once none of those exist does it
    pre-create empty weeks, to the resolved week count: a module attached with
    "10 weeks" has to actually hold 10 week rows, or a page that reads the
    structure straight from storage (rather than going through a client-side
    "fill in a default structure" fallback) sees none of them.
    """
    for candidate in (
        (item or {}).get('weekStructure'),
        (item or {}).get('weeks'),
        (current_structure or {}).get('weekStructure'),
    ):
        weeks = payload_week_list(candidate)
        if weeks:
            return weeks
    target = week_count if week_count is not None else attachment_week_count(item, session_count, schedule)
    return [empty_authoring_week(index + 1) for index in range(max(0, target))]


def attachment_session_count(item, weeks=None):
    """Resolve the session count for an attachment payload.

    `weeks` may arrive as an integer count or as a list of authored weeks, so the
    count is taken from sessionsNumber first, then an integer `weeks`, then the
    length of the resolved week structure.
    """
    item = item or {}
    explicit = parse_int(item.get('sessionsNumber'), 0)
    if explicit:
        return explicit
    weekly = module_weekly_schedule(item)
    if weekly:
        count = parse_int(item.get('weeks') or item.get('weeksNumber'), 0) or len(weeks or payload_week_list(item.get('weekStructure') or item.get('weeks')))
        return max(1, count) * len(weekly)
    raw_weeks = item.get('weeks')
    if not isinstance(raw_weeks, (list, tuple, dict)):
        counted = parse_int(raw_weeks, 0)
        if counted:
            return counted
    return len(weeks or payload_week_list(raw_weeks))


def module_structure_component_count(structure):
    return sum(len(week.get('components') or []) for week in ((structure or {}).get('weekStructure') or []))


def contentful_catalogue_id_for_attachment(item, group, cohort, module_name, current_catalogue_id=''):
    title_key = normalise(module_name)
    candidate_id = ''
    try:
        component_counts = authoring_component_counts_by_catalogue()
        programme_values = [
            item.get('programmeId'),
            item.get('programme_id'),
            item.get('programme'),
            group.get('programmeId'),
            group.get('programme_id'),
            group.get('programme'),
            cohort.get('programmeId') if cohort else '',
            cohort.get('programme_id') if cohort else '',
            cohort.get('programme') if cohort else '',
        ]
        cohort_values = [
            item.get('cohortId'),
            item.get('cohort_id'),
            item.get('cohort'),
            group.get('cohortId'),
            group.get('cohort_id'),
            cohort.get('id') if cohort else '',
            cohort.get('cohortId') if cohort else '',
            cohort.get('name') if cohort else '',
        ]
        group_values = [
            item.get('groupId'),
            item.get('group_id'),
            item.get('group'),
            group.get('id'),
            group.get('groupId'),
            group.get('name'),
        ]
        # Canonical-id-only views of the context. A group name is not unique
        # across cohorts (each cohort may hold its own "G1-Wed"), so matching on
        # the pooled id+name sets alone would reuse a different cohort's module
        # row and strand the target group with no modules, no tutor and no
        # delivery window. When both sides carry an id, it has to agree.
        cohort_context_ids = [item.get('cohortId'), item.get('cohort_id'), group.get('cohortId'), group.get('cohort_id')]
        if cohort:
            cohort_context_ids += [cohort.get('id'), cohort.get('cohortId')]
        group_context_ids = [item.get('groupId'), item.get('group_id'), group.get('id'), group.get('groupId')]
        candidates = [
            row for row in authoring_fetch_all(AUTHORING_MODULES_TABLE)
            if normalise(row.get('title')) == title_key
            and identity_values_match_context([row.get('programme_id'), row.get('programme_name')], programme_values)
            and identity_values_match_context([row.get('cohort_id'), row.get('cohort_name')], cohort_values)
            and identity_values_match_context([row.get('group_id'), row.get('group_name')], group_values)
            and not identity_ids_conflict(row.get('cohort_id'), cohort_context_ids)
            and not identity_ids_conflict(row.get('group_id'), group_context_ids)
        ]
        candidates.sort(
            key=lambda row: (component_counts.get(clean_str(row.get('module_catalogue_id')), 0), row.get('updated_at') or ''),
            reverse=True,
        )
        if candidates:
            candidate_id = clean_str(candidates[0].get('module_catalogue_id'))
    except Exception:
        logger.debug('Unable to resolve contentful catalogue attachment for %s.', module_name, exc_info=True)
    if not candidate_id or candidate_id == current_catalogue_id:
        return current_catalogue_id
    if not current_catalogue_id:
        return candidate_id
    current_structure = get_authoring_structure_payload(current_catalogue_id) if authoring_module_exists(current_catalogue_id) else None
    candidate_structure = get_authoring_structure_payload(candidate_id) if authoring_module_exists(candidate_id) else None
    if module_structure_component_count(candidate_structure) > module_structure_component_count(current_structure):
        return candidate_id
    return current_catalogue_id


@csrf_exempt
def curriculum_group_modules(request, identifier):
    if request.method == 'GET':
        payload = get_cached_payload(request)
        group = next((item for item in payload['groups'] if matches_curriculum_identifier(item.get('id'), identifier)), None)
        if not group:
            return json_error('Group not found.', status=404)
        results = [module for module in payload['modules'] if module_belongs_to_group(module, group)]
        return curriculum_collection_response(payload, 'modules', results)

    if request.method not in {'POST', 'PATCH'}:
        return json_error('Method not allowed.', status=405)

    payload = json_body(request)
    if payload is None:
        return json_error('Invalid JSON body.')

    modules = payload.get('modules') if isinstance(payload.get('modules'), list) else [payload]
    if not isinstance(modules, list):
        return json_error('At least one module is required.', fields=['modules'])
    for item in modules:
        if not isinstance(item, dict):
            return json_error('Each module attachment must be an object.', status=400)
        try:
            module_weekly_schedule(item)
        except ValueError as exc:
            return json_error(str(exc), fields=['weeklySchedule'])

    # Resolve group and parent cohort from the normalized tables only.
    group_row = resolve_group_row(identifier)
    if not group_row:
        return json_error('Group not found.', status=404)
    group = curriculum_group_from_authoring_detail(serialize_group_authoring_detail(group_row))
    cohort_row = resolve_cohort_row(group_row.get('cohort_id'))
    cohort = curriculum_cohort_from_authoring_detail(serialize_cohort_authoring_detail(cohort_row)) if cohort_row else None
    if not cohort:
        return json_error('Parent cohort not found.', status=404)

    # Existing module attachments for this group come from curriculum.modules.
    existing_rows = [row for row in safe_authoring_module_rows() if clean_str(row.get('group_id')) == clean_str(group_row.get('group_id'))]
    existing_names = {normalise(row.get('title')) for row in existing_rows if row.get('title')}
    existing_catalogue_ids = {clean_str(row.get('module_catalogue_id')) for row in existing_rows if row.get('module_catalogue_id')}
    created_rows = []
    skipped = []
    allow_tutor_conflict = tutor_conflict_override_requested(payload)
    # Read once for the whole request; each attachment is compared against the
    # same snapshot plus the attachments accepted before it.
    stored_module_rows = safe_authoring_module_rows()
    pending_candidates = []

    try:
        with transaction.atomic():
            created_modules = []
            updated_modules = []
            saved_catalogue_ids = set()
            for item in modules:
                if not isinstance(item, dict):
                    return json_error('Each module attachment must be an object.', status=400)
                module_name = clean_str(item.get('moduleName') or item.get('name'))
                if not module_name:
                    return json_error('Module name is required for each attachment.', fields=['moduleName'])
                explicit_catalogue_value = clean_str(item.get('moduleCatalogueId'))
                if explicit_catalogue_value and not is_canonical_module_catalogue_id(explicit_catalogue_value):
                    return json_error('moduleCatalogueId must be a valid MOD-... canonical module ID.', fields=['moduleCatalogueId'])
                requested_value = clean_str(explicit_catalogue_value or item.get('catalogueId') or item.get('moduleId'))
                requested_catalogue_id = requested_value if is_canonical_module_catalogue_id(requested_value) else ''

                try:
                    weekly = module_weekly_schedule(item)
                except ValueError as exc:
                    return json_error(str(exc), fields=['weeklySchedule'])
                start_date = item.get('startDate') or cohort.get('startDate')
                start_error = module_cohort_date_error(module_name, start_date, None, cohort)
                if start_error:
                    return json_error(start_error[0], fields=[start_error[1]], status=400)

                delivery_days = ', '.join(slot['day'] for slot in weekly) or item.get('weekDays') or group.get('weekDays') or group.get('schedule')
                session_count = attachment_session_count(item)
                item_weeks = parse_int(item.get('weeksNumber') or item.get('weeks'), 0)
                end_date = item.get('endDate') or module_calendar_end_date(start_date, item_weeks) or cohort.get('endDate')
                # Checked after the plan is generated, so a start date that sits
                # inside the cohort but whose sessions run past its end is caught
                # too -- whether the end date was sent or calculated here.
                end_error = module_cohort_date_error(module_name, start_date, end_date, cohort)
                if end_error:
                    return json_error(end_error[0], fields=[end_error[1]], status=400)
                catalogue_id = contentful_catalogue_id_for_attachment(
                    item,
                    group,
                    cohort,
                    module_name,
                    requested_catalogue_id,
                ) or unique_module_catalogue_id(item.get('catalogueId') or item.get('moduleId') or module_name)
                current_structure = locked_attachment_structure(item, catalogue_id)
                is_duplicate = (
                    bool(requested_catalogue_id and requested_catalogue_id in existing_catalogue_ids)
                    or bool(not requested_catalogue_id and normalise(module_name) in existing_names)
                )
                # An attachment that carries authored weeks must persist them here and
                # now; module_attachment_authoring_payload otherwise falls back to the
                # stored structure and the new content would need a manual Save.
                structure_payload = module_attachment_authoring_payload(
                    {**item, 'weekStructure': attachment_week_structure(item, current_structure, session_count=session_count, schedule=delivery_days)},
                    group,
                    cohort,
                    catalogue_id,
                    module_name,
                    session_count,
                    start_date,
                    end_date,
                    current_structure,
                )
                # Checked against what this save is about to produce, not against
                # what is stored: `pending_candidates` carries the attachments
                # already accepted in this request, so two new modules that clash
                # with each other are caught as well as one that clashes with an
                # existing booking. An attachment is appended either way -- a later
                # one still has to be compared against it.
                candidate = module_schedule_view(structure_payload)
                # The group's own delivery day is what dates these modules -- a
                # day sent for the module alone is the copy that has no effect --
                # so a tutor cannot be put against one until the group has it.
                if not clean_str(group.get('weekDays') or group.get('deliveryDays') or schedule_day_part(group.get('schedule'))):
                    delivery_day_error = tutor_assignment_delivery_day_error(
                        candidate, before=module_schedule_view(current_structure or {}),
                    )
                    if delivery_day_error:
                        raise TutorAssignmentDeliveryDayError(delivery_day_error)
                if not allow_tutor_conflict and module_schedule_assignment_changed(
                    module_schedule_view(current_structure or {}), candidate
                ):
                    conflicts = tutor_schedule_conflicts_created(
                        module_schedule_view(current_structure or {}),
                        candidate,
                        module_rows=stored_module_rows,
                        exclude_catalogue_ids=[catalogue_id],
                        pending=pending_candidates,
                    )
                    if conflicts:
                        raise TutorScheduleConflictError(candidate, conflicts)
                pending_candidates.append(candidate)
                saved = save_module_authoring_structure(catalogue_id, structure_payload)
                notify_staff_assignment_change()
                saved_catalogue_ids.add(catalogue_id)
                if is_duplicate:
                    skipped.append(module_name)
                    updated_modules.append(saved)
                else:
                    created_modules.append(saved)
                existing_names.add(normalise(module_name))
                existing_catalogue_ids.add(catalogue_id)

            # PATCH from the structure wizard represents the group's complete
            # module list, so omitted modules should be unassigned. POST is an
            # append-style endpoint used by createGroupModule(); it must not detach
            # existing modules that were not included in the request.
            removed_module_ids = (
                unassign_authoring_modules_from_group(group_row.get('group_id'), saved_catalogue_ids)
                if request.method == 'PATCH'
                else []
            )
            # Refresh only the group's derived module_ids/module_names from
            # curriculum.modules. Coach/tutor/dates/status stay untouched.
            refresh_group_module_cache(group_row.get('group_id'))
            repair_curriculum_parent_links(clean_str(group.get('programmeId') or group.get('programme_id')))
            invalidate_curriculum_cache()
            return JsonResponse({
                'updated': True,
                'groupId': identifier,
                'created': created_modules,
                'updatedModules': updated_modules,
                'removedModuleIds': removed_module_ids,
                'skippedDuplicates': skipped,
            })
    except ModuleAuthoringValidationError as exc:
        return json_error(
            str(exc),
            fields=list(dict.fromkeys(error['path'] for error in exc.errors)),
            validationErrors=exc.errors,
        )
    except (TutorScheduleConflictError, TutorAssignmentDeliveryDayError, StaleModuleStructureWrite) as exc:
        # Raised mid-loop, so the attachments already written in this
        # request roll back with it and the group is left as it was.
        return exc.as_response()


def module_scoped_sessions(module_catalogue_id):
    """One authoring module's sessions, read fresh, exactly as the overview lists them.

    The overview derives every session in the curriculum at once, and a caller
    that must see the latest dates (the Teams dialog, before Create) could only
    get them by forcing that whole build -- about 13s of round trips for the
    one module it wanted. This feeds the same builder the same inputs the
    overview would, for this module alone: its row, its cohort's holidays and
    its group's clock. Returns ``None`` for a module the authoring tables do not
    hold, whose sessions only the overview's legacy generator knows.
    """
    rows = authoring_fetch_all(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [module_catalogue_id])
    if not rows:
        return None
    module = rows[0]
    # Same visibility as the operational overview: a deleted programme's
    # modules deliver nothing there, so they deliver nothing here.
    if programme_deleted_row(module):
        return []
    holiday_rows = get_holiday_rows_safe()

    holidays_by_cohort = {}
    cohort_id = clean_str(module.get('cohort_id'))
    if cohort_id:
        cohort_rows = authoring_fetch_all(COHORT_AUTHORING_DETAILS_TABLE, 'cohort_id = %s', [cohort_id])
        detail = serialize_cohort_authoring_detail(cohort_rows[0], holiday_rows) if cohort_rows else None
        # build_cohorts_and_groups leaves deleted and archived cohorts out, and
        # with them their holidays.
        if detail and not programme_deleted_row(detail) and not detail_is_archived(detail):
            holidays_by_cohort = cohort_selected_holidays_by_id([{
                'id': cohort_id,
                'startDate': format_date(detail.get('startDate')),
                'excludedHolidayIds': [clean_str(value) for value in (detail.get('excludedHolidayIds') or []) if clean_str(value)],
            }], holiday_rows)

    groups_by_id = {}
    group_id = clean_str(module.get('group_id'))
    if group_id:
        group_rows = authoring_fetch_all(GROUPS_TABLE, 'group_id = %s', [group_id])
        detail = serialize_group_authoring_detail(group_rows[0]) if group_rows else None
        if detail and not programme_deleted_row(detail) and not detail_is_archived(detail):
            clock = {'session_start_time': clean_str(detail.get('startTime')), 'session_end_time': clean_str(detail.get('endTime'))}
        else:
            # A group the overview rebuilds from its module rows takes the clock
            # of the first of them, as build_cohorts_and_groups does.
            siblings = [row for row in authoring_fetch_all(AUTHORING_MODULES_TABLE, 'group_id = %s', [group_id])
                        if not programme_deleted_row(row)]
            first = siblings[0] if siblings else {}
            clock = {'session_start_time': clean_str(first.get('session_start_time')),
                     'session_end_time': clean_str(first.get('session_end_time'))}
        groups_by_id = {group_id: clock}

    return build_sessions_from_authoring_modules([module], holidays_by_cohort, groups_by_id=groups_by_id)


@require_GET
def curriculum_sessions(request):
    requested = clean_str(request.GET.get('module_catalogue_id') or request.GET.get('moduleCatalogueId'))
    if requested:
        # Never the cached overview: this read exists for callers that need the
        # current dates of one module without rebuilding everyone's.
        scoped = module_scoped_sessions(requested) if curriculum_visibility(request) == 'operational' else None
        if scoped is not None:
            return curriculum_results_response(scoped)
        # Not an authoring module (or an archive view): the overview decides.
        payload = get_cached_payload(request)
        return curriculum_results_response([
            session for session in payload['sessions']
            if requested in (clean_str(session.get('moduleCatalogueId')), clean_str(session.get('moduleId')))
        ])
    return curriculum_collection_response(get_cached_payload(request), 'sessions')


@csrf_exempt
def curriculum_session_collection(request):
    if request.method == 'GET':
        return curriculum_sessions(request)
    return json_error('Generated sessions are derived from normalized curriculum modules. Create a module/cohort/group allocation first.', status=409)


@csrf_exempt
def curriculum_session_detail(request, identifier):
    if request.method not in {'PATCH', 'DELETE'}:
        return json_error('Method not allowed.', status=405)
    module_match = re.match(r'^module-(.+)-session-(\d+)$', clean_str(identifier))
    if module_match:
        module_catalogue_id, week_number = module_match.groups()
        rows = authoring_fetch_all(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [module_catalogue_id])
        if not rows:
            return json_error('Session not found.', status=404)
        if request.method == 'DELETE':
            return json_error('Individual generated sessions cannot be safely cancelled without updating the parent module allocation.', status=409)
        payload = json_body(request)
        if payload is None:
            return json_error('Invalid JSON body.')
        current = rows[0]
        updates = {
            **current,
            'session_start_time': payload.get('startTime') if 'startTime' in payload else current.get('session_start_time'),
            'session_end_time': payload.get('endTime') if 'endTime' in payload else current.get('session_end_time'),
            'tutor_name': canonical_staff_assignment_name('tutor', payload.get('tutor')) if 'tutor' in payload else current.get('tutor_name'),
        }
        if payload.get('date'):
            non_delivery_reason = england_non_delivery_reason(payload.get('date'))
            if non_delivery_reason:
                return json_error(non_delivery_reason, status=400, code='non_delivery_date', fields=['date'])
            if int(week_number) != 1:
                return json_error('Only week 1 generated sessions can update start_date directly. Later session dates are calculated from the parent module start date.', status=409)
            updates['start_date'] = payload.get('date')
        # Editing a session from the calendar moves the whole module: `updates`
        # is the module row, and start_date/times/tutor here are the same fields
        # the module PATCH guards. Checked after the date is merged in, so a move
        # onto a taken day is caught as well as a change of tutor.
        candidate = module_schedule_view(updates)
        delivery_day_error = tutor_assignment_delivery_day_error(
            candidate, before=module_schedule_view(current),
        )
        if delivery_day_error:
            return delivery_day_error
        if not tutor_conflict_override_requested(payload) and module_schedule_assignment_changed(
            module_schedule_view(current), candidate
        ):
            conflicts = tutor_schedule_conflicts_created(module_schedule_view(current), candidate)
            if conflicts:
                return tutor_conflict_error(candidate, conflicts)
        authoring_upsert(AUTHORING_MODULES_TABLE, ['module_catalogue_id'], updates)
        invalidate_curriculum_cache()
        return JsonResponse({'updated': True, 'id': identifier})

    match = re.match(r'^training-(\d+)-session-(\d+)$', clean_str(identifier))
    if not match:
        return json_error('Session not found.', status=404)
    return json_error('Legacy training-plan sessions are no longer editable in the current curriculum schema.', status=409)


@csrf_exempt
def curriculum_staffing_collection(request):
    if request.method == 'GET':
        payload = get_cached_payload(request)
        assignments = [
            {
                'id': group['id'],
                'groupId': group['id'],
                'group': group['name'],
                'cohort': group['cohort'],
                'programme': group['programme'],
                'tutor': group['tutor'],
                'coach': group['coach'],
                'status': 'unassigned' if group['tutor'] == 'Unassigned' and group['coach'] == 'Unassigned' else 'assigned',
            }
            for group in payload['groups']
        ]
        return JsonResponse({'schema': payload['schema'], 'count': len(assignments), 'results': assignments})
    if request.method != 'POST':
        return json_error('Method not allowed.', status=405)
    payload = json_body(request)
    if payload is None:
        return json_error('Invalid JSON body.')
    missing = require_fields(payload, ['groupId'])
    if missing:
        return json_error('Missing required fields.', fields=missing)
    return update_staffing_assignment(payload.get('groupId'), payload)


@csrf_exempt
def curriculum_staffing_detail(request, identifier):
    if request.method not in {'PATCH', 'DELETE'}:
        return json_error('Method not allowed.', status=405)
    payload = {} if request.method == 'DELETE' else json_body(request)
    if payload is None:
        return json_error('Invalid JSON body.')
    if request.method == 'DELETE':
        payload = {'tutor': '', 'coach': ''}
    return update_staffing_assignment(identifier, payload)


def update_staffing_assignment(identifier, payload):
    group_row = resolve_group_row(identifier)
    if not group_row:
        return json_error('Group not found for staffing assignment.', status=404)
    group_id = clean_str(group_row.get('group_id'))
    previous_coach = clean_str(group_row.get('coach_name'))

    # Same reasoning as the group PATCH: the coach write below lands before the
    # tutor is pushed onto the group's modules, so the refusal has to come first.
    if 'tutor' in payload:
        delivery_day_error = group_tutor_assignment_delivery_day_error(
            group_id,
            canonical_staff_assignment_name('tutor', payload.get('tutor')),
        )
        if delivery_day_error:
            return delivery_day_error
    if 'tutor' in payload and not tutor_conflict_override_requested(payload):
        candidate, conflicts = group_tutor_assignment_conflict(
            group_id,
            canonical_staff_assignment_name('tutor', payload.get('tutor')),
        )
        if conflicts:
            return tutor_conflict_error(candidate, conflicts)

    updates = {}
    if 'coach' in payload:
        updates['coach_name'] = canonical_staff_assignment_name('coach', payload.get('coach'))
    update_group_fields(group_id, updates)

    next_tutor = canonical_staff_assignment_name('tutor', payload.get('tutor')) if 'tutor' in payload else ''
    next_tutor_email = resolve_staff_assignment_email('tutor', next_tutor) if next_tutor else ''
    next_coach = canonical_staff_assignment_name('coach', payload.get('coach')) if 'coach' in payload else clean_str(group_row.get('coach_name'))
    module_assignment_ids = [
        clean_str(row.get('module_catalogue_id'))
        for row in safe_authoring_module_rows()
        if clean_str(row.get('group_id')) == group_id and row.get('module_catalogue_id')
    ]
    if 'tutor' in payload:
        for module_id in module_assignment_ids:
            update_authoring_rows(AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [module_id], {
                'tutor_name': next_tutor or None,
                'tutor_email': next_tutor_email or None,
                'updated_at': datetime.utcnow(),
            })
    notify_staff_assignment_change()
    invalidate_curriculum_cache()
    return JsonResponse({'updated': True, 'id': group_id})


def find_staff_profile_row(role, identifier, include_archived=True):
    ident = clean_str(identifier)
    if not ident:
        return None
    rows = get_staff_profile_rows(role, include_archived=include_archived)
    for row in rows:
        if clean_str(row.get('id')) == ident:
            return row
    searchable_rows = [row for row in rows if not staff_profile_is_archived(row)] + [row for row in rows if staff_profile_is_archived(row)]
    email_key = normalise(ident)
    if email_key:
        for row in searchable_rows:
            if normalise(staff_profile_email(row)) == email_key:
                return row
    slug = slugify(ident)
    ident_key = staff_assignment_key(ident)
    for row in searchable_rows:
        name = staff_profile_name(row)
        if slugify(name) == slug or staff_assignment_key(name) == ident_key:
            return row
    return None


def clean_assignment_ids(values):
    seen = set()
    result = []
    for value in values or []:
        text = clean_str(value)
        if not text:
            continue
        expanded = [text]
        canonical_match = re.search(r'(MOD-[A-Z0-9][A-Z0-9_-]*)', text, re.IGNORECASE)
        if canonical_match:
            expanded.append(canonical_match.group(1))
        for item in expanded:
            if item in seen:
                continue
            seen.add(item)
            result.append(item)
    return result


def notify_staff_assignment_change():
    """Tell a tutor their assignment changed.

    This is all that is left of the old profile-link sync. Assignments live on
    ``curriculum.modules.tutor_name`` / ``curriculum.groups.coach_name``, and the
    staff themselves live in the directory, so there is no second copy to mirror
    a change into -- but the person still has to hear about it, and every write
    path that moves an assignment calls through here to make sure they do.
    """
    tutor_notifications.schedule_assignment_notifications()


def find_staff_user_profile(role, identifier):
    """One tutor or coach, by whichever identifier a caller has for them.

    An id, the staff user's uuid or row id, an email, or the name a module or
    group holds them under: a curriculum screen has only ever had one of those,
    and they all name the same person in the staff directory.
    """
    ident = clean_str(identifier)
    if not ident:
        return None
    profiles = build_staff_user_profile_collection(role, 'all')
    for profile in profiles:
        candidates = [
            clean_str(profile.get('id')),
            clean_str(profile.get('uuid')),
            clean_str(profile.get('staffUserId')),
        ]
        if ident in [value for value in candidates if value]:
            return profile
    email_key = normalise(ident)
    if email_key:
        for profile in profiles:
            if normalise(profile.get('email')) == email_key:
                return profile
    name_key = staff_assignment_key(ident)
    if name_key:
        for profile in profiles:
            if staff_assignment_key(profile.get('name')) == name_key:
                return profile
    return None


# Curriculum does not own staff records. Tutors and coaches are staff users an
# administrator invited and gave that access to, so the curriculum API reads them
# and never writes them: creating, renaming or deleting a person happens once, in
# Users, and every screen that shows them follows from there. These endpoints
# answer the reads and refuse the writes rather than quietly keeping a second
# copy of a person that the directory knows nothing about.
STAFF_PROFILE_READ_ONLY_MESSAGE = (
    'Tutors and coaches are managed in Users. Curriculum reads them from the staff '
    'directory and cannot create, change or delete them.'
)


@csrf_exempt
def curriculum_staff_profile_collection(request, role):
    if request.method != 'GET':
        return json_error(STAFF_PROFILE_READ_ONLY_MESSAGE, status=405)
    visibility = curriculum_visibility(request)
    # A staff profile carries what the person teaches, so building the list walks
    # the modules, cohorts and groups -- and it read every one of those tables
    # more than once: the programme config twice, the modules table three times.
    # The scope memoises them for the request, which is the difference between
    # ~13 round trips and ~8 on an endpoint the UI asks for twice per page (once
    # for tutors, once for coaches).
    with curriculum_read_scope():
        profiles = build_staff_user_profile_collection(role, visibility)
    return curriculum_results_response(profiles)


@csrf_exempt
def curriculum_staff_profile_detail(request, role, identifier):
    if request.method != 'GET':
        return json_error(STAFF_PROFILE_READ_ONLY_MESSAGE, status=405)
    # Same build as the collection above, for one person. See the note there.
    with curriculum_read_scope():
        profile = find_staff_user_profile(role, identifier)
    if not profile:
        return json_error(f'{role.title()} profile not found.', status=404)
    return JsonResponse({'schema': CURRICULUM_SCHEMA, 'profile': profile})


@require_GET
def curriculum_holidays(request):
    """The curriculum's holiday calendar, both halves of it.

    England's bank holidays, mirrored from GOV.UK, plus this organisation's own
    authored closure periods -- in one list, in the one label/start/end shape
    every caller already reads. See ``get_holiday_rows``.

    ``/curriculum/england-holidays/`` serves the GOV.UK half on its own, in the
    feed's raw shape (title, notes, bunting), for the page that lists it.
    """
    visibility = curriculum_visibility(request)
    include_archived = visibility == 'all'

    def build_holidays():
        return [
            serialize_holiday_row(item)
            for item in get_holiday_rows(include_archived=include_archived)
        ]

    # Keyed on visibility again now that authored holidays are back: an archived
    # closure period is in one answer and not the other, and a single cache key
    # would serve whichever was asked for first to both.
    holidays = cached_curriculum_value(f'holidays:{visibility}', build_holidays)
    # Any read of the calendar is a chance to notice GOV.UK has moved a date.
    # Costs this request nothing: it starts a thread at most once per interval,
    # and does nothing at all in the overwhelmingly common case. Imported here
    # rather than at module load: england_holidays imports this module, the way
    # reviews.py does, so the cycle is broken by deferring to call time.
    from . import england_holidays
    england_holidays.auto_sync_if_due()
    return curriculum_results_response(holidays)


HOLIDAY_READ_ONLY_MESSAGE = (
    'That holiday is one of the published England and Wales bank holidays, '
    'mirrored from GOV.UK. It cannot be edited here -- it changes when GOV.UK '
    'changes it.'
)


@csrf_exempt
def curriculum_holiday_collection(request):
    """Read the whole calendar; write the authored half of it.

    A POST here creates one of this organisation's own closure periods -- a
    Christmas shutdown, an exam week, a staff training day -- with its own start
    and end date. It never touches the GOV.UK mirror: nobody here gets to invent
    a national holiday, and ``curriculum_holiday_detail`` refuses to edit one for
    the same reason.
    """
    if request.method == 'GET':
        return curriculum_holidays(request)
    if request.method != 'POST':
        return json_error('Method not allowed.', status=405)

    source_table = authored_holiday_table_name()
    if not source_table:
        return json_error(
            'The holidays table is not provisioned. Apply '
            'sql/2026-09-14_curriculum_authored_holidays.sql first.',
            status=404,
        )

    payload = json_body(request)
    if payload is None:
        return json_error('Invalid JSON body.')
    missing = require_fields(payload, ['label', 'startDate'])
    if missing:
        return json_error('Missing required fields.', fields=missing)

    dates = holiday_date_payload(payload)
    if isinstance(dates, JsonResponse):
        return dates

    row = insert_row(source_table, {
        'label': clean_str(payload.get('label')),
        'start_date': dates['start'],
        # A holiday with no end date is a single day, stored as such rather than
        # left null: every reader downstream measures a period, and "one day" is
        # a period whose two ends are the same date.
        'end_date': dates['end'],
        'type': clean_str(payload.get('type')),
        'color': clean_str(payload.get('color')) or AUTHORED_HOLIDAY_COLOR,
        'notes': clean_str(payload.get('notes')),
        'created_at': datetime.utcnow(),
        'updated_at': datetime.utcnow(),
        'is_archived': False,
    })
    invalidate_curriculum_cache()
    return JsonResponse({'created': True, 'holiday': serialize_holiday_row(row)}, status=201)


@csrf_exempt
def curriculum_holiday_detail(request, identifier):
    """One holiday: read either kind, edit or archive only an authored one."""
    identifier = clean_str(identifier)

    if request.method == 'GET':
        rows = [
            item for item in get_holiday_rows(include_archived=True)
            if clean_str(item.get('id')) == identifier
        ]
        if not rows:
            return json_error('Holiday not found.', status=404)
        return JsonResponse(serialize_holiday_row(rows[0]))

    if request.method not in {'PATCH', 'DELETE'}:
        return json_error('Method not allowed.', status=405)

    source_table = authored_holiday_table_name()
    if not source_table:
        return json_error('The holidays table is not provisioned.', status=404)

    rows = fetch_all(f'select * from {table_name(source_table)} where id = %s', [identifier])
    if not rows:
        # A GOV.UK id reaching a write is a client that has not noticed the two
        # kinds apart, so say which it is rather than "not found".
        if england_holiday_exists(identifier):
            return json_error(HOLIDAY_READ_ONLY_MESSAGE, status=405)
        return json_error('Holiday not found.', status=404)

    if request.method == 'DELETE':
        payload = archive_payload(source_table, rows[0].get('notes'))
        if payload:
            update_rows(source_table, 'id = %s', [identifier], payload)
        else:
            delete_rows(source_table, 'id = %s', [identifier])
        invalidate_curriculum_cache()
        return JsonResponse({'archived': True, 'id': identifier})

    payload = json_body(request)
    if payload is None:
        return json_error('Invalid JSON body.')

    updates = {'updated_at': datetime.utcnow()}
    # Only what was sent is written. The Holidays page saves a type rename by
    # PATCHing the type alone across every holiday that carries it, and a patch
    # that also blanked the dates would move every one of those holidays.
    if 'label' in payload:
        updates['label'] = clean_str(payload.get('label'))
    if 'type' in payload:
        updates['type'] = clean_str(payload.get('type'))
    if 'color' in payload:
        updates['color'] = clean_str(payload.get('color'))
    if 'notes' in payload:
        updates['notes'] = clean_str(payload.get('notes'))
    if 'startDate' in payload or 'endDate' in payload:
        dates = holiday_date_payload(payload, existing=rows[0])
        if isinstance(dates, JsonResponse):
            return dates
        updates['start_date'] = dates['start']
        updates['end_date'] = dates['end']

    update_rows(source_table, 'id = %s', [identifier], updates)
    invalidate_curriculum_cache()
    return JsonResponse({'updated': True, 'id': identifier})


def holiday_date_payload(payload, existing=None):
    """The start/end pair to store, or the 400 explaining why there is not one.

    An end date is optional -- most closures are a single day -- and an omitted
    one is stored as the start date rather than as null, so a holiday is always
    a period and never a special case. An end before the start is rejected here
    rather than silently swapped: a fortnight typed backwards is a typo, and
    quietly reinterpreting it would close the wrong fortnight.
    """
    existing = existing or {}
    start = format_date(payload.get('startDate')) or format_date(existing.get('start_date'))
    if not start:
        return json_error('Give the holiday a start date.')
    if 'endDate' in payload:
        end = format_date(payload.get('endDate')) or start
    else:
        end = format_date(existing.get('end_date')) or start
    if end < start:
        return json_error('The end date cannot be before the start date.')
    return {'start': start, 'end': end}


def england_holiday_exists(identifier):
    if not table_exists(ENGLAND_HOLIDAYS_TABLE):
        return False
    rows = fetch_all(
        f'select 1 from {table_name(ENGLAND_HOLIDAYS_TABLE)} where id = %s limit 1',
        [clean_str(identifier)],
    )
    return bool(rows)


@require_GET
def curriculum_england_holidays(request):
    """England's bank holidays as GOV.UK publishes them.

    Reference data, not the authored half of the calendar above: nobody here
    edits these, so the route is read-only. The table is loaded by
    sql/2026-09-13_curriculum_england_holidays.sql and kept current by
    ``england_holidays.run_sync`` -- automatically on the interval, by the
    refresh route below on demand, or by the fetch_england_holidays command.

    Deliberately uncached. It is one indexed read of well under a hundred rows,
    and caching it would pin an empty list for the whole TTL on any environment
    where the table has not been created yet.
    """
    # Reading the page is the most likely moment for the mirror to be checked,
    # and the least costly: the check runs behind the response.
    from . import england_holidays
    england_holidays.auto_sync_if_due()
    rows = []
    if table_exists(ENGLAND_HOLIDAYS_TABLE):
        rows = fetch_all(f'''
            select *
            from {table_name(ENGLAND_HOLIDAYS_TABLE)}
            order by holiday_date
        ''')
    results = [serialize_england_holiday_row(row) for row in rows]
    # The sync state rides along with the list rather than costing the page a
    # second request: "these are the dates" and "this is when they were last
    # checked" are one answer, and the page shows them together.
    return JsonResponse({
        'schema': CURRICULUM_SCHEMA,
        'count': len(results),
        'results': results,
        'syncStatus': england_holidays.sync_status(),
    })


@require_GET
def curriculum_england_holiday_syncs(request):
    """Every recent check against GOV.UK, and what each one found.

    This is the "which holidays changed on the website?" answer. A check that
    found nothing is listed too -- without it, the last real change reads as the
    last time anyone looked, which is the one wrong conclusion available here.
    """
    from . import england_holidays
    limit = parse_int(request.GET.get('limit'), 20) or 20
    return JsonResponse({
        'schema': CURRICULUM_SCHEMA,
        'status': england_holidays.sync_status(),
        'results': england_holidays.recent_syncs(min(limit, 100)),
    })


@csrf_exempt
def curriculum_england_holidays_refresh(request):
    """Check GOV.UK now, and report what moved.

    The button behind this exists because "it will refresh itself within a day"
    is not an answer when someone has just read that a bank holiday changed and
    needs the cohorts under it rescheduled today.

    ``?dryRun=1`` reports what would change without writing it.
    """
    from . import england_holidays
    if request.method != 'POST':
        return json_error('Method not allowed.', status=405)
    payload = json_body(request) or {}
    dry_run = truthy(request.GET.get('dryRun')) or truthy(payload.get('dryRun'))
    summary = england_holidays.run_sync(source='manual', apply=not dry_run)
    # The next automatic check is a full interval from this one, and the latch
    # holding that answer in memory was set before this check happened.
    england_holidays.reset_auto_sync_state()
    status = 200 if summary.get('status') == 'ok' else 502
    return JsonResponse({'summary': summary, 'status': england_holidays.sync_status()}, status=status)


